# v9.7 hotfix: broker promotion is event-based, not backlog-based.
# Default false means the rescue scanner is not allowed to promote old unlinked
# shadow trades just because broker capacity increases/frees up. Only the fresh
# TradingView signal path may mirror a newly-created shadow trade.
BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL = os.getenv("BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL", "false").strip().lower() == "true"
# v10.0.20: price/preview retry window for fresh broker entries.
# If OANDA price fetch/preview fails, keep retrying briefly rather than marking
# the fresh trade as permanently missed immediately. This is still idempotent:
# a queued retry blocks duplicate broker opens for the same shadow trade.
BROKER_SHADOW_AUTO_PREVIEW_RETRY_ENABLED = os.getenv("BROKER_SHADOW_AUTO_PREVIEW_RETRY_ENABLED", "true").strip().lower() == "true"
BROKER_SHADOW_AUTO_PREVIEW_RETRY_MAX_SECONDS = int(float(os.getenv("BROKER_SHADOW_AUTO_PREVIEW_RETRY_MAX_SECONDS", "300")))
BROKER_SHADOW_AUTO_PREVIEW_RETRY_LIMIT = int(float(os.getenv("BROKER_SHADOW_AUTO_PREVIEW_RETRY_LIMIT", "10")))
# v10.0.26: immediate diagnostic retry before queuing a missed price/preview.
# This means a temporary quote/API hiccup gets a few quick attempts immediately,
# then falls back to the short retry queue if still not executable.
BROKER_SHADOW_AUTO_PREVIEW_IMMEDIATE_ATTEMPTS = max(1, int(float(os.getenv("BROKER_SHADOW_AUTO_PREVIEW_IMMEDIATE_ATTEMPTS", "3"))))
BROKER_SHADOW_AUTO_PREVIEW_IMMEDIATE_SLEEP_SECONDS = max(0.0, min(float(os.getenv("BROKER_SHADOW_AUTO_PREVIEW_IMMEDIATE_SLEEP_SECONDS", "2")), 10.0))

# v10.0.27: live-style retry maintenance worker.
# Do not rely on a human keeping the dashboard open. In live, queued broker
# price/preview retries must be checked by the app itself.
BROKER_RETRY_BACKGROUND_WORKER_ENABLED = os.getenv("BROKER_RETRY_BACKGROUND_WORKER_ENABLED", "true").strip().lower() == "true"
BROKER_RETRY_BACKGROUND_INTERVAL_SECONDS = max(5.0, min(float(os.getenv("BROKER_RETRY_BACKGROUND_INTERVAL_SECONDS", "15")), 120.0))
BROKER_RETRY_BACKGROUND_QUEUE_LIMIT = max(1, int(float(os.getenv("BROKER_RETRY_BACKGROUND_QUEUE_LIMIT", str(BROKER_SHADOW_AUTO_PREVIEW_RETRY_LIMIT)))))

# v10.0.70: keep TradingView webhook responses fast. Webhooks now store the
