# ============================================================
# HELPERS
# ============================================================

def now_utc_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def now_utc() -> datetime:
    return datetime.now(timezone.utc)


def ensure_db_folder() -> None:
    Path(DB_PATH).parent.mkdir(parents=True, exist_ok=True)


def get_conn() -> sqlite3.Connection:
    if DATABASE_ENGINE not in {"sqlite", "sqlite3", ""}:
        # Fail closed rather than accidentally running live trading on a half-migrated
        # database layer. Postgres work in v10.0.72 is sidecar/readiness only.
        raise RuntimeError(
            f"DATABASE_ENGINE={DATABASE_ENGINE!r} is not live-enabled in this build. "
            "Keep live DATABASE_ENGINE=sqlite and use /db/postgres-readiness for sidecar checks."
        )
    ensure_db_folder()
    # v10.0.67: TradingView can send several index/research alerts at the same
    # second while the dashboard/background worker is also reading/writing.
    # Give SQLite time to wait instead of immediately throwing
    # `sqlite3.OperationalError: database is locked`. WAL/busy_timeout also
    # reduces read/write contention on Railway's persistent volume.
    conn = sqlite3.connect(DB_PATH, timeout=SQLITE_TIMEOUT_SECONDS, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    try:
        conn.execute(f"PRAGMA busy_timeout = {int(SQLITE_BUSY_TIMEOUT_MS)}")
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA synchronous = NORMAL")
    except Exception:
        # Do not fail app startup/dashboard purely because a PRAGMA cannot be
        # applied during a transient lock. The connection timeout still applies.
        pass
    return conn


def safe_str(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


def safe_float(value: Any) -> Optional[float]:
    try:
        if value is None or value == "":
            return None
        return float(
            str(value)
            .replace(",", "")
            .replace("£", "")
            .replace("$", "")
            .replace("%", "")
            .strip()
        )
    except Exception:
        return None


def is_true(value: Any) -> bool:
    return safe_str(value).lower() in {"true", "yes", "y", "1", "long", "buy", "take"}


def parse_bool(value: Any, default: bool = False) -> bool:
    """Parse env/API boolean-ish values safely.

    Accepts true/false, yes/no, 1/0, on/off. Returns default for None/empty/unknown.
    """
    if value is None:
        return default
    txt = safe_str(value).lower()
    if txt == "":
        return default
    if txt in {"true", "t", "yes", "y", "1", "on", "enabled", "enable"}:
        return True
    if txt in {"false", "f", "no", "n", "0", "off", "disabled", "disable"}:
        return False
    return default


def esc(value: Any) -> str:
    if value is None:
        return ""
    return str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def account_currency_symbol(currency: str = "") -> str:
    """Dashboard display symbol.

    The standalone BCO demo mirrors the live Project Exit Plan dashboard in GBP.
    DISPLAY_CURRENCY controls presentation only; it does not FX-convert OANDA
    account values. Use a GBP-denominated practice account for exact parity.
    """
    c = safe_str(currency or DISPLAY_CURRENCY).upper()
    if c == "GBP":
        return "£"
    if c == "EUR":
        return "€"
    if c == "JPY":
        return "¥"
    return "$"


def money(value: Any, currency: str = "") -> str:
    try:
        v = float(value or 0)
        sign = "-" if v < 0 else ""
        sym = account_currency_symbol(currency)
        return f"{sign}{sym}{abs(v):,.2f}"
    except Exception:
        return f"{account_currency_symbol(currency)}0.00"


def pct(value: Any) -> str:
    try:
        return f"{float(value or 0):.4f}%"
    except Exception:
        return "0.0000%"


def pnl_class(value: Any) -> str:
    try:
        v = float(value or 0)
        if v > 0:
            return "pos"
        if v < 0:
            return "neg"
        return "flat"
    except Exception:
        return "flat"


def status_class(value: Any) -> str:
    s = safe_str(value).lower()
    if s == "green":
        return "status_green"
    if s == "amber":
        return "status_amber"
    if s == "red":
        return "status_red"
    if s == "critical":
        return "status_critical"
    return "flat"


# ============================================================
# TREND MATURITY / EXHAUSTION WATCH (research-only monitor)
# ============================================================

def _risk_state_rank(state: str) -> int:
    ranks = {
        "HEALTHY_TREND": 0,
        "NEUTRAL": 1,
        "EXTENDED_CAUTION": 2,
        "LATE_TREND_EXHAUSTION": 3,
        "WEAK_CONTEXT": 3,
        "COOLDOWN_PULLBACK": 3,
        "NO_DATA": 1,
    }
    return ranks.get(safe_str(state).upper(), 1)


def _risk_state_class(state: str) -> str:
    s = safe_str(state).upper()
    if s == "HEALTHY_TREND":
        return "status_green"
    if s in {"EXTENDED_CAUTION", "NEUTRAL"}:
        return "status_amber" if s == "EXTENDED_CAUTION" else "flat"
    if s in {"LATE_TREND_EXHAUSTION", "WEAK_CONTEXT", "COOLDOWN_PULLBACK"}:
        return "status_red"
    return "flat"


def _fmt_metric(value: Any, suffix: str = "", dp: int = 2) -> str:
    v = safe_float(value)
    if v is None:
        return "n/a"
    return f"{v:.{dp}f}{suffix}"


def _latest_index_signal_rows_for_maturity(conn: sqlite3.Connection) -> List[sqlite3.Row]:
    """Latest stable NAS100/US500 1H/8H signal rows only.

    This deliberately excludes RESEARCH_MULTI_CTX_1H / MULTI rows so the live
    index trend-maturity watch is based on the unchanged NAS100/US500 signal
    stream.
    """
    rows: List[sqlite3.Row] = []
    for asset in ["NAS100", "US500"]:
        row = conn.execute(
            """
            SELECT *
            FROM raw_signals
            WHERE UPPER(pair) = ?
              AND UPPER(COALESCE(context_tf,'')) = '8H'
              AND UPPER(COALESCE(execution_tf,'')) = '1H'
              AND UPPER(COALESCE(model_version,'')) != 'RESEARCH_MULTI_CTX_1H'
            ORDER BY id DESC
            LIMIT 1
            """,
            (asset,),
        ).fetchone()
        if row is not None:
            rows.append(row)
    return rows


def _classify_trend_maturity(raw: Dict[str, Any], candidate: bool) -> Dict[str, Any]:
    ctx_rsi = safe_float(raw.get("ctx_rsi"))
    d_rsi = safe_float(raw.get("d_rsi"))
    ctx_dist_ema20 = safe_float(raw.get("ctx_dist_ema20_pct"))
    ctx_dist_ema50 = safe_float(raw.get("ctx_dist_ema50_pct"))
    ctx_close_gt_ema20 = parse_bool(raw.get("ctx_close_gt_ema20"), False)
    ctx_close_gt_ema50 = parse_bool(raw.get("ctx_close_gt_ema50"), False)
    ctx_hist_up = parse_bool(raw.get("ctx_hist_up"), False)
    ctx_rsi_up = parse_bool(raw.get("ctx_rsi_up"), False)
    ctx_bull_stack = parse_bool(raw.get("ctx_bull_stack"), False)
    ctx_trend = safe_str(raw.get("ctx_trend_state") or "unknown").lower()

    warnings: List[str] = []
    severe: List[str] = []

    if ctx_rsi is not None:
        if ctx_rsi >= 75:
            severe.append("8H RSI very hot")
        elif ctx_rsi >= 70:
            warnings.append("8H RSI > 70")
    if d_rsi is not None:
        if d_rsi >= 75:
            severe.append("Daily RSI > 75")
        elif d_rsi >= 70:
            warnings.append("Daily RSI > 70")
    if ctx_dist_ema20 is not None:
        if ctx_dist_ema20 >= 2.5:
            severe.append("Price >2.5% above 8H EMA20")
        elif ctx_dist_ema20 >= 1.5:
            warnings.append("Price >1.5% above 8H EMA20")
    if ctx_dist_ema50 is not None:
        if ctx_dist_ema50 >= 5.0:
            severe.append("Price >5% above 8H EMA50")
        elif ctx_dist_ema50 >= 3.0:
            warnings.append("Price >3% above 8H EMA50")

    if not ctx_hist_up:
        warnings.append("8H MACD hist not improving")
    if not ctx_rsi_up:
        warnings.append("8H RSI not improving")

    below_ema20 = not ctx_close_gt_ema20
    below_ema50 = not ctx_close_gt_ema50

    if below_ema20 and below_ema50 and not candidate:
        state = "COOLDOWN_PULLBACK"
        action = "No stacking bias; monitor for reset/rebuild."
    elif below_ema20 and ctx_trend != "bull":
        state = "WEAK_CONTEXT"
        action = "Defensive bias if basket active; avoid treating this as a healthy continuation."
    elif severe:
        state = "LATE_TREND_EXHAUSTION"
        action = "Research warning only: consider this late-trend territory; avoid changing live rules yet."
    elif warnings:
        state = "EXTENDED_CAUTION"
        action = "Trend may still continue, but stacking quality should be monitored."
    elif candidate and ctx_bull_stack and ctx_close_gt_ema20 and ctx_trend == "bull":
        state = "HEALTHY_TREND"
        action = "Context supportive. Normal system behaviour."
    else:
        state = "NEUTRAL"
        action = "No strong maturity warning. Monitor normal candidate support."

    return {
        "state": state,
        "warnings": warnings,
        "severe": severe,
        "action": action,
        "ctx_rsi": ctx_rsi,
        "d_rsi": d_rsi,
        "ctx_dist_ema20_pct": ctx_dist_ema20,
        "ctx_dist_ema50_pct": ctx_dist_ema50,
        "ctx_hist_up": ctx_hist_up,
        "ctx_rsi_up": ctx_rsi_up,
        "ctx_close_gt_ema20": ctx_close_gt_ema20,
        "ctx_close_gt_ema50": ctx_close_gt_ema50,
        "ctx_trend": ctx_trend,
    }


def build_trend_maturity_exhaustion_watch_html() -> str:
    """Research-only dashboard layer for trend maturity / exhaustion.

    This is intentionally display-only. It must not block entries, close trades,
    alter risk sizing, or change basket-manager decisions until future evidence
    justifies a rule change.
    """
    try:
        with get_conn() as conn:
            rows = _latest_index_signal_rows_for_maturity(conn)
    except Exception as e:
        return f"""
        <details class="priority">
            <summary>Trend Maturity / Exhaustion Watch — Research Only</summary>
            <div class="section-note warn">Trend maturity watch temporarily unavailable: {esc(e)}</div>
        </details>
        """

    if not rows:
        return """
        <details class="priority">
            <summary>Trend Maturity / Exhaustion Watch — Research Only</summary>
            <div class="section-note small">No latest NAS100/US500 1H/8H rows found yet. This layer is monitoring-only and does not affect execution.</div>
        </details>
        """

    asset_cards = ""
    table_rows = ""
    family_rank = 0
    family_state = "HEALTHY_TREND"
    active_candidates = 0

    for row in rows:
        asset = safe_str(row["pair"]).upper()
        candidate = is_true(row["forward_test_candidate"])
        if candidate:
            active_candidates += 1
        try:
            raw = json.loads(row["raw_json"] or "{}")
        except Exception:
            raw = {}
        metrics = _classify_trend_maturity(raw, candidate)
        state = metrics["state"]
        rank = _risk_state_rank(state)
        if rank > family_rank:
            family_rank = rank
            family_state = state
        notes = metrics["severe"] + metrics["warnings"]
        note_text = "; ".join(notes[:4]) if notes else "No major warning flags"
        if len(notes) > 4:
            note_text += f"; +{len(notes) - 4} more"
        state_cls = _risk_state_class(state)

        asset_cards += f"""
        <div class="card">
            <div class="label">{esc(asset)} trend maturity</div>
            <div class="value {state_cls}">{esc(state.replace('_', ' '))}</div>
            <div class="small">Candidate: {'true' if candidate else 'false'} | 8H RSI: {_fmt_metric(metrics['ctx_rsi'], '', 1)} | Daily RSI: {_fmt_metric(metrics['d_rsi'], '', 1)}</div>
            <div class="small">8H EMA20 dist: {_fmt_metric(metrics['ctx_dist_ema20_pct'], '%', 2)} | EMA50 dist: {_fmt_metric(metrics['ctx_dist_ema50_pct'], '%', 2)}</div>
        </div>
        """

        table_rows += f"""
        <tr>
            <td><strong>{esc(asset)}</strong></td>
            <td>{esc(display_candle_time(row['timestamp_readable'] or row['timestamp']))}</td>
            <td class="{'true' if candidate else 'false'}">{'true' if candidate else 'false'}</td>
            <td class="{state_cls}"><strong>{esc(state)}</strong></td>
            <td>{esc(safe_str(metrics['ctx_trend']).upper())}</td>
            <td>{_fmt_metric(metrics['ctx_rsi'], '', 1)}</td>
            <td>{_fmt_metric(metrics['d_rsi'], '', 1)}</td>
            <td>{_fmt_metric(metrics['ctx_dist_ema20_pct'], '%', 2)}</td>
            <td>{_fmt_metric(metrics['ctx_dist_ema50_pct'], '%', 2)}</td>
            <td>{'yes' if metrics['ctx_hist_up'] else 'no'}</td>
            <td>{'yes' if metrics['ctx_rsi_up'] else 'no'}</td>
            <td>{esc(note_text)}</td>
            <td>{esc(metrics['action'])}</td>
        </tr>
        """

    if family_rank >= 3:
        family_label = family_state.replace('_', ' ')
        family_class = "status_red"
    elif family_rank == 2:
        family_label = "EXTENDED / CAUTION"
        family_class = "status_amber"
    elif family_rank == 1:
        family_label = "NEUTRAL / RESETTING"
        family_class = "flat"
    else:
        family_label = "HEALTHY TREND"
        family_class = "status_green"

    return f"""
    <details class="priority">
        <summary>Trend Maturity / Exhaustion Watch — Research Only</summary>
        <div class="section-note small">
            Monitors whether NAS100/US500 are in healthy continuation, extended/late-trend, or pullback/cooldown territory.
            Research-only: this does not block entries, close trades, or change live risk.
        </div>
        <div class="cards three">
            <div class="card">
                <div class="label">Index maturity state</div>
                <div class="value {family_class}">{esc(family_label)}</div>
                <div class="small">Candidate support: {esc(active_candidates)} / {esc(len(rows))}</div>
            </div>
            {asset_cards}
        </div>
        <div class="table-scroll"><table>
            <thead><tr>
                <th>Asset</th><th>Signal</th><th>Candidate</th><th>State</th><th>8H Trend</th><th>8H RSI</th><th>Daily RSI</th><th>8H EMA20 Dist</th><th>8H EMA50 Dist</th><th>Hist Up</th><th>RSI Up</th><th>Warnings</th><th>Research Note</th>
            </tr></thead>
            <tbody>{table_rows}</tbody>
        </table></div>
    </details>
    """


# ============================================================
# ADAPTIVE ACCELERATION WATCH (research-only monitor)
# ============================================================

def _pct_change(current: Any, previous: Any) -> Optional[float]:
    cur = safe_float(current)
    prev = safe_float(previous)
    if cur is None or prev is None or prev == 0:
        return None
    return (cur - prev) / prev * 100.0


def _accel_state_rank(state: str) -> int:
    ranks = {
        "ACCELERATION_SUPPORTIVE": 0,
        "NEUTRAL": 1,
        "CANDIDATE_OFF_NEUTRAL": 1,
        "CANDIDATE_BUT_DECELERATING": 2,
        "ACCELERATION_OVERHEAT_WATCH": 2,
        "PULLBACK_DECELERATION": 3,
        "NO_DATA": 1,
    }
    return ranks.get(safe_str(state).upper(), 1)


def _accel_state_class(state: str) -> str:
    s = safe_str(state).upper()
    if s == "ACCELERATION_SUPPORTIVE":
        return "status_green"
    if s in {"CANDIDATE_BUT_DECELERATING", "ACCELERATION_OVERHEAT_WATCH"}:
        return "status_amber"
    if s == "PULLBACK_DECELERATION":
        return "status_red"
    return "flat"


def _latest_index_signal_rows_for_acceleration(conn: sqlite3.Connection, asset: str, limit: int = 8) -> List[sqlite3.Row]:
    return conn.execute(
        """
        SELECT *
        FROM raw_signals
        WHERE UPPER(pair) = ?
          AND UPPER(COALESCE(context_tf,'')) = '8H'
          AND UPPER(COALESCE(execution_tf,'')) = '1H'
          AND UPPER(COALESCE(model_version,'')) != 'RESEARCH_MULTI_CTX_1H'
        ORDER BY id DESC
        LIMIT ?
        """,
        (safe_str(asset).upper(), int(limit)),
    ).fetchall()


def _raw_json_dict(row: sqlite3.Row) -> Dict[str, Any]:
    try:
        raw = json.loads(row["raw_json"] or "{}")
        return raw if isinstance(raw, dict) else {}
    except Exception:
        return {}


def _classify_adaptive_acceleration(asset: str, rows: List[sqlite3.Row]) -> Dict[str, Any]:
    if not rows:
        return {
            "asset": safe_str(asset).upper(),
            "latest_signal_time": "",
            "latest_signal_time_display": "",
            "candidate": 0,
            "state": "NO_DATA",
            "state_rank": _accel_state_rank("NO_DATA"),
            "one_bar_return_pct": None,
            "previous_bar_return_pct": None,
            "acceleration_delta_pct": None,
            "ctx_rsi": None,
            "ctx_rsi_delta": None,
            "d_rsi": None,
            "d_rsi_delta": None,
            "ctx_dist_ema20_pct": None,
            "ctx_dist_ema20_delta": None,
            "score_raw": None,
            "score_delta": None,
            "candidate_true_last_3": 0,
            "candidate_true_last_6": 0,
            "research_bias": "NO_DATA",
            "research_multiplier_idea": 1.00,
            "live_execution_multiplier": effective_live_execution_multiplier(),
            "execution_multiplier_locked": 1,
            "warnings": "No stable 1H/8H index signal rows found.",
            "research_note": "No action. Research-only monitor.",
        }

    latest = rows[0]
    prev = rows[1] if len(rows) > 1 else None
    prior = rows[2] if len(rows) > 2 else None
    raw = _raw_json_dict(latest)
    prev_raw = _raw_json_dict(prev) if prev is not None else {}

    latest_close = safe_float(latest["exec_close"])
    prev_close = safe_float(prev["exec_close"]) if prev is not None else None
    prior_close = safe_float(prior["exec_close"]) if prior is not None else None
    one_bar_return = _pct_change(latest_close, prev_close)
    previous_bar_return = _pct_change(prev_close, prior_close)
    acceleration_delta = None
    if one_bar_return is not None and previous_bar_return is not None:
        acceleration_delta = one_bar_return - previous_bar_return

    candidate = is_true(latest["forward_test_candidate"])
    last3 = rows[:3]
    last6 = rows[:6]
    candidate_true_last_3 = sum(1 for r in last3 if is_true(r["forward_test_candidate"]))
    candidate_true_last_6 = sum(1 for r in last6 if is_true(r["forward_test_candidate"]))

    ctx_rsi = safe_float(raw.get("ctx_rsi"))
    prev_ctx_rsi = safe_float(prev_raw.get("ctx_rsi"))
    ctx_rsi_delta = ctx_rsi - prev_ctx_rsi if ctx_rsi is not None and prev_ctx_rsi is not None else None
    d_rsi = safe_float(raw.get("d_rsi"))
    prev_d_rsi = safe_float(prev_raw.get("d_rsi"))
    d_rsi_delta = d_rsi - prev_d_rsi if d_rsi is not None and prev_d_rsi is not None else None
    ctx_dist_ema20 = safe_float(raw.get("ctx_dist_ema20_pct"))
    prev_ctx_dist_ema20 = safe_float(prev_raw.get("ctx_dist_ema20_pct"))
    ctx_dist_ema20_delta = ctx_dist_ema20 - prev_ctx_dist_ema20 if ctx_dist_ema20 is not None and prev_ctx_dist_ema20 is not None else None
    score_raw = safe_float(raw.get("score_raw"))
    prev_score = safe_float(prev_raw.get("score_raw"))
    score_delta = score_raw - prev_score if score_raw is not None and prev_score is not None else None
    ctx_hist_up = parse_bool(raw.get("ctx_hist_up"), False)
    ctx_rsi_up = parse_bool(raw.get("ctx_rsi_up"), False)
    ctx_trend = safe_str(raw.get("ctx_trend_state") or "unknown").lower()

    warnings: List[str] = []
    overheat = False
    if ctx_rsi is not None and ctx_rsi >= 72:
        overheat = True
        warnings.append("8H RSI hot")
    if d_rsi is not None and d_rsi >= 72:
        overheat = True
        warnings.append("Daily RSI hot")
    if ctx_dist_ema20 is not None and ctx_dist_ema20 >= 2.0:
        overheat = True
        warnings.append("Price extended above 8H EMA20")

    price_accelerating = bool(one_bar_return is not None and one_bar_return > 0 and (acceleration_delta is None or acceleration_delta > 0))
    price_decelerating = bool(one_bar_return is not None and one_bar_return < 0 and (acceleration_delta is None or acceleration_delta < 0))
    context_improving = bool((ctx_rsi_delta is not None and ctx_rsi_delta > 0) or ctx_hist_up or ctx_rsi_up)

    if not candidate and price_decelerating:
        state = "PULLBACK_DECELERATION"
        research_bias = "DECELERATION_CAUTION_RESEARCH"
        research_multiplier_idea = 0.75
        note = "Research warning: candidate is off and price momentum is decelerating. Live multiplier remains locked at 1.00x."
    elif candidate and price_accelerating and overheat:
        state = "ACCELERATION_OVERHEAT_WATCH"
        research_bias = "ACCELERATION_BUT_EXTENDED_RESEARCH"
        research_multiplier_idea = 1.00
        note = "Research warning: acceleration is present but extension/RSI heat argues against blindly increasing exposure. Live multiplier remains 1.00x."
    elif candidate and price_accelerating and context_improving:
        state = "ACCELERATION_SUPPORTIVE"
        research_bias = "ACCELERATION_SUPPORTIVE_RESEARCH"
        research_multiplier_idea = 1.15
        note = "Research-only supportive acceleration. No live sizing change; multiplier remains 1.00x."
    elif candidate and acceleration_delta is not None and acceleration_delta < 0:
        state = "CANDIDATE_BUT_DECELERATING"
        research_bias = "CANDIDATE_DECELERATING_RESEARCH"
        research_multiplier_idea = 0.90
        note = "Candidate remains true but acceleration is fading. Research-only caution; live multiplier remains 1.00x."
    elif not candidate:
        state = "CANDIDATE_OFF_NEUTRAL"
        research_bias = "NO_ACCELERATION_RESEARCH"
        research_multiplier_idea = 1.00
        note = "Candidate is off. Research-only monitor; no live action."
    else:
        state = "NEUTRAL"
        research_bias = "NORMAL_RESEARCH"
        research_multiplier_idea = 1.00
        note = "No strong acceleration/deceleration read. Research-only monitor."

    if not warnings:
        warnings.append("No major acceleration warning flags")

    return {
        "asset": safe_str(asset).upper(),
        "latest_signal_time": safe_str(latest["timestamp_readable"] or latest["timestamp"]),
        "latest_signal_time_display": display_candle_time(latest["timestamp_readable"] or latest["timestamp"]),
        "latest_raw_signal_id": int(latest["id"]),
        "candidate": 1 if candidate else 0,
        "state": state,
        "state_rank": _accel_state_rank(state),
        "one_bar_return_pct": one_bar_return,
        "previous_bar_return_pct": previous_bar_return,
        "acceleration_delta_pct": acceleration_delta,
        "ctx_trend_state": ctx_trend,
        "ctx_rsi": ctx_rsi,
        "ctx_rsi_delta": ctx_rsi_delta,
        "d_rsi": d_rsi,
        "d_rsi_delta": d_rsi_delta,
        "ctx_dist_ema20_pct": ctx_dist_ema20,
        "ctx_dist_ema20_delta": ctx_dist_ema20_delta,
        "score_raw": score_raw,
        "score_delta": score_delta,
        "ctx_hist_up": 1 if ctx_hist_up else 0,
        "ctx_rsi_up": 1 if ctx_rsi_up else 0,
        "candidate_true_last_3": candidate_true_last_3,
        "candidate_true_last_6": candidate_true_last_6,
        "research_bias": research_bias,
        "research_multiplier_idea": research_multiplier_idea,
        "live_execution_multiplier": effective_live_execution_multiplier(),
        "execution_multiplier_locked": 1,
        "warnings": "; ".join(warnings),
        "research_note": note,
    }


def build_adaptive_acceleration_watch_snapshot_from_conn(conn: sqlite3.Connection, limit_per_asset: int = 8) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    for asset in ["NAS100", "US500"]:
        signal_rows = _latest_index_signal_rows_for_acceleration(conn, asset, limit=limit_per_asset)
        rows.append(_classify_adaptive_acceleration(asset, list(signal_rows)))

    worst_rank = max([int(r.get("state_rank") or 0) for r in rows], default=1)
    supportive_assets = sum(1 for r in rows if safe_str(r.get("state")).upper() == "ACCELERATION_SUPPORTIVE")
    caution_assets = sum(1 for r in rows if int(r.get("state_rank") or 0) >= 2)
    candidate_assets = sum(1 for r in rows if int(r.get("candidate") or 0) == 1)

    if worst_rank >= 3:
        index_state = "PULLBACK_DECELERATION"
        index_action = "Research caution only; do not increase live exposure."
    elif caution_assets > 0:
        index_state = "MIXED_ACCELERATION_CAUTION"
        index_action = "Research-only caution: acceleration/extension is mixed."
    elif supportive_assets == len(rows) and rows:
        index_state = "BROAD_ACCELERATION_SUPPORTIVE"
        index_action = "Research-only supportive read. Live multiplier remains locked at 1.00x."
    elif supportive_assets > 0:
        index_state = "PARTIAL_ACCELERATION_SUPPORTIVE"
        index_action = "Research-only supportive on one asset. Wait for evidence before rule changes."
    else:
        index_state = "NEUTRAL"
        index_action = "No strong acceleration signal."

    return {
        "status": "ok",
        "research_only": True,
        "index_state": index_state,
        "index_action": index_action,
        "candidate_assets": candidate_assets,
        "supportive_assets": supportive_assets,
        "caution_assets": caution_assets,
        "live_execution_multiplier": effective_live_execution_multiplier(),
        "execution_multiplier_hard_locked": LIVE_EXECUTION_MULTIPLIER_HARD_LOCKED,
        "multiplier_note": "Live broker execution is hard-locked at 1.00x. Adaptive acceleration output is dashboard/export research only.",
        "rows": rows,
        "time_utc": now_utc_iso(),
    }


def build_adaptive_acceleration_watch_snapshot(limit_per_asset: int = 8) -> Dict[str, Any]:
    init_db()
    with get_conn() as conn:
        return build_adaptive_acceleration_watch_snapshot_from_conn(conn, limit_per_asset=limit_per_asset)


def adaptive_acceleration_watch_csv_rows(snapshot: Dict[str, Any]) -> List[Dict[str, Any]]:
    base = {
        "snapshot_time_utc": snapshot.get("time_utc"),
        "index_state": snapshot.get("index_state"),
        "index_action": snapshot.get("index_action"),
        "candidate_assets": snapshot.get("candidate_assets"),
        "supportive_assets": snapshot.get("supportive_assets"),
        "caution_assets": snapshot.get("caution_assets"),
        "live_execution_multiplier": snapshot.get("live_execution_multiplier"),
        "execution_multiplier_hard_locked": 1 if snapshot.get("execution_multiplier_hard_locked") else 0,
        "research_only": 1,
    }
    rows = []
    for item in snapshot.get("rows", []) or []:
        row = dict(base)
        row.update(item)
        rows.append(row)
    if not rows:
        rows.append(base)
    return rows


