def calc_next_review_candle(
    hold_candles: Any,
    decision_48: Any = "",
    decision_72: Any = "",
    max_hold_candles: Any = 96,
) -> str:
    """
    Calculates the next actionable management review for dashboard/export clarity.

    v8.1 Mature Runner Mode:
    - Before 48c, the first decision point is 48.
    - From 48c onwards, any extended/open trade is reviewed every new candle.
    - 72c/96c/120c are milestones/checkpoints only. They are NOT forced exits.
    - 96c+ trades remain open while conditions are favourable and are managed by
      asset/basket weakness, giveback, runner protection, or emergency SL rules.
    """
    try:
        hold = int(float(hold_candles or 0))
    except Exception:
        hold = 0

    d48 = safe_str(decision_48).lower()
    d72 = safe_str(decision_72).lower()

    if d48.startswith("exit") or d72.startswith("exit"):
        return "EXIT"

    if hold < 48:
        return "48"

    return str(hold + 1)


def calc_next_review_candle_for_asset(asset: str, hold_candles: Any, decision_48: Any = "", decision_72: Any = "") -> str:
    cfg = get_cfg(asset)
    return calc_next_review_candle(
        hold_candles=hold_candles,
        decision_48=decision_48,
        decision_72=decision_72,
        max_hold_candles=cfg.get("max_hold_candles", 96),
    )




def basket_phase_from_count(open_count: Any) -> str:
    """Research phase label for basket size / stacking maturity."""
    try:
        c = int(open_count or 0)
    except Exception:
        c = 0
    if c <= 0:
        return "FLAT"
    if c <= 9:
        return "TINY"
    if c <= 24:
        return "EARLY"
    if c <= 49:
        return "DEVELOPING"
    if c < int(JUNE_FULL_DEMO_HEAVY_BASKET_OPEN_TRADES):
        return "MATURE"
    return "HEAVY"


def basket_execution_stage(open_count: Any) -> Dict[str, Any]:
    """Live-demo staged execution permission for basket-manager defence."""
    try:
        c = int(open_count or 0)
    except Exception:
        c = 0
    min_light = max(1, int(JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_LIGHT_TRIM))
    min_normal = max(min_light, int(JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_NORMAL_TRIM))
    min_full = max(min_normal, int(JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_FULL_BASKET_CLOSE))
    heavy = max(min_full, int(JUNE_FULL_DEMO_HEAVY_BASKET_OPEN_TRADES))

    if c <= 0:
        return {"stage": "FLAT", "max_close_fraction": 0.0, "full_close_eligible": False, "description": "No open basket."}
    if c < min_light:
        return {"stage": "TINY_OBSERVE_ONLY", "max_close_fraction": 0.0, "full_close_eligible": False, "description": f"{c} open trade(s): observe/pause only; no basket-manager trim before {min_light}."}
    if c < min_normal:
        return {"stage": "EARLY_LIGHT_DEFENCE", "max_close_fraction": 0.10, "full_close_eligible": False, "description": f"{c} open trades: light defence only; max weakest 10% trim."}
    if c < min_full:
        return {"stage": "DEVELOPING_NORMAL_TRIM", "max_close_fraction": 0.25, "full_close_eligible": False, "description": f"{c} open trades: normal 25% trim eligible; full close blocked before {min_full}."}
    if c < heavy:
        return {"stage": "MATURE_STRONG_DEFENCE", "max_close_fraction": 0.50, "full_close_eligible": True, "description": f"{c} open trades: 25-50% trims eligible; full close only if severe."}
    return {"stage": "HEAVY_FULL_DEFENCE", "max_close_fraction": 1.0, "full_close_eligible": True, "description": f"{c} open trades: heavy basket; full defence eligible if severe/persistent."}

def is_index_asset(asset: str) -> bool:
    return safe_str(asset).upper() in {"NAS100", "US500"}


def get_basket_family(asset: str) -> str:
    """Returns the correlated family basket for an asset, or the asset itself if unmapped."""
    a = safe_str(asset).upper()
    for family, assets in BASKET_FAMILIES.items():
        if a in {safe_str(x).upper() for x in assets}:
            return family
    return a


def get_family_assets(family: str) -> List[str]:
    """Returns configured asset symbols for a family basket."""
    f = safe_str(family).upper()
    return list(BASKET_FAMILIES.get(f, [f]))


def is_june_full_demo_broker_asset(asset: str) -> bool:
    return safe_str(asset).upper() in JUNE_FULL_DEMO_BROKER_ASSETS


def is_research_only_asset(asset: str) -> bool:
    return safe_str(asset).upper() in JUNE_FULL_DEMO_RESEARCH_ONLY_ASSETS


def effective_broker_auto_sl_pct(asset: str = "") -> float:
    """Use per-asset demo SLs for automatic shadow->broker entries."""
    a = safe_str(asset).upper()
    if NIKKEI_DEMO_ENABLED and a == "NIKKEI":
        return float(NIKKEI_DEMO_SL_PCT)
    if BCO_DEMO_ENABLED and a == "BCOUSD":
        return float(BCO_DEMO_SL_PCT)
    if JUNE_FULL_DEMO_ENABLED and a in JUNE_FULL_DEMO_BROKER_ASSETS:
        return float(JUNE_FULL_DEMO_INDEX_SL_PCT)
    return float(BROKER_SHADOW_AUTO_SL_PCT)


def is_family_basket(value: str) -> bool:
    return safe_str(value).upper() in BASKET_FAMILIES


def is_sunday_monday_gap_watch_window(timestamp_value: Any) -> bool:
    """
    Gap-aware research window for index baskets.

    Uses dashboard/display timezone because the live rule is intended to be
    Sunday 23:00 UK reopen through Monday evening UK time.
    """
    dt = parse_signal_candle_dt(timestamp_value)
    if not dt:
        return False
    uk_dt = dt.astimezone(_zone(DISPLAY_TIMEZONE))
    # Python weekday: Monday=0, Sunday=6.
    if uk_dt.weekday() == 6 and uk_dt.hour >= 23:
        return True
    if uk_dt.weekday() == 0 and uk_dt.hour <= 23:
        return True
    return False


def live_gap_watch_override_decision(
    asset: str,
    latest_signal_time: Any,
    tide_status: Any,
    original_action: Any,
    original_detail: Any,
    open_count: Any,
    open_basket_R: Any,
    losing_pct: Any,
    basket_giveback_pct: Any,
) -> Dict[str, Any]:
    """Return the effective live action during the Sunday/Monday gap-watch window.

    The override is deliberately narrow:
    - individual hard emergency SLs remain active elsewhere;
    - ordinary basket-manager trims/full closes are suppressed while the active
      index basket is inside the gap-watch window;
    - new stacking is blocked while an existing basket is being watched;
    - genuinely severe basket damage can still re-enable normal defence.
    """
    a = safe_str(asset).upper()
    action = safe_str(original_action)
    detail = safe_str(original_detail)
    try:
        open_n = int(open_count or 0)
    except Exception:
        open_n = 0
    basket_r = float(safe_float(open_basket_R) or 0.0)
    losing = float(safe_float(losing_pct) or 0.0)
    giveback = float(safe_float(basket_giveback_pct) or 0.0)
    in_window = bool(is_index_asset(a) and is_sunday_monday_gap_watch_window(latest_signal_time))
    active = bool(LIVE_GAP_WATCH_OVERRIDE_ENABLED and in_window and open_n > 0)

    severe_reasons: List[str] = []
    if basket_r <= float(LIVE_GAP_WATCH_SEVERE_R):
        severe_reasons.append(f"basket_R<={LIVE_GAP_WATCH_SEVERE_R:.2f}")
    if (
        open_n >= int(LIVE_GAP_WATCH_SEVERE_MIN_OPEN_TRADES)
        and losing >= float(LIVE_GAP_WATCH_SEVERE_LOSING_PCT)
        and basket_r <= float(LIVE_GAP_WATCH_SEVERE_BROAD_LOSS_R)
    ):
        severe_reasons.append(
            f"broad_loss_open>={LIVE_GAP_WATCH_SEVERE_MIN_OPEN_TRADES}_losing>={LIVE_GAP_WATCH_SEVERE_LOSING_PCT:.0f}pct_R<={LIVE_GAP_WATCH_SEVERE_BROAD_LOSS_R:.2f}"
        )
    severe_override = bool(active and severe_reasons)

    if active and not severe_override:
        effective_action = "GAP_WATCH_HOLD_EXISTING_BLOCK_NEW_ENTRIES"
        effective_detail = (
            "Live gap-watch override: hold existing index trades and suppress ordinary basket-manager "
            "trim/close actions during the Sunday/Monday gap window. New stacking is blocked while the "
            "basket is active. Individual hard emergency SLs remain live. Reassess each new hourly signal."
        )
        suppress_basket_closes = True
    elif severe_override:
        effective_action = action
        effective_detail = (
            "Gap-watch severe-damage override: normal basket defence is allowed because "
            + ",".join(severe_reasons)
            + ". Individual hard emergency SLs remain live."
        )
        suppress_basket_closes = False
    else:
        effective_action = action
        effective_detail = detail
        suppress_basket_closes = False

    entry_block = bool(active and LIVE_GAP_WATCH_BLOCK_NEW_STACKING)
    return {
        "enabled": bool(LIVE_GAP_WATCH_OVERRIDE_ENABLED),
        "in_window": in_window,
        "active": active,
        "asset": a,
        "open_trades": open_n,
        "tide_status": safe_str(tide_status).upper(),
        "open_basket_R": basket_r,
        "losing_trade_pct": losing,
        "basket_giveback_pct": giveback,
        "original_action": action,
        "original_detail": detail,
        "effective_action": effective_action,
        "effective_detail": effective_detail,
        "entry_block": entry_block,
        "suppress_basket_closes": suppress_basket_closes,
        "severe_override": severe_override,
        "severe_reasons": severe_reasons,
        "hard_sl_unchanged": True,
        "hold_non_sl_exits": bool(active and LIVE_GAP_WATCH_HOLD_NON_SL_EXITS),
    }


def theoretical_open_risk_for_asset(asset: str, open_count: int) -> float:
    cfg = get_cfg(asset)
    return float(cfg.get("risk_dollars", 50)) * int(open_count or 0)


def latest_tide_status_for_asset(conn: sqlite3.Connection, asset: str) -> Dict[str, Any]:
    row = conn.execute("""
        SELECT tide_status, tide_turn_score, tiered_action, basket_giveback_pct, open_basket_pnl_50risk, open_basket_R
        FROM tide_turn_checks
        WHERE asset = ?
        ORDER BY id DESC
        LIMIT 1
    """, (asset,)).fetchone()
    if not row:
        return {}
    return dict(row)

def signal_candle_is_ignored(timestamp_value: Any) -> bool:
    dt = parse_signal_candle_dt(timestamp_value)
    if not dt:
        return False
    return dt.hour in IGNORED_SIGNAL_HOURS


def build_signal_coverage(conn: sqlite3.Connection, lookback: int = SIGNAL_COVERAGE_LOOKBACK) -> Dict[str, Any]:
    """
    Checks whether each valid hourly candle received all expected asset signals.

    Expected assets:
    - NAS100
    - US500
    - XAUUSD
    - XAGUSD

    Known exception:
    - ignore timestamp hour 17 because no candle is expected in the current stream.
    """
    rows = conn.execute(
        """
        SELECT
            id,
            received_at_utc,
            pair,
            timestamp_readable,
            signal_id
        FROM raw_signals
        WHERE timestamp_readable IS NOT NULL
          AND timestamp_readable != ''
        ORDER BY timestamp_readable DESC, id DESC
        LIMIT 500
        """
    ).fetchall()

    grouped: Dict[str, Dict[str, Any]] = {}

    for row in rows:
        candle_time = safe_str(row["timestamp_readable"])
        pair = safe_str(row["pair"])

        if not candle_time:
            continue
        if signal_candle_is_ignored(candle_time):
            continue
        if pair not in EXPECTED_SIGNAL_PAIRS:
            continue

        if candle_time not in grouped:
            grouped[candle_time] = {
                "candle_time": candle_time,
                "received_pairs_set": set(),
                "latest_received_at_utc": "",
                "latest_received_dt": None,
                "signal_ids": [],
            }

        grouped[candle_time]["received_pairs_set"].add(pair)
        grouped[candle_time]["signal_ids"].append(safe_str(row["signal_id"]))

        received_dt = parse_dt(row["received_at_utc"])
        current_latest = grouped[candle_time]["latest_received_dt"]
        if received_dt and (current_latest is None or received_dt > current_latest):
            grouped[candle_time]["latest_received_dt"] = received_dt
            grouped[candle_time]["latest_received_at_utc"] = safe_str(row["received_at_utc"])

    candles = []
    for candle_time, data in grouped.items():
        received_pairs = sorted(list(data["received_pairs_set"]))
        missing_pairs = [p for p in EXPECTED_SIGNAL_PAIRS if p not in data["received_pairs_set"]]
        received_count = len(received_pairs)
        status = "OK" if received_count == len(EXPECTED_SIGNAL_PAIRS) else "WARNING"

        candles.append({
            "candle_time": candle_time,
            "candle_time_display": display_candle_time(candle_time),
            "status": status,
            "expected_count": len(EXPECTED_SIGNAL_PAIRS),
            "received_count": received_count,
            "received_pairs": received_pairs,
            "missing_pairs": missing_pairs,
            "latest_received_at_utc": data["latest_received_at_utc"],
            "latest_received_at_display": display_utc_time(data["latest_received_at_utc"]),
        })

    candles.sort(
        key=lambda x: parse_signal_candle_dt(x["candle_time"]) or datetime.min.replace(tzinfo=timezone.utc),
        reverse=True,
    )
    candles = candles[:lookback]

    latest = candles[0] if candles else None
    if latest and latest["status"] != "OK":
        latest_received_dt = parse_dt(latest.get("latest_received_at_utc"))
        if latest_received_dt:
            age_seconds = (now_utc() - latest_received_dt).total_seconds()
            if age_seconds <= SIGNAL_COVERAGE_GRACE_SECONDS:
                latest["status"] = "WAITING"

    overall_status = latest["status"] if latest else "UNKNOWN"

    return {
        "status": overall_status,
        "expected_pairs": EXPECTED_SIGNAL_PAIRS,
        "ignored_hours": sorted(list(IGNORED_SIGNAL_HOURS)),
        "latest": latest,
        "recent_candles": candles,
        "time_utc": now_utc_iso(),
        "display_timezone": DISPLAY_TIMEZONE,
        "signal_candle_timezone": SIGNAL_CANDLE_TIMEZONE,
    }



# ============================================================
# OANDA READ-ONLY HELPERS
# ============================================================

def mask_secret(value: str, visible: int = 4) -> str:
    s = safe_str(value)
    if not s:
        return ""
    if len(s) <= visible * 2:
        return "*" * len(s)
    return s[:visible] + "..." + s[-visible:]


def oanda_config_status() -> Dict[str, Any]:
    missing = []
    if not OANDA_ACCOUNT_ID:
        missing.append("OANDA_ACCOUNT_ID")
    if not OANDA_API_TOKEN:
        missing.append("OANDA_API_TOKEN")
    if not OANDA_API_BASE:
        missing.append("OANDA_API_BASE")

    return {
        "enabled": OANDA_ENABLED,
        "env": OANDA_ENV,
        "api_base": OANDA_API_BASE,
        "account_id": OANDA_ACCOUNT_ID,
        "token_present": bool(OANDA_API_TOKEN),
        "token_preview": mask_secret(OANDA_API_TOKEN),
        "read_only": BROKER_READ_ONLY,
        "execution_enabled": BROKER_EXECUTION_ENABLED,
        "kill_switch": BROKER_KILL_SWITCH,
        "timeout_seconds": OANDA_TIMEOUT_SECONDS,
        "missing": missing,
        "symbol_map": OANDA_SYMBOL_MAP,
    }


def oanda_orders_allowed() -> Tuple[bool, str]:
    """Single hard gate for broker order placement.

    Earlier demo versions deliberately allowed orders only in OANDA live account.
    For the live rollout, the same guard now allows either practice or live as
    long as the explicit safety variables are open. Research assets remain
    blocked elsewhere by BROKER_SHADOW_AUTO_ALLOWED_ASSETS / research-only logic.
    """
    if not OANDA_ENABLED:
        return False, "OANDA_ENABLED is false."
    env = safe_str(OANDA_ENV).lower()
    if env not in {"practice", "live"}:
        return False, f"Unsupported OANDA_ENV: {OANDA_ENV}."
    if BROKER_READ_ONLY:
        return False, "BROKER_READ_ONLY is true."
    if not BROKER_EXECUTION_ENABLED:
        return False, "BROKER_EXECUTION_ENABLED is false."
    if BROKER_KILL_SWITCH:
        return False, "BROKER_KILL_SWITCH is true."
    if not OANDA_ACCOUNT_ID or not OANDA_API_TOKEN:
        return False, "Missing OANDA account/token config."
    return True, f"OANDA {env} broker execution unlocked."


def oanda_safety_state() -> Dict[str, Any]:
    """Hard safety status used by broker routes and dashboard."""
    allowed, reason = oanda_orders_allowed()
    return {
        "mode": "BROKER_EXECUTION_UNLOCKED" if allowed else "SAFE_BLOCKED_OR_READ_ONLY",
        "orders_allowed": allowed,
        "reason": reason,
        "broker_read_only": BROKER_READ_ONLY,
        "broker_execution_enabled": BROKER_EXECUTION_ENABLED,
        "broker_kill_switch": BROKER_KILL_SWITCH,
        "max_test_units": BROKER_MAX_TEST_UNITS,
        "max_order_units": BROKER_MAX_ORDER_UNITS,
        "min_order_units": BROKER_MIN_ORDER_UNITS,
        "order_unit_step": BROKER_ORDER_UNIT_STEP,
        "bco_max_order_units": BROKER_MAX_ORDER_UNITS_BCO_USD,
        "bco_min_order_units": BROKER_MIN_ORDER_UNITS_BCO_USD,
        "bco_order_unit_step": BROKER_ORDER_UNIT_STEP_BCO_USD,
        "allow_min_units_fallback": BROKER_ALLOW_MIN_UNITS_FALLBACK,
        "min_units_ignore_risk_overage_env": BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE,
        "min_units_fallback_hard_lock": BROKER_MIN_UNITS_FALLBACK_HARD_LOCK,
        "min_units_effective_ignore_risk_overage": bool(BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE or BROKER_MIN_UNITS_FALLBACK_HARD_LOCK),
        "max_risk_test_amount": BROKER_MAX_RISK_TEST_AMOUNT,
        "default_risk_test_amount": BROKER_DEFAULT_RISK_TEST_AMOUNT,
        "default_sl_pct": BROKER_DEFAULT_SL_PCT,
        "allowed_instruments": sorted(list(BROKER_ALLOWED_INSTRUMENTS)),
        "live_execution_multiplier": effective_live_execution_multiplier(),
        "live_execution_multiplier_hard_locked": LIVE_EXECUTION_MULTIPLIER_HARD_LOCKED,
        "live_execution_multiplier_note": "Hard-locked at 1.00x. Research layers cannot increase live broker sizing.",
        "manual_only": True,
        "signal_auto_execution_enabled": False,
        "basket_manager_execution_enabled": False,
    }


def broker_control_status() -> Dict[str, Any]:
    """Compact operational broker safety/control view for the dashboard."""
    safety = oanda_safety_state()
    open_positions_count = None
    open_trades_count = None
    open_link_count = None
    last_reconciled_at = ""
    last_audit_at = ""

    if OANDA_ENABLED:
        try:
            positions_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")
            positions = positions_resp.get("data", {}).get("positions", []) if positions_resp.get("ok") else []
            allowed = set(BROKER_ALLOWED_INSTRUMENTS or [])
            positions = [p for p in (positions or []) if not allowed or safe_str(p.get("instrument")) in allowed]
            open_positions_count = len(positions or [])
        except Exception:
            open_positions_count = "ERR"
        try:
            trades_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openTrades")
            trades = trades_resp.get("data", {}).get("trades", []) if trades_resp.get("ok") else []
            allowed = set(BROKER_ALLOWED_INSTRUMENTS or [])
            trades = [t for t in (trades or []) if not allowed or safe_str(t.get("instrument")) in allowed]
            open_trades_count = len(trades or [])
        except Exception:
            open_trades_count = "ERR"

    try:
        with get_conn() as conn:
            row = conn.execute("SELECT COUNT(*) AS c FROM broker_trade_links WHERE status IN ('OPEN','LINKED','PENDING')").fetchone()
            open_link_count = row["c"] if row else 0
            lr = conn.execute("SELECT MAX(last_reconciled_at_utc) AS t FROM broker_trade_links").fetchone()
            last_reconciled_at = lr["t"] if lr and lr["t"] else ""
            la = conn.execute("SELECT MAX(created_at_utc) AS t FROM execution_audit_events").fetchone()
            last_audit_at = la["t"] if la and la["t"] else ""
    except Exception:
        open_link_count = "ERR"

    if safety.get("orders_allowed"):
        control_state = "UNLOCKED"
        control_level = "danger"
        message = "Manual practice execution is unlocked. Lock it after testing."
    elif BROKER_KILL_SWITCH:
        control_state = "LOCKED"
        control_level = "safe"
        message = "Kill switch is on. Orders are blocked."
    elif BROKER_READ_ONLY:
        control_state = "READ_ONLY"
        control_level = "safe"
        message = "Read-only mode is on. Orders are blocked."
    elif not BROKER_EXECUTION_ENABLED:
        control_state = "EXECUTION_DISABLED"
        control_level = "safe"
        message = "Execution flag is off. Orders are blocked."
    else:
        control_state = "BLOCKED"
        control_level = "warn"
        message = safe_str(safety.get("reason"))

    return {
        "control_state": control_state,
        "control_level": control_level,
        "message": message,
        "orders_allowed": bool(safety.get("orders_allowed")),
        "read_only": BROKER_READ_ONLY,
        "execution_enabled": BROKER_EXECUTION_ENABLED,
        "kill_switch": BROKER_KILL_SWITCH,
        "manual_only": True,
        "signal_auto_execution_enabled": False,
        "basket_manager_execution_enabled": False,
        "environment": OANDA_ENV,
        "account_id": OANDA_ACCOUNT_ID,
        "allowed_instruments": sorted(list(BROKER_ALLOWED_INSTRUMENTS)),
        "max_test_units": BROKER_MAX_TEST_UNITS,
        "max_order_units": BROKER_MAX_ORDER_UNITS,
        "max_risk_test_amount": BROKER_MAX_RISK_TEST_AMOUNT,
        "live_execution_multiplier": effective_live_execution_multiplier(),
        "live_execution_multiplier_hard_locked": LIVE_EXECUTION_MULTIPLIER_HARD_LOCKED,
        "open_oanda_positions": open_positions_count,
        "open_oanda_trades": open_trades_count,
        "open_broker_links": open_link_count,
        "last_link_reconcile_at_utc": last_reconciled_at,
        "last_execution_audit_at_utc": last_audit_at,
        "time_utc": now_utc_iso(),
        "safety": safety,
    }


def oanda_request(path: str, params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Performs a read-only GET request to OANDA v20 REST API."""
    config = oanda_config_status()
    if not OANDA_ENABLED:
        return {"ok": False, "disabled": True, "status_code": None, "error": "OANDA_ENABLED is false", "config": config}
    if config["missing"]:
        return {"ok": False, "disabled": False, "status_code": None, "error": "Missing OANDA config: " + ",".join(config["missing"]), "config": config}

    clean_path = "/" + safe_str(path).lstrip("/")
    url = OANDA_API_BASE + clean_path
    if params:
        url += "?" + urllib.parse.urlencode({k: v for k, v in params.items() if v is not None})

    req = urllib.request.Request(
        url,
        method="GET",
        headers={
            "Authorization": f"Bearer {OANDA_API_TOKEN}",
            "Accept": "application/json",
            "Content-Type": "application/json",
        },
    )

    try:
        with urllib.request.urlopen(req, timeout=OANDA_TIMEOUT_SECONDS) as resp:
            body = resp.read().decode("utf-8")
            try:
                data = json.loads(body) if body else {}
            except Exception:
                data = {"raw_body": body}
            return {"ok": True, "disabled": False, "status_code": resp.status, "url_path": clean_path, "data": data, "config": config}
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        try:
            data = json.loads(body) if body else {}
        except Exception:
            data = {"raw_body": body}
        return {"ok": False, "disabled": False, "status_code": e.code, "url_path": clean_path, "error": str(e), "data": data, "config": config}
    except Exception as e:
        return {"ok": False, "disabled": False, "status_code": None, "url_path": clean_path, "error": str(e), "config": config}


def oanda_write_request(path: str, method: str, body: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Performs a manual restricted in live mode write request to OANDA v20 REST API."""
    config = oanda_config_status()
    safety = oanda_safety_state()
    allowed, reason = oanda_orders_allowed()
    if not allowed:
        return {"ok": False, "blocked": True, "status_code": None, "error": reason, "config": config, "safety": safety}

    clean_path = "/" + safe_str(path).lstrip("/")
    url = OANDA_API_BASE + clean_path
    data_bytes = json.dumps(body or {}).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=data_bytes,
        method=safe_str(method).upper(),
        headers={
            "Authorization": f"Bearer {OANDA_API_TOKEN}",
            "Accept": "application/json",
            "Content-Type": "application/json",
        },
    )

    try:
        with urllib.request.urlopen(req, timeout=OANDA_TIMEOUT_SECONDS) as resp:
            raw_body = resp.read().decode("utf-8")
            try:
                data = json.loads(raw_body) if raw_body else {}
            except Exception:
                data = {"raw_body": raw_body}
            return {"ok": True, "blocked": False, "status_code": resp.status, "url_path": clean_path, "data": data, "config": config, "safety": safety}
    except urllib.error.HTTPError as e:
        raw_body = e.read().decode("utf-8", errors="replace")
        try:
            data = json.loads(raw_body) if raw_body else {}
        except Exception:
            data = {"raw_body": raw_body}
        return {"ok": False, "blocked": False, "status_code": e.code, "url_path": clean_path, "error": str(e), "data": data, "config": config, "safety": safety}
    except Exception as e:
        return {"ok": False, "blocked": False, "status_code": None, "url_path": clean_path, "error": str(e), "config": config, "safety": safety}


def log_execution_audit_event(
    mode: str,
    asset: str,
    trade_id: str,
    action: str,
    success: bool,
    message: str,
    broker_order_id: str = "",
    retry_count: int = 0,
    close_all_required: bool = False,
    broker_position_confirmed_flat: bool = False,
    raw: Optional[Dict[str, Any]] = None,
    intended_price: Optional[float] = None,
    actual_price: Optional[float] = None,
    spread_pct: Optional[float] = None,
    side: str = "",
    requested_units: Optional[float] = None,
    filled_units: Optional[float] = None,
    close_units: Optional[float] = None,
    risk_amount: Optional[float] = None,
    sl_pct: Optional[float] = None,
    estimated_risk: Optional[float] = None,
    broker_trade_id: str = "",
    response_status_code: Optional[int] = None,
) -> Optional[int]:
    """Logs broker test actions with enough detail to audit execution quality later."""
    try:
        slippage_pct = None
        if intended_price is not None and actual_price is not None and intended_price > 0:
            slippage_pct = (actual_price / intended_price - 1) * 100

        response_summary_json = ""
        if raw is not None:
            try:
                response_summary_json = json.dumps(raw)[:4000]
            except Exception:
                response_summary_json = safe_str(raw)[:4000]

        with get_conn() as conn:
            conn.execute("""
                INSERT INTO execution_audit_events (
                    created_at_utc, mode, asset, trade_id, action,
                    intended_price, actual_price, slippage_pct, spread_pct,
                    broker_order_id, success, retry_count, close_all_required,
                    broker_position_confirmed_flat, message
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                now_utc_iso(), mode, asset, trade_id, action,
                intended_price, actual_price, slippage_pct, spread_pct,
                broker_order_id, 1 if success else 0, retry_count,
                1 if close_all_required else 0,
                1 if broker_position_confirmed_flat else 0,
                message + (" | raw=" + response_summary_json[:2000] if raw is not None else ""),
            ))
            audit_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]

            # v5.1 optional audit columns. These are added on startup for existing DBs.
            update_cols = {
                "instrument": asset,
                "side": side,
                "requested_units": requested_units,
                "filled_units": filled_units,
                "close_units": close_units,
                "risk_amount": risk_amount,
                "sl_pct": sl_pct,
                "estimated_risk": estimated_risk,
                "broker_trade_id": broker_trade_id,
                "response_status_code": response_status_code,
                "response_summary_json": response_summary_json,
            }
            available = {r["name"] for r in conn.execute("PRAGMA table_info(execution_audit_events)").fetchall()}
            cols = [k for k in update_cols.keys() if k in available]
            if cols:
                set_sql = ", ".join([f"{c} = ?" for c in cols])
                vals = [update_cols[c] for c in cols] + [audit_id]
                conn.execute(f"UPDATE execution_audit_events SET {set_sql} WHERE id = ?", vals)

            conn.commit()
            return int(audit_id)
    except Exception:
        return None



def create_broker_trade_link(
    source: str,
    mode: str,
    shadow_trade_id: str,
    shadow_asset: str,
    shadow_trade_ref: str,
    instrument: str,
    side: str,
    requested_units: Optional[float],
    filled_units: Optional[float],
    broker_order_id: str,
    broker_trade_id: str,
    source_audit_id: Optional[int] = None,
    status: str = "OPEN",
    last_known_price: Optional[float] = None,
    notes: str = "",
    raw: Optional[Dict[str, Any]] = None,
) -> int:
    """Records the manual bridge between a Railway shadow trade/intention and an OANDA trade."""
    with get_conn() as conn:
        cur = conn.execute("""
            INSERT INTO broker_trade_links (
                created_at_utc, updated_at_utc, source, mode,
                shadow_trade_id, shadow_asset, shadow_trade_ref,
                broker, environment, instrument, side,
                requested_units, filled_units, broker_order_id, broker_trade_id,
                source_audit_id, status, opened_at_utc, closed_at_utc,
                last_reconciled_at_utc, last_known_units, last_known_price,
                last_known_unrealized_pl, notes, raw_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            now_utc_iso(), now_utc_iso(), source, mode,
            safe_str(shadow_trade_id), safe_str(shadow_asset), safe_str(shadow_trade_ref),
            "OANDA", OANDA_ENV, normalise_oanda_instrument(instrument), safe_str(side).lower(),
            requested_units, filled_units, safe_str(broker_order_id), safe_str(broker_trade_id),
            source_audit_id, safe_str(status or "OPEN"), now_utc_iso() if safe_str(status).upper() == "OPEN" else "", "",
            now_utc_iso(), filled_units, last_known_price, None, safe_str(notes), json.dumps(raw or {})[:4000],
        ))
        conn.commit()
        return int(cur.lastrowid)


def broker_trade_link_rows(limit: int = 100) -> List[Dict[str, Any]]:
    init_db()
    with get_conn() as conn:
        rows = conn.execute("SELECT * FROM broker_trade_links ORDER BY id DESC LIMIT ?", (int(limit),)).fetchall()
    return [dict(r) for r in rows]


def broker_trade_link_rows_by_status(statuses: List[str], limit: int = 250) -> List[Dict[str, Any]]:
    """Return broker trade links filtered by status. Used by the dashboard so OPEN links are not hidden by recent closed/test rows."""
    init_db()
    clean_statuses = [safe_str(s).upper() for s in statuses if safe_str(s).strip()]
    if not clean_statuses:
        return broker_trade_link_rows(limit)
    placeholders = ",".join(["?"] * len(clean_statuses))
    with get_conn() as conn:
        rows = conn.execute(
            f"SELECT * FROM broker_trade_links WHERE UPPER(COALESCE(status,'')) IN ({placeholders}) ORDER BY shadow_asset ASC, created_at_utc ASC, id ASC LIMIT ?",
            (*clean_statuses, int(limit)),
        ).fetchall()
    return [dict(r) for r in rows]


def broker_trade_link_count_by_status(statuses: List[str]) -> int:
    init_db()
    clean_statuses = [safe_str(s).upper() for s in statuses if safe_str(s).strip()]
    if not clean_statuses:
        return 0
    placeholders = ",".join(["?"] * len(clean_statuses))
    with get_conn() as conn:
        row = conn.execute(
            f"SELECT COUNT(*) AS n FROM broker_trade_links WHERE UPPER(COALESCE(status,'')) IN ({placeholders})",
            tuple(clean_statuses),
        ).fetchone()
    return int(row["n"] if row else 0)


def linked_trade_comparison_rows(limit: int = 250, open_only: bool = True) -> List[Dict[str, Any]]:
    """Compare Railway shadow trade state with linked OANDA demo broker trade state.

    This is a read-only validation layer. It helps answer whether the broker demo
    account is tracking the Railway shadow model closely enough for future testing.
    Values will not match perfectly because OANDA uses bid/ask fills, spread,
    account-currency conversion and real broker pricing, while the shadow model
    uses candle close/return logic.
    """
    init_db()
    limit = max(1, min(int(limit or 250), 1000))
    where = "WHERE UPPER(COALESCE(l.status,'')) = 'OPEN'" if open_only else ""
    with get_conn() as conn:
        rows = conn.execute(f"""
            SELECT
                l.*,
                ot.asset AS shadow_asset_live,
                ot.direction AS shadow_direction,
                ot.status AS shadow_status,
                ot.entry_time AS shadow_entry_time,
                ot.entry_price AS shadow_entry_price,
                ot.last_seen_time AS shadow_last_seen_time,
                ot.current_price AS shadow_current_price,
                ot.hold_candles AS shadow_hold_candles,
                ot.return_pct AS shadow_return_pct,
                ot.mfe_pct AS shadow_mfe_pct,
                ot.mae_pct AS shadow_mae_pct,
                ot.decision_48 AS shadow_decision_48,
                ot.decision_72 AS shadow_decision_72
            FROM broker_trade_links l
            LEFT JOIN open_trades ot ON ot.trade_id = l.shadow_trade_id
            {where}
            ORDER BY l.shadow_asset ASC, l.created_at_utc ASC, l.id ASC
            LIMIT ?
        """, (limit,)).fetchall()

    out: List[Dict[str, Any]] = []
    for r in rows:
        d = dict(r)
        link_status = safe_str(d.get("status")).upper()
        shadow_present = bool(d.get("shadow_asset_live"))
        asset = safe_str(d.get("shadow_asset_live") or d.get("shadow_asset") or "")
        shadow_entry = safe_float(d.get("shadow_entry_price"))
        broker_fill = safe_float(d.get("last_known_price"))
        shadow_current = safe_float(d.get("shadow_current_price"))
        shadow_return = safe_float(d.get("shadow_return_pct"))
        broker_pl = safe_float(d.get("last_known_unrealized_pl"))
        shadow_pnl = pnl_from_return(asset, shadow_return) if shadow_return is not None else None

        entry_diff = None
        entry_diff_pct = None
        if shadow_entry not in (None, 0) and broker_fill is not None:
            entry_diff = broker_fill - shadow_entry
            entry_diff_pct = (entry_diff / shadow_entry) * 100

        pnl_diff = None
        if broker_pl is not None and shadow_pnl is not None:
            pnl_diff = broker_pl - shadow_pnl

        warnings: List[str] = []
        if link_status == "OPEN" and not shadow_present:
            warnings.append("broker_link_open_but_shadow_trade_not_open")
        if link_status != "OPEN" and shadow_present:
            warnings.append("shadow_trade_open_but_broker_link_not_open")
        if entry_diff_pct is not None and abs(entry_diff_pct) > 0.15:
            warnings.append("large_entry_price_difference")
        if pnl_diff is not None and abs(pnl_diff) > 25:
            warnings.append("large_shadow_vs_broker_pnl_difference")
        if safe_str(d.get("broker_trade_id")) == "":
            warnings.append("missing_broker_trade_id")

        comparison_status = "OK" if not warnings else "CHECK"
        out.append({
            "link_id": d.get("id"),
            "created_at_utc": d.get("created_at_utc"),
            "shadow_trade_id": d.get("shadow_trade_id"),
            "asset": asset,
            "instrument": d.get("instrument"),
            "side": d.get("side"),
            "broker_trade_id": d.get("broker_trade_id"),
            "link_status": d.get("status"),
            "shadow_present_open": shadow_present,
            "shadow_direction": d.get("shadow_direction"),
            "shadow_entry_time": d.get("shadow_entry_time"),
            "shadow_entry_price": shadow_entry,
            "broker_fill_price": broker_fill,
            "entry_price_diff": entry_diff,
            "entry_price_diff_pct": entry_diff_pct,
            "shadow_current_price": shadow_current,
            "shadow_hold_candles": d.get("shadow_hold_candles"),
            "shadow_return_pct": shadow_return,
            "shadow_mfe_pct": safe_float(d.get("shadow_mfe_pct")),
            "shadow_mae_pct": safe_float(d.get("shadow_mae_pct")),
            "shadow_pnl_50risk": shadow_pnl,
            "broker_unrealized_pl": broker_pl,
            "broker_last_known_units": d.get("last_known_units"),
            "broker_filled_units": d.get("filled_units"),
            "pnl_diff_broker_minus_shadow": pnl_diff,
            "last_reconciled_at_utc": d.get("last_reconciled_at_utc"),
            "comparison_status": comparison_status,
            "warnings": "; ".join(warnings),
        })
    return out


def broker_action_queue_rows(limit: int = 100) -> List[Dict[str, Any]]:
    init_db()
    with get_conn() as conn:
        rows = conn.execute("SELECT * FROM broker_action_queue ORDER BY id DESC LIMIT ?", (int(limit),)).fetchall()
    return [dict(r) for r in rows]


def create_broker_action_queue_item(
    action: str,
    instrument: str,
    side: str = "",
    shadow_trade_id: str = "",
    shadow_asset: str = "",
    family: str = "",
    risk_amount: Optional[float] = None,
    sl_pct: Optional[float] = None,
    requested_units: Optional[float] = None,
    estimated_risk: Optional[float] = None,
    preview_price: Optional[float] = None,
    reason: str = "",
    preview: Optional[Dict[str, Any]] = None,
    mode: str = "manual_dry_run",
    source: str = "manual",
    status: str = "QUEUED_DRY_RUN",
    notes: str = "",
) -> int:
    init_db()
    now = now_utc_iso()
    safety = oanda_safety_state()
    with get_conn() as conn:
        cur = conn.execute("""
            INSERT INTO broker_action_queue (
                created_at_utc, updated_at_utc, status, mode, source, action,
                shadow_trade_id, shadow_asset, family, instrument, side,
                risk_amount, sl_pct, requested_units, estimated_risk, preview_price,
                reason, safety_snapshot_json, preview_json, notes
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            now, now, safe_str(status), safe_str(mode), safe_str(source), safe_str(action),
            safe_str(shadow_trade_id), safe_str(shadow_asset), safe_str(family), normalise_oanda_instrument(instrument), safe_str(side).lower(),
            risk_amount, sl_pct, requested_units, estimated_risk, preview_price,
            safe_str(reason), json.dumps(safety)[:4000], json.dumps(preview or {})[:4000], safe_str(notes),
        ))
        conn.commit()
        return int(cur.lastrowid)


def update_broker_action_queue_status(queue_id: int, status: str, notes: str = "", executed_audit_id: Optional[int] = None, broker_trade_link_id: Optional[int] = None) -> None:
    init_db()
    updates = ["updated_at_utc = ?", "status = ?"]
    vals: List[Any] = [now_utc_iso(), safe_str(status)]
    if notes:
        updates.append("notes = ?")
        vals.append(safe_str(notes))
    if executed_audit_id is not None:
        updates.append("executed_audit_id = ?")
        updates.append("executed_at_utc = ?")
        vals.extend([executed_audit_id, now_utc_iso()])
    if broker_trade_link_id is not None:
        updates.append("broker_trade_link_id = ?")
        vals.append(broker_trade_link_id)
    vals.append(int(queue_id))
    with get_conn() as conn:
        conn.execute(f"UPDATE broker_action_queue SET {', '.join(updates)} WHERE id = ?", vals)
        conn.commit()




# ============================================================
# OANDA MARKET-CLOSED / REOPEN QUEUE HANDLING (v9.1)
# ============================================================

def is_oanda_market_closed_response(resp: Optional[Dict[str, Any]]) -> bool:
    """Best-effort detection for OANDA market/instrument closed errors.

    OANDA wording can vary by endpoint/reject transaction. Keep this narrow so
    genuine broker/order errors still become failures rather than endless retries.
    """
    if not isinstance(resp, dict):
        return False
    hay = json.dumps(resp, default=str).upper()
    market_closed_terms = [
        "MARKET_HALTED",
        "MARKET_CLOSED",
        "INSTRUMENT_CLOSED",
        "INSTRUMENT_HALTED",
        "PRICE_HALTED",
        "TRADING_HALTED",
        "TRADING_DISABLED",
        "MARKET_IS_CLOSED",
        "THE MARKET IS CLOSED",
        "INSTRUMENT IS NOT TRADEABLE",
        "INSTRUMENT_NOT_TRADEABLE",
        "NO PRICE",
        "PRICE NOT AVAILABLE",
    ]
    return any(term in hay for term in market_closed_terms)


def mark_queue_waiting_market_reopen(queue_id: int, resp: Optional[Dict[str, Any]], executed_audit_id: Optional[int] = None, broker_trade_link_id: Optional[int] = None) -> None:
    msg = "Market/instrument appears closed; waiting for market reopen retry."
    raw = ""
    try:
        raw = json.dumps(resp or {}, default=str)[:1200]
    except Exception:
        raw = safe_str(resp)[:1200]
    notes = f"{msg} raw={raw}"
    update_broker_action_queue_status(queue_id, "WAITING_MARKET_REOPEN", notes, executed_audit_id, broker_trade_link_id)


def is_oanda_timeout_or_unknown_response(resp: Optional[Dict[str, Any]]) -> bool:
    """True when the OANDA write result is ambiguous and may have executed despite no clean response.

    A timeout must NOT be treated like a normal failed order, because the broker may
    have accepted the trade but Railway failed to receive/read the response. These
    rows should block duplicate opens until reconciliation/manual review.
    """
    try:
        hay = json.dumps(resp or {}, default=str).upper()
    except Exception:
        hay = safe_str(resp).upper()
    terms = [
        "TIMED OUT", "TIMEOUT", "READ OPERATION TIMED OUT", "WRITE OPERATION TIMED OUT",
        "CONNECTION ABORTED", "REMOTE END CLOSED", "CONNECTION RESET", "TEMPORARILY UNAVAILABLE",
    ]
    return any(t in hay for t in terms)


def mark_queue_waiting_reconciliation(queue_id: int, resp: Optional[Dict[str, Any]], executed_audit_id: Optional[int] = None, broker_trade_link_id: Optional[int] = None) -> None:
    msg = "Ambiguous OANDA write/timeout; waiting for reconciliation before any retry."
    raw = ""
    try:
        raw = json.dumps(resp or {}, default=str)[:1200]
    except Exception:
        raw = safe_str(resp)[:1200]
    notes = f"{msg} raw={raw}"
    update_broker_action_queue_status(queue_id, "WAITING_RECONCILIATION", notes, executed_audit_id, broker_trade_link_id)


def queue_shadow_trade_still_valid(q: Dict[str, Any]) -> Tuple[bool, str]:
    """Before retrying a delayed open, ensure the shadow trade is still open and fresh enough."""
    action = safe_str(q.get("action")).lower()
    shadow_trade_id = safe_str(q.get("shadow_trade_id"))
    if action != "place_risk_order":
        return True, "not an open action"
    if not shadow_trade_id:
        return False, "missing shadow_trade_id for delayed open"
    with get_conn() as conn:
        row = conn.execute("SELECT trade_id, status, created_at_utc, entry_time FROM open_trades WHERE trade_id=? LIMIT 1", (shadow_trade_id,)).fetchone()
    if not row:
        return False, "shadow trade no longer exists"
    d = dict(row)
    if safe_str(d.get("status")).lower() != "open":
        return False, "shadow trade is no longer open"
    min_entry_utc = broker_shadow_auto_min_entry_utc()
    entry_ref = safe_str(d.get("created_at_utc") or d.get("entry_time"))
    try:
        if parse_dt(entry_ref) and parse_dt(min_entry_utc) and parse_dt(entry_ref) < parse_dt(min_entry_utc):
            return False, "shadow trade predates fresh-only watermark"
    except Exception:
        pass
    return True, "shadow trade still open"



def broker_queue_item_age_seconds(q: Dict[str, Any]) -> Optional[float]:
    """Age of a broker_action_queue row, using created_at_utc."""
    dt = parse_dt(q.get("created_at_utc"))
    if not dt:
        return None
    return max(0.0, (now_utc() - dt).total_seconds())


def broker_preview_retry_still_allowed(q: Dict[str, Any]) -> bool:
    """Whether a fresh auto broker preview failure should keep retrying.

    This handles temporary price/quote preview failures. It deliberately uses a
    short age window so a missed signal does not get opened long after the candle.
    """
    if not BROKER_SHADOW_AUTO_PREVIEW_RETRY_ENABLED:
        return False
    if safe_str(q.get("mode")) != "shadow_demo_auto":
        return False
    if safe_str(q.get("action")).lower() != "place_risk_order":
        return False
    if safe_str(q.get("status")).upper() != "WAITING_PRICE_RETRY":
        return False
    age = broker_queue_item_age_seconds(q)
    if age is None:
        return False
    return age <= float(BROKER_SHADOW_AUTO_PREVIEW_RETRY_MAX_SECONDS)


def mark_queue_waiting_price_retry(queue_id: int, preview: Optional[Dict[str, Any]] = None, note_prefix: str = "Price/preview unavailable; waiting for retry") -> None:
    raw = ""
    try:
        raw = json.dumps(preview or {}, default=str)[:1200]
    except Exception:
        raw = safe_str(preview)[:1200]
    notes = f"{note_prefix}. retry_window_seconds={BROKER_SHADOW_AUTO_PREVIEW_RETRY_MAX_SECONDS}; raw={raw}"
    update_broker_action_queue_status(queue_id, "WAITING_PRICE_RETRY", notes)


def expire_waiting_price_retry_item(q: Dict[str, Any], reason: str = "preview retry window expired") -> Dict[str, Any]:
    """Expire a WAITING_PRICE_RETRY row without leaving the live trading in NO_GO.

    A preview retry is a short-lived execution-quality problem, not a broker
    reconciliation break. If it cannot be placed inside the retry window, the
    broker entry is treated as MISSED and the related shadow trade is removed
    from live exposure so OANDA-confirmed exposure remains the source of
    truth.
    """
    qid = int(q.get("id") or 0)
    shadow_trade_id = safe_str(q.get("shadow_trade_id"))
    existing_link = broker_shadow_open_link_exists(shadow_trade_id) if shadow_trade_id else None
    if existing_link:
        update_broker_action_queue_status(
            qid,
            "CANCELLED_DUPLICATE_LINK_EXISTS",
            f"Price retry cancelled because active broker link {existing_link.get('id')} already exists for this shadow trade.",
            None,
            int(existing_link.get("id") or 0),
        )
        return {"queue_id": qid, "ok": False, "cancelled": True, "reason": "duplicate broker link already exists", "broker_trade_link_id": existing_link.get("id")}

    shadow_closed = False
    if shadow_trade_id:
        try:
            with get_conn() as _miss_conn:
                shadow_closed = close_shadow_trade_as_broker_missed(_miss_conn, shadow_trade_id, "broker_entry_missed_price_retry_expired")
                _miss_conn.commit()
        except Exception as _e:
            log_system_event("broker_entry_missed_shadow_close_failed", f"Failed to close missed broker shadow {shadow_trade_id}: {_e}")

    # Do not use a status containing FAILED/ERROR here. This was a missed broker
    # entry after a controlled retry window, not an active reconciliation fault.
    update_broker_action_queue_status(
        qid,
        "MISSED_BROKER_ENTRY_RETRY_EXPIRED",
        f"{reason}; broker entry missed; shadow_closed={bool(shadow_closed)}; retry_window_seconds={BROKER_SHADOW_AUTO_PREVIEW_RETRY_MAX_SECONDS}",
    )
    return {"queue_id": qid, "ok": False, "expired": True, "shadow_closed": bool(shadow_closed), "status": "MISSED_BROKER_ENTRY_RETRY_EXPIRED"}


def expire_stale_waiting_price_retries(limit: int = 100) -> Dict[str, Any]:
    """Housekeeping pass to clear stale WAITING_PRICE_RETRY rows.

    This runs independently from order execution so a stale retry row cannot sit
    on the dashboard for 20+ minutes and keep Broker Preflight in NO_GO/WARN.
    """
    init_db()
    try:
        limit = max(1, min(int(limit or 100), 500))
    except Exception:
        limit = 100
    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute(
            """
            SELECT * FROM broker_action_queue
            WHERE status = 'WAITING_PRICE_RETRY'
            ORDER BY id ASC
            LIMIT ?
            """,
            (limit,),
        ).fetchall()]
    expired = []
    active = []
    for q in rows:
        if broker_preview_retry_still_allowed(q):
            active.append(int(q.get("id") or 0))
            continue
        expired.append(expire_waiting_price_retry_item(q, "preview retry window expired during housekeeping"))
    return {"ok": True, "checked": len(rows), "active": active, "expired": expired, "time_utc": now_utc_iso()}


def execute_waiting_market_reopen_queue(limit: int = 10) -> Dict[str, Any]:
    """Retry broker queue items that failed only because the market was closed.

    This is intentionally conservative: if the shadow trade is no longer valid,
    the delayed open is cancelled instead of being opened late.
    """
    init_db()
    try:
        limit = max(1, min(int(limit), 25))
    except Exception:
        limit = 10
    safety = oanda_safety_state()
    if not safety.get("orders_allowed"):
        return {"status": "blocked", "ok": False, "reason": safe_str(safety.get("reason") or "orders not allowed"), "retried": 0, "time_utc": now_utc_iso()}
    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute("""
            SELECT * FROM broker_action_queue
            WHERE status IN ('WAITING_MARKET_REOPEN','WAITING_PRICE_RETRY')
            ORDER BY id ASC
            LIMIT ?
        """, (limit,)).fetchall()]
    results = []
    for q in rows:
        qid = int(q.get("id") or 0)
        # Hard-expire stale price-preview retries before any new preview/order attempt.
        # This prevents a 5-minute retry window becoming a late stale entry.
        if safe_str(q.get("status")).upper() == "WAITING_PRICE_RETRY" and not broker_preview_retry_still_allowed(q):
            results.append(expire_waiting_price_retry_item(q, "preview retry window expired before retry execution"))
            continue
        # Never retry/open a delayed queue item if an active broker link already exists
        # for the same shadow trade. This prevents duplicate OANDA entries after a
        # price/market retry row lingers behind a successful execution.
        if safe_str(q.get("action")).lower() == "place_risk_order":
            existing_link = broker_shadow_open_link_exists(safe_str(q.get("shadow_trade_id") or ""))
            if existing_link:
                update_broker_action_queue_status(qid, "CANCELLED_DUPLICATE_LINK_EXISTS", f"Retry cancelled because active broker link {existing_link.get('id')} already exists for this shadow trade.", None, int(existing_link.get("id") or 0))
                results.append({"queue_id": qid, "ok": False, "cancelled": True, "reason": "duplicate broker link already exists", "broker_trade_link_id": existing_link.get("id")})
                continue
        valid, reason = queue_shadow_trade_still_valid(q)
        if not valid:
            update_broker_action_queue_status(qid, "CANCELLED_STALE_AFTER_REOPEN", reason)
            results.append({"queue_id": qid, "ok": False, "cancelled": True, "reason": reason})
            continue
        action = safe_str(q.get("action")).lower()
        # Retry only the open/linked-close actions here. close_until_flat is left for manual control.
        if action == "place_risk_order":
            instrument = normalise_oanda_instrument(q.get("instrument") or "")
            side = safe_str(q.get("side") or "buy").lower()
            requested_units = safe_float(q.get("requested_units"))
            if requested_units is None or abs(float(requested_units or 0)) <= 0:
                preview = build_risk_order_preview_with_immediate_retries(instrument=instrument, side=side, risk_amount=safe_float(q.get("risk_amount")), sl_pct=safe_float(q.get("sl_pct")), attempts=1, sleep_seconds=0)
                requested_units = safe_float(preview.get("signed_units")) if preview.get("ok") else None
            else:
                try:
                    preview = json.loads(q.get("preview_json") or "{}")
                except Exception:
                    preview = {}
            if requested_units is None or abs(float(requested_units or 0)) <= 0:
                if safe_str(q.get("status")).upper() == "WAITING_PRICE_RETRY" and broker_preview_retry_still_allowed(q):
                    mark_queue_waiting_price_retry(qid, preview, "Preview still unavailable during retry window")
                    results.append({"queue_id": qid, "ok": False, "waiting": True, "reason": "preview still unavailable; retry window still open"})
                elif safe_str(q.get("status")).upper() == "WAITING_PRICE_RETRY":
                    results.append(expire_waiting_price_retry_item(q, "preview retry window expired"))
                else:
                    update_broker_action_queue_status(qid, "EXECUTION_FAILED", "retry after reopen failed: requested_units missing/zero")
                    results.append({"queue_id": qid, "ok": False, "error": "requested_units missing/zero"})
                continue
            order_body = {"order": {"type": "MARKET", "instrument": instrument, "units": str(requested_units), "timeInForce": "FOK", "positionFill": "DEFAULT"}}
            resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/orders", "POST", order_body)
            details = extract_oanda_execution_details(resp)
            broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
            success = oanda_open_order_was_filled(resp, details)
            audit_id = log_execution_audit_event(
                "shadow_demo_auto", instrument, safe_str(q.get("shadow_trade_id", "")), "retry_waiting_market_reopen_place_order",
                success, f"retry market-reopen queued action {qid}", broker_order_id, raw={"queue": q, "request": order_body, "response": resp},
                intended_price=safe_float(q.get("preview_price")) or safe_float((preview or {}).get("current_mid_price")),
                actual_price=details.get("actual_price"), spread_pct=safe_float((preview or {}).get("spread_pct")), side=side, requested_units=requested_units, filled_units=details.get("filled_units"),
                risk_amount=safe_float(q.get("risk_amount")), sl_pct=safe_float(q.get("sl_pct")), estimated_risk=safe_float(q.get("estimated_risk")),
                broker_trade_id=details.get("broker_trade_id", ""), response_status_code=details.get("response_status_code"),
            )
            if success:
                link_id = create_broker_trade_link(
                    source="queue_market_reopen_retry", mode=safe_str(q.get("mode") or "shadow_demo_auto"),
                    shadow_trade_id=safe_str(q.get("shadow_trade_id", "")), shadow_asset=safe_str(q.get("shadow_asset", "")) or instrument,
                    shadow_trade_ref=f"broker_action_queue_id={qid}", instrument=instrument, side=side, requested_units=requested_units,
                    filled_units=details.get("filled_units"), broker_order_id=broker_order_id, broker_trade_id=details.get("broker_trade_id", ""),
                    source_audit_id=audit_id, status="OPEN", last_known_price=details.get("actual_price"),
                    notes="Executed after WAITING_MARKET_REOPEN retry. Practice/live-controlled.", raw={"queue": q, "response": resp},
                )
                update_broker_action_queue_status(qid, "EXECUTED_AFTER_REOPEN", "Queued open executed after market reopened", audit_id, link_id)
                results.append({"queue_id": qid, "ok": True, "broker_trade_link_id": link_id, "broker_trade_id": details.get("broker_trade_id", "")})
            elif is_oanda_market_closed_response(resp):
                mark_queue_waiting_market_reopen(qid, resp, audit_id, None)
                results.append({"queue_id": qid, "ok": False, "waiting": True, "reason": "market still closed"})
            else:
                update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA order failed"), audit_id, None)
                results.append({"queue_id": qid, "ok": False, "error": safe_str(resp.get("error") or "OANDA order failed")})
        elif action == "close_linked_trade":
            link_id = int(q.get("broker_trade_link_id") or 0)
            with get_conn() as conn:
                link_row = conn.execute("SELECT * FROM broker_trade_links WHERE id=?", (link_id,)).fetchone() if link_id > 0 else None
            if not link_row:
                update_broker_action_queue_status(qid, "CANCELLED_STALE_AFTER_REOPEN", "linked broker trade no longer exists")
                results.append({"queue_id": qid, "ok": False, "cancelled": True, "reason": "link missing"})
                continue
            link = dict(link_row)
            broker_trade_id = safe_str(link.get("broker_trade_id") or "")
            close_body = {"units": "ALL"}
            resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
            details = extract_oanda_execution_details(resp)
            broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
            success = bool(resp.get("ok"))
            audit_id = log_execution_audit_event("shadow_demo_auto", normalise_oanda_instrument(link.get("instrument") or ""), safe_str(link.get("shadow_trade_id") or ""), "retry_waiting_market_reopen_close_linked_trade", success, f"retry market-reopen close queue {qid}", broker_order_id, raw={"queue": q, "broker_trade_link": link, "request": close_body, "response": resp}, side=safe_str(link.get("side") or ""), close_units=details.get("closed_units"), actual_price=details.get("actual_price"), broker_trade_id=broker_trade_id, response_status_code=details.get("response_status_code"))
            if success:
                now_closed = now_utc_iso()
                with get_conn() as conn:
                    conn.execute("""UPDATE broker_trade_links SET updated_at_utc=?, status='CLOSE_SENT', closed_at_utc=COALESCE(NULLIF(closed_at_utc,''), ?), last_reconciled_at_utc=?, notes=? WHERE id=?""", (now_closed, now_closed, now_closed, f"Close sent after market reopen queue id {qid}", link_id))
                    conn.commit()
                update_broker_action_queue_status(qid, "EXECUTED_AFTER_REOPEN", "Queued close executed after market reopened", audit_id, link_id)
                results.append({"queue_id": qid, "ok": True, "broker_trade_link_id": link_id})
            elif is_oanda_market_closed_response(resp):
                mark_queue_waiting_market_reopen(qid, resp, audit_id, link_id)
                results.append({"queue_id": qid, "ok": False, "waiting": True, "reason": "market still closed"})
            else:
                update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA close failed"), audit_id, link_id)
                results.append({"queue_id": qid, "ok": False, "error": safe_str(resp.get("error") or "OANDA close failed")})
        else:
            results.append({"queue_id": qid, "ok": False, "skipped": True, "reason": f"unsupported retry action {action}"})
    try:
        reconcile_broker_trade_links()
    except Exception:
        pass
    return {"status": "ok", "ok": True, "checked": len(rows), "retried": sum(1 for r in results if r.get("ok")), "results": results, "time_utc": now_utc_iso()}


def reconcile_broker_trade_links() -> Dict[str, Any]:
    """Best-effort reconciliation: marks linked broker trade IDs OPEN if OANDA reports them open, otherwise CLOSED/MISSING."""
    init_db()
    resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openTrades")
    if not resp.get("ok"):
        return {"ok": False, "status": "error", "response": resp, "time_utc": now_utc_iso()}

    open_trades = resp.get("data", {}).get("trades", []) or []
    by_id = {safe_str(t.get("id")): t for t in open_trades if isinstance(t, dict)}
    updated = []
    now = now_utc_iso()

    with get_conn() as conn:
        links = conn.execute("SELECT * FROM broker_trade_links WHERE status IN ('OPEN','UNKNOWN','PENDING','CLOSE_SENT') ORDER BY id ASC").fetchall()
        for row in links:
            d = dict(row)
            broker_trade_id = safe_str(d.get("broker_trade_id"))
            match = by_id.get(broker_trade_id)
            if match:
                units = safe_float(match.get("currentUnits"))
                price = safe_float(match.get("price"))
                upl = safe_float(match.get("unrealizedPL") or match.get("trueUnrealizedPL"))
                conn.execute("""
                    UPDATE broker_trade_links
                    SET updated_at_utc=?, last_reconciled_at_utc=?, status='OPEN',
                        last_known_units=?, last_known_price=?, last_known_unrealized_pl=?, raw_json=?
                    WHERE id=?
                """, (now, now, units, price, upl, json.dumps(match)[:4000], d.get("id")))
                updated.append({"id": d.get("id"), "broker_trade_id": broker_trade_id, "status": "OPEN", "units": units})
            else:
                conn.execute("""
                    UPDATE broker_trade_links
                    SET updated_at_utc=?, last_reconciled_at_utc=?, status='CLOSED_OR_NOT_OPEN', closed_at_utc=COALESCE(NULLIF(closed_at_utc,''), ?)
                    WHERE id=?
                """, (now, now, now, d.get("id")))
                updated.append({"id": d.get("id"), "broker_trade_id": broker_trade_id, "status": "CLOSED_OR_NOT_OPEN", "closed_at_utc": now})
        conn.commit()

    shadow_cleanup = None
    try:
        shadow_cleanup = sync_missed_broker_shadow_trades(limit=500)
    except Exception as e:
        shadow_cleanup = {"ok": False, "error": safe_str(e)}

    return {
        "ok": True,
        "status": "ok",
        "open_oanda_trade_count": len(open_trades),
        "updated_links": updated,
        "shadow_cleanup": shadow_cleanup,
        "time_utc": now,
    }


def normalise_oanda_instrument(value: Any) -> str:
    instrument = safe_str(value).upper()
    if instrument in OANDA_SYMBOL_MAP:
        instrument = safe_str(OANDA_SYMBOL_MAP[instrument]).upper()
    return instrument


def validate_manual_oanda_instrument(instrument: str) -> Tuple[bool, str]:
    if not instrument:
        return False, "Missing instrument."
    if instrument not in BROKER_ALLOWED_INSTRUMENTS:
        return False, f"Instrument {instrument} is not in BROKER_ALLOWED_INSTRUMENTS."
    return True, "ok"


def broker_min_order_units_for_instrument(instrument: str) -> float:
    inst = normalise_oanda_instrument(instrument)
    if inst == BCO_DEMO_INSTRUMENT:
        return max(0.0, float(BROKER_MIN_ORDER_UNITS_BCO_USD))
    return max(0.0, float(BROKER_MIN_ORDER_UNITS))


def broker_order_unit_step_for_instrument(instrument: str) -> float:
    inst = normalise_oanda_instrument(instrument)
    if inst == BCO_DEMO_INSTRUMENT:
        return max(0.000001, float(BROKER_ORDER_UNIT_STEP_BCO_USD))
    return max(0.000001, float(BROKER_ORDER_UNIT_STEP))


def broker_max_order_units_for_instrument(instrument: str) -> float:
    inst = normalise_oanda_instrument(instrument)
    if inst == BCO_DEMO_INSTRUMENT:
        return max(0.0, float(BROKER_MAX_ORDER_UNITS_BCO_USD))
    return max(0.0, float(BROKER_MAX_ORDER_UNITS))


def validate_manual_oanda_units(units: Any, allow_all: bool = False) -> Tuple[bool, str, Optional[float]]:
    if allow_all and safe_str(units).upper() == "ALL":
        return True, "ok", None
    val = safe_float(units)
    if val is None or val <= 0:
        return False, "Units must be a positive number.", None
    if val > BROKER_MAX_ORDER_UNITS:
        return False, f"Units {val} exceeds BROKER_MAX_ORDER_UNITS {BROKER_MAX_ORDER_UNITS}.", None
    return True, "ok", val


def extract_transaction_id(resp: Dict[str, Any]) -> str:
    data = resp.get("data", {}) if isinstance(resp, dict) else {}
    if not isinstance(data, dict):
        return ""
    for key in ["orderCreateTransaction", "orderFillTransaction", "orderCancelTransaction", "longOrderCreateTransaction", "shortOrderCreateTransaction"]:
        item = data.get(key)
        if isinstance(item, dict) and item.get("id"):
            return safe_str(item.get("id"))
    return ""


def extract_oanda_execution_details(resp: Dict[str, Any]) -> Dict[str, Any]:
    """Best-effort parser for OANDA order/close responses for audit/export clarity."""
    data = resp.get("data", {}) if isinstance(resp, dict) else {}
    if not isinstance(data, dict):
        data = {}

    fill = data.get("orderFillTransaction") if isinstance(data.get("orderFillTransaction"), dict) else {}
    create = data.get("orderCreateTransaction") if isinstance(data.get("orderCreateTransaction"), dict) else {}

    broker_trade_id = ""
    filled_units = None
    closed_units = None

    trade_opened = fill.get("tradeOpened") if isinstance(fill.get("tradeOpened"), dict) else {}
    trade_reduced = fill.get("tradeReduced") if isinstance(fill.get("tradeReduced"), dict) else {}
    trades_closed = fill.get("tradesClosed") if isinstance(fill.get("tradesClosed"), list) else []

    if trade_opened:
        broker_trade_id = safe_str(trade_opened.get("tradeID"))
        filled_units = safe_float(trade_opened.get("units"))
    elif trade_reduced:
        broker_trade_id = safe_str(trade_reduced.get("tradeID"))
        closed_units = safe_float(trade_reduced.get("units"))
    elif trades_closed:
        ids = []
        total = 0.0
        for item in trades_closed:
            if isinstance(item, dict):
                if item.get("tradeID"):
                    ids.append(safe_str(item.get("tradeID")))
                u = safe_float(item.get("units"))
                if u is not None:
                    total += abs(u)
        broker_trade_id = ",".join(ids)
        closed_units = total

    requested_units = safe_float(create.get("units")) if create else None
    actual_price = safe_float(fill.get("price")) if fill else None
    instrument = safe_str(fill.get("instrument") or create.get("instrument"))
    reason = safe_str(fill.get("reason") or create.get("reason"))

    return {
        "instrument": instrument,
        "broker_order_id": extract_transaction_id(resp),
        "broker_trade_id": broker_trade_id,
        "requested_units": requested_units,
        "filled_units": filled_units,
        "closed_units": closed_units,
        "actual_price": actual_price,
        "response_status_code": resp.get("status_code"),
        "reason": reason,
    }


def oanda_open_order_was_filled(resp: Dict[str, Any], details: Optional[Dict[str, Any]] = None) -> bool:
    """True only when an automatic market entry actually created a broker trade.

    OANDA can return HTTP 201 for an order request that is immediately cancelled
    (for example MARKET_HALTED at the weekend reopen). Earlier versions treated
    any HTTP-level success as an executed trade, created an empty broker link,
    and then repeatedly retried the same shadow trade after reconciliation.

    For the live shadow mirror, an entry is successful only when there is an
    orderFillTransaction and a concrete tradeOpened.tradeID.
    """
    if not isinstance(resp, dict) or not resp.get("ok"):
        return False
    data = resp.get("data", {})
    if not isinstance(data, dict):
        return False
    if isinstance(data.get("orderCancelTransaction"), dict):
        return False
    if isinstance(data.get("orderRejectTransaction"), dict):
        return False
    fill = data.get("orderFillTransaction")
    if not isinstance(fill, dict):
        return False
    d = details or extract_oanda_execution_details(resp)
    return bool(safe_str(d.get("broker_trade_id")))


def floor_to_step(value: float, step: float = 0.01) -> float:
    try:
        if value <= 0 or step <= 0:
            return 0.0
        return int(value / step) * step
    except Exception:
        return 0.0


def extract_oanda_price_quote(pricing_data: Dict[str, Any]) -> Dict[str, Any]:
    prices = pricing_data.get("prices") if isinstance(pricing_data, dict) else None
    if not prices:
        return {"ok": False, "mid_price": None, "bid": None, "ask": None, "spread": None, "spread_pct": None}
    price = prices[0]
    bid = safe_float(price.get("closeoutBid"))
    ask = safe_float(price.get("closeoutAsk"))
    if bid is None:
        bids = price.get("bids") or []
        if bids and isinstance(bids[0], dict):
            bid = safe_float(bids[0].get("price"))
    if ask is None:
        asks = price.get("asks") or []
        if asks and isinstance(asks[0], dict):
            ask = safe_float(asks[0].get("price"))

    mid = None
    if bid is not None and ask is not None and bid > 0 and ask > 0:
        mid = (bid + ask) / 2
    elif bid is not None and bid > 0:
        mid = bid
    elif ask is not None and ask > 0:
        mid = ask

    spread = None
    spread_pct = None
    if bid is not None and ask is not None and bid > 0 and ask > 0 and ask >= bid:
        spread = ask - bid
        if mid and mid > 0:
            spread_pct = spread / mid * 100.0

    return {
        "ok": mid is not None and mid > 0,
        "mid_price": mid,
        "bid": bid,
        "ask": ask,
        "spread": spread,
        "spread_pct": spread_pct,
    }


def extract_oanda_mid_price(pricing_data: Dict[str, Any]) -> Optional[float]:
    return safe_float(extract_oanda_price_quote(pricing_data).get("mid_price"))


def broker_max_spread_pct_for_instrument(instrument: str) -> float:
    inst = normalise_oanda_instrument(instrument)
    if inst == "NAS100_USD":
        return float(BROKER_MAX_SPREAD_PCT_NAS100_USD)
    if inst == "SPX500_USD":
        return float(BROKER_MAX_SPREAD_PCT_SPX500_USD)
    if inst == NIKKEI_DEMO_INSTRUMENT:
        return float(BROKER_MAX_SPREAD_PCT_JP225_USD)
    if inst == BCO_DEMO_INSTRUMENT:
        return float(BROKER_MAX_SPREAD_PCT_BCO_USD)
    return float(BROKER_MAX_SPREAD_PCT_DEFAULT)


def get_oanda_mid_price(instrument: str) -> Dict[str, Any]:
    instrument = normalise_oanda_instrument(instrument)
    resp = oanda_request(
        f"/v3/accounts/{OANDA_ACCOUNT_ID}/pricing",
        params={"instruments": instrument},
    )
    quote = extract_oanda_price_quote(resp.get("data", {})) if resp.get("ok") else {"ok": False}
    return {
        "ok": bool(resp.get("ok")) and bool(quote.get("ok")),
        "instrument": instrument,
        "mid_price": safe_float(quote.get("mid_price")),
        "bid": safe_float(quote.get("bid")),
        "ask": safe_float(quote.get("ask")),
        "spread": safe_float(quote.get("spread")),
        "spread_pct": safe_float(quote.get("spread_pct")),
        "max_spread_pct": broker_max_spread_pct_for_instrument(instrument),
        "response": resp,
    }



def classify_preview_price_failure(price_info: Dict[str, Any]) -> Tuple[str, str, bool]:
    """Classify why the broker preview could not get a usable OANDA price.

    Returns: (failure_code, human_message, retryable)
    """
    resp = price_info.get("response") if isinstance(price_info, dict) else None
    status_code = None
    if isinstance(resp, dict):
        status_code = resp.get("status_code")
        if resp.get("disabled"):
            return "OANDA_DISABLED", "OANDA is disabled or not configured", False
        if resp.get("error"):
            err = safe_str(resp.get("error"))
            hay = err.upper()
            if "TIMEOUT" in hay or "TIMED OUT" in hay:
                return "OANDA_PRICE_TIMEOUT", f"OANDA pricing request timed out: {err}", True
            if status_code in {401, 403}:
                return "OANDA_AUTH_ERROR", f"OANDA pricing auth/config error: HTTP {status_code}", False
            if status_code == 429:
                return "OANDA_RATE_LIMIT", "OANDA pricing rate-limited the request", True
            if isinstance(status_code, int) and status_code >= 500:
                return "OANDA_SERVER_ERROR", f"OANDA pricing server error: HTTP {status_code}", True
            return "OANDA_PRICE_REQUEST_ERROR", f"OANDA pricing request error: {err}", True
        if status_code in {401, 403}:
            return "OANDA_AUTH_ERROR", f"OANDA pricing auth/config error: HTTP {status_code}", False
        if status_code == 429:
            return "OANDA_RATE_LIMIT", "OANDA pricing rate-limited the request", True
        if isinstance(status_code, int) and status_code >= 500:
            return "OANDA_SERVER_ERROR", f"OANDA pricing server error: HTTP {status_code}", True

    bid = safe_float(price_info.get("bid") if isinstance(price_info, dict) else None)
    ask = safe_float(price_info.get("ask") if isinstance(price_info, dict) else None)
    mid = safe_float(price_info.get("mid_price") if isinstance(price_info, dict) else None)
    if bid is None and ask is None:
        return "NO_BID_ASK", "OANDA pricing response had no usable bid/ask", True
    if mid is None or mid <= 0:
        return "NO_MID_PRICE", "OANDA pricing response had no usable mid price", True
    return "PRICE_PREVIEW_FAILED", "Could not build a valid OANDA price preview", True


def preview_failure_summary(preview: Optional[Dict[str, Any]]) -> str:
    """Compact operator-facing reason for queue/dashboard rows."""
    if not isinstance(preview, dict):
        return "PREVIEW_FAILED: no preview payload"
    code = safe_str(preview.get("failure_code") or "PREVIEW_FAILED")
    msg = safe_str(preview.get("error") or preview.get("failure_message") or "broker order preview failed")
    spread_pct = safe_float(preview.get("spread_pct"))
    cost_pct = safe_float(preview.get("estimated_entry_cost_pct_of_risk"))
    parts = [code]
    if msg:
        parts.append(msg)
    extras = []
    if spread_pct is not None:
        extras.append(f"spread={spread_pct:.4f}%")
    if cost_pct is not None:
        extras.append(f"entry_cost={cost_pct:.2f}% of risk")
    if extras:
        parts.append("; ".join(extras))
    return " | ".join(parts)[:500]


def build_risk_order_preview_with_immediate_retries(
    instrument: str,
    side: str = "buy",
    risk_amount: Optional[float] = None,
    sl_pct: Optional[float] = None,
    attempts: Optional[int] = None,
    sleep_seconds: Optional[float] = None,
) -> Dict[str, Any]:
    """Try to build an OANDA risk preview a few times immediately."""
    attempts = max(1, int(attempts or BROKER_SHADOW_AUTO_PREVIEW_IMMEDIATE_ATTEMPTS))
    sleep_seconds = BROKER_SHADOW_AUTO_PREVIEW_IMMEDIATE_SLEEP_SECONDS if sleep_seconds is None else max(0.0, float(sleep_seconds))
    history: List[Dict[str, Any]] = []
    last: Dict[str, Any] = {}
    for attempt_no in range(1, attempts + 1):
        last = build_risk_order_preview(instrument=instrument, side=side, risk_amount=risk_amount, sl_pct=sl_pct)
        try:
            history.append({
                "attempt": attempt_no,
                "ok": bool(last.get("ok")),
                "failure_code": safe_str(last.get("failure_code")),
                "error": safe_str(last.get("error")),
                "spread_pct": safe_float(last.get("spread_pct")),
                "estimated_entry_cost_pct_of_risk": safe_float(last.get("estimated_entry_cost_pct_of_risk")),
                "time_utc": now_utc_iso(),
            })
        except Exception:
            pass
        if last.get("ok"):
            last["preview_attempts"] = attempt_no
            last["preview_attempt_history"] = history
            return last
        if not bool(last.get("retryable_preview") or last.get("retryable_cost_guard")):
            break
        if attempt_no < attempts and sleep_seconds > 0:
            time.sleep(sleep_seconds)
    if isinstance(last, dict):
        last["preview_attempts"] = len(history) or 1
        last["preview_attempt_history"] = history
    return last


def build_risk_order_preview(
    instrument: str,
    side: str = "buy",
    risk_amount: Optional[float] = None,
    sl_pct: Optional[float] = None,
) -> Dict[str, Any]:
    instrument = normalise_oanda_instrument(instrument)
    side = safe_str(side or "buy").lower()
    risk_amount = float(risk_amount if risk_amount is not None else BROKER_DEFAULT_RISK_TEST_AMOUNT)
    sl_pct = float(sl_pct if sl_pct is not None else BROKER_DEFAULT_SL_PCT)

    inst_ok, inst_msg = validate_manual_oanda_instrument(instrument)
    if not inst_ok:
        return {"ok": False, "blocked": True, "failure_code": "INSTRUMENT_NOT_ALLOWED", "retryable_preview": False, "error": inst_msg, "safety": oanda_safety_state()}
    if side not in {"buy", "sell"}:
        return {"ok": False, "blocked": True, "failure_code": "INVALID_SIDE", "retryable_preview": False, "error": "side must be buy or sell", "safety": oanda_safety_state()}
    if risk_amount <= 0:
        return {"ok": False, "blocked": True, "failure_code": "INVALID_RISK_AMOUNT", "retryable_preview": False, "error": "risk_amount must be positive", "safety": oanda_safety_state()}
    if risk_amount > BROKER_MAX_RISK_TEST_AMOUNT:
        return {"ok": False, "blocked": True, "failure_code": "RISK_AMOUNT_EXCEEDS_LIMIT", "retryable_preview": False, "error": f"risk_amount {risk_amount} exceeds BROKER_MAX_RISK_TEST_AMOUNT {BROKER_MAX_RISK_TEST_AMOUNT}", "safety": oanda_safety_state()}
    if sl_pct <= 0:
        return {"ok": False, "blocked": True, "failure_code": "INVALID_SL_PCT", "retryable_preview": False, "error": "sl_pct must be positive", "safety": oanda_safety_state()}

    price_info = get_oanda_mid_price(instrument)
    current_price = safe_float(price_info.get("mid_price"))
    if not price_info.get("ok") or current_price is None or current_price <= 0:
        failure_code, failure_message, retryable = classify_preview_price_failure(price_info)
        return {
            "ok": False, "blocked": False, "failure_code": failure_code,
            "retryable_preview": bool(retryable), "error": failure_message,
            "instrument": instrument, "side": side, "risk_amount_requested": risk_amount,
            "sl_pct": sl_pct, "price_info": price_info, "safety": oanda_safety_state(),
        }

    stop_distance_points = current_price * (sl_pct / 100.0)
    raw_units = risk_amount / stop_distance_points if stop_distance_points > 0 else 0.0
    unit_step = broker_order_unit_step_for_instrument(instrument)
    min_order_units = broker_min_order_units_for_instrument(instrument)
    if min_order_units <= 0:
        min_order_units = unit_step
    max_order_units = broker_max_order_units_for_instrument(instrument)
    units = floor_to_step(raw_units, unit_step)
    min_units_fallback_used = False
    min_units_estimated_risk = min_order_units * stop_distance_points
    min_units_max_allowed_risk = min(
        BROKER_MAX_RISK_TEST_AMOUNT,
        risk_amount * (1.0 + (BROKER_MIN_UNITS_MAX_RISK_OVERAGE_PCT / 100.0)),
    )
    effective_min_units_ignore_risk_overage = bool(
        BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE or BROKER_MIN_UNITS_FALLBACK_HARD_LOCK
    )

    # Live account minimum-size rule:
    # If the risk-based calculation produces anything below OANDA's minimum tradable unit,
    # use the OANDA minimum rather than missing an otherwise-valid signal. This is intentional:
    # the estimated SL risk may exceed the current target risk/trade when the account is small,
    # but it keeps execution live instead of creating phantom/missed broker entries.
    if units < min_order_units:
        if BROKER_ALLOW_MIN_UNITS_FALLBACK and min_order_units > 0:
            if effective_min_units_ignore_risk_overage or min_units_estimated_risk <= min_units_max_allowed_risk:
                units = min_order_units
                min_units_fallback_used = True
            else:
                return {
                    "ok": False, "blocked": True, "failure_code": "UNITS_BELOW_MINIMUM",
                    "retryable_preview": False,
                    "error": (
                        f"Calculated units {raw_units:.6f} are below minimum {min_order_units:.4f}. "
                        f"Minimum-size SL risk would be {min_units_estimated_risk:.2f}, "
                        f"allowed up to {min_units_max_allowed_risk:.2f}."
                    ),
                    "raw_units": raw_units, "min_order_units": min_order_units,
                    "min_units_estimated_risk": min_units_estimated_risk,
                    "min_units_max_allowed_risk": min_units_max_allowed_risk,
                    "min_units_ignore_risk_overage": effective_min_units_ignore_risk_overage,
                    "min_units_ignore_risk_overage_env": BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE,
                    "min_units_fallback_hard_lock": BROKER_MIN_UNITS_FALLBACK_HARD_LOCK,
                    "safety": oanda_safety_state(),
                }
        else:
            return {
                "ok": False, "blocked": True, "failure_code": "UNITS_BELOW_MINIMUM",
                "retryable_preview": False,
                "error": (
                    f"Calculated units {raw_units:.6f} are below minimum {min_order_units:.4f}. "
                    f"Minimum-size fallback disabled."
                ),
                "raw_units": raw_units, "min_order_units": min_order_units,
                "min_units_estimated_risk": min_units_estimated_risk,
                "min_units_max_allowed_risk": min_units_max_allowed_risk,
                "min_units_ignore_risk_overage": effective_min_units_ignore_risk_overage,
                    "min_units_ignore_risk_overage_env": BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE,
                    "min_units_fallback_hard_lock": BROKER_MIN_UNITS_FALLBACK_HARD_LOCK,
                "safety": oanda_safety_state(),
            }
    if units > max_order_units:
        return {"ok": False, "blocked": True, "failure_code": "UNITS_EXCEED_MAX_ORDER", "retryable_preview": False, "error": f"Calculated units {units} exceeds instrument max order units {max_order_units}", "raw_units": raw_units, "max_order_units": max_order_units, "safety": oanda_safety_state()}

    signed_units = units if side == "buy" else -units
    estimated_risk = units * stop_distance_points
    stop_price = current_price - stop_distance_points if side == "buy" else current_price + stop_distance_points

    bid = safe_float(price_info.get("bid"))
    ask = safe_float(price_info.get("ask"))
    spread = safe_float(price_info.get("spread"))
    spread_pct = safe_float(price_info.get("spread_pct"))
    max_spread_pct = broker_max_spread_pct_for_instrument(instrument)
    estimated_entry_cost = abs(units) * spread if spread is not None else None
    estimated_entry_cost_pct_of_risk = (estimated_entry_cost / risk_amount * 100.0) if estimated_entry_cost is not None and risk_amount > 0 else None

    if BROKER_COST_GUARD_ENABLED:
        if spread_pct is not None and spread_pct > max_spread_pct:
            return {
                "ok": False, "blocked": False, "failure_code": "SPREAD_TOO_WIDE",
                "retryable_preview": True, "retryable_cost_guard": True,
                "error": f"Spread too wide: {spread_pct:.4f}% > max {max_spread_pct:.4f}%",
                "instrument": instrument, "side": side, "current_mid_price": current_price,
                "bid": bid, "ask": ask, "spread": spread, "spread_pct": spread_pct,
                "max_spread_pct": max_spread_pct, "risk_amount_requested": risk_amount,
                "sl_pct": sl_pct, "raw_units": raw_units, "units": units,
                "min_order_units": min_order_units, "unit_step": unit_step,
                "min_units_fallback_used": min_units_fallback_used,
                "min_units_estimated_risk": min_units_estimated_risk,
                "min_units_max_allowed_risk": min_units_max_allowed_risk,
                "min_units_ignore_risk_overage": effective_min_units_ignore_risk_overage,
                    "min_units_ignore_risk_overage_env": BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE,
                    "min_units_fallback_hard_lock": BROKER_MIN_UNITS_FALLBACK_HARD_LOCK,
                "estimated_entry_cost": estimated_entry_cost,
                "estimated_entry_cost_pct_of_risk": estimated_entry_cost_pct_of_risk,
                "max_entry_cost_pct_of_risk": BROKER_MAX_ENTRY_COST_PCT_OF_RISK,
                "price_info": price_info, "safety": oanda_safety_state(),
            }
        if estimated_entry_cost_pct_of_risk is not None and estimated_entry_cost_pct_of_risk > BROKER_MAX_ENTRY_COST_PCT_OF_RISK:
            return {
                "ok": False, "blocked": False, "failure_code": "ENTRY_COST_TOO_HIGH",
                "retryable_preview": True, "retryable_cost_guard": True,
                "error": f"Entry spread cost too high: {estimated_entry_cost_pct_of_risk:.2f}% of risk > max {BROKER_MAX_ENTRY_COST_PCT_OF_RISK:.2f}%",
                "instrument": instrument, "side": side, "current_mid_price": current_price,
                "bid": bid, "ask": ask, "spread": spread, "spread_pct": spread_pct,
                "max_spread_pct": max_spread_pct, "risk_amount_requested": risk_amount,
                "sl_pct": sl_pct, "raw_units": raw_units, "units": units,
                "min_order_units": min_order_units, "unit_step": unit_step,
                "min_units_fallback_used": min_units_fallback_used,
                "min_units_estimated_risk": min_units_estimated_risk,
                "min_units_max_allowed_risk": min_units_max_allowed_risk,
                "min_units_ignore_risk_overage": effective_min_units_ignore_risk_overage,
                    "min_units_ignore_risk_overage_env": BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE,
                    "min_units_fallback_hard_lock": BROKER_MIN_UNITS_FALLBACK_HARD_LOCK,
                "estimated_entry_cost": estimated_entry_cost,
                "estimated_entry_cost_pct_of_risk": estimated_entry_cost_pct_of_risk,
                "max_entry_cost_pct_of_risk": BROKER_MAX_ENTRY_COST_PCT_OF_RISK,
                "price_info": price_info, "safety": oanda_safety_state(),
            }

    return {
        "ok": True,
        "instrument": instrument,
        "side": side,
        "current_mid_price": current_price,
        "bid": bid,
        "ask": ask,
        "spread": spread,
        "spread_pct": spread_pct,
        "max_spread_pct": max_spread_pct,
        "estimated_entry_cost": estimated_entry_cost,
        "estimated_entry_cost_pct_of_risk": estimated_entry_cost_pct_of_risk,
        "max_entry_cost_pct_of_risk": BROKER_MAX_ENTRY_COST_PCT_OF_RISK,
        "risk_amount_requested": risk_amount,
        "sl_pct": sl_pct,
        "stop_distance_points": stop_distance_points,
        "estimated_stop_price": stop_price,
        "raw_units": raw_units,
        "units": units,
        "signed_units": signed_units,
        "min_order_units": min_order_units,
        "unit_step": unit_step,
        "min_units_fallback_used": min_units_fallback_used,
        "min_units_estimated_risk": min_units_estimated_risk,
        "min_units_max_allowed_risk": min_units_max_allowed_risk,
                "min_units_ignore_risk_overage": effective_min_units_ignore_risk_overage,
                    "min_units_ignore_risk_overage_env": BROKER_MIN_UNITS_IGNORE_RISK_OVERAGE,
                    "min_units_fallback_hard_lock": BROKER_MIN_UNITS_FALLBACK_HARD_LOCK,
        "estimated_risk_amount": estimated_risk,
        "note": "Approximate account-currency risk sizing. If the calculated risk-sized units are below the OANDA minimum, the bot may use the minimum size only within the configured hard risk guardrails. CFD/index P&L conversion may vary by broker/account currency; verify using live OANDA fills and realised P&L.",
        "price_info": {
            "ok": price_info.get("ok"),
            "instrument": instrument,
            "mid_price": current_price,
            "bid": bid,
            "ask": ask,
            "spread": spread,
            "spread_pct": spread_pct,
        },
        "safety": oanda_safety_state(),
    }


def extract_oanda_account_summary(account_data: Dict[str, Any]) -> Dict[str, Any]:
    account = account_data.get("account") if isinstance(account_data, dict) else None
    if not isinstance(account, dict):
        return {}

    return {
        "id": safe_str(account.get("id")),
        "alias": safe_str(account.get("alias")),
        "currency": safe_str(account.get("currency")),
        "balance": safe_float(account.get("balance")),
        "NAV": safe_float(account.get("NAV")),
        "unrealizedPL": safe_float(account.get("unrealizedPL")),
        "pl": safe_float(account.get("pl")),
        "marginUsed": safe_float(account.get("marginUsed")),
        "marginAvailable": safe_float(account.get("marginAvailable")),
        "marginCloseoutPercent": safe_float(account.get("marginCloseoutPercent")),
        "openTradeCount": int(safe_float(account.get("openTradeCount")) or 0),
        "openPositionCount": int(safe_float(account.get("openPositionCount")) or 0),
        "pendingOrderCount": int(safe_float(account.get("pendingOrderCount")) or 0),
    }


def oanda_build_snapshot() -> Dict[str, Any]:
    """Fetches account/trades/positions and stores a broker snapshot when possible."""
    config = oanda_config_status()
    safety = oanda_safety_state()
    control = broker_control_status()

    if not OANDA_ENABLED:
        return {"ok": False, "disabled": True, "status": "DISABLED", "config": config, "safety": safety}

    account_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/summary")
    trades_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openTrades")
    positions_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")

    ok = bool(account_resp.get("ok")) and bool(trades_resp.get("ok")) and bool(positions_resp.get("ok"))
    status = "OK" if ok else "ERROR"

    account_summary = extract_oanda_account_summary(account_resp.get("data", {})) if account_resp.get("ok") else {}
    trades = []
    positions = []
    if trades_resp.get("ok"):
        trades = trades_resp.get("data", {}).get("trades", []) or []
    if positions_resp.get("ok"):
        positions = positions_resp.get("data", {}).get("positions", []) or []

    snapshot = {
        "ok": ok,
        "disabled": False,
        "status": status,
        "created_at_utc": now_utc_iso(),
        "config": config,
        "safety": safety,
        "account": account_summary,
        "open_trades_count": len(trades),
        "open_positions_count": len(positions),
        "open_trades": trades,
        "open_positions": positions,
        "responses": {
            "account_ok": account_resp.get("ok"),
            "account_status_code": account_resp.get("status_code"),
            "account_error": account_resp.get("error", ""),
            "trades_ok": trades_resp.get("ok"),
            "trades_status_code": trades_resp.get("status_code"),
            "trades_error": trades_resp.get("error", ""),
            "positions_ok": positions_resp.get("ok"),
            "positions_status_code": positions_resp.get("status_code"),
            "positions_error": positions_resp.get("error", ""),
        },
    }

    try:
        with get_conn() as conn:
            conn.execute("""
                INSERT INTO broker_snapshots (
                    created_at_utc, broker, environment, account_id, status,
                    balance, nav, unrealized_pl, margin_used, margin_available,
                    margin_closeout_percent, open_trade_count, open_position_count,
                    read_only, execution_enabled, kill_switch, raw_json
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                snapshot["created_at_utc"], "OANDA", OANDA_ENV, OANDA_ACCOUNT_ID, status,
                account_summary.get("balance"), account_summary.get("NAV"), account_summary.get("unrealizedPL"),
                account_summary.get("marginUsed"), account_summary.get("marginAvailable"),
                account_summary.get("marginCloseoutPercent"), len(trades), len(positions),
                "true" if BROKER_READ_ONLY else "false",
                "true" if BROKER_EXECUTION_ENABLED else "false",
                "true" if BROKER_KILL_SWITCH else "false",
                json.dumps(snapshot),
            ))
            conn.commit()
    except Exception as e:
        snapshot["snapshot_insert_error"] = str(e)

    return snapshot



