            ("executed_bank_pnl_approx", "REAL"), ("risk_per_trade", "REAL"),
            ("high_water_pnl", "REAL"), ("high_water_r", "REAL"), ("status", "TEXT"),
            ("selected_trade_ids", "TEXT"), ("selected_broker_trade_ids", "TEXT"),
            ("response_status_code", "INTEGER"), ("reason", "TEXT"), ("raw_json", "TEXT"),
