# v10.0.96 - TEMPORARY GAP-SL EXTENSION RESEARCH (RESEARCH ONLY)
# ============================================================

def _gap_sl_future_signal_rows(
    conn: sqlite3.Connection,
    asset: str,
    trigger_raw_signal_id: int,
    limit: int = 60,
) -> List[sqlite3.Row]:
    variants = index_asset_pair_variants(asset)
    if not variants:
        return []
    placeholders = ",".join(["?"] * len(variants))
    return conn.execute(f"""
        SELECT id, timestamp_readable, exec_close, exec_low
        FROM raw_signals
        WHERE UPPER(pair) IN ({placeholders})
          AND id > ?
          AND exec_close IS NOT NULL
          AND UPPER(COALESCE(model_version,'')) != 'RESEARCH_MULTI_CTX_1H'
        ORDER BY id ASC
        LIMIT ?
    """, tuple([v.upper() for v in variants] + [int(trigger_raw_signal_id or 0), int(limit)])).fetchall()


def record_gap_sl_extension_research_trigger(
    conn: sqlite3.Connection,
    trade: sqlite3.Row,
    signal: sqlite3.Row,
    hold_candles: int,
    current_low: Optional[float],
    current_close: Optional[float],
) -> Dict[str, Any]:
    """Record a research cohort when the LIVE 1.5% hard SL is touched in gap watch.

    This never changes the live stop. It only asks whether hypothetical 2.0% or
    2.5% temporary gap-window stops would have survived and what happened later.
    """
    asset = safe_str(trade["asset"]).upper()
    signal_time = safe_str(signal["timestamp_readable"])
    if not is_index_asset(asset) or not is_sunday_monday_gap_watch_window(signal_time):
        return {"ok": True, "skipped": True, "reason": "outside_index_gap_watch", "research_only": True}

    entry = safe_float(trade["entry_price"])
    low = safe_float(current_low)
    close = safe_float(current_close)
    if entry is None or entry <= 0 or low is None:
        return {"ok": False, "skipped": True, "reason": "missing_entry_or_low", "research_only": True}

    normal_pct = float(get_cfg(asset).get("sl_pct", JUNE_FULL_DEMO_INDEX_SL_PCT))
    normal_price = entry * (1.0 - normal_pct / 100.0)
    if low > normal_price:
        return {"ok": True, "skipped": True, "reason": "normal_hard_sl_not_hit", "research_only": True}

    temp2_pct = float(GAP_SL_EXTENSION_RESEARCH_PCTS[0])
    temp25_pct = float(GAP_SL_EXTENSION_RESEARCH_PCTS[1])
    temp2_price = entry * (1.0 - temp2_pct / 100.0)
    temp25_price = entry * (1.0 - temp25_pct / 100.0)

    conn.execute("""
        INSERT OR IGNORE INTO gap_sl_extension_research (
            created_at_utc, updated_at_utc, trigger_raw_signal_id, trade_id, asset,
            entry_time, entry_price, trigger_signal_time, trigger_hold_candles,
            trigger_candle_low, trigger_candle_close,
            normal_sl_pct, normal_sl_price, normal_sl_hit,
            temp_2_sl_pct, temp_2_sl_price, temp_2_sl_hit_on_trigger,
            temp_25_sl_pct, temp_25_sl_price, temp_25_sl_hit_on_trigger,
            live_rule, research_note, completed_48
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
    """, (
        now_utc_iso(), now_utc_iso(), int(signal["id"]), safe_str(trade["trade_id"]), asset,
        safe_str(trade["entry_time"]), entry, signal_time, int(hold_candles or 0),
        low, close, normal_pct, normal_price, 1,
        temp2_pct, temp2_price, 1 if low <= temp2_price else 0,
        temp25_pct, temp25_price, 1 if low <= temp25_price else 0,
        "LIVE_1.5PCT_HARD_SL_UNCHANGED",
        "Research only: compare live 1.5% stop with hypothetical 2.0%/2.5% temporary gap-window stops and later recovery.",
    ))
    return {
        "ok": True,
        "recorded": True,
        "trade_id": safe_str(trade["trade_id"]),
        "asset": asset,
        "normal_sl_hit": True,
        "temp_2_sl_hit_on_trigger": low <= temp2_price,
        "temp_25_sl_hit_on_trigger": low <= temp25_price,
        "research_only": True,
    }


def update_gap_sl_extension_research_outcomes(conn: sqlite3.Connection, limit: int = 250) -> Dict[str, Any]:
    rows = [dict(r) for r in conn.execute("""
        SELECT * FROM gap_sl_extension_research
        WHERE COALESCE(completed_48,0)=0
        ORDER BY id ASC
        LIMIT ?
    """, (int(limit),)).fetchall()]
    updated = 0
    for r in rows:
        asset = safe_str(r.get("asset")).upper()
        trigger_id = int(r.get("trigger_raw_signal_id") or 0)
        entry = safe_float(r.get("entry_price"))
        if asset not in {"NAS100", "US500"} or trigger_id <= 0 or entry is None or entry <= 0:
            continue
        future = _gap_sl_future_signal_rows(conn, asset, trigger_id, max(GAP_SL_EXTENSION_RESEARCH_HORIZONS) + 5)
        if not future:
            continue
        temp2_price = safe_float(r.get("temp_2_sl_price"))
        temp25_price = safe_float(r.get("temp_25_sl_price"))
        sets: List[str] = []
        vals: List[Any] = []
        for h in GAP_SL_EXTENSION_RESEARCH_HORIZONS:
            if len(future) < h or safe_str(r.get(f"outcome_{h}_signal_time")):
                continue
            horizon_row = future[h - 1]
            horizon_close = safe_float(horizon_row["exec_close"])
            lows = [safe_float(x["exec_low"]) for x in future[:h]]
            lows = [float(x) for x in lows if x is not None]
            if horizon_close is None:
                continue
            min_low = min(lows) if lows else None
            return_pct = (horizon_close / entry - 1.0) * 100.0
            prefix = f"outcome_{h}"
            sets.extend([
                f"{prefix}_signal_time=?", f"{prefix}_close=?", f"{prefix}_return_pct=?",
                f"{prefix}_min_low=?", f"{prefix}_temp_2_sl_hit=?",
                f"{prefix}_temp_25_sl_hit=?", f"{prefix}_recovered_above_entry=?",
            ])
            vals.extend([
                safe_str(horizon_row["timestamp_readable"]), horizon_close, return_pct, min_low,
                1 if (min_low is not None and temp2_price is not None and min_low <= temp2_price) else 0,
                1 if (min_low is not None and temp25_price is not None and min_low <= temp25_price) else 0,
                1 if horizon_close >= entry else 0,
            ])
            if h == 48:
                sets.append("completed_48=?")
                vals.append(1)
        if sets:
            sets.append("updated_at_utc=?")
            vals.append(now_utc_iso())
            vals.append(int(r.get("id")))
            conn.execute(f"UPDATE gap_sl_extension_research SET {', '.join(sets)} WHERE id=?", tuple(vals))
            updated += 1
    return {"ok": True, "checked": len(rows), "updated": updated, "research_only": True}


def record_gap_sl_extension_research_for_raw_signal(raw_signal_id: int) -> Dict[str, Any]:
    raw_signal_id = int(raw_signal_id or 0)
    if raw_signal_id <= 0:
        return {"ok": False, "reason": "invalid_raw_signal_id", "research_only": True}
    with get_conn() as conn:
        row = conn.execute("SELECT id, pair FROM raw_signals WHERE id=? LIMIT 1", (raw_signal_id,)).fetchone()
        if not row:
            return {"ok": False, "reason": "raw_signal_not_found", "research_only": True}
        asset = normalise_index_asset(row["pair"])
        if asset not in {"NAS100", "US500"}:
            return {"ok": True, "skipped": True, "reason": "non_index_asset", "research_only": True}
        out = update_gap_sl_extension_research_outcomes(conn)
        conn.commit()
    return {"ok": True, "asset": asset, "outcomes": out, "research_only": True}


def gap_sl_extension_research_snapshot(limit: int = 100) -> Dict[str, Any]:
    init_db()
    with get_conn() as conn:
        try:
            update_gap_sl_extension_research_outcomes(conn)
            conn.commit()
        except Exception:
            pass
        rows = [dict(r) for r in conn.execute(
            "SELECT * FROM gap_sl_extension_research ORDER BY id DESC LIMIT ?", (int(limit),)
        ).fetchall()]
        summary = [dict(r) for r in conn.execute("""
            SELECT asset,
                   COUNT(*) AS triggers,
                   AVG(CASE WHEN temp_2_sl_hit_on_trigger=0 THEN 1.0 ELSE 0.0 END) AS temp_2_survival_trigger_rate,
                   AVG(CASE WHEN temp_25_sl_hit_on_trigger=0 THEN 1.0 ELSE 0.0 END) AS temp_25_survival_trigger_rate,
                   AVG(outcome_12_return_pct) AS avg_12h_return_pct,
                   AVG(outcome_24_return_pct) AS avg_24h_return_pct,
                   AVG(outcome_48_return_pct) AS avg_48h_return_pct,
                   AVG(outcome_24_recovered_above_entry) AS recovered_above_entry_24_rate,
                   AVG(outcome_48_recovered_above_entry) AS recovered_above_entry_48_rate
            FROM gap_sl_extension_research
            GROUP BY asset
            ORDER BY asset
        """).fetchall()]
    return {
        "status": "ok",
        "research_only": True,
        "live_hard_sl_unchanged": True,
        "temporary_sl_tests": GAP_SL_EXTENSION_RESEARCH_PCTS,
        "horizons": GAP_SL_EXTENSION_RESEARCH_HORIZONS,
        "summary": summary,
        "rows": rows,
        "time_utc": now_utc_iso(),
    }


