def broker_shadow_auto_can_execute(asset: str = "") -> Tuple[bool, str]:
    a = safe_str(asset).upper()
    if not BROKER_SHADOW_AUTO_EXECUTION_ENABLED:
        return False, "BROKER_SHADOW_AUTO_EXECUTION_ENABLED is false"
    if safe_str(OANDA_ENV).lower() not in {"practice", "live"}:
        return False, f"shadow auto execution unsupported OANDA_ENV={OANDA_ENV}"
    if not OANDA_ENABLED:
        return False, "OANDA_ENABLED is false"
    safety = oanda_safety_state()
    if not safety.get("orders_allowed"):
        return False, safe_str(safety.get("reason") or "OANDA orders not allowed")
    if JUNE_FULL_DEMO_ENABLED and a:
        if is_research_only_asset(a):
            return False, f"asset {a} is RESEARCH_ONLY for {JUNE_FULL_DEMO_NAME}; broker promotion disabled"
        if not is_june_full_demo_broker_asset(a):
            return False, f"asset {a} is outside {JUNE_FULL_DEMO_NAME} broker scope {sorted(JUNE_FULL_DEMO_BROKER_ASSETS)}"
    if a and a not in BROKER_SHADOW_AUTO_ALLOWED_ASSETS:
        return False, f"asset {a} not in BROKER_SHADOW_AUTO_ALLOWED_ASSETS"
    with get_conn() as c:
        active = c.execute("""
            SELECT COUNT(*) AS c
            FROM broker_trade_links
            WHERE status IN ('OPEN','CLOSE_SENT')
              AND mode = 'shadow_demo_auto'
        """).fetchone()["c"]
    if int(active or 0) >= int(BROKER_SHADOW_AUTO_MAX_OPEN_LINKS):
        return False, f"open auto broker links {active} >= BROKER_SHADOW_AUTO_MAX_OPEN_LINKS {BROKER_SHADOW_AUTO_MAX_OPEN_LINKS}"
    return True, "ok"






BROKER_OPEN_INTENT_ACTIVE_STATUSES = {
    "QUEUED_AUTO_SHADOW",
    "WAITING_PRICE_RETRY",
    "WAITING_MARKET_REOPEN",
    "WAITING_RECONCILIATION",
    "EXECUTION_PENDING",
    "QUEUED_DRY_RUN",
    "QUEUED_AUTO_CLOSE",
}

BROKER_OPEN_INTENT_TERMINAL_STATUSES = {
    "EXECUTED",
    "EXECUTED_AFTER_REOPEN",
    "CANCELLED",
    "CANCELLED_STALE_AFTER_REOPEN",
    "CANCELLED_DUPLICATE_LINK_EXISTS",
    "CANCELLED_DUPLICATE_OPEN_INTENT",
    "REVIEWED_NO_ACTION",
    "EXECUTION_FAILED",
    "AUTO_PREVIEW_FAILED",
    "EXECUTION_PREVIEW_ERROR",
}


def broker_shadow_open_link_exists(shadow_trade_id: str) -> Optional[Dict[str, Any]]:
    """Return an active broker link for this shadow trade, if one exists."""
    stid = safe_str(shadow_trade_id)
    if not stid:
        return None
    with get_conn() as conn:
        row = conn.execute("""
            SELECT * FROM broker_trade_links
            WHERE shadow_trade_id = ?
              AND mode = 'shadow_demo_auto'
              AND status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
            ORDER BY id DESC LIMIT 1
        """, (stid,)).fetchone()
    return dict(row) if row else None


def broker_shadow_open_intent_exists(shadow_trade_id: str) -> Optional[Dict[str, Any]]:
    """Return an active queued/retry open intent for this shadow trade, if one exists.

    This is an idempotency guard. A WAITING_PRICE_RETRY or WAITING_MARKET_REOPEN
    row must block the scanner from creating another open for the same candle.
    """
    stid = safe_str(shadow_trade_id)
    if not stid:
        return None
    active = tuple(sorted(BROKER_OPEN_INTENT_ACTIVE_STATUSES))
    placeholders = ",".join(["?"] * len(active))
    with get_conn() as conn:
        row = conn.execute(f"""
            SELECT * FROM broker_action_queue
            WHERE shadow_trade_id = ?
              AND mode = 'shadow_demo_auto'
              AND action = 'place_risk_order'
              AND status IN ({placeholders})
            ORDER BY id ASC LIMIT 1
        """, (stid, *active)).fetchone()
    return dict(row) if row else None


def cancel_duplicate_open_queue_items(limit: int = 200) -> Dict[str, Any]:
    """Cancel queued open intents that are duplicates of an already-linked trade or another active intent.

    Safe cleanup for cases where price/market retry rows were left behind after a
    successful mirror order for the same shadow_trade_id.
    """
    init_db()
    try:
        limit = max(1, min(int(limit), 1000))
    except Exception:
        limit = 200
    active = tuple(sorted(BROKER_OPEN_INTENT_ACTIVE_STATUSES))
    placeholders = ",".join(["?"] * len(active))
    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute(f"""
            SELECT * FROM broker_action_queue
            WHERE mode = 'shadow_demo_auto'
              AND action = 'place_risk_order'
              AND status IN ({placeholders})
            ORDER BY id ASC
            LIMIT ?
        """, (*active, limit)).fetchall()]

    seen_shadow: set = set()
    cancelled = []
    kept = []
    for q in rows:
        qid = int(q.get("id") or 0)
        stid = safe_str(q.get("shadow_trade_id") or "")
        if not qid or not stid:
            continue
        link = broker_shadow_open_link_exists(stid)
        if link:
            update_broker_action_queue_status(qid, "CANCELLED_DUPLICATE_LINK_EXISTS", f"Cancelled because active broker link {link.get('id')} already exists for shadow_trade_id {stid}.", None, int(link.get("id") or 0))
            cancelled.append({"queue_id": qid, "shadow_trade_id": stid, "reason": "active broker link already exists", "broker_trade_link_id": link.get("id")})
            continue
        if stid in seen_shadow:
            update_broker_action_queue_status(qid, "CANCELLED_DUPLICATE_OPEN_INTENT", f"Cancelled duplicate active open intent for shadow_trade_id {stid}. Earlier active queue item kept.")
            cancelled.append({"queue_id": qid, "shadow_trade_id": stid, "reason": "duplicate active open intent"})
            continue
        seen_shadow.add(stid)
        kept.append({"queue_id": qid, "shadow_trade_id": stid, "status": q.get("status")})
    return {"status": "ok", "ok": True, "checked": len(rows), "cancelled": len(cancelled), "kept": kept, "cancelled_items": cancelled, "time_utc": now_utc_iso()}
def broker_shadow_auto_can_close() -> Tuple[bool, str]:
    """Safety gate for automatic demo closes.

    This deliberately does NOT enforce BROKER_SHADOW_AUTO_MAX_OPEN_LINKS.
    The max-open-links cap is only an entry throttle; it must never block exits.
    """
    if not BROKER_SHADOW_AUTO_CLOSE_ENABLED:
        return False, "BROKER_SHADOW_AUTO_CLOSE_ENABLED is false"
    if not BROKER_SHADOW_AUTO_EXECUTION_ENABLED:
        return False, "BROKER_SHADOW_AUTO_EXECUTION_ENABLED is false"
    if safe_str(OANDA_ENV).lower() not in {"practice", "live"}:
        return False, f"shadow auto close unsupported OANDA_ENV={OANDA_ENV}"
    if not OANDA_ENABLED:
        return False, "OANDA_ENABLED is false"
    safety = oanda_safety_state()
    if not safety.get("orders_allowed"):
        return False, safe_str(safety.get("reason") or "OANDA orders not allowed")
    return True, "ok"

def broker_auto_execute_new_shadow_trade(trade_id: str, asset: str, from_current_signal_event: bool = False) -> Dict[str, Any]:
    """Demo-only automatic mirror from a newly-created Railway shadow trade to OANDA live account.

    v9.7 hotfix: this is now fresh-event gated. The normal allowed path is:
    TradingView webhook -> create_new_open_trade() returns a new trade_id ->
    process_shadow_manager() calls this function with from_current_signal_event=True.

    Scanner/manual calls are blocked by default so old shadow trades cannot be
    retroactively promoted when BROKER_SHADOW_AUTO_MAX_OPEN_LINKS is increased.
    """
    init_db()
    trade_id = safe_str(trade_id)
    asset = safe_str(asset).upper()

    if not from_current_signal_event and not BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL:
        return {
            "ok": False,
            "skipped": True,
            "reason": "fresh_arrivals_only: old/unlinked shadow trades are not eligible for broker promotion",
            "trade_id": trade_id,
            "asset": asset,
            "from_current_signal_event": bool(from_current_signal_event),
            "allow_open_scan_backfill": bool(BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL),
            "auto_status": broker_shadow_auto_status(),
        }

    can, reason = broker_shadow_auto_can_execute(asset)
    if not can:
        return {"ok": False, "skipped": True, "reason": reason, "trade_id": trade_id, "asset": asset, "auto_status": broker_shadow_auto_status()}

    with get_conn() as c:
        existing = c.execute("""
            SELECT * FROM broker_trade_links
            WHERE shadow_trade_id = ?
              AND status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
            ORDER BY id DESC LIMIT 1
        """, (trade_id,)).fetchone()
    if existing:
        return {"ok": False, "skipped": True, "reason": "broker link already exists for this shadow trade", "trade_id": trade_id, "existing_link_id": existing["id"]}

    # Idempotency guard: if a prior attempt is waiting for price/market retry,
    # do NOT create a second order for the same shadow trade/candle.
    existing_intent = broker_shadow_open_intent_exists(trade_id)
    if existing_intent:
        return {
            "ok": False, "skipped": True,
            "reason": "active broker open intent already exists for this shadow trade",
            "trade_id": trade_id, "existing_queue_id": existing_intent.get("id"),
            "existing_queue_status": existing_intent.get("status"),
        }

    cfg = get_cfg(asset)
    direction = safe_str(cfg.get("direction") or "long").lower()
    side = "buy" if direction != "short" else "sell"
    instrument = normalise_oanda_instrument(asset)
    family = get_basket_family(asset)
    risk_amount = effective_broker_shadow_auto_risk_amount_for_asset(asset)

    preview = build_risk_order_preview_with_immediate_retries(
        instrument=instrument,
        side=side,
        risk_amount=risk_amount,
        sl_pct=effective_broker_auto_sl_pct(asset),
    )
    if not preview.get("ok"):
        initial_status = "WAITING_PRICE_RETRY" if BROKER_SHADOW_AUTO_PREVIEW_RETRY_ENABLED else "AUTO_PREVIEW_FAILED"
        qid = create_broker_action_queue_item(
            action="place_risk_order", instrument=instrument, side=side, shadow_trade_id=trade_id,
            shadow_asset=asset, family=family, risk_amount=risk_amount,
            sl_pct=effective_broker_auto_sl_pct(asset), reason=preview_failure_summary(preview),
            preview=preview, mode="shadow_demo_auto", source="shadow_manager", status=initial_status,
            notes=(
                f"{preview_failure_summary(preview)}; immediate_attempts={safe_str(preview.get('preview_attempts') or '')}; will retry for up to {BROKER_SHADOW_AUTO_PREVIEW_RETRY_MAX_SECONDS}s"
                if initial_status == "WAITING_PRICE_RETRY"
                else preview_failure_summary(preview)
            ),
        )
        if initial_status == "WAITING_PRICE_RETRY":
            mark_queue_waiting_price_retry(qid, preview, "Initial preview failed; queued for short retry window")
        else:
            try:
                with get_conn() as _miss_conn:
                    close_shadow_trade_as_broker_missed(_miss_conn, trade_id, "broker_entry_missed_initial_preview_failed")
                    _miss_conn.commit()
            except Exception as _e:
                log_system_event("broker_entry_missed_shadow_close_failed", f"Failed to close initial preview-missed shadow {trade_id}: {_e}")
        log_execution_audit_event("shadow_demo_auto", instrument, trade_id, "auto_place_risk_order_preview", False, preview_failure_summary(preview), raw=preview)
        return {"ok": False, "queue_id": qid, "retrying": initial_status == "WAITING_PRICE_RETRY", "error": preview_failure_summary(preview), "preview": preview}

    qid = create_broker_action_queue_item(
        action="place_risk_order", instrument=instrument, side=side, shadow_trade_id=trade_id,
        shadow_asset=asset, family=family, risk_amount=safe_float(preview.get("risk_amount_requested")),
        sl_pct=safe_float(preview.get("sl_pct")), requested_units=safe_float(preview.get("signed_units")),
        estimated_risk=safe_float(preview.get("estimated_risk_amount")), preview_price=safe_float(preview.get("current_mid_price")),
        reason="auto broker mirror from fresh signal", preview=preview, mode="shadow_demo_auto", source="shadow_manager",
        status="QUEUED_AUTO_SHADOW", notes="Auto-created from fresh TradingView signal/new Railway shadow trade. Practice/live-controlled.",
    )

    if not BROKER_SHADOW_AUTO_EXECUTE_QUEUED:
        return {"ok": True, "queued_only": True, "queue_id": qid, "trade_id": trade_id, "asset": asset, "preview": preview}

    order_body = {
        "order": {
            "type": "MARKET",
            "instrument": preview["instrument"],
            "units": str(preview["signed_units"]),
            "timeInForce": "FOK",
            "positionFill": "DEFAULT",
        }
    }
    # v10.0.98 BCO safety: submit an immediate 3.5% emergency stop with the
    # market order, then rebase it to the actual broker fill after execution.
    # This prevents a fast oil reversal leaving a fresh demo trade unprotected.
    if asset == "BCOUSD":
        preview_stop = safe_float(preview.get("estimated_stop_price"))
        if preview_stop is not None and preview_stop > 0:
            rounded_preview_stop = managed_stop_round_price(preview["instrument"], preview_stop)
            order_body["order"]["stopLossOnFill"] = {"price": str(rounded_preview_stop)}

    # Final idempotency check immediately before sending the broker order.
    # This protects against overlapping scans/webhooks and against a timeout from a
    # prior attempt being reconciled while this request was being built.
    existing_link_before_send = broker_shadow_open_link_exists(trade_id)
    if existing_link_before_send:
        update_broker_action_queue_status(qid, "CANCELLED_DUPLICATE_LINK_EXISTS", f"Pre-send cancelled because active broker link {existing_link_before_send.get('id')} already exists for shadow_trade_id {trade_id}.", None, int(existing_link_before_send.get("id") or 0))
        return {"ok": False, "skipped": True, "cancelled": True, "reason": "broker link already exists before send", "trade_id": trade_id, "queue_id": qid, "existing_link_id": existing_link_before_send.get("id")}
    existing_intent_before_send = broker_shadow_open_intent_exists(trade_id)
    if existing_intent_before_send and int(existing_intent_before_send.get("id") or 0) != int(qid):
        update_broker_action_queue_status(qid, "CANCELLED_DUPLICATE_OPEN_INTENT", f"Pre-send cancelled because active queue item {existing_intent_before_send.get('id')} already exists for shadow_trade_id {trade_id}.")
        return {"ok": False, "skipped": True, "cancelled": True, "reason": "active queue intent already exists before send", "trade_id": trade_id, "queue_id": qid, "existing_queue_id": existing_intent_before_send.get("id"), "existing_queue_status": existing_intent_before_send.get("status")}

    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/orders", "POST", order_body)
    details = extract_oanda_execution_details(resp)
    broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
    success = oanda_open_order_was_filled(resp, details)
    audit_id = log_execution_audit_event(
        "shadow_demo_auto", preview["instrument"], trade_id, "auto_execute_shadow_place_risk_order",
        success, f"auto demo execution from shadow trade {trade_id} queue {qid}", broker_order_id,
        raw={"queue_id": qid, "preview": preview, "request": order_body, "response": resp},
        intended_price=safe_float(preview.get("current_mid_price")), actual_price=details.get("actual_price"),
        spread_pct=safe_float(preview.get("spread_pct")),
        side=safe_str(preview.get("side")), requested_units=safe_float(preview.get("signed_units")),
        filled_units=details.get("filled_units"), risk_amount=safe_float(preview.get("risk_amount_requested")),
        sl_pct=safe_float(preview.get("sl_pct")), estimated_risk=safe_float(preview.get("estimated_risk_amount")),
        broker_trade_id=details.get("broker_trade_id", ""), response_status_code=details.get("response_status_code"),
    )
    link_id = None
    initial_stop_result: Dict[str, Any] = {}
    if success:
        link_id = create_broker_trade_link(
            source="shadow_manager_auto", mode="shadow_demo_auto",
            shadow_trade_id=trade_id, shadow_asset=asset, shadow_trade_ref=f"broker_action_queue_id={qid}",
            instrument=preview["instrument"], side=side,
            requested_units=safe_float(preview.get("signed_units")), filled_units=details.get("filled_units"),
            broker_order_id=broker_order_id, broker_trade_id=details.get("broker_trade_id", ""),
            source_audit_id=audit_id, status="OPEN", last_known_price=details.get("actual_price"),
            notes="Auto mirror of Railway shadow trade. BCO uses immediate fill-rebased emergency stop.", raw={"queue_id": qid, "preview": preview, "response": resp},
        )

        if asset == "BCOUSD":
            broker_trade_id = safe_str(details.get("broker_trade_id", ""))
            fill_price = safe_float(details.get("actual_price")) or safe_float(preview.get("current_mid_price"))
            sl_pct_value = float(effective_broker_auto_sl_pct(asset))
            fill_rebased_stop = None
            if broker_trade_id and fill_price is not None and fill_price > 0:
                if side == "buy":
                    fill_rebased_stop = fill_price * (1.0 - sl_pct_value / 100.0)
                else:
                    fill_rebased_stop = fill_price * (1.0 + sl_pct_value / 100.0)
                fill_rebased_stop = managed_stop_round_price(preview["instrument"], fill_rebased_stop)
                stop_resp = oanda_set_trade_stop_loss(broker_trade_id, fill_rebased_stop, preview["instrument"])
                stop_ok = bool(stop_resp.get("ok"))
                initial_stop_result = {
                    "ok": stop_ok,
                    "broker_trade_id": broker_trade_id,
                    "fill_price": fill_price,
                    "sl_pct": sl_pct_value,
                    "fill_rebased_stop_price": fill_rebased_stop,
                    "response": stop_resp,
                }
                try:
                    insert_managed_stop_event(
                        link_id, trade_id, preview["instrument"], broker_trade_id,
                        "initial_emergency_stop_rebase", "SET" if stop_ok else "FAILED",
                        "ENTRY_3_5PCT_EMERGENCY", side, 0,
                        details.get("filled_units"), fill_price, fill_price,
                        safe_float(preview.get("estimated_stop_price")), fill_rebased_stop,
                        None, None, stop_resp.get("status_code"),
                        "BCO entry stop rebased to actual OANDA fill.",
                        {"preview": preview, "order_response": resp, "stop_response": stop_resp},
                    )
                except Exception as stop_event_error:
                    initial_stop_result["event_log_error"] = safe_str(stop_event_error)
                if not stop_ok:
                    log_system_event(
                        "bco_initial_emergency_stop_rebase_failed",
                        f"trade_id={trade_id}; broker_trade_id={broker_trade_id}; stop={fill_rebased_stop}; response={safe_str(stop_resp)[:1200]}",
                    )
            else:
                initial_stop_result = {
                    "ok": False,
                    "reason": "missing broker trade id or fill price for BCO stop rebase",
                    "broker_trade_id": broker_trade_id,
                    "fill_price": fill_price,
                }
                log_system_event(
                    "bco_initial_emergency_stop_rebase_missing_fill",
                    f"trade_id={trade_id}; broker_trade_id={broker_trade_id}; fill_price={fill_price}",
                )

        queue_note = "Auto broker order executed"
        if asset == "BCOUSD":
            queue_note += f"; initial_stop_ok={bool(initial_stop_result.get('ok'))}; fill_rebased_stop={safe_str(initial_stop_result.get('fill_rebased_stop_price'))}"
        update_broker_action_queue_status(qid, "EXECUTED", queue_note, audit_id, link_id)
    else:
        if is_oanda_market_closed_response(resp):
            mark_queue_waiting_market_reopen(qid, resp, audit_id, None)
        elif is_oanda_timeout_or_unknown_response(resp):
            mark_queue_waiting_reconciliation(qid, resp, audit_id, None)
        else:
            update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or "OANDA order failed"), audit_id, None)
    return {"ok": success, "queue_id": qid, "audit_id": audit_id, "broker_trade_link_id": link_id, "broker_order_id": broker_order_id, "broker_trade_id": details.get("broker_trade_id", ""), "initial_stop_result": initial_stop_result, "waiting_market_reopen": (not success and is_oanda_market_closed_response(resp)), "response": resp}


def broker_auto_close_closed_shadow_links() -> Dict[str, Any]:
    """Demo-only automatic broker close when a linked shadow trade is no longer open."""
    init_db()
    if not (BROKER_SHADOW_AUTO_EXECUTION_ENABLED and BROKER_SHADOW_AUTO_CLOSE_ENABLED):
        return {"ok": True, "skipped": True, "reason": "auto execution/close disabled", "auto_status": broker_shadow_auto_status()}
    can, reason = broker_shadow_auto_can_close()
    if not can:
        return {"ok": False, "skipped": True, "reason": reason, "auto_status": broker_shadow_auto_status()}

    with get_conn() as c:
        rows = c.execute("""
            SELECT l.*
            FROM broker_trade_links l
            LEFT JOIN open_trades o ON o.trade_id = l.shadow_trade_id AND o.status = 'open'
            WHERE l.mode = 'shadow_demo_auto'
              AND l.status = 'OPEN'
              AND o.trade_id IS NULL
            ORDER BY l.id ASC
            LIMIT 20
        """).fetchall()
    results = []
    for row in rows:
        link = dict(row)
        broker_trade_id = safe_str(link.get("broker_trade_id") or "")
        if not broker_trade_id:
            results.append({"link_id": link.get("id"), "ok": False, "error": "missing broker_trade_id"})
            continue
        qid = create_broker_action_queue_item(
            action="close_linked_trade", instrument=normalise_oanda_instrument(link.get("instrument") or ""), side=safe_str(link.get("side") or ""),
            shadow_trade_id=safe_str(link.get("shadow_trade_id") or ""), shadow_asset=safe_str(link.get("shadow_asset") or ""),
            family=get_basket_family(safe_str(link.get("shadow_asset") or "")), requested_units=safe_float(link.get("filled_units")),
            reason="auto broker close: shadow trade no longer open", preview={"broker_trade_link_id": link.get("id"), "broker_trade_id": broker_trade_id},
            mode="shadow_demo_auto", source="shadow_manager", status="QUEUED_AUTO_CLOSE", notes="Auto close generated because linked Railway shadow trade is closed/missing.",
        )
        with get_conn() as c:
            c.execute("UPDATE broker_action_queue SET broker_trade_link_id = ? WHERE id = ?", (int(link.get("id")), qid))
            c.commit()
        close_body = {"units": "ALL"}
        resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
        details = extract_oanda_execution_details(resp)
        broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
        success = bool(resp.get("ok"))
        audit_id = log_execution_audit_event(
            "shadow_demo_auto", normalise_oanda_instrument(link.get("instrument") or ""), safe_str(link.get("shadow_trade_id") or ""), "auto_close_linked_trade",
            success, f"auto close linked trade because shadow trade closed; queue {qid}", broker_order_id,
            raw={"queue_id": qid, "broker_trade_link": link, "request": close_body, "response": resp},
            side=safe_str(link.get("side") or ""), close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
            broker_trade_id=broker_trade_id, response_status_code=details.get("response_status_code"),
        )
        if success:
            now_closed = now_utc_iso()
            with get_conn() as c:
                c.execute("""
                    UPDATE broker_trade_links
                    SET updated_at_utc=?, status='CLOSE_SENT', closed_at_utc=COALESCE(NULLIF(closed_at_utc,''), ?),
                        last_reconciled_at_utc=?, notes=?
                    WHERE id=?
                """, (now_closed, now_closed, now_closed, f"Auto close sent from broker_action_queue id {qid}", int(link.get("id"))))
                c.commit()
            update_broker_action_queue_status(qid, "EXECUTED", "Auto linked close executed", audit_id, int(link.get("id")))
        else:
            if is_oanda_market_closed_response(resp):
                mark_queue_waiting_market_reopen(qid, resp, audit_id, int(link.get("id")))
            else:
                update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or "OANDA close failed"), audit_id, int(link.get("id")))
        results.append({"link_id": link.get("id"), "queue_id": qid, "ok": success, "waiting_market_reopen": (not success and is_oanda_market_closed_response(resp)), "broker_trade_id": broker_trade_id, "response_status_code": details.get("response_status_code")})
    if results:
        try:
            reconcile_broker_trade_links()
        except Exception:
            pass
    return {"ok": True, "checked": True, "closed_count": sum(1 for r in results if r.get("ok")), "results": results, "time_utc": now_utc_iso()}

def live_demo_action_blocks_new_entry(action: Any) -> bool:
    """True when a raw action word implies entries may need to be blocked.

    v10.0.24 note: this is now only the raw semantic test. The final live
    decision is made by live_demo_should_block_new_entry(), which stages entry
    blocking by broker-confirmed basket size so young baskets are not starved.
    """
    a = safe_str(action).upper()
    if not a:
        return False
    if "CONTINUE_STACKING_CAUTION" in a:
        return False
    block_terms = [
        "PAUSE", "NO_NEW", "STOP_STACK", "REDUCE", "TRIM",
        "CLOSE", "DEFENCE", "DEFENSE", "HARVEST",
    ]
    return any(term in a for term in block_terms)


def count_live_demo_active_broker_links_for_asset(conn: sqlite3.Connection, asset: str) -> int:
    """Broker-confirmed open/pending linked exposure count for an asset.

    Entry blocking must be based on actual broker-confirmed live exposure,
    not raw shadow rows. Failed/missed broker entries must not make the manager
    think the live basket is larger than it really is.
    """
    a = safe_str(asset).upper()
    row = conn.execute("""
        SELECT COUNT(*) AS c
        FROM broker_trade_links
        WHERE UPPER(COALESCE(shadow_asset,'')) = ?
          AND mode = 'shadow_demo_auto'
          AND UPPER(COALESCE(status,'')) IN ('OPEN','LINKED','PENDING')
    """, (a,)).fetchone()
    return int(row["c"] if row else 0)


def live_demo_should_block_new_entry(
    conn: sqlite3.Connection,
    asset: str,
    action: Any,
    tide_result: Optional[Dict[str, Any]],
) -> Tuple[bool, str, Dict[str, Any]]:
    """Staged live entry-block decision.

    A young basket can flash RED/CRITICAL simply because every early trade is a
    small loser. That is not enough evidence to starve the basket. This function
    allows true fresh signals through until the basket is sufficiently developed,
    unless damage is already severe.
    """
    action_txt = safe_str(action)

    # v10.0.96: gap-watch stacking block is explicit and must not be bypassed by
    # the normal tiny/early-basket allowances. It only applies when an existing
    # index basket is active; a completely flat basket has no tide_result here.
    gap_meta = (tide_result or {}).get("gap_watch") or {}
    if bool(gap_meta.get("entry_block")):
        live_open_count = count_live_demo_active_broker_links_for_asset(conn, asset)
        meta = {
            "action": action_txt,
            "asset": safe_str(asset).upper(),
            "live_open_count": live_open_count,
            "stage": basket_execution_stage(live_open_count).get("stage"),
            "status": safe_str((tide_result or {}).get("tide_status")).upper(),
            "basket_R": safe_float((tide_result or {}).get("open_basket_R")) or 0.0,
            "gap_watch": gap_meta,
        }
        return True, "gap_watch_blocks_new_stacking", meta

    if not live_demo_action_blocks_new_entry(action_txt):
        return False, "action_does_not_block_entries", {"action": action_txt}

    live_open_count = count_live_demo_active_broker_links_for_asset(conn, asset)
    min_entry_block = max(1, int(JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_ENTRY_BLOCK))
    min_strict_block = max(min_entry_block, int(JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_STRICT_ENTRY_BLOCK))
    basket_r = safe_float((tide_result or {}).get("open_basket_R"))
    if basket_r is None:
        basket_r = safe_float((tide_result or {}).get("basket_R"))
    basket_r_val = float(basket_r or 0.0)
    status = safe_str((tide_result or {}).get("tide_status") or (tide_result or {}).get("status")).upper()
    stage = basket_execution_stage(live_open_count)

    meta = {
        "action": action_txt,
        "asset": safe_str(asset).upper(),
        "live_open_count": live_open_count,
        "stage": stage.get("stage"),
        "status": status,
        "basket_R": basket_r_val,
        "min_entry_block": min_entry_block,
        "min_strict_block": min_strict_block,
        "tiny_severe_R": JUNE_FULL_DEMO_ENTRY_BLOCK_TINY_SEVERE_R,
        "early_severe_R": JUNE_FULL_DEMO_ENTRY_BLOCK_EARLY_SEVERE_R,
    }

    # 1-9 by default: do not starve a basket that barely exists. Only block if
    # the current broker-confirmed basket is already in severe realised-model damage.
    if live_open_count < min_entry_block:
        if basket_r_val <= float(JUNE_FULL_DEMO_ENTRY_BLOCK_TINY_SEVERE_R):
            return True, "tiny_basket_severe_R_entry_block", meta
        return False, "tiny_basket_entry_block_bypassed_allow_development", meta

    # 10-24: early basket. It can pause only if the current damage is materially
    # worse than normal early noise. A fresh true signal should usually still be allowed.
    if live_open_count < min_strict_block:
        if status in {"RED", "CRITICAL"} and basket_r_val <= float(JUNE_FULL_DEMO_ENTRY_BLOCK_EARLY_SEVERE_R):
            return True, "early_basket_severe_R_entry_block", meta
        return False, "early_basket_entry_block_bypassed_allow_development", meta

    # 25+: developed enough to let normal basket pause/defence block entries.
    return True, "strict_basket_entry_block", meta


def execute_live_demo_basket_manager_action(
    conn: sqlite3.Connection,
    asset: str,
    latest_signal_time: str,
    latest_price: Optional[float],
    tide_result: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Execute index basket-manager actions in the baseline open_trades model.

    The previous implementation logged tiered defence as advice/research only.
    In Live Index Trading live mode, NAS100/US500 should act like the intended
    live system: close the weakest baseline trades when the tiered action implies
    a partial/full basket close. Broker auto-close then closes the linked OANDA
    practice trades after the DB transaction commits.
    """
    asset = safe_str(asset).upper()
    if not JUNE_FULL_DEMO_ENABLED or not JUNE_FULL_DEMO_EXECUTE_BASKET_MANAGER:
        return {"ok": True, "skipped": True, "reason": "live_basket_execution_disabled"}
    if not is_june_full_demo_broker_asset(asset):
        return {"ok": True, "skipped": True, "reason": f"asset {asset} outside live broker scope"}
    if is_research_only_asset(asset):
        return {"ok": True, "skipped": True, "reason": f"asset {asset} is research-only"}
    if not tide_result:
        return {"ok": True, "skipped": True, "reason": "no_tide_result"}

    # v10.0.96 defence-in-depth: even if an old/raw close label somehow reaches
    # the executor, the live gap-watch decision can veto the basket-manager close.
    gap_meta = tide_result.get("gap_watch") or live_gap_watch_override_decision(
        asset=asset,
        latest_signal_time=latest_signal_time,
        tide_status=tide_result.get("tide_status"),
        original_action=tide_result.get("original_tiered_action") or tide_result.get("tiered_action") or tide_result.get("shadow_action"),
        original_detail=tide_result.get("original_tiered_detail") or tide_result.get("tiered_detail"),
        open_count=tide_result.get("open_trades"),
        open_basket_R=tide_result.get("open_basket_R"),
        losing_pct=tide_result.get("losing_trade_pct"),
        basket_giveback_pct=tide_result.get("basket_giveback_pct"),
    )
    if bool(gap_meta.get("suppress_basket_closes")):
        msg = (
            f"asset={asset}; signal_time={latest_signal_time}; gap_watch_override=true; "
            f"original_action={safe_str(gap_meta.get('original_action'))}; "
            f"effective_action={safe_str(gap_meta.get('effective_action'))}; "
            f"basket_R={safe_str(gap_meta.get('open_basket_R'))}; hard_sl_unchanged=true"
        )
        conn.execute("INSERT INTO system_events (created_at_utc, event_type, message) VALUES (?, ?, ?)",
                     (now_utc_iso(), "live_basket_manager_close_suppressed_gap_watch", msg[:4000]))
        return {
            "ok": True,
            "skipped": True,
            "reason": "gap_watch_suppressed_basket_manager_close",
            "gap_watch": gap_meta,
            "action": safe_str(gap_meta.get("effective_action")),
        }

    action = safe_str(tide_result.get("tiered_action") or tide_result.get("shadow_action") or "")
    close_fraction = suggested_close_fraction_from_action(action)
    if close_fraction <= 0:
        return {"ok": True, "skipped": True, "reason": "no_executable_close_fraction", "action": action}

    # Idempotency: only execute one basket-manager close action per asset/candle/action.
    event_type = "live_basket_manager_execute"
    existing = conn.execute("""
        SELECT id FROM system_events
        WHERE event_type = ?
          AND message LIKE ?
        LIMIT 1
    """, (event_type, f"%asset={asset}; signal_time={latest_signal_time}; action={action}%")).fetchone()
    if existing:
        return {"ok": True, "skipped": True, "reason": "already_executed_for_asset_candle_action", "action": action}

    open_rows = [dict(r) for r in conn.execute("""
        SELECT * FROM open_trades
        WHERE asset = ? AND status = 'open'
        ORDER BY return_pct ASC, entry_time ASC
    """, (asset,)).fetchall()]
    open_count = len(open_rows)
    if open_count <= 0:
        return {"ok": True, "skipped": True, "reason": "no_open_trades", "action": action}

    # v10.0.6 hard execution guard: scale basket-manager closes by basket size.
    # This prevents 10-trade baskets being treated like 100-trade baskets.
    # Trade-level emergency SL/normal exits remain independent; this only governs
    # basket-manager defensive trims/closes.
    stage = basket_execution_stage(open_count)
    max_allowed_fraction = float(stage.get("max_close_fraction") or 0.0)
    if max_allowed_fraction <= 0:
        msg = (
            f"asset={asset}; signal_time={latest_signal_time}; action={action}; "
            f"blocked_by_staged_basket_guard=true; open_count={open_count}; stage={stage.get('stage')}; "
            f"tide_status={safe_str(tide_result.get('tide_status'))}; basket_R={safe_str(tide_result.get('open_basket_R'))}"
        )
        conn.execute("""
            INSERT INTO system_events (created_at_utc, event_type, message)
            VALUES (?, ?, ?)
        """, (now_utc_iso(), "live_basket_manager_blocked_staged_guard", msg[:4000]))
        return {
            "ok": True,
            "skipped": True,
            "reason": "staged_basket_guard_blocked_executable_close",
            "action": action,
            "open_count": open_count,
            "stage": stage.get("stage"),
            "stage_description": stage.get("description"),
        }

    if close_fraction >= 1.0 and not bool(stage.get("full_close_eligible")):
        close_fraction = max_allowed_fraction
        action = action + f"__DOWNGRADED_TO_{int(max_allowed_fraction * 100)}PCT_BY_STAGED_FULL_CLOSE_GUARD"
    elif close_fraction > max_allowed_fraction:
        close_fraction = max_allowed_fraction
        action = action + f"__CAPPED_TO_{int(max_allowed_fraction * 100)}PCT_BY_STAGED_GUARD"

    close_count = open_count if close_fraction >= 1.0 else max(1, int(round(open_count * close_fraction)))
    close_count = min(close_count, open_count, max(1, int(JUNE_FULL_DEMO_MAX_BASKET_MANAGER_CLOSES_PER_CANDLE)))
    selected = open_rows[:close_count]
    closed_ids: List[str] = []

    for d in selected:
        # Convert to a Row-like object is not required: sqlite3.Row supports mapping,
        # but close_open_trade only uses named fields, so a tiny dict wrapper works.
        class _TradeDict(dict):
            def __getitem__(self, k):
                return self.get(k)
        t = _TradeDict(d)
        exit_price = safe_float(d.get("current_price")) or safe_float(d.get("entry_price")) or latest_price or 0.0
        close_open_trade(
            conn=conn,
            trade=t,
            exit_time=latest_signal_time,
            exit_price=float(exit_price),
            hold_candles=int(safe_float(d.get("hold_candles")) or 0),
            exit_reason=f"demo_live_basket_manager:{action}",
            return_pct=safe_float(d.get("return_pct")) or 0.0,
            mfe_pct=safe_float(d.get("mfe_pct")) or 0.0,
            mae_pct=safe_float(d.get("mae_pct")) or 0.0,
            highest_high=safe_float(d.get("highest_high")) or float(exit_price),
            lowest_low=safe_float(d.get("lowest_low")) or float(exit_price),
            sl_hit=False,
        )
        closed_ids.append(safe_str(d.get("trade_id")))

    msg = (
        f"asset={asset}; signal_time={latest_signal_time}; action={action}; "
        f"close_fraction={close_fraction}; closed_count={len(closed_ids)}; "
        f"open_count_before={open_count}; tide_status={safe_str(tide_result.get('tide_status'))}; "
        f"basket_R={safe_str(tide_result.get('open_basket_R'))}; closed_ids={','.join(closed_ids[:50])}"
    )
    conn.execute("""
        INSERT INTO system_events (created_at_utc, event_type, message)
        VALUES (?, ?, ?)
    """, (now_utc_iso(), event_type, msg[:4000]))

    return {
        "ok": True,
        "executed": True,
        "asset": asset,
        "signal_time": latest_signal_time,
        "action": action,
        "close_fraction": close_fraction,
        "open_count_before": open_count,
        "closed_count": len(closed_ids),
        "closed_trade_ids": closed_ids,
    }


def process_shadow_manager(new_signal_db_id: int) -> None:
    new_trade_id: Optional[str] = None
    asset = ""
    allow_new_entry = True
    demo_live_execution_result: Dict[str, Any] = {}

    with get_conn() as conn:
        signal = get_latest_raw_signal(conn, new_signal_db_id)
        if not signal:
            return

        asset = safe_str(signal["pair"]).upper()
        if asset not in CONFIG or not CONFIG[asset]["enabled"]:
            return

        run_entry_confirmation_check(conn, signal)

        open_trades = get_open_trades_for_asset(conn, asset)
        for trade in open_trades:
            update_single_open_trade(conn, trade, signal)

        # Separate post-48 dynamic uncapped exit shadow model remains research-only;
        # the baseline open_trades manager is what drives live broker mirroring.
        update_dynamic_exit_shadow_trades(conn, signal)

        run_24h_basket_risk_check(conn, asset)
        tide_result = run_tide_turn_check(conn, asset)
        update_advice_outcome_audit(conn, asset, safe_str(signal["timestamp_readable"]))

        # v10.0.3: June live mode.
        # Execute basket-manager defensive close actions on baseline open_trades so
        # linked OANDA live account trades are closed by the normal auto-close check.
        if tide_result:
            demo_live_execution_result = execute_live_demo_basket_manager_action(
                conn=conn,
                asset=asset,
                latest_signal_time=safe_str(signal["timestamp_readable"]),
                latest_price=safe_float(signal["exec_close"]),
                tide_result=tide_result,
            )

            if JUNE_FULL_DEMO_ENABLED and JUNE_FULL_DEMO_BLOCK_ENTRIES_ON_BASKET_PAUSE and is_june_full_demo_broker_asset(asset):
                action = safe_str(tide_result.get("tiered_action") or tide_result.get("shadow_action") or "")
                should_block_entry, block_reason, block_meta = live_demo_should_block_new_entry(conn, asset, action, tide_result)
                if should_block_entry:
                    allow_new_entry = False
                    conn.execute("""
                        INSERT INTO system_events (created_at_utc, event_type, message)
                        VALUES (?, ?, ?)
                    """, (
                        now_utc_iso(),
                        "live_entry_blocked_by_basket_manager",
                        (
                            f"asset={asset}; signal_time={safe_str(signal['timestamp_readable'])}; action={action}; "
                            f"reason={block_reason}; live_open_count={block_meta.get('live_open_count')}; "
                            f"stage={block_meta.get('stage')}; status={block_meta.get('status')}; "
                            f"basket_R={block_meta.get('basket_R')}"
                        )[:4000]
                    ))
                elif live_demo_action_blocks_new_entry(action):
                    conn.execute("""
                        INSERT INTO system_events (created_at_utc, event_type, message)
                        VALUES (?, ?, ?)
                    """, (
                        now_utc_iso(),
                        "live_entry_block_bypassed_young_basket_guard",
                        (
                            f"asset={asset}; signal_time={safe_str(signal['timestamp_readable'])}; action={action}; "
                            f"reason={block_reason}; live_open_count={block_meta.get('live_open_count')}; "
                            f"stage={block_meta.get('stage')}; status={block_meta.get('status')}; "
                            f"basket_R={block_meta.get('basket_R')}"
                        )[:4000]
                    ))

        if allow_new_entry:
            new_trade_id = create_new_open_trade(conn, signal)
            create_new_dynamic_exit_shadow_trade(conn, signal)
        else:
            # Keep dynamic research stream independent, but do not create a baseline
            # broker-trackable trade when the live manager has paused entries.
            create_new_dynamic_exit_shadow_trade(conn, signal)

        conn.commit()

    # v6.8: live-controlled automation happens after the shadow DB transaction commits,
    # avoiding SQLite lock contention and keeping broker execution isolated/audited.
    if new_trade_id:
        broker_auto_execute_new_shadow_trade(new_trade_id, asset, from_current_signal_event=True)
    broker_auto_close_closed_shadow_links()


