def get_period_starts() -> Dict[str, datetime]:
    n = now_utc()
    today = datetime(n.year, n.month, n.day, tzinfo=timezone.utc)
    week = today - timedelta(days=today.weekday())
    month = datetime(n.year, n.month, 1, tzinfo=timezone.utc)
    return {"today": today, "week": week, "month": month}


def empty_trade_status() -> Dict[str, Any]:
    return {
        "count": 0,
        "win_count": 0,
        "loss_count": 0,
        "flat_count": 0,
        "return_sum_pct": 0.0,
        "winner_return_sum_pct": 0.0,
        "loser_return_sum_pct": 0.0,
        "mfe_sum_pct": 0.0,
        "mae_sum_pct": 0.0,
        "avg_return_pct": 0.0,
        "avg_winner_return_pct": 0.0,
        "avg_loser_return_pct": 0.0,
        "avg_mfe_pct": 0.0,
        "avg_mae_pct": 0.0,
        "win_rate_pct": 0.0,
        "loss_rate_pct": 0.0,
    }


def add_trade_status_row(status: Dict[str, Any], return_pct: Any, mfe_pct: Any = None, mae_pct: Any = None) -> None:
    ret = safe_float(return_pct) or 0.0
    mfe = safe_float(mfe_pct) or 0.0
    mae = safe_float(mae_pct) or 0.0

    status["count"] += 1
    status["return_sum_pct"] += ret
    status["mfe_sum_pct"] += mfe
    status["mae_sum_pct"] += mae

    if ret > 0:
        status["win_count"] += 1
        status["winner_return_sum_pct"] += ret
    elif ret < 0:
        status["loss_count"] += 1
        status["loser_return_sum_pct"] += ret
    else:
        status["flat_count"] += 1


def finalise_trade_status(status: Dict[str, Any]) -> Dict[str, Any]:
    count = int(status["count"] or 0)
    wins = int(status["win_count"] or 0)
    losses = int(status["loss_count"] or 0)

    if count > 0:
        status["avg_return_pct"] = status["return_sum_pct"] / count
        status["avg_mfe_pct"] = status["mfe_sum_pct"] / count
        status["avg_mae_pct"] = status["mae_sum_pct"] / count
        status["win_rate_pct"] = wins / count * 100
        status["loss_rate_pct"] = losses / count * 100

    if wins > 0:
        status["avg_winner_return_pct"] = status["winner_return_sum_pct"] / wins

    if losses > 0:
        status["avg_loser_return_pct"] = status["loser_return_sum_pct"] / losses

    return status


def build_performance_summary(conn: sqlite3.Connection) -> Dict[str, Any]:
    if PERFORMANCE_SCOPE_ASSETS:
        scope_placeholders = ",".join(["?"] * len(PERFORMANCE_SCOPE_ASSETS))
        open_rows = conn.execute(
            f"SELECT * FROM open_trades WHERE UPPER(asset) IN ({scope_placeholders})",
            tuple(PERFORMANCE_SCOPE_ASSETS),
        ).fetchall()
        closed_rows = conn.execute(
            f"SELECT * FROM closed_trades WHERE UPPER(asset) IN ({scope_placeholders})",
            tuple(PERFORMANCE_SCOPE_ASSETS),
        ).fetchall()
    else:
        open_rows = conn.execute("SELECT * FROM open_trades").fetchall()
        closed_rows = conn.execute("SELECT * FROM closed_trades").fetchall()
    starts = get_period_starts()
    assets = sorted(set(list(CONFIG.keys()) + [safe_str(r["asset"]) for r in open_rows] + [safe_str(r["asset"]) for r in closed_rows]))

    summary = {
        "overall": {
            "open_unrealised_pnl": 0.0,
            "closed_realised_pnl": 0.0,
            "total_shadow_pnl": 0.0,
            "open_trade_count": len(open_rows),
            "closed_trade_count": len(closed_rows),
            "winning_closed_trades": 0,
            "losing_closed_trades": 0,
            "sl_hits": 0,
        },
        "periods": {
            "today": {"open_pnl": 0.0, "closed_pnl": 0.0, "total_pnl": 0.0, "open_count": 0, "closed_count": 0},
            "week": {"open_pnl": 0.0, "closed_pnl": 0.0, "total_pnl": 0.0, "open_count": 0, "closed_count": 0},
            "month": {"open_pnl": 0.0, "closed_pnl": 0.0, "total_pnl": 0.0, "open_count": 0, "closed_count": 0},
        },
        "by_asset": {},
        "trade_status": {
            "open_total": empty_trade_status(),
            "closed_total": empty_trade_status(),
            "combined_total": empty_trade_status(),
            "by_asset": {},
        },
    }

    for asset in assets:
        if asset:
            summary["by_asset"][asset] = {
                "open_count": 0,
                "open_pnl": 0.0,
                "closed_count": 0,
                "closed_pnl": 0.0,
                "total_pnl": 0.0,
                "wins": 0,
                "losses": 0,
                "sl_hits": 0,
                "avg_closed_return_pct": 0.0,
                "closed_return_sum_pct": 0.0,
            }
            summary["trade_status"]["by_asset"][asset] = {
                "open": empty_trade_status(),
                "closed": empty_trade_status(),
                "combined": empty_trade_status(),
            }

    for r in open_rows:
        asset = safe_str(r["asset"])
        ret = safe_float(r["return_pct"]) or 0.0
        pnl = pnl_from_return(asset, ret)

        summary["overall"]["open_unrealised_pnl"] += pnl
        add_trade_status_row(summary["trade_status"]["open_total"], r["return_pct"], r["mfe_pct"], r["mae_pct"])
        add_trade_status_row(summary["trade_status"]["combined_total"], r["return_pct"], r["mfe_pct"], r["mae_pct"])

        if asset in summary["by_asset"]:
            summary["by_asset"][asset]["open_count"] += 1
            summary["by_asset"][asset]["open_pnl"] += pnl
            add_trade_status_row(summary["trade_status"]["by_asset"][asset]["open"], r["return_pct"], r["mfe_pct"], r["mae_pct"])
            add_trade_status_row(summary["trade_status"]["by_asset"][asset]["combined"], r["return_pct"], r["mfe_pct"], r["mae_pct"])

        entry_dt = parse_dt(r["entry_time"])
        if entry_dt:
            for name, start in starts.items():
                if entry_dt >= start:
                    summary["periods"][name]["open_pnl"] += pnl
                    summary["periods"][name]["open_count"] += 1

    for r in closed_rows:
        asset = safe_str(r["asset"])
        pnl = safe_float(r["paper_pnl_50risk"])
        if pnl is None:
            pnl = pnl_from_return(asset, r["return_pct"])

        ret = safe_float(r["return_pct"]) or 0.0

        summary["overall"]["closed_realised_pnl"] += pnl
        add_trade_status_row(summary["trade_status"]["closed_total"], r["return_pct"], r["mfe_pct"], r["mae_pct"])
        add_trade_status_row(summary["trade_status"]["combined_total"], r["return_pct"], r["mfe_pct"], r["mae_pct"])

        if pnl > 0:
            summary["overall"]["winning_closed_trades"] += 1
        elif pnl < 0:
            summary["overall"]["losing_closed_trades"] += 1

        if is_true(r["sl_hit"]):
            summary["overall"]["sl_hits"] += 1

        if asset in summary["by_asset"]:
            summary["by_asset"][asset]["closed_count"] += 1
            summary["by_asset"][asset]["closed_pnl"] += pnl
            summary["by_asset"][asset]["closed_return_sum_pct"] += ret
            add_trade_status_row(summary["trade_status"]["by_asset"][asset]["closed"], r["return_pct"], r["mfe_pct"], r["mae_pct"])
            add_trade_status_row(summary["trade_status"]["by_asset"][asset]["combined"], r["return_pct"], r["mfe_pct"], r["mae_pct"])

            if pnl > 0:
                summary["by_asset"][asset]["wins"] += 1
            elif pnl < 0:
                summary["by_asset"][asset]["losses"] += 1
            if is_true(r["sl_hit"]):
                summary["by_asset"][asset]["sl_hits"] += 1

        exit_dt = parse_dt(r["exit_time"])
        if exit_dt:
            for name, start in starts.items():
                if exit_dt >= start:
                    summary["periods"][name]["closed_pnl"] += pnl
                    summary["periods"][name]["closed_count"] += 1

    summary["overall"]["total_shadow_pnl"] = summary["overall"]["open_unrealised_pnl"] + summary["overall"]["closed_realised_pnl"]

    for name in summary["periods"]:
        summary["periods"][name]["total_pnl"] = summary["periods"][name]["open_pnl"] + summary["periods"][name]["closed_pnl"]

    for asset, data in summary["by_asset"].items():
        data["total_pnl"] = data["open_pnl"] + data["closed_pnl"]
        if data["closed_count"] > 0:
            data["avg_closed_return_pct"] = data["closed_return_sum_pct"] / data["closed_count"]

    summary["trade_status"]["open_total"] = finalise_trade_status(summary["trade_status"]["open_total"])
    summary["trade_status"]["closed_total"] = finalise_trade_status(summary["trade_status"]["closed_total"])
    summary["trade_status"]["combined_total"] = finalise_trade_status(summary["trade_status"]["combined_total"])

    for asset in summary["trade_status"]["by_asset"]:
        summary["trade_status"]["by_asset"][asset]["open"] = finalise_trade_status(summary["trade_status"]["by_asset"][asset]["open"])
        summary["trade_status"]["by_asset"][asset]["closed"] = finalise_trade_status(summary["trade_status"]["by_asset"][asset]["closed"])
        summary["trade_status"]["by_asset"][asset]["combined"] = finalise_trade_status(summary["trade_status"]["by_asset"][asset]["combined"])

    return summary


# ============================================================
# EXPORT HELPERS
# ============================================================

def rows_to_csv_text(rows: List[sqlite3.Row]) -> str:
    output = io.StringIO()
    if not rows:
        return ""
    fieldnames = list(rows[0].keys())
    writer = csv.DictWriter(output, fieldnames=fieldnames)
    writer.writeheader()
    for row in rows:
        writer.writerow({k: row[k] for k in fieldnames})
    return output.getvalue()


def export_table_as_csv(conn: sqlite3.Connection, table_name: str) -> str:
    rows = conn.execute(f"SELECT * FROM {table_name}").fetchall()
    return rows_to_csv_text(rows)




# ============================================================
# METALS DEEP RESEARCH OUTCOME HELPERS (v10.0.87, research-only, no broker action)
# ============================================================

METALS_RESEARCH_ASSETS = {"XAUUSD", "XAU", "XAGUSD", "XAG"}
METALS_RESEARCH_MILESTONES = [12, 24, 48, 72, 96]

def metal_research_sl_pct(asset: str) -> float:
    a = safe_str(asset).upper()
    if a in {"XAU", "XAUUSD"}:
        return float(os.getenv("METALS_RESEARCH_XAU_SL_PCT", "2.21"))
    if a in {"XAG", "XAGUSD"}:
        return float(os.getenv("METALS_RESEARCH_XAG_SL_PCT", "5.24"))
    return float(os.getenv("METALS_RESEARCH_DEFAULT_SL_PCT", "3.0"))

def _raw_signal_json(row: Any) -> Dict[str, Any]:
    try:
        return json.loads(row["raw_json"] or "{}")
    except Exception:
        return {}

def _raw_bool_value(value: Any) -> bool:
    return safe_str(value).lower() in {"true", "1", "yes", "y", "take"}

def _return_to_50risk(asset: str, return_pct_value: Any) -> Optional[float]:
    r = safe_float(return_pct_value)
    if r is None:
        return None
    sl = metal_research_sl_pct(asset)
    if sl == 0:
        return None
    return r / sl * 50.0

def build_metals_research_outcomes(limit: int = 1000, candidates_only: bool = False) -> List[Dict[str, Any]]:
    """Builds research-only metal outcome rows directly from raw_signals.

    This intentionally does not open/close trades and does not affect the June
    index demo. It treats each XAU/XAG signal as a research row and calculates
    forward close returns plus MFE/MAE over 12/24/48/72/96 subsequent hourly
    metal signals when enough future candles exist.
    """
    init_db()
    limit = max(1, min(int(limit or 1000), 10000))
    with get_conn() as conn:
        rows = conn.execute("""
            SELECT id, received_at_utc, pair, timestamp_readable, exec_close, exec_high, exec_low,
                   forward_test_candidate, take_trade, raw_json
            FROM raw_signals
            WHERE UPPER(pair) IN ('XAUUSD','XAGUSD','XAU','XAG')
            ORDER BY UPPER(pair) ASC, id ASC
        """).fetchall()

    by_pair: Dict[str, List[sqlite3.Row]] = {}
    for r in rows:
        by_pair.setdefault(safe_str(r["pair"]).upper(), []).append(r)

    out: List[Dict[str, Any]] = []
    for pair, items in by_pair.items():
        for idx, row in enumerate(items):
            raw = _raw_signal_json(row)
            cand = _raw_bool_value(row["forward_test_candidate"])
            take = _raw_bool_value(row["take_trade"])
            quality = safe_str(raw.get("signal_quality", ""))
            is_candidate_like = cand or take or "candidate" in quality.lower()
            if candidates_only and not is_candidate_like:
                continue

            entry = safe_float(row["exec_close"])
            d: Dict[str, Any] = {
                "signal_id": row["id"],
                "asset": pair,
                "candle_time": row["timestamp_readable"],
                "candle_time_display": display_candle_time(row["timestamp_readable"]),
                "received_at_utc": row["received_at_utc"],
                "candidate": 1 if cand else 0,
                "take_trade": 1 if take else 0,
                "candidate_like": 1 if is_candidate_like else 0,
                "score": raw.get("score_raw", ""),
                "signal_quality": quality,
                "setup_type": raw.get("setup_type", ""),
                "ctx_trend_state": raw.get("ctx_trend_state", ""),
                "d_bull": raw.get("d_bull", ""),
                "d_bear": raw.get("d_bear", ""),
                "reject_reason": raw.get("reject_reason", ""),
                "entry_close": entry,
                "placeholder_sl_pct": metal_research_sl_pct(pair),
            }
            for m in METALS_RESEARCH_MILESTONES:
                d[f"return_{m}h_pct"] = None
                d[f"pnl50_{m}h"] = None
                d[f"mfe_{m}h_pct"] = None
                d[f"mae_{m}h_pct"] = None
                d[f"mfe50_{m}h"] = None
                d[f"mae50_{m}h"] = None
                d[f"has_{m}h"] = 0
                if entry is None or entry == 0:
                    continue
                future = items[idx + 1: idx + m + 1]
                if len(future) < m:
                    continue
                target = future[-1]
                target_close = safe_float(target["exec_close"])
                highs = [safe_float(x["exec_high"]) for x in future]
                lows = [safe_float(x["exec_low"]) for x in future]
                highs = [x for x in highs if x is not None]
                lows = [x for x in lows if x is not None]
                if target_close is not None:
                    ret = (target_close / entry - 1.0) * 100.0
                    d[f"return_{m}h_pct"] = ret
                    d[f"pnl50_{m}h"] = _return_to_50risk(pair, ret)
                if highs:
                    mfe = (max(highs) / entry - 1.0) * 100.0
                    d[f"mfe_{m}h_pct"] = mfe
                    d[f"mfe50_{m}h"] = _return_to_50risk(pair, mfe)
                if lows:
                    mae = (min(lows) / entry - 1.0) * 100.0
                    d[f"mae_{m}h_pct"] = mae
                    d[f"mae50_{m}h"] = _return_to_50risk(pair, mae)
                d[f"has_{m}h"] = 1
            out.append(d)

    out.sort(key=lambda x: int(x.get("signal_id") or 0), reverse=True)
    return out[:limit]


# ============================================================
# METALS SHORT RESEARCH HELPERS (v10.0.88, research-only, no broker action)
# ============================================================
# This creates a synthetic SHORT research lane from the same XAU/XAG raw signal
# stream. It does not open trades, close trades, broker-promote metals, change
# index basket state, or alter the live NAS100/US500 rules.

METALS_SHORT_RESEARCH_ENABLED = os.getenv("METALS_SHORT_RESEARCH_ENABLED", "true").strip().lower() == "true"
METALS_SHORT_RESEARCH_VERSION = "metal_short_v1_research_only"


def _raw_has_key(raw: Dict[str, Any], key: str) -> bool:
    return key in raw and safe_str(raw.get(key)) != ""


def _raw_any_true(raw: Dict[str, Any], keys: List[str]) -> bool:
    return any(_raw_bool_value(raw.get(k)) for k in keys if k in raw)


def _raw_any_false_when_present(raw: Dict[str, Any], keys: List[str]) -> bool:
    return any((k in raw and not _raw_bool_value(raw.get(k))) for k in keys)


def infer_metal_short_candidate(raw: Dict[str, Any], row: Any = None) -> Dict[str, Any]:
    """Generate a research-only metal short candidate from existing signal fields.

    The rule is deliberately conservative-ish and transparent, not optimised.
    It asks: is the metal row bearish enough to justify *testing* a short?
    It is not an instruction to trade.
    """
    if not METALS_SHORT_RESEARCH_ENABLED:
        return {
            "short_candidate": 0,
            "short_watch": 0,
            "short_score": 0,
            "short_reason": "METALS_SHORT_RESEARCH_ENABLED=false",
            "short_blockers": "disabled_by_env",
            "short_model_version": METALS_SHORT_RESEARCH_VERSION,
        }

    ctx = safe_str(raw.get("ctx_trend_state", "")).lower()
    quality = safe_str(raw.get("signal_quality", "")).lower()
    setup = safe_str(raw.get("setup_type", "")).lower()
    reject = safe_str(raw.get("reject_reason", "")).lower()

    d_bear = _raw_bool_value(raw.get("d_bear"))
    d_bull = _raw_bool_value(raw.get("d_bull"))
    long_trend_rule = _raw_bool_value(raw.get("rule_trend_long_v1"))
    long_continuation_rule = _raw_bool_value(raw.get("rule_bull_continuation_v1"))
    long_forward_candidate = _raw_bool_value(row["forward_test_candidate"]) if row is not None else False

    exec_rsi = safe_float(raw.get("exec_rsi"))
    ctx_rsi = safe_float(raw.get("ctx_rsi"))
    d_rsi = safe_float(raw.get("d_rsi"))
    score_raw = safe_float(raw.get("score_raw"))

    # Use bearish fields if the Pine script provides them; otherwise fall back
    # to bearish context inferred from d_bear / trend text / RSI / failed long rules.
    ctx_bearish_flag = _raw_any_true(raw, [
        "ctx_bear", "ctx_bear_stack", "ctx_down_stack", "ctx_close_lt_ema20", "ctx_close_lt_ema50",
        "ctx_hist_down", "ctx_macd_hist_down", "ctx_rsi_down", "rule_trend_short_v1", "rule_bear_continuation_v1",
    ])
    ctx_below_ema_when_known = _raw_any_false_when_present(raw, ["ctx_close_gt_ema20", "ctx_close_gt_ema50"])
    breakdown_trigger = _raw_any_true(raw, [
        "exec_break_low", "exec_is_breakdown", "exec_breakdown", "exec_close_lt_ema20", "exec_close_lt_ema50",
        "rule_breakdown_short_v1", "rule_bear_breakdown_v1",
    ])

    reasons: List[str] = []
    blockers: List[str] = []
    score = 0

    if d_bear:
        score += 2
        reasons.append("daily_bear")
    if "bear" in ctx or "down" in ctx or "weak" in ctx:
        score += 2
        reasons.append(f"ctx_{ctx or 'bearish'}")
    if ctx_bearish_flag or ctx_below_ema_when_known:
        score += 1
        reasons.append("context_below_or_bearish")
    if breakdown_trigger:
        score += 1
        reasons.append("breakdown_trigger")
    if exec_rsi is not None and exec_rsi < 50:
        score += 1
        reasons.append(f"exec_rsi_{exec_rsi:.1f}_below_50")
    if ctx_rsi is not None and ctx_rsi < 50:
        score += 1
        reasons.append(f"ctx_rsi_{ctx_rsi:.1f}_below_50")
    if d_rsi is not None and d_rsi < 50:
        score += 1
        reasons.append(f"daily_rsi_{d_rsi:.1f}_below_50")
    if "bear" in quality or "short" in quality or "sell" in quality or "bear" in setup or "short" in setup or "sell" in setup:
        score += 1
        reasons.append("bearish_quality_or_setup")
    if "daily bear" in reject or "bear" in reject:
        score += 1
        reasons.append("long_rejected_by_bearish_context")

    if long_forward_candidate:
        blockers.append("long_forward_candidate_true")
    if d_bull and not d_bear:
        blockers.append("daily_bull_without_daily_bear")
    if (long_trend_rule or long_continuation_rule) and not d_bear:
        blockers.append("long_rules_still_supportive")
    if exec_rsi is not None and exec_rsi > 62 and not d_bear:
        blockers.append("exec_rsi_too_bullish_for_short")
    if score_raw is not None and score_raw >= 80 and not d_bear:
        blockers.append("high_long_score_without_bear_filter")

    # Candidate: enough bearish evidence and no obvious long-side blocker.
    # Watch: some bearish evidence but not enough for the generated candidate.
    short_candidate = bool(score >= 3 and not blockers)
    short_watch = bool(score >= 2 and not long_forward_candidate)

    if not reasons:
        reasons.append("no_bearish_short_evidence")
    return {
        "short_candidate": 1 if short_candidate else 0,
        "short_watch": 1 if short_watch else 0,
        "short_score": score,
        "short_reason": "; ".join(reasons[:8]),
        "short_blockers": "; ".join(blockers),
        "short_model_version": METALS_SHORT_RESEARCH_VERSION,
    }


def build_metals_short_research_outcomes(limit: int = 1000, candidates_only: bool = False) -> List[Dict[str, Any]]:
    """Build generated metal SHORT research rows from XAU/XAG raw_signals.

    Return/MFE/MAE are inverted for short logic:
    - positive return = price moved down from entry
    - MFE = best downside move after entry
    - MAE = worst upside move against the short after entry
    """
    init_db()
    limit = max(1, min(int(limit or 1000), 10000))
    with get_conn() as conn:
        rows = conn.execute("""
            SELECT id, received_at_utc, pair, timestamp_readable, exec_close, exec_high, exec_low,
                   forward_test_candidate, take_trade, raw_json
            FROM raw_signals
            WHERE UPPER(pair) IN ('XAUUSD','XAGUSD','XAU','XAG')
            ORDER BY UPPER(pair) ASC, id ASC
        """).fetchall()

    by_pair: Dict[str, List[sqlite3.Row]] = {}
    for r in rows:
        by_pair.setdefault(safe_str(r["pair"]).upper(), []).append(r)

    out: List[Dict[str, Any]] = []
    for pair, items in by_pair.items():
        for idx, row in enumerate(items):
            raw = _raw_signal_json(row)
            short_info = infer_metal_short_candidate(raw, row)
            short_candidate = int(short_info.get("short_candidate") or 0) == 1
            short_watch = int(short_info.get("short_watch") or 0) == 1
            if candidates_only and not (short_candidate or short_watch):
                continue

            entry = safe_float(row["exec_close"])
            d: Dict[str, Any] = {
                "signal_id": row["id"],
                "asset": pair,
                "research_side": "SHORT",
                "candle_time": row["timestamp_readable"],
                "candle_time_display": display_candle_time(row["timestamp_readable"]),
                "received_at_utc": row["received_at_utc"],
                # For this short table, candidate means generated SHORT candidate.
                "candidate": 1 if short_candidate else 0,
                "take_trade": 0,
                "candidate_like": 1 if (short_candidate or short_watch) else 0,
                "short_candidate": 1 if short_candidate else 0,
                "short_watch": 1 if short_watch else 0,
                "short_score": short_info.get("short_score"),
                "short_reason": short_info.get("short_reason"),
                "short_blockers": short_info.get("short_blockers"),
                "short_model_version": short_info.get("short_model_version"),
                "forward_test_candidate_long": 1 if _raw_bool_value(row["forward_test_candidate"]) else 0,
                "score": raw.get("score_raw", ""),
                "signal_quality": raw.get("signal_quality", ""),
                "setup_type": raw.get("setup_type", ""),
                "ctx_trend_state": raw.get("ctx_trend_state", ""),
                "d_bull": raw.get("d_bull", ""),
                "d_bear": raw.get("d_bear", ""),
                "reject_reason": raw.get("reject_reason", ""),
                "entry_close": entry,
                "placeholder_sl_pct": metal_research_sl_pct(pair),
            }
            for m in METALS_RESEARCH_MILESTONES:
                d[f"return_{m}h_pct"] = None
                d[f"pnl50_{m}h"] = None
                d[f"mfe_{m}h_pct"] = None
                d[f"mae_{m}h_pct"] = None
                d[f"mfe50_{m}h"] = None
                d[f"mae50_{m}h"] = None
                d[f"has_{m}h"] = 0
                if entry is None or entry == 0:
                    continue
                future = items[idx + 1: idx + m + 1]
                if len(future) < m:
                    continue
                target = future[-1]
                target_close = safe_float(target["exec_close"])
                highs = [safe_float(x["exec_high"]) for x in future]
                lows = [safe_float(x["exec_low"]) for x in future]
                highs = [x for x in highs if x is not None]
                lows = [x for x in lows if x is not None]
                if target_close is not None:
                    ret = (entry - target_close) / entry * 100.0
                    d[f"return_{m}h_pct"] = ret
                    d[f"pnl50_{m}h"] = _return_to_50risk(pair, ret)
                if lows:
                    mfe = (entry - min(lows)) / entry * 100.0
                    d[f"mfe_{m}h_pct"] = mfe
                    d[f"mfe50_{m}h"] = _return_to_50risk(pair, mfe)
                if highs:
                    mae = (entry - max(highs)) / entry * 100.0
                    d[f"mae_{m}h_pct"] = mae
                    d[f"mae50_{m}h"] = _return_to_50risk(pair, mae)
                d[f"has_{m}h"] = 1
            out.append(d)

    out.sort(key=lambda x: int(x.get("signal_id") or 0), reverse=True)
    return out[:limit]


def _managed_sl_adjusted_metal_pnl(row: Dict[str, Any], milestone: int = 48) -> Optional[float]:
    asset = safe_str(row.get("asset")).upper()
    sl = metal_research_sl_pct(asset)
    mae = safe_float(row.get(f"mae_{milestone}h_pct"))
    pnl = safe_float(row.get(f"pnl50_{milestone}h"))
    if pnl is None:
        return None
    if mae is not None and mae <= -abs(sl):
        return -50.0
    return pnl


def build_metal_basket_simulation_summary(outcome_rows: List[Dict[str, Any]], milestone: int = 48) -> List[Dict[str, Any]]:
    """Emergency-SL proxy summary for metal long or generated short rows."""
    sim_rows: List[Dict[str, Any]] = []
    keys = sorted({(safe_str(r.get("asset")).upper(), safe_str(r.get("research_side") or "LONG").upper()) for r in outcome_rows if safe_str(r.get("asset"))})
    for asset, side in keys:
        subset = [r for r in outcome_rows if safe_str(r.get("asset")).upper() == asset and safe_str(r.get("research_side") or "LONG").upper() == side]
        sl = metal_research_sl_pct(asset)
        matured = [r for r in subset if int(r.get(f"has_{milestone}h") or 0) == 1]
        rets = [safe_float(r.get(f"return_{milestone}h_pct")) for r in matured]
        maes = [safe_float(r.get(f"mae_{milestone}h_pct")) for r in matured]
        pnls = [safe_float(r.get(f"pnl50_{milestone}h")) for r in matured]
        adj = [_managed_sl_adjusted_metal_pnl(r, milestone) for r in matured]
        rets = [v for v in rets if v is not None]
        maes = [v for v in maes if v is not None]
        pnls = [v for v in pnls if v is not None]
        adj = [v for v in adj if v is not None]
        sl_pressure = sum(1 for v in maes if v <= -abs(sl))
        avg_ret = (sum(rets) / len(rets)) if rets else None
        avg_mae = (sum(maes) / len(maes)) if maes else None
        if not matured:
            state = "WAITING_FOR_48H_DATA"
        elif sl_pressure > 0 and (avg_ret is not None and avg_ret < 0):
            state = "DEFENCE_LIKELY"
        elif avg_ret is not None and avg_ret < 0:
            state = "CAUTION"
        else:
            state = "BENIGN_SO_FAR"
        sim_rows.append({
            "asset": asset,
            "research_side": side,
            "candidate_rows": len(subset),
            "matured_48h": len(matured),
            "placeholder_sl_pct": sl,
            "avg_return_48h_pct": avg_ret,
            "avg_mae_48h_pct": avg_mae,
            "sl_pressure_count_48h": sl_pressure,
            "sl_pressure_rate_48h_pct": (sl_pressure / len(maes) * 100.0) if maes else None,
            "raw_pnl50_sum_48h": sum(pnls) if pnls else None,
            "emergency_sl_adjusted_pnl50_sum_48h": sum(adj) if adj else None,
            "simulation_state": state,
            "note": "Emergency-SL-adjusted research proxy only; no live broker/basket action.",
        })
    return sim_rows


def _metal_basket_simulation_html(sim_rows: List[Dict[str, Any]], empty: str = "No metal rows ready for basket-manager simulation yet.") -> str:
    html = ""
    for r in sim_rows or []:
        sim_state = safe_str(r.get("simulation_state"))
        sim_cls = "flat"
        if sim_state == "DEFENCE_LIKELY":
            sim_cls = "status_red"
        elif sim_state == "CAUTION":
            sim_cls = "status_amber"
        elif sim_state == "BENIGN_SO_FAR":
            sim_cls = "status_green"
        sl_pressure_rate = safe_float(r.get("sl_pressure_rate_48h_pct"))
        html += f"""
        <tr>
            <td><strong>{esc(r.get('asset'))}</strong></td>
            <td>{esc(r.get('research_side') or 'LONG')}</td>
            <td>{esc(r.get('candidate_rows'))}</td>
            <td>{esc(r.get('matured_48h'))}</td>
            <td>{float(r.get('placeholder_sl_pct') or 0):.2f}%</td>
            <td class=\"{pnl_class(r.get('avg_return_48h_pct'))}\">{pct(r.get('avg_return_48h_pct') or 0)}</td>
            <td class=\"{pnl_class(r.get('avg_mae_48h_pct'))}\">{pct(r.get('avg_mae_48h_pct') or 0)}</td>
            <td>{esc(r.get('sl_pressure_count_48h'))}</td>
            <td>{'' if sl_pressure_rate is None else f'{sl_pressure_rate:.1f}%'}</td>
            <td class=\"{pnl_class(r.get('raw_pnl50_sum_48h'))}\">{money(r.get('raw_pnl50_sum_48h') or 0)}</td>
            <td class=\"{pnl_class(r.get('emergency_sl_adjusted_pnl50_sum_48h'))}\">{money(r.get('emergency_sl_adjusted_pnl50_sum_48h') or 0)}</td>
            <td class=\"{sim_cls}\"><strong>{esc(sim_state)}</strong></td>
        </tr>
        """
    return html or f'<tr><td colspan="12">{esc(empty)}</td></tr>'

def summarise_metal_outcomes(outcomes: List[Dict[str, Any]], candidate_like_only: bool = True) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for asset in sorted({safe_str(o.get("asset")).upper() for o in outcomes if safe_str(o.get("asset"))}):
        subset = [o for o in outcomes if safe_str(o.get("asset")).upper() == asset and (not candidate_like_only or int(o.get("candidate_like") or 0) == 1)]
        if not subset:
            continue
        summary: Dict[str, Any] = {"asset": asset, "rows": len(subset), "placeholder_sl_pct": metal_research_sl_pct(asset)}
        for m in METALS_RESEARCH_MILESTONES:
            vals = [safe_float(o.get(f"return_{m}h_pct")) for o in subset if int(o.get(f"has_{m}h") or 0) == 1]
            mfes = [safe_float(o.get(f"mfe_{m}h_pct")) for o in subset if int(o.get(f"has_{m}h") or 0) == 1]
            maes = [safe_float(o.get(f"mae_{m}h_pct")) for o in subset if int(o.get(f"has_{m}h") or 0) == 1]
            vals = [v for v in vals if v is not None]
            mfes = [v for v in mfes if v is not None]
            maes = [v for v in maes if v is not None]
            summary[f"n_{m}h"] = len(vals)
            summary[f"avg_return_{m}h_pct"] = (sum(vals) / len(vals)) if vals else None
            summary[f"win_rate_{m}h_pct"] = (sum(1 for v in vals if v > 0) / len(vals) * 100.0) if vals else None
            summary[f"avg_mfe_{m}h_pct"] = (sum(mfes) / len(mfes)) if mfes else None
            summary[f"avg_mae_{m}h_pct"] = (sum(maes) / len(maes)) if maes else None
            summary[f"avg_pnl50_{m}h"] = _return_to_50risk(asset, summary[f"avg_return_{m}h_pct"]) if summary[f"avg_return_{m}h_pct"] is not None else None
        rows.append(summary)
    return rows



