def advice_outcome_summary_rows(limit: int = 1000) -> List[Dict[str, Any]]:
    """
    Derived research view for basket-manager advice.

    Interpretation:
    - selected_pnl_at_advice = what would have been banked if we followed close/trim advice.
    - latest_selected_pnl = where those same selected trades are now if they were held.
    - follow_advice_vs_hold = selected_pnl_at_advice - latest_selected_pnl.
      Positive means following the advice would currently be better than holding.
      Negative means holding has so far been better than following the advice.
    """
    limit = max(1, min(int(limit or 1000), 5000))
    with get_conn() as conn:
        rows = conn.execute("""
            SELECT *
            FROM advice_outcome_audit
            ORDER BY id DESC
            LIMIT ?
        """, (limit,)).fetchall()

    out: List[Dict[str, Any]] = []
    for r in rows:
        selected_count = int(r["selected_count"] or 0)
        selected_at = safe_float(r["selected_pnl_at_advice_50risk"]) or 0.0
        latest = safe_float(r["latest_selected_pnl_50risk"])
        latest_delta = safe_float(r["latest_delta_vs_advice_50risk"])
        if latest is None and latest_delta is not None:
            latest = selected_at + latest_delta
        if latest is None:
            latest = selected_at
        delta_hold_vs_advice = latest - selected_at
        follow_advice_vs_hold = selected_at - latest

        # Snapshot outcome columns use the same convention: current/held minus advice-time banked value.
        def benefit_from_delta(name: str) -> Optional[float]:
            d = safe_float(r[name])
            if d is None:
                return None
            return -d

        status = "PENDING"
        if selected_count <= 0:
            status = "CONTEXT_ONLY"
        elif follow_advice_vs_hold > 0.01:
            status = "ADVICE_WOULD_HELP"
        elif follow_advice_vs_hold < -0.01:
            status = "HOLDING_BETTER_SO_FAR"
        else:
            status = "NEUTRAL"

        out.append({
            "id": r["id"],
            "created_at_utc": r["created_at_utc"],
            "asset": r["asset"],
            "basket_cycle_id": r["basket_cycle_id"],
            "advice_signal_time": r["advice_signal_time"],
            "latest_signal_time": r["latest_signal_time"],
            "tide_status": r["tide_status"],
            "tiered_action": r["tiered_action"],
            "basket_phase": r["basket_phase"],
            "open_trades": r["open_trades"],
            "selected_fraction": r["selected_fraction"],
            "selected_count": selected_count,
            "selected_trade_ids": r["selected_trade_ids"],
            "selected_pnl_at_advice_50risk": selected_at,
            "latest_selected_pnl_50risk": latest,
            "hold_vs_advice_latest_50risk": delta_hold_vs_advice,
            "follow_advice_vs_hold_latest_50risk": follow_advice_vs_hold,
            "follow_advice_vs_hold_1h_50risk": benefit_from_delta("outcome_1h_delta_50risk"),
            "follow_advice_vs_hold_4h_50risk": benefit_from_delta("outcome_4h_delta_50risk"),
            "follow_advice_vs_hold_12h_50risk": benefit_from_delta("outcome_12h_delta_50risk"),
            "follow_advice_vs_hold_24h_50risk": benefit_from_delta("outcome_24h_delta_50risk"),
            "completed_24h": bool(r["completed_24h"]),
            "status": status,
            "reason": r["reason"],
        })
    return out


def advice_outcome_group_summary(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    grouped: Dict[Tuple[str, str, str], Dict[str, Any]] = {}

    horizon_fields = [
        ("latest", "follow_advice_vs_hold_latest_50risk"),
        ("1h", "follow_advice_vs_hold_1h_50risk"),
        ("4h", "follow_advice_vs_hold_4h_50risk"),
        ("12h", "follow_advice_vs_hold_12h_50risk"),
        ("24h", "follow_advice_vs_hold_24h_50risk"),
    ]

    for r in rows:
        if int(r.get("selected_count") or 0) <= 0:
            continue
        key = (safe_str(r.get("asset")), safe_str(r.get("tiered_action")), safe_str(r.get("basket_phase")))
        g = grouped.setdefault(key, {
            "asset": key[0],
            "tiered_action": key[1],
            "basket_phase": key[2],
            "advice_count": 0,
            "advice_help_count": 0,
            "holding_better_count": 0,
            "neutral_count": 0,
            "avg_follow_advice_vs_hold_latest_50risk": 0.0,
            "total_follow_advice_vs_hold_latest_50risk": 0.0,
            "latest_sample_count": 0,
            "h1_sample_count": 0,
            "h4_sample_count": 0,
            "h12_sample_count": 0,
            "h24_sample_count": 0,
            "avg_follow_advice_vs_hold_1h_50risk": None,
            "avg_follow_advice_vs_hold_4h_50risk": None,
            "avg_follow_advice_vs_hold_12h_50risk": None,
            "avg_follow_advice_vs_hold_24h_50risk": None,
            "total_follow_advice_vs_hold_1h_50risk": 0.0,
            "total_follow_advice_vs_hold_4h_50risk": 0.0,
            "total_follow_advice_vs_hold_12h_50risk": 0.0,
            "total_follow_advice_vs_hold_24h_50risk": 0.0,
        })

        g["advice_count"] += 1

        latest_v = safe_float(r.get("follow_advice_vs_hold_latest_50risk"))
        if latest_v is not None:
            g["latest_sample_count"] += 1
            g["total_follow_advice_vs_hold_latest_50risk"] += latest_v
            if latest_v > 0.01:
                g["advice_help_count"] += 1
            elif latest_v < -0.01:
                g["holding_better_count"] += 1
            else:
                g["neutral_count"] += 1

        for label, field in horizon_fields[1:]:
            v = safe_float(r.get(field))
            if v is None:
                continue
            # label values are like "1h" / "4h"; store counts as h1_sample_count, h4_sample_count, etc.
            horizon_num = label.replace("h", "")
            count_key = f"h{horizon_num}_sample_count"
            total_key = f"total_follow_advice_vs_hold_{label}_50risk"
            g[count_key] = int(g.get(count_key) or 0) + 1
            g[total_key] = safe_float(g.get(total_key)) or 0.0
            g[total_key] += v

    out = []
    for g in grouped.values():
        latest_n = max(1, int(g.get("latest_sample_count") or 0))
        g["avg_follow_advice_vs_hold_latest_50risk"] = g["total_follow_advice_vs_hold_latest_50risk"] / latest_n
        for label in ["1h", "4h", "12h", "24h"]:
            horizon_num = label.replace("h", "")
            count_key = f"h{horizon_num}_sample_count"
            total_key = f"total_follow_advice_vs_hold_{label}_50risk"
            avg_key = f"avg_follow_advice_vs_hold_{label}_50risk"
            n = int(g.get(count_key) or 0)
            g[avg_key] = (g.get(total_key, 0.0) / n) if n > 0 else None
        out.append(g)
    out.sort(key=lambda x: (x["asset"], x["tiered_action"], x["basket_phase"]))
    return out



# ============================================================
# BASKET PROFIT PROTECTION RESEARCH
# ============================================================

def _profit_protection_stage(high_water_r: float, giveback_pct: float, family_status: str, candidate_assets: int, assets_with_open: int, giveback_delta: float) -> Tuple[str, str, str]:
    """Research-only profit protection model.

    This is intentionally not executable. It frames when a profitable basket should move from
    trend-capture into protection/harvest mode. It also catches sharp 1-candle deterioration,
    because a pure trailing stop can be too late on fast reversals.
    """
    hwr = safe_float(high_water_r) or 0.0
    gb = safe_float(giveback_pct) or 0.0
    cand = int(candidate_assets or 0)
    total_assets = max(1, int(assets_with_open or 0))
    fs = safe_str(family_status).upper()
    shock = (safe_float(giveback_delta) or 0.0) >= 20.0

    if hwr < 40:
        return (
            "OFF",
            "NO_PROFIT_PROTECTION",
            "Family high-water below +40R research activation threshold.",
        )

    # Hard deterioration after a large basket win. This is the area the current reversal exposed.
    if hwr >= 60 and gb >= 60 and cand == 0 and fs in {"RED", "CRITICAL"}:
        return (
            "HARD_DEFENCE_CANDIDATE",
            "CLOSE_MOST_OR_ALL_MATURE_RUNNERS_THEN_REASSESS",
            "Large high-water basket has given back 60%+ with zero candidate support and family RED/CRITICAL.",
        )

    if hwr >= 60 and (gb >= 50 or (shock and cand < total_assets)):
        return (
            "REAL_DEFENCE",
            "CLOSE_BREACHED_MATURE_RUNNERS_OR_WEAKEST_MATURE_50_PERCENT",
            "Large high-water basket has severe giveback or a fast one-candle deterioration; act before a normal trail is too late.",
        )

    if hwr >= 60 and gb >= 40:
        return (
            "HARVEST_MODE",
            "CLOSE_WEAKEST_MATURE_25_TO_30_PERCENT",
            "Large high-water basket has meaningful giveback; harvest mature/weak exposure but keep strongest runners.",
        )

    if hwr >= 60 and gb >= 30:
        return (
            "PROFIT_PROTECTION_ACTIVE",
            "PAUSE_STACKING_AND_PREPARE_MATURE_RUNNER_HARVEST",
            "Basket has achieved large profit and started giving back; do not panic-close, but tighten.",
        )

    if hwr >= 100:
        return (
            "POST_100R_RUNNER_MODE",
            "MAJOR_HARVEST_50_PERCENT_REMAINING_MATURE_EXPOSURE",
            "Basket reached 100R+; major harvest should bank a large chunk, then leave a smaller protected runner basket.",
        )

    if hwr >= 75:
        return (
            "HIGH_PROFIT_WATCH",
            "NO_TRIM_YET_BUT_STRICTER_RUNNER_PROTECTION",
            "Basket reached 75R+; trend can continue but tolerance for giveback should shrink.",
        )

    return (
        "ARMED",
        "CONTINUE_HOLD_WITH_PROFIT_PROTECTION_ARMED",
        "Basket has reached 40R+; start monitoring high-water giveback and shock reversals.",
    )


def basket_profit_protection_rows(limit: int = 500, latest_only: bool = False) -> List[Dict[str, Any]]:
    """Derived research rows for basket-level TP/harvest/profit-protection ideas.

    It compares fixed TP references and adaptive high-water protection without changing execution.
    """
    limit = max(1, min(int(limit or 500), 5000))
    rows_out: List[Dict[str, Any]] = []
    with get_conn() as conn:
        if latest_only:
            rows = conn.execute("""
                SELECT f.*
                FROM family_basket_checks f
                INNER JOIN (
                    SELECT family, MAX(id) AS max_id
                    FROM family_basket_checks
                    GROUP BY family
                ) x ON f.family = x.family AND f.id = x.max_id
                ORDER BY f.family ASC
            """).fetchall()
        else:
            # One final basket/profit-protection snapshot per family/candle.
            # TradingView sends one webhook per asset, so the family check can be
            # written more than once for the same hourly candle as NAS100/US500
            # arrive separately.  For dashboard/export clarity we keep only the
            # last row for each (family, latest_signal_time), which represents
            # the final/most complete state for that candle.
            rows = conn.execute("""
                SELECT f.*
                FROM family_basket_checks f
                INNER JOIN (
                    SELECT family, latest_signal_time, MAX(id) AS max_id
                    FROM family_basket_checks
                    WHERE latest_signal_time IS NOT NULL
                      AND latest_signal_time != ''
                    GROUP BY family, latest_signal_time
                ) x
                  ON f.family = x.family
                 AND f.latest_signal_time = x.latest_signal_time
                 AND f.id = x.max_id
                ORDER BY f.id DESC
                LIMIT ?
            """, (limit,)).fetchall()

        for r in rows:
            family = safe_str(r["family"])
            hwm = safe_float(r["basket_high_water_pnl_50risk"]) or 0.0
            pnl = safe_float(r["open_basket_pnl_50risk"]) or 0.0
            giveback = safe_float(r["basket_giveback_pct"]) or 0.0
            hwm_r = hwm / 50.0 if hwm else 0.0
            pnl_r = pnl / 50.0 if pnl else 0.0
            lost_from_high_water = hwm - pnl
            capture_ratio = (pnl / hwm) if hwm > 0 else None

            prev = conn.execute("""
                SELECT *
                FROM family_basket_checks
                WHERE family = ? AND id < ?
                ORDER BY id DESC
                LIMIT 1
            """, (family, r["id"])).fetchone()
            prev_giveback = safe_float(prev["basket_giveback_pct"]) if prev else None
            prev_candidate_assets = int(prev["latest_candidate_assets"] or 0) if prev else None
            giveback_delta = (giveback - prev_giveback) if prev_giveback is not None else 0.0
            candidate_delta = None if prev_candidate_assets is None else int(r["latest_candidate_assets"] or 0) - prev_candidate_assets
            shock_reversal = bool(giveback_delta >= 20.0 or (candidate_delta is not None and candidate_delta <= -2 and giveback_delta >= 10.0))

            stage, proposed_action, reason = _profit_protection_stage(
                high_water_r=hwm_r,
                giveback_pct=giveback,
                family_status=safe_str(r["family_status"]),
                candidate_assets=int(r["latest_candidate_assets"] or 0),
                assets_with_open=int(r["assets_with_open_trades"] or 0),
                giveback_delta=giveback_delta,
            )

            # Fixed TP references are deliberately labelled as references, not recommendations.
            fixed_tp_40_hit = hwm_r >= 40
            fixed_tp_60_hit = hwm_r >= 60
            fixed_tp_75_hit = hwm_r >= 75
            fixed_tp_100_hit = hwm_r >= 100
            if fixed_tp_75_hit:
                fixed_reference = "TP_75R_WOULD_HAVE_BANKED";
            elif fixed_tp_60_hit:
                fixed_reference = "TP_60R_WOULD_HAVE_BANKED";
            elif fixed_tp_40_hit:
                fixed_reference = "TP_40R_WOULD_HAVE_BANKED";
            else:
                fixed_reference = "NO_FIXED_TP_REFERENCE_HIT"

            rows_out.append({
                "id": r["id"],
                "created_at_utc": r["created_at_utc"],
                "family": family,
                "assets": r["assets"],
                "latest_signal_time": r["latest_signal_time"],
                "family_cycle_id": r["family_cycle_id"],
                "open_trades": r["open_trades"],
                "basket_phase": r["basket_phase"],
                "family_status": r["family_status"],
                "family_action": r["family_action"],
                "latest_candidate_assets": r["latest_candidate_assets"],
                "assets_with_open_trades": r["assets_with_open_trades"],
                "open_basket_pnl_50risk": round(pnl, 4),
                "open_basket_R": round(pnl_r, 4),
                "basket_high_water_pnl_50risk": round(hwm, 4),
                "basket_high_water_R": round(hwm_r, 4),
                "lost_from_high_water_50risk": round(lost_from_high_water, 4),
                "basket_giveback_pct": round(giveback, 4),
                "profit_capture_ratio": round(capture_ratio, 4) if capture_ratio is not None else None,
                "prev_giveback_pct": round(prev_giveback, 4) if prev_giveback is not None else None,
                "giveback_delta_vs_prev": round(giveback_delta, 4),
                "candidate_delta_vs_prev": candidate_delta,
                "shock_reversal_flag": int(shock_reversal),
                "fixed_tp_reference": fixed_reference,
                "fixed_tp_40R_hit": int(fixed_tp_40_hit),
                "fixed_tp_60R_hit": int(fixed_tp_60_hit),
                "fixed_tp_75R_hit": int(fixed_tp_75_hit),
                "fixed_tp_100R_hit": int(fixed_tp_100_hit),
                "profit_protection_stage": stage,
                "proposed_profit_action": proposed_action,
                "decision_reason": reason,
            })
    return rows_out


