# ============================================================
# DEFENCE ESCALATION TRACKER
# ============================================================

def _count_consecutive_asset_states(conn: sqlite3.Connection, asset: str, states: set, limit: int = 24, max_id: Optional[int] = None) -> int:
    """Count consecutive tide states for an asset, optionally as-of a specific tide_turn_checks row id."""
    states_upper = {safe_str(x).upper() for x in states}
    if max_id is None:
        rows = conn.execute("""
            SELECT tide_status
            FROM tide_turn_checks
            WHERE asset = ?
            ORDER BY id DESC
            LIMIT ?
        """, (asset, limit)).fetchall()
    else:
        rows = conn.execute("""
            SELECT tide_status
            FROM tide_turn_checks
            WHERE asset = ? AND id <= ?
            ORDER BY id DESC
            LIMIT ?
        """, (asset, max_id, limit)).fetchall()
    count = 0
    for r in rows:
        if safe_str(r["tide_status"]).upper() in states_upper:
            count += 1
        else:
            break
    return count


def _count_consecutive_candidate_false(conn: sqlite3.Connection, asset: str, limit: int = 24, max_id: Optional[int] = None) -> int:
    """Count consecutive false candidate states, optionally as-of a tide_turn_checks row id."""
    if max_id is None:
        rows = conn.execute("""
            SELECT latest_candidate
            FROM tide_turn_checks
            WHERE asset = ?
            ORDER BY id DESC
            LIMIT ?
        """, (asset, limit)).fetchall()
    else:
        rows = conn.execute("""
            SELECT latest_candidate
            FROM tide_turn_checks
            WHERE asset = ? AND id <= ?
            ORDER BY id DESC
            LIMIT ?
        """, (asset, max_id, limit)).fetchall()
    count = 0
    for r in rows:
        if not bool(r["latest_candidate"]):
            count += 1
        else:
            break
    return count


def _latest_family_check_for_asset(conn: sqlite3.Connection, asset: str, latest_signal_time: Optional[str] = None) -> Optional[sqlite3.Row]:
    """Get the family row aligned to the asset check time where possible.

    For historical defence rows this avoids using the newest family state for old asset checks.
    """
    family = get_basket_family(asset)
    if latest_signal_time:
        row = conn.execute("""
            SELECT *
            FROM family_basket_checks
            WHERE family = ? AND latest_signal_time <= ?
            ORDER BY latest_signal_time DESC, id DESC
            LIMIT 1
        """, (family, latest_signal_time)).fetchone()
        if row:
            return row
    return conn.execute("""
        SELECT *
        FROM family_basket_checks
        WHERE family = ?
        ORDER BY id DESC
        LIMIT 1
    """, (family,)).fetchone()


def _mature_runner_counts(conn: sqlite3.Connection, asset: str) -> Dict[str, Any]:
    # v10.0.59: defence escalation must be grounded in broker-confirmed live
    # exposure, not all local shadow open rows. A shadow row can exist after a
    # missed/failed broker entry; those are audit/missed-entry records, not live
    # positions, and must not affect open count, maturity, checkpoint-breach,
    # close-candidate or defence calculations.
    rows = conn.execute("""
        SELECT o.trade_id, o.hold_candles, o.return_pct
        FROM open_trades o
        INNER JOIN broker_trade_links l
            ON l.shadow_trade_id = o.trade_id
        WHERE UPPER(COALESCE(o.asset,'')) = UPPER(?)
          AND LOWER(COALESCE(o.status,'')) = 'open'
          AND COALESCE(l.mode,'') = 'shadow_demo_auto'
          AND UPPER(COALESCE(l.status,'')) IN ('OPEN','LINKED','PENDING')
    """, (asset,)).fetchall()
    out = {
        "open_count": len(rows),
        "count_48h_plus": 0,
        "count_72h_plus": 0,
        "count_96h_plus": 0,
        "count_120h_plus": 0,
        "breach_48_checkpoint_count": 0,
        "breach_96_checkpoint_count": 0,
        "breach_48_trade_ids": [],
        "breach_96_trade_ids": [],
        "close_candidate_trade_ids": [],
        "close_candidate_count": 0,
        "close_candidate_current_pnl_50risk": 0.0,
        "checkpoint_giveback_50risk": 0.0,
        "open_current_pnl_50risk": 0.0,
    }
    if not rows:
        return out

    # Store per-trade breach information so the proposed action can name the actual candidates.
    candidates: Dict[str, Dict[str, Any]] = {}
    open_current_pnl_total = 0.0

    for r in rows:
        hold = int(safe_float(r["hold_candles"]) or 0)
        tid = safe_str(r["trade_id"])
        current_pnl = pnl_from_return(asset, r["return_pct"])
        open_current_pnl_total += float(current_pnl or 0.0)
        if hold >= 48:
            out["count_48h_plus"] += 1
        if hold >= 72:
            out["count_72h_plus"] += 1
        if hold >= 96:
            out["count_96h_plus"] += 1
        if hold >= 120:
            out["count_120h_plus"] += 1

        # Checkpoint breach: current model P&L is below the recorded milestone P&L.
        # A small buffer avoids treating rounding/noise as a breach.
        for milestone, key, list_key in [
            (48, "breach_48_checkpoint_count", "breach_48_trade_ids"),
            (96, "breach_96_checkpoint_count", "breach_96_trade_ids"),
        ]:
            snap = conn.execute("""
                SELECT paper_pnl_50risk
                FROM milestone_snapshots
                WHERE trade_id = ? AND milestone_candle = ?
                ORDER BY id DESC
                LIMIT 1
            """, (tid, milestone)).fetchone()
            if snap:
                snap_pnl = safe_float(snap["paper_pnl_50risk"])
                if snap_pnl is not None and current_pnl < snap_pnl - 2.0:
                    out[key] += 1
                    out[list_key].append(tid)
                    giveback_vs_checkpoint = float(snap_pnl - current_pnl)
                    # Prefer later/more mature breaches; keep the largest checkpoint giveback per trade.
                    existing = candidates.get(tid)
                    if existing is None or milestone > existing.get("milestone", 0):
                        candidates[tid] = {
                            "trade_id": tid,
                            "milestone": milestone,
                            "current_pnl": float(current_pnl),
                            "checkpoint_pnl": float(snap_pnl),
                            "giveback_vs_checkpoint": giveback_vs_checkpoint,
                            "hold_candles": hold,
                        }

    # Select mature breached runners first. Sort by maturity then worst giveback.
    selected = sorted(
        candidates.values(),
        key=lambda x: (x.get("milestone", 0), x.get("hold_candles", 0), x.get("giveback_vs_checkpoint", 0.0)),
        reverse=True,
    )
    out["open_current_pnl_50risk"] = round(open_current_pnl_total, 4)
    out["close_candidate_trade_ids"] = [x["trade_id"] for x in selected]
    out["close_candidate_count"] = len(selected)
    out["close_candidate_current_pnl_50risk"] = round(sum(x["current_pnl"] for x in selected), 4)
    out["checkpoint_giveback_50risk"] = round(sum(x["giveback_vs_checkpoint"] for x in selected), 4)
    return out


def _giveback_band(giveback_pct: float) -> str:
    g = safe_float(giveback_pct) or 0.0
    if g >= 70:
        return "70%+"
    if g >= 60:
        return "60-70%"
    if g >= 50:
        return "50-60%"
    if g >= 35:
        return "35-50%"
    if g >= 25:
        return "25-35%"
    if g > 0:
        return "0-25%"
    return "0%"


def _defence_escalation_decision(asset_row: sqlite3.Row, family_row: Optional[sqlite3.Row], red_persistence: int, critical_persistence: int, candidate_false_persistence: int, mature: Dict[str, Any]) -> Tuple[str, str, str]:
    """Returns defence_stage, proposed_action, reason.

    This is research-only. It deliberately moves from blunt RED=trim logic to staged,
    confirmation-based defence with asset-first management and family overlay.
    """
    asset = safe_str(asset_row["asset"])
    status = safe_str(asset_row["tide_status"]).upper()
    family_status = safe_str(family_row["family_status"]).upper() if family_row else "UNKNOWN"
    # Use broker-confirmed open count for maturity/phase; do not let phantom shadow rows
    # make defence escalation think the live basket is bigger than it is.
    phase = safe_str(basket_phase_from_count(int(mature.get("open_count") or 0))).upper()
    open_R = safe_float(asset_row["open_basket_R"]) or 0.0
    giveback = safe_float(asset_row["basket_giveback_pct"]) or 0.0
    losing_pct = safe_float(asset_row["losing_trade_pct"]) or 0.0
    candidate_true_last_3 = int(safe_float(asset_row["candidate_true_last_3"]) or 0)
    latest_candidate = bool(asset_row["latest_candidate"])
    family_green = family_status in {"GREEN", "UNKNOWN", ""}
    family_bad = family_status in {"RED", "CRITICAL"}
    candidate_support = latest_candidate or candidate_true_last_3 >= 2
    breach48 = int(mature.get("breach_48_checkpoint_count") or 0)
    breach96 = int(mature.get("breach_96_checkpoint_count") or 0)
    runners96 = int(mature.get("count_96h_plus") or 0)

    if status == "GREEN":
        return "GREEN_HOLD", "HOLD", f"{asset} is GREEN. Continue to let runners work."

    if status == "AMBER":
        if giveback >= 60 and breach48 > 0 and not candidate_support:
            return "PROTECTIVE_MODE", "CLOSE_BREACHED_MATURE_RUNNERS_ONLY", "AMBER with severe giveback, weak candidate support, and mature-runner checkpoint breaches."
        return "CAUTION", "PAUSE_STACKING_ONLY", "AMBER is a warning state. Pause/slow stacking; no trim without persistence or runner breach."

    if status == "RED":
        if red_persistence <= 1 and family_green:
            return "RED_FIRST_WARNING", "PAUSE_STACKING_OBSERVE", "First RED and family is still healthy. Do not trim yet; observe next candle."
        if family_green and candidate_support and giveback < 50 and breach48 == 0:
            return "RED_DIVERGENCE_WATCH", "PAUSE_STACKING_MONITOR_MATURE_RUNNERS", "Asset RED but family/support remain intact and no mature-runner checkpoint breach. Avoid reactive trim."
        if breach96 > 0 or (breach48 > 0 and (red_persistence >= 2 or giveback >= 50)):
            return "PROTECTIVE_MODE", "CLOSE_BREACHED_MATURE_RUNNERS_ONLY", "RED with mature-runner checkpoint breach. Bank/protect runners first, not young trades."
        if red_persistence >= 3 and (giveback >= 50 or candidate_false_persistence >= 3 or family_bad):
            return "REAL_DEFENCE", "REDUCE_WEAKEST_MATURE_25_TO_30_PERCENT", "Persistent RED with support/giveback/family confirmation. Trim mature/weakest exposure."
        return "RED_CONFIRMATION_NEEDED", "PAUSE_STACKING_OBSERVE", "RED but confirmation is incomplete. Pause entries and wait for persistence/support failure."

    if status == "CRITICAL":
        if family_green and critical_persistence <= 1 and breach48 == 0 and open_R > 0:
            return "CRITICAL_RECOVERY_TEST", "PAUSE_STACKING_ONE_MORE_CHECK", "CRITICAL asset state but family is GREEN, basket is positive, and no runner breach. Run one-candle recovery test before trimming."
        if breach96 > 0 or breach48 > 0:
            return "PROTECTIVE_MODE", "CLOSE_BREACHED_MATURE_RUNNERS_THEN_REASSESS", "CRITICAL plus checkpoint breaches. Protect mature runners first."
        if family_bad or candidate_false_persistence >= 3 or giveback >= 60 or losing_pct >= 60:
            return "HARD_DEFENCE_CANDIDATE", "REDUCE_WEAKEST_MATURE_30_TO_50_PERCENT", "CRITICAL confirmed by family/support/giveback/loss pressure. Larger trim is justified."
        return "CRITICAL_CONFIRMATION_NEEDED", "PAUSE_STACKING_MONITOR_MATURE_RUNNERS", "CRITICAL alone is not enough; family/support still not fully confirming broad failure."

    return "UNKNOWN", "HOLD", "Unknown status; default to hold/review."


def defence_escalation_rows(limit: int = 200, latest_only: bool = True) -> List[Dict[str, Any]]:
    init_db()
    limit = max(1, min(int(limit or 200), 2000))
    out: List[Dict[str, Any]] = []
    with get_conn() as conn:
        if latest_only:
            rows = conn.execute("""
                SELECT t.*
                FROM tide_turn_checks t
                INNER JOIN (
                    SELECT asset, MAX(id) AS max_id
                    FROM tide_turn_checks
                    GROUP BY asset
                ) x ON t.asset = x.asset AND t.id = x.max_id
                ORDER BY t.asset ASC
            """).fetchall()
        else:
            rows = conn.execute("""
                SELECT *
                FROM tide_turn_checks
                ORDER BY id DESC
                LIMIT ?
            """, (limit,)).fetchall()

        for r in rows:
            asset = safe_str(r["asset"])
            family_row = _latest_family_check_for_asset(conn, asset, r["latest_signal_time"])
            row_id = int(safe_float(r["id"]) or 0)
            red_persist = _count_consecutive_asset_states(conn, asset, {"RED", "CRITICAL"}, max_id=row_id)
            critical_persist = _count_consecutive_asset_states(conn, asset, {"CRITICAL"}, max_id=row_id)
            non_green_persist = _count_consecutive_asset_states(conn, asset, {"AMBER", "RED", "CRITICAL"}, max_id=row_id)
            cand_false_persist = _count_consecutive_candidate_false(conn, asset, max_id=row_id)
            mature = _mature_runner_counts(conn, asset)
            broker_open_count = int(mature.get("open_count") or 0)
            broker_open_pnl = safe_float(mature.get("open_current_pnl_50risk")) or 0.0
            risk_unit = safe_float(effective_broker_shadow_auto_risk_amount()) or 0.0
            broker_open_r = (broker_open_pnl / risk_unit) if risk_unit > 0 else 0.0
            stage, action, decision_reason = _defence_escalation_decision(r, family_row, red_persist, critical_persist, cand_false_persist, mature)
            giveback = safe_float(r["basket_giveback_pct"]) or 0.0
            out.append({
                "asset": asset,
                "family": get_basket_family(asset),
                "latest_signal_time": r["latest_signal_time"],
                "open_trades": broker_open_count,
                "basket_phase": basket_phase_from_count(broker_open_count),
                "asset_status": r["tide_status"],
                "asset_score": r["tide_turn_score"],
                "asset_tiered_action_old": r["tiered_action"],
                "family_status": family_row["family_status"] if family_row else None,
                "family_action": family_row["family_action"] if family_row else None,
                "family_giveback_pct": safe_float(family_row["basket_giveback_pct"]) if family_row else None,
                "open_basket_pnl_50risk": broker_open_pnl,
                "open_basket_R": broker_open_r,
                "basket_high_water_pnl_50risk": safe_float(r["basket_high_water_pnl_50risk"]),
                "basket_giveback_pct": giveback,
                "giveback_band": _giveback_band(giveback),
                "losing_trade_pct": safe_float(r["losing_trade_pct"]),
                "latest_candidate": bool(r["latest_candidate"]),
                "candidate_true_last_3": int(safe_float(r["candidate_true_last_3"]) or 0),
                "candidate_true_last_6": int(safe_float(r["candidate_true_last_6"]) or 0),
                "red_or_critical_persistence": red_persist,
                "critical_persistence": critical_persist,
                "non_green_persistence": non_green_persist,
                "candidate_false_persistence": cand_false_persist,
                "runners_48h_plus": mature["count_48h_plus"],
                "runners_72h_plus": mature["count_72h_plus"],
                "runners_96h_plus": mature["count_96h_plus"],
                "runners_120h_plus": mature["count_120h_plus"],
                "breach_48_checkpoint_count": mature["breach_48_checkpoint_count"],
                "breach_96_checkpoint_count": mature["breach_96_checkpoint_count"],
                "breach_48_trade_ids": ",".join(mature.get("breach_48_trade_ids", [])),
                "breach_96_trade_ids": ",".join(mature.get("breach_96_trade_ids", [])),
                "close_candidate_trade_ids": ",".join(mature.get("close_candidate_trade_ids", [])),
                "close_candidate_count": mature.get("close_candidate_count", 0),
                "close_candidate_current_pnl_50risk": mature.get("close_candidate_current_pnl_50risk", 0.0),
                "checkpoint_giveback_50risk": mature.get("checkpoint_giveback_50risk", 0.0),
                "defence_stage": stage,
                "proposed_action": action,
                "decision_reason": decision_reason,
                "raw_reason": r["reason"],
            })
    return out


