def build_advice_outcome_dashboard_html() -> str:
    try:
        rows = advice_outcome_summary_rows(200)
        grouped = advice_outcome_group_summary(rows)
    except Exception as e:
        return f"""
        <details>
            <summary>Basket Advice Outcome Tracker</summary>
            <div class="small">Advice outcome tracker unavailable: {esc(e)}</div>
        </details>
        """

    def horizon_cell(v: Any) -> str:
        fv = safe_float(v)
        if fv is None:
            return "<td class='muted'>—</td>"
        return f'<td class="{pnl_class(fv)}">{money(fv)}</td>'

    group_rows = ""
    for g in grouped[:50]:
        latest_avg = safe_float(g.get("avg_follow_advice_vs_hold_latest_50risk")) or 0.0
        latest_total = safe_float(g.get("total_follow_advice_vs_hold_latest_50risk")) or 0.0
        group_rows += f"""
        <tr>
            <td><strong>{esc(g.get('asset'))}</strong></td>
            <td>{esc(g.get('tiered_action'))}</td>
            <td>{esc(g.get('basket_phase'))}</td>
            <td>{esc(g.get('advice_count'))}</td>
            <td class="{pnl_class(latest_avg)}">{money(latest_avg)}</td>
            <td class="{pnl_class(latest_total)}"><strong>{money(latest_total)}</strong></td>
            {horizon_cell(g.get('avg_follow_advice_vs_hold_1h_50risk'))}
            {horizon_cell(g.get('avg_follow_advice_vs_hold_4h_50risk'))}
            {horizon_cell(g.get('avg_follow_advice_vs_hold_12h_50risk'))}
            {horizon_cell(g.get('avg_follow_advice_vs_hold_24h_50risk'))}
            <td>{esc(g.get('advice_help_count'))}</td>
            <td>{esc(g.get('holding_better_count'))}</td>
            <td>{esc(g.get('neutral_count'))}</td>
        </tr>
        """
    if not group_rows:
        group_rows = "<tr><td colspan='13'>No actionable advice outcome rows yet.</td></tr>"

    detail_rows = ""
    for r in rows[:120]:
        selected_count = int(r.get("selected_count") or 0)
