def execution_audit_summary_rows(limit: int = 50) -> List[Dict[str, Any]]:
    """Return a compact execution-audit view for dashboard/API use.

    The full raw OANDA payload is deliberately kept in /execution-audit and CSV exports,
    but that JSON is too large for quick checks. This summary keeps only the useful
    reconciliation fields.
    """
    limit = max(1, min(int(limit or 50), 500))
    with get_conn() as conn:
        rows = conn.execute("SELECT * FROM execution_audit_events ORDER BY id DESC LIMIT ?", (limit,)).fetchall()

    out: List[Dict[str, Any]] = []
    for r in rows:
        d = dict(r)
        response_raw = d.get("response_summary_json") or ""
        response_obj = {}
        if response_raw:
            try:
                response_obj = json.loads(response_raw)
            except Exception:
                response_obj = {}

        data = response_obj.get("data", {}) if isinstance(response_obj, dict) else {}
        if not isinstance(data, dict):
            data = {}

        # Try to pull useful broker IDs/prices even when older audit rows only have raw message.
        broker_order_id = safe_str(d.get("broker_order_id") or data.get("lastTransactionID") or "")
        broker_trade_id = safe_str(d.get("broker_trade_id") or "")
        actual_price = d.get("actual_price")
        filled_units = d.get("filled_units")

        fill_candidates = [
            data.get("orderFillTransaction"),
            data.get("longOrderFillTransaction"),
            data.get("shortOrderFillTransaction"),
        ]
        for fill in fill_candidates:
            if not isinstance(fill, dict):
                continue
            if not broker_order_id:
                broker_order_id = safe_str(fill.get("orderID") or fill.get("id") or broker_order_id)
            if actual_price in (None, "", 0):
                actual_price = safe_float(fill.get("price"))
            if filled_units in (None, "", 0):
                filled_units = safe_float(fill.get("units"))
            trade_opened = fill.get("tradeOpened")
            if isinstance(trade_opened, dict) and not broker_trade_id:
                broker_trade_id = safe_str(trade_opened.get("tradeID") or "")
            trades_closed = fill.get("tradesClosed")
            if isinstance(trades_closed, list) and trades_closed and not broker_trade_id:
                broker_trade_id = safe_str(trades_closed[0].get("tradeID") or "") if isinstance(trades_closed[0], dict) else broker_trade_id

        out.append({
            "id": d.get("id"),
            "created_at_utc": d.get("created_at_utc"),
            "mode": d.get("mode"),
            "action": d.get("action"),
            "instrument": d.get("instrument") or d.get("asset"),
            "side": d.get("side"),
            "requested_units": d.get("requested_units"),
            "filled_units": filled_units,
            "close_units": d.get("close_units"),
            "risk_amount": d.get("risk_amount"),
            "sl_pct": d.get("sl_pct"),
            "estimated_risk": d.get("estimated_risk"),
            "actual_price": actual_price,
            "slippage_pct": d.get("slippage_pct"),
            "spread_pct": d.get("spread_pct"),
            "broker_order_id": broker_order_id,
            "broker_trade_id": broker_trade_id or d.get("trade_id"),
            "success": bool(d.get("success")),
            "retry_count": d.get("retry_count"),
            "close_all_required": bool(d.get("close_all_required")),
            "confirmed_flat": bool(d.get("broker_position_confirmed_flat")),
            "response_status_code": d.get("response_status_code"),
            "message": safe_str(d.get("message"))[:220],
        })
    return out


@app.get("/execution-audit-summary")
def execution_audit_summary(limit: int = 50) -> Dict[str, Any]:
    init_db()
    rows = execution_audit_summary_rows(limit)
    successes = sum(1 for r in rows if r.get("success"))
    failures = len(rows) - successes
    return {
        "status": "ok",
        "count": len(rows),
        "successes": successes,
        "failures": failures,
        "execution_audit_summary": rows,
        "time_utc": now_utc_iso(),
    }


