@app.get("/broker/oanda/preview-diagnostics")
def broker_oanda_preview_diagnostics(limit: int = 50) -> Dict[str, Any]:
    """Recent broker preview/order failures with explicit failure codes."""
    rows = broker_action_queue_rows(limit)
    out = []
    for r in rows:
        d = dict(r)
        try:
            preview = json.loads(d.get("preview_json") or "{}")
        except Exception:
            preview = {}
        if safe_str(d.get("action")).lower() != "place_risk_order":
            continue
        code = safe_str(preview.get("failure_code"))
        if not code and safe_str(d.get("status")).upper() not in {"WAITING_PRICE_RETRY", "MISSED_BROKER_ENTRY_RETRY_EXPIRED", "AUTO_PREVIEW_FAILED", "EXECUTION_PREVIEW_ERROR", "PREVIEW_ERROR"}:
            continue
        out.append({
            "id": d.get("id"),
            "created_at_utc": d.get("created_at_utc"),
            "updated_at_utc": d.get("updated_at_utc"),
            "status": d.get("status"),
            "shadow_trade_id": d.get("shadow_trade_id"),
            "asset": d.get("shadow_asset"),
            "instrument": d.get("instrument"),
            "side": d.get("side"),
            "failure_code": code or "UNKNOWN",
            "reason": preview_failure_summary(preview) if preview else safe_str(d.get("reason") or d.get("notes")),
            "retryable_preview": bool(preview.get("retryable_preview") or preview.get("retryable_cost_guard")),
            "preview_attempts": preview.get("preview_attempts"),
            "spread_pct": safe_float(preview.get("spread_pct")),
            "max_spread_pct": safe_float(preview.get("max_spread_pct")),
            "estimated_entry_cost_pct_of_risk": safe_float(preview.get("estimated_entry_cost_pct_of_risk")),
            "max_entry_cost_pct_of_risk": safe_float(preview.get("max_entry_cost_pct_of_risk")),
            "notes": d.get("notes"),
        })
    return {"status": "ok", "count": len(out), "diagnostics": out, "time_utc": now_utc_iso()}


@app.get("/export/broker-action-queue.csv")
def export_broker_action_queue_csv(limit: int = 1000) -> Response:
    init_db()
    rows = broker_action_queue_rows(limit)
    output = io.StringIO()
    fieldnames = list(rows[0].keys()) if rows else [
        "id", "created_at_utc", "updated_at_utc", "status", "mode", "source", "action",
        "shadow_trade_id", "shadow_asset", "family", "instrument", "side", "risk_amount",
        "sl_pct", "requested_units", "estimated_risk", "preview_price", "reason",
        "executed_audit_id", "broker_trade_link_id", "executed_at_utc", "cancelled_at_utc", "notes"
    ]
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow(row)
    return Response(
        content=output.getvalue(),
        media_type="text/csv",
        headers={"Content-Disposition": 'attachment; filename="broker-action-queue.csv"'},
    )



def _count_oanda_allowed_open_exposure() -> Dict[str, Any]:
    """Return counts/details for current allowed OANDA exposure.

    Used before wiping local broker test records so we do not hide evidence while
    demo broker exposure is still open.
    """
    allowed = set(BROKER_ALLOWED_INSTRUMENTS or [])
    trades_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openTrades")
    positions_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")
    if not trades_resp.get("ok") or not positions_resp.get("ok"):
        return {
            "ok": False,
            "error": "Could not verify OANDA open trades/positions before wipe.",
            "trades_response_ok": trades_resp.get("ok"),
            "positions_response_ok": positions_resp.get("ok"),
            "trades_error": trades_resp.get("error", ""),
            "positions_error": positions_resp.get("error", ""),
        }

    trades = trades_resp.get("data", {}).get("trades", []) or []
    positions = positions_resp.get("data", {}).get("positions", []) or []
    if allowed:
        trades = [t for t in trades if safe_str(t.get("instrument")) in allowed]
        positions = [p for p in positions if safe_str(p.get("instrument")) in allowed]

    return {
        "ok": True,
        "open_trade_count": len(trades),
        "open_position_count": len(positions),
        "open_trades": trades,
        "open_positions": positions,
    }


async def wipe_broker_test_data_impl(request: Request) -> Dict[str, Any]:
    """Wipe local broker-test tables after confirming OANDA is flat.

    This clears only local testing/audit/link/queue records. It does not touch
    strategy research tables or any OANDA broker account data.
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    confirm = safe_str(payload.get("confirm") or payload.get("confirmation") or "")
    if confirm != "WIPE_BROKER_TEST_DATA":
        return {
            "status": "blocked",
            "ok": False,
            "reason": "Send confirm='WIPE_BROKER_TEST_DATA' to wipe local broker test records.",
            "time_utc": now_utc_iso(),
        }

    include_snapshots = parse_bool(payload.get("include_broker_snapshots"), False)
    force = parse_bool(payload.get("force"), False)

    exposure = _count_oanda_allowed_open_exposure() if OANDA_ENABLED else {"ok": True, "open_trade_count": 0, "open_position_count": 0, "open_trades": [], "open_positions": []}
    if not exposure.get("ok") and not force:
        return {"status": "blocked", "ok": False, "reason": exposure.get("error"), "exposure_check": exposure, "time_utc": now_utc_iso()}
    if not force and (int(exposure.get("open_trade_count") or 0) > 0 or int(exposure.get("open_position_count") or 0) > 0):
        return {
            "status": "blocked",
            "ok": False,
            "reason": "OANDA still has open allowed trades/positions. Close broker exposure before wiping test records.",
            "exposure_check": exposure,
            "time_utc": now_utc_iso(),
        }

    tables = ["execution_audit_events", "broker_action_queue", "broker_trade_links"]
    if include_snapshots:
        tables.append("broker_snapshots")

    deleted_counts: Dict[str, int] = {}
    with get_conn() as conn:
        for table in tables:
            before = conn.execute(f"SELECT COUNT(*) AS c FROM {table}").fetchone()["c"]
            conn.execute(f"DELETE FROM {table}")
            deleted_counts[table] = int(before or 0)
            try:
                conn.execute("DELETE FROM sqlite_sequence WHERE name = ?", (table,))
            except Exception:
                pass
        conn.commit()

    return {
        "status": "ok",
        "ok": True,
        "message": "Local broker test records wiped. OANDA broker exposure was verified flat first.",
        "deleted_counts": deleted_counts,
        "include_broker_snapshots": include_snapshots,
        "exposure_check": {k: v for k, v in exposure.items() if k not in {"open_trades", "open_positions"}},
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/oanda/test/wipe-broker-test-data")
async def broker_oanda_test_wipe_broker_test_data(request: Request) -> Dict[str, Any]:
    return await wipe_broker_test_data_impl(request)


@app.post("/broker/oanda/test/wipe-test-data")
async def broker_oanda_test_wipe_test_data_alias(request: Request) -> Dict[str, Any]:
    return await wipe_broker_test_data_impl(request)


# ============================================================
# BROKER DEMO MIRROR RESET
# ============================================================

async def reset_broker_demo_mirror_impl(request: Request) -> Dict[str, Any]:
    """Close current OANDA demo mirror exposure, then wipe local broker mirror/test records.

    This is for cleaning out backfilled/testing broker links so the OANDA account
    can start fresh and only mirror newly-created shadow trades. It does not touch
    strategy research data, raw signals, shadow open/closed trades, basket logs, or
    performance tables.
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    confirm = safe_str(payload.get("confirm") or payload.get("confirmation") or "")
    if confirm != "RESET_BROKER_DEMO_MIRROR":
        return {
            "status": "blocked",
            "ok": False,
            "reason": "Send confirm='RESET_BROKER_DEMO_MIRROR' to close demo broker mirror exposure and wipe local broker mirror records.",
            "time_utc": now_utc_iso(),
        }

    if safe_str(OANDA_ENV).lower() != "practice":
        return {
            "status": "blocked",
            "ok": False,
            "reason": "Broker demo mirror reset is practice/live-controlled. OANDA_ENV must be 'practice'.",
            "oanda_env": OANDA_ENV,
            "time_utc": now_utc_iso(),
        }

    close_oanda_positions = parse_bool(payload.get("close_oanda_positions"), True)
    wipe_local_records = parse_bool(payload.get("wipe_local_records"), True)
    include_broker_snapshots = parse_bool(payload.get("include_broker_snapshots"), False)

    requested = payload.get("instruments") or list(BROKER_ALLOWED_INSTRUMENTS)
    if isinstance(requested, str):
        instruments = [normalise_oanda_instrument(x) for x in requested.split(",")]
    else:
        instruments = [normalise_oanda_instrument(x) for x in requested]
    instruments = [x for x in dict.fromkeys(instruments) if x]

    try:
        max_retries = int(payload.get("max_retries", os.getenv("BROKER_CLOSE_ALL_MAX_RETRIES", "3")))
    except Exception:
        max_retries = 3
    max_retries = max(0, min(max_retries, 10))

    try:
        retry_sleep_seconds = float(payload.get("retry_sleep_seconds", os.getenv("BROKER_CLOSE_ALL_RETRY_SLEEP_SECONDS", "0.75")))
    except Exception:
        retry_sleep_seconds = 0.75
    retry_sleep_seconds = max(0.0, min(retry_sleep_seconds, 5.0))

    close_result: Dict[str, Any] = {
        "skipped": not close_oanda_positions,
        "confirmed_flat": False,
        "passes": [],
        "remaining_allowed_positions": [],
    }

    def allowed_open_positions() -> Tuple[bool, List[Dict[str, Any]], Dict[str, Any]]:
        resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")
        if not resp.get("ok"):
            return False, [], resp
        positions = resp.get("data", {}).get("positions", []) or []
        remaining = [p for p in positions if safe_str(p.get("instrument")) in set(instruments)]
        return True, remaining, resp

    if close_oanda_positions:
        safety = oanda_safety_state()
        if not safety.get("orders_allowed"):
            return {
                "status": "blocked",
                "ok": False,
                "reason": "OANDA close is blocked by broker safety state. To reset existing demo exposure, unlock practice execution first or close positions manually, then rerun with close_oanda_positions=false.",
                "safety": safety,
                "time_utc": now_utc_iso(),
            }

        ok, remaining, resp = allowed_open_positions()
        if not ok:
            return {
                "status": "error",
                "ok": False,
                "reason": "Could not fetch OANDA open positions before reset.",
                "response": resp,
                "time_utc": now_utc_iso(),
            }

        passes = []
        initial_remaining_count = len(remaining)
        for pass_index in range(max_retries + 1):
            if not remaining:
                passes.append({
                    "pass": pass_index,
                    "skipped": True,
                    "reason": "Already flat before this pass.",
                    "remaining_before_count": 0,
                    "results": [],
                    "remaining_after_count": 0,
                })
                break

            pass_results = []
            for pos in remaining:
                instrument = safe_str(pos.get("instrument"))
                long_units = safe_float((pos.get("long") or {}).get("units")) or 0.0
                short_units = safe_float((pos.get("short") or {}).get("units")) or 0.0
                close_body: Dict[str, Any] = {}
                if long_units > 0:
                    close_body["longUnits"] = "ALL"
                if short_units < 0:
                    close_body["shortUnits"] = "ALL"
                if close_body:
                    close_resp = oanda_write_request(
                        f"/v3/accounts/{OANDA_ACCOUNT_ID}/positions/{urllib.parse.quote(instrument)}/close",
                        "PUT",
                        close_body,
                    )
                    pass_results.append({
                        "instrument": instrument,
                        "ok": bool(close_resp.get("ok")),
                        "request": close_body,
                        "long_units_before": long_units,
                        "short_units_before": short_units,
                        "response_status_code": close_resp.get("status_code"),
                        "error": close_resp.get("error", ""),
                    })
                else:
                    pass_results.append({
                        "instrument": instrument,
                        "ok": True,
                        "skipped": True,
                        "reason": "No non-zero side to close.",
                    })

            if retry_sleep_seconds > 0:
                time.sleep(retry_sleep_seconds)

            ok, after_remaining, after_resp = allowed_open_positions()
            passes.append({
                "pass": pass_index,
                "remaining_before_count": len(remaining),
                "results": pass_results,
                "recheck_ok": ok,
                "remaining_after_count": len(after_remaining) if ok else None,
                "remaining_after": after_remaining if ok else [],
                "recheck_error": after_resp.get("error", "") if not ok else "",
            })
            if not ok:
                break
            remaining = after_remaining
            if not remaining:
                break

        confirmed_flat = len(remaining) == 0
        close_result = {
            "skipped": False,
            "confirmed_flat": confirmed_flat,
            "requested_instruments": instruments,
            "initial_remaining_count": initial_remaining_count,
            "remaining_allowed_positions": remaining,
            "max_retries": max_retries,
            "passes_run": len(passes),
            "passes": passes,
        }

        log_execution_audit_event(
            "practice_manual", "INDEX_BASKET", "", "reset_broker_demo_mirror_close_until_flat", confirmed_flat,
            "broker demo mirror reset: close existing allowed OANDA exposure before wiping local links", "",
            retry_count=max(0, len(passes) - 1), close_all_required=True,
            broker_position_confirmed_flat=confirmed_flat, raw=close_result,
        )

        if not confirmed_flat:
            return {
                "status": "warning",
                "ok": False,
                "reason": "OANDA exposure was not confirmed flat. Local broker records were not wiped.",
                "close_result": close_result,
                "time_utc": now_utc_iso(),
            }

    deleted_counts: Dict[str, int] = {}
    if wipe_local_records:
        tables = ["execution_audit_events", "broker_action_queue", "broker_trade_links"]
        if include_broker_snapshots:
            tables.append("broker_snapshots")
        with get_conn() as conn:
            for table in tables:
                before = conn.execute(f"SELECT COUNT(*) AS c FROM {table}").fetchone()["c"]
                conn.execute(f"DELETE FROM {table}")
                deleted_counts[table] = int(before or 0)
                try:
                    conn.execute("DELETE FROM sqlite_sequence WHERE name = ?", (table,))
                except Exception:
                    pass
            conn.commit()

    # v8.2: after a reset, only broker-mirror shadow trades created from this point forward.
    # This avoids polluting broker-vs-shadow drift with old/backfilled trades.
    new_auto_watermark_utc = now_utc_iso()
    set_broker_runtime_setting("broker_shadow_auto_min_entry_utc", new_auto_watermark_utc)

    exposure_after = _count_oanda_allowed_open_exposure() if OANDA_ENABLED else {"ok": True, "open_trade_count": 0, "open_position_count": 0}

    return {
        "status": "ok",
        "ok": True,
        "message": "Broker demo mirror reset complete. Existing allowed OANDA exposure was closed before local broker mirror/test records were wiped.",
        "close_oanda_positions": close_oanda_positions,
        "wipe_local_records": wipe_local_records,
        "include_broker_snapshots": include_broker_snapshots,
        "deleted_counts": deleted_counts,
        "close_result": close_result,
        "exposure_after": {k: v for k, v in exposure_after.items() if k not in {"open_trades", "open_positions"}},
        "new_shadow_auto_min_entry_utc": new_auto_watermark_utc,
        "note": "Fresh-only broker mirroring is now active. Existing open shadow trades older than this watermark will not be auto-backfilled into OANDA.",
        "time_utc": now_utc_iso(),
    }


class _JsonPayloadRequest:
    def __init__(self, payload: Dict[str, Any]):
        self._payload = payload

    async def json(self) -> Dict[str, Any]:
        return self._payload


def archive_sqlite_db(label: str = "pre_june_full_demo_reset") -> Dict[str, Any]:
    """Copies the live SQLite DB to /data/archives before destructive demo resets."""
    try:
        src = Path(DB_PATH)
        if not src.exists():
            return {"ok": False, "error": f"DB_PATH does not exist: {DB_PATH}"}
        archive_dir = src.parent / "archives"
        archive_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
        safe_label = ''.join(ch if ch.isalnum() or ch in {'_', '-'} else '_' for ch in safe_str(label) or 'archive')
        dest = archive_dir / f"{safe_label}_{stamp}.sqlite"
        shutil.copy2(src, dest)
        return {"ok": True, "archive_path": str(dest), "source_path": str(src), "created_at_utc": now_utc_iso()}
    except Exception as e:
        return {"ok": False, "error": str(e), "time_utc": now_utc_iso()}


def wipe_full_demo_local_tables() -> Dict[str, int]:
    """Wipe all live/demo operational tables after an archive has been made.

    broker_runtime_settings and system_events are retained so the app can record the reset
    and enforce a fresh-only watermark immediately after the wipe.
    """
    tables = [
        "raw_signals", "open_trades", "closed_trades", "decision_log",
        "basket_risk_checks", "entry_confirmation_checks", "tide_turn_checks",
        "dynamic_exit_shadow_trades", "active_basket_cycles", "active_family_basket_cycles",
        "family_basket_checks", "basket_exposure_checks", "partial_defence_simulations",
        "post48_review_log", "milestone_snapshots", "weekend_gap_watch_checks",
        "advice_outcome_audit", "execution_audit_events", "broker_snapshots",
        "broker_trade_links", "broker_managed_stop_events", "broker_action_queue",
        "broker_financing_transactions", "broker_cost_sync_state",
    ]
    deleted: Dict[str, int] = {}
    with get_conn() as conn:
        existing = {r["name"] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        for table in tables:
            if table not in existing:
                continue
            before = conn.execute(f"SELECT COUNT(*) AS c FROM {table}").fetchone()["c"]
            conn.execute(f"DELETE FROM {table}")
            deleted[table] = int(before or 0)
            try:
                conn.execute("DELETE FROM sqlite_sequence WHERE name = ?", (table,))
            except Exception:
                pass
        conn.commit()
    return deleted


@app.post("/broker/oanda/test/start-june-full-demo")
async def broker_oanda_test_start_june_full_demo(request: Request) -> Dict[str, Any]:
    """Archive current data, flatten index broker exposure, then start a clean June full-demo DB state.

    Confirmation required: confirm='START_JUNE_FULL_DEMO'.
    Default behaviour:
    - copy SQLite DB to /data/archives first
    - close only configured index demo instruments on OANDA live account
    - wipe local operational/research tables so June starts from zero
    - set fresh-only broker watermark to the reset timestamp
    - keep metals research-only and broker-disabled
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    confirm = safe_str(payload.get("confirm") or payload.get("confirmation") or "")
    if confirm != "START_JUNE_FULL_DEMO":
        return {
            "status": "blocked",
            "ok": False,
            "reason": "Send confirm='START_JUNE_FULL_DEMO' to archive current DB, flatten OANDA live account index exposure, and wipe local state for the June full demo.",
            "time_utc": now_utc_iso(),
        }

    if safe_str(OANDA_ENV).lower() != "practice":
        return {"status": "blocked", "ok": False, "reason": "June full-demo reset is restricted in live mode. OANDA_ENV must be practice.", "oanda_env": OANDA_ENV, "time_utc": now_utc_iso()}

    archive_result = archive_sqlite_db("pre_june_full_demo_reset") if parse_bool(payload.get("archive_db"), True) else {"ok": True, "skipped": True}
    if not archive_result.get("ok") and not parse_bool(payload.get("force_without_archive"), False):
        return {"status": "blocked", "ok": False, "reason": "Archive failed. Reset not performed.", "archive_result": archive_result, "time_utc": now_utc_iso()}

    close_oanda_positions = parse_bool(payload.get("close_oanda_positions"), True)
    close_instruments = payload.get("instruments") or sorted(JUNE_FULL_DEMO_CLOSE_INSTRUMENTS)
    if isinstance(close_instruments, str):
        close_instruments = [x.strip() for x in close_instruments.split(",") if x.strip()]

    close_result = {"skipped": True}
    if close_oanda_positions:
        reset_payload = {
            "confirm": "RESET_BROKER_DEMO_MIRROR",
            "close_oanda_positions": True,
            "wipe_local_records": False,
            "include_broker_snapshots": False,
            "instruments": close_instruments,
            "max_retries": payload.get("max_retries", 3),
            "retry_sleep_seconds": payload.get("retry_sleep_seconds", 0.75),
        }
        close_result = await reset_broker_demo_mirror_impl(_JsonPayloadRequest(reset_payload))
        if not close_result.get("ok") and not parse_bool(payload.get("force_after_close_warning"), False):
            return {
                "status": "blocked",
                "ok": False,
                "reason": "OANDA index exposure was not confirmed flat, so local state was not wiped.",
                "archive_result": archive_result,
                "close_result": close_result,
                "time_utc": now_utc_iso(),
            }

    deleted_counts = wipe_full_demo_local_tables()
    reset_time = now_utc_iso()
    set_broker_runtime_setting("broker_shadow_auto_min_entry_utc", reset_time)
    set_broker_runtime_setting("june_full_demo_started_at_utc", reset_time)
    set_broker_runtime_setting("june_full_demo_name", JUNE_FULL_DEMO_NAME)
    log_system_event(
        "june_full_demo_started",
        f"{JUNE_FULL_DEMO_NAME} started. Broker assets={sorted(JUNE_FULL_DEMO_BROKER_ASSETS)} research_only={sorted(JUNE_FULL_DEMO_RESEARCH_ONLY_ASSETS)} sl={JUNE_FULL_DEMO_INDEX_SL_PCT}% cap={BROKER_SHADOW_AUTO_MAX_OPEN_LINKS}. Archive={archive_result.get('archive_path','')}",
    )

    exposure_after = _count_oanda_allowed_open_exposure() if OANDA_ENABLED else {"ok": True, "open_trade_count": 0, "open_position_count": 0}
    return {
        "status": "ok",
        "ok": True,
        "message": f"{JUNE_FULL_DEMO_NAME} reset complete. New broker mirroring will start from fresh TradingView signals only.",
        "archive_result": archive_result,
        "close_result": close_result,
        "deleted_counts": deleted_counts,
        "new_shadow_auto_min_entry_utc": reset_time,
        "scope": {
            "broker_assets": sorted(JUNE_FULL_DEMO_BROKER_ASSETS),
            "research_only_assets": sorted(JUNE_FULL_DEMO_RESEARCH_ONLY_ASSETS),
            "index_sl_pct": JUNE_FULL_DEMO_INDEX_SL_PCT,
            "max_open_links": BROKER_SHADOW_AUTO_MAX_OPEN_LINKS,
            "allow_open_scan_backfill": bool(BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL),
        },
        "exposure_after": {k: v for k, v in exposure_after.items() if k not in {"open_trades", "open_positions"}},
        "time_utc": reset_time,
    }


