@app.post("/broker/oanda/test/queue-risk-order")
async def broker_oanda_test_queue_risk_order(request: Request) -> Dict[str, Any]:
    """Creates a dry-run broker intent from a risk-sized order preview. It does not place an order."""
    init_db()
    payload = await request.json()
    instrument = normalise_oanda_instrument(payload.get("instrument") or payload.get("asset") or "")
    side = safe_str(payload.get("side") or "buy").lower()
    shadow_trade_id = safe_str(payload.get("shadow_trade_id") or payload.get("trade_id") or f"MANUAL_QUEUE_{int(time.time())}")
    shadow_asset = safe_str(payload.get("shadow_asset") or payload.get("asset") or instrument)
    family = safe_str(payload.get("family") or ("INDEX_BASKET" if instrument in ("SPX500_USD", "NAS100_USD") else ""))
    reason = safe_str(payload.get("reason") or "manual dry-run broker intent")

    preview = build_risk_order_preview(
        instrument=payload.get("instrument") or payload.get("asset") or "SPX500_USD",
        side=payload.get("side") or "buy",
        risk_amount=safe_float(payload.get("risk_amount")) if payload.get("risk_amount") is not None else None,
        sl_pct=safe_float(payload.get("sl_pct")) if payload.get("sl_pct") is not None else None,
    )
    if not preview.get("ok"):
        qid = create_broker_action_queue_item(
            "place_risk_order", instrument, side, shadow_trade_id, shadow_asset, family,
            reason=reason, preview=preview, status="PREVIEW_ERROR", notes=safe_str(preview.get("error", "preview failed")),
        )
        return {"status": "error", "ok": False, "queue_id": qid, "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}

    qid = create_broker_action_queue_item(
        "place_risk_order", instrument, side, shadow_trade_id, shadow_asset, family,
        risk_amount=safe_float(preview.get("risk_amount_requested")),
        sl_pct=safe_float(preview.get("sl_pct")),
        requested_units=safe_float(preview.get("signed_units")),
        estimated_risk=safe_float(preview.get("estimated_risk_amount")),
        preview_price=safe_float(preview.get("current_mid_price")),
        reason=reason, preview=preview, status="QUEUED_DRY_RUN",
        notes="Dry-run only. No broker order placed.",
    )
    return {"status": "ok", "ok": True, "queue_id": qid, "queued_action": "place_risk_order", "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/queue-shadow-open-trade")
async def broker_oanda_test_queue_shadow_open_trade(request: Request) -> Dict[str, Any]:
    """
    Creates a dry-run broker queue item from an existing Railway shadow open trade.
    This is a manual bridge test only: it does not place an order.
    """
    init_db()
    payload = await request.json()
    shadow_trade_id = safe_str(payload.get("shadow_trade_id") or payload.get("trade_id") or "")
    if not shadow_trade_id:
        return {"status": "error", "ok": False, "error": "shadow_trade_id is required", "time_utc": now_utc_iso()}

    with get_conn() as conn:
        row = conn.execute("SELECT * FROM open_trades WHERE trade_id = ? LIMIT 1", (shadow_trade_id,)).fetchone()

    if not row:
        return {"status": "error", "ok": False, "error": f"open shadow trade not found: {shadow_trade_id}", "time_utc": now_utc_iso()}

    trade = dict(row)
    asset = safe_str(trade.get("asset") or "")
    direction = safe_str(trade.get("direction") or "long").lower()
    instrument = normalise_oanda_instrument(payload.get("instrument") or asset)
    side = safe_str(payload.get("side") or ("sell" if direction in ("short", "sell") else "buy")).lower()
    family = safe_str(payload.get("family") or ("INDEX_BASKET" if instrument in ("SPX500_USD", "NAS100_USD") else "METALS_BASKET" if instrument in ("XAU_USD", "XAG_USD") else ""))
    risk_amount = safe_float(payload.get("risk_amount")) if payload.get("risk_amount") is not None else BROKER_DEFAULT_RISK_TEST_AMOUNT
    sl_pct = safe_float(payload.get("sl_pct")) if payload.get("sl_pct") is not None else BROKER_DEFAULT_SL_PCT
    reason = safe_str(payload.get("reason") or "manual queue from existing shadow open trade")

    preview = build_risk_order_preview(
        instrument=instrument,
        side=side,
        risk_amount=risk_amount,
        sl_pct=sl_pct,
    )

    if not preview.get("ok"):
        qid = create_broker_action_queue_item(
            "place_risk_order", instrument, side, shadow_trade_id, asset, family,
            reason=reason, preview=preview, status="PREVIEW_ERROR", notes=safe_str(preview.get("error", "preview failed")),
        )
        return {"status": "error", "ok": False, "queue_id": qid, "shadow_trade": trade, "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}

    qid = create_broker_action_queue_item(
        "place_risk_order", instrument, side, shadow_trade_id, asset, family,
        risk_amount=safe_float(preview.get("risk_amount_requested")),
        sl_pct=safe_float(preview.get("sl_pct")),
        requested_units=safe_float(preview.get("signed_units")),
        estimated_risk=safe_float(preview.get("estimated_risk_amount")),
        preview_price=safe_float(preview.get("current_mid_price")),
        reason=reason, preview=preview, status="QUEUED_DRY_RUN",
        notes="Queued from existing Railway shadow open trade. No broker order placed.",
    )
    return {
        "status": "ok",
        "ok": True,
        "queue_id": qid,
        "queued_action": "place_risk_order",
        "source": "shadow_open_trade",
        "shadow_trade": trade,
        "preview": preview,
        "safety": oanda_safety_state(),
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/oanda/test/cancel-queued-action")
async def broker_oanda_test_cancel_queued_action(request: Request) -> Dict[str, Any]:
    init_db()
    payload = await request.json()
    queue_id = int(payload.get("queue_id") or 0)
    if queue_id <= 0:
        raise HTTPException(status_code=400, detail="queue_id is required")
    with get_conn() as conn:
        row = conn.execute("SELECT * FROM broker_action_queue WHERE id = ?", (queue_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail=f"queue_id {queue_id} not found")
        conn.execute("UPDATE broker_action_queue SET status = ?, updated_at_utc = ?, cancelled_at_utc = ?, notes = ? WHERE id = ?", (
            "CANCELLED", now_utc_iso(), now_utc_iso(), safe_str(payload.get("reason") or "manual cancel"), queue_id
        ))
        conn.commit()
    return {"status": "ok", "ok": True, "queue_id": queue_id, "message": "Queued action cancelled", "time_utc": now_utc_iso()}



@app.post("/broker/oanda/test/queue-close-linked-trade")
async def broker_oanda_test_queue_close_linked_trade(request: Request) -> Dict[str, Any]:
    """Queues a manual dry-run close intent for an existing broker trade link.

    This does not close anything. It creates an auditable intent to close one linked
    OANDA trade, ready for a separate manual execute call.
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    link_id = int(payload.get("broker_trade_link_id") or payload.get("link_id") or 0)
    shadow_trade_id = safe_str(payload.get("shadow_trade_id") or "")

    with get_conn() as conn:
        row = None
        if link_id > 0:
            row = conn.execute("SELECT * FROM broker_trade_links WHERE id = ?", (link_id,)).fetchone()
        elif shadow_trade_id:
            row = conn.execute(
                "SELECT * FROM broker_trade_links WHERE shadow_trade_id = ? ORDER BY id DESC LIMIT 1",
                (shadow_trade_id,),
            ).fetchone()

    if not row:
        raise HTTPException(status_code=404, detail="broker trade link not found; provide broker_trade_link_id or shadow_trade_id")

    link = dict(row)
    instrument = normalise_oanda_instrument(link.get("instrument") or "")
    side = safe_str(link.get("side") or "")
    broker_trade_id = safe_str(link.get("broker_trade_id") or "")
    status = safe_str(link.get("status") or "")

    if not broker_trade_id:
        raise HTTPException(status_code=400, detail="broker trade link has no broker_trade_id")

    reason = safe_str(payload.get("reason") or f"manual dry-run close intent for broker_trade_link_id={link.get('id')}")
    preview = {
        "ok": True,
        "action": "close_linked_trade",
        "broker_trade_link_id": link.get("id"),
        "shadow_trade_id": link.get("shadow_trade_id"),
        "instrument": instrument,
        "side": side,
        "broker_trade_id": broker_trade_id,
        "current_link_status": status,
        "close_units": "ALL",
        "note": "Dry-run close intent only. No broker close sent until execute-queued-action is called.",
    }

    qid = create_broker_action_queue_item(
        action="close_linked_trade",
        instrument=instrument,
        side=side,
        shadow_trade_id=safe_str(link.get("shadow_trade_id") or ""),
        shadow_asset=safe_str(link.get("shadow_asset") or instrument),
        family=safe_str(payload.get("family") or ("INDEX_BASKET" if instrument in ("SPX500_USD", "NAS100_USD") else "")),
        requested_units=safe_float(link.get("last_known_units")) or safe_float(link.get("filled_units")),
        reason=reason,
        preview=preview,
        status="QUEUED_DRY_RUN",
        notes="Dry-run close intent only. No broker close placed.",
    )
    with get_conn() as conn:
        conn.execute("UPDATE broker_action_queue SET broker_trade_link_id = ? WHERE id = ?", (int(link.get("id")), qid))
        conn.commit()

    return {"status": "ok", "ok": True, "queue_id": qid, "queued_action": "close_linked_trade", "broker_trade_link": link, "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/queue-close-until-flat")
async def broker_oanda_test_queue_close_until_flat(request: Request) -> Dict[str, Any]:
    """Queues a manual dry-run close-until-flat intent for one or more instruments.

    This does not close anything. It creates an auditable intent to run the same
    close-until-flat/reconciliation safety routine from a later manual execute call.
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    requested = payload.get("instruments") or list(BROKER_ALLOWED_INSTRUMENTS)
    if isinstance(requested, str):
        instruments = [normalise_oanda_instrument(x) for x in requested.split(",")]
    else:
        instruments = [normalise_oanda_instrument(x) for x in requested]
    instruments = [x for x in instruments if x]
    instruments = list(dict.fromkeys(instruments))

    validation_results = []
    valid_instruments = []
    for instrument in instruments:
        inst_ok, inst_msg = validate_manual_oanda_instrument(instrument)
        if inst_ok:
            valid_instruments.append(instrument)
        else:
            validation_results.append({"instrument": instrument, "ok": False, "error": inst_msg})

    if not valid_instruments:
        raise HTTPException(status_code=400, detail={"error": "No valid allowed instruments supplied", "validation_results": validation_results})

    try:
        max_retries = int(payload.get("max_retries", os.getenv("BROKER_CLOSE_ALL_MAX_RETRIES", "3")))
    except Exception:
        max_retries = 3
    max_retries = max(0, min(max_retries, 10))

    try:
        retry_sleep_seconds = float(payload.get("retry_sleep_seconds", os.getenv("BROKER_CLOSE_ALL_RETRY_SLEEP_SECONDS", "0.75")))
    except Exception:
        retry_sleep_seconds = 0.75
    retry_sleep_seconds = max(0.0, min(retry_sleep_seconds, 5.0))

    reason = safe_str(payload.get("reason") or "manual dry-run close-until-flat intent")
    family = safe_str(payload.get("family") or "INDEX_BASKET")
    shadow_trade_id = safe_str(payload.get("shadow_trade_id") or f"CLOSE_UNTIL_FLAT_{int(time.time())}")

    preview = {
        "ok": True,
        "action": "close_until_flat",
        "instruments": valid_instruments,
        "validation_results": validation_results,
        "max_retries": max_retries,
        "retry_sleep_seconds": retry_sleep_seconds,
        "family": family,
        "note": "Dry-run close-until-flat intent only. No broker close sent until execute-queued-action is called.",
    }

    qid = create_broker_action_queue_item(
        action="close_until_flat",
        instrument=",".join(valid_instruments),
        side="flat",
        shadow_trade_id=shadow_trade_id,
        shadow_asset=family,
        family=family,
        reason=reason,
        preview=preview,
        status="QUEUED_DRY_RUN",
        notes="Dry-run close-until-flat intent only. No broker close placed.",
    )

    return {"status": "ok", "ok": True, "queue_id": qid, "queued_action": "close_until_flat", "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}




def reclassify_market_closed_failures(limit: int = 20) -> Dict[str, Any]:
    """Convert recent market-closed EXECUTION_FAILED queue items into WAITING_MARKET_REOPEN.

    Useful for the first deployment after v9.1, where older failed queue rows may
    have been created before market-closed handling existed.
    """
    init_db()
    try:
        limit = max(1, min(int(limit), 100))
    except Exception:
        limit = 20
    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute("""
            SELECT * FROM broker_action_queue
            WHERE status LIKE '%FAILED%' OR status LIKE '%ERROR%'
            ORDER BY id DESC
            LIMIT ?
        """, (limit,)).fetchall()]
    updated = []
    for q in rows:
        qid = int(q.get("id") or 0)
        hay = {
            "status": q.get("status"),
            "notes": q.get("notes"),
            "preview_json": q.get("preview_json"),
            "reason": q.get("reason"),
        }
        if is_oanda_market_closed_response(hay):
            update_broker_action_queue_status(qid, "WAITING_MARKET_REOPEN", "Reclassified from failure to WAITING_MARKET_REOPEN after v9.1 market-closed handling deploy.")
            updated.append({"queue_id": qid, "old_status": q.get("status"), "action": q.get("action"), "instrument": q.get("instrument")})
    return {"status": "ok", "ok": True, "checked": len(rows), "reclassified": len(updated), "updated": updated, "time_utc": now_utc_iso()}


