@app.post("/broker/monthly-live-risk-review")
async def broker_monthly_live_risk_review(request: Request, x_webhook_secret: Optional[str] = Header(None)) -> Dict[str, Any]:
    """Preview/apply monthly risk-per-trade from current OANDA NAV.

    This is a deliberate manual control for the monthly live process. It updates
    broker_runtime_settings only; it does not place orders and does not alter
    existing/open trades. New auto broker entries use the new risk amount.
    """
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}
    body_secret = safe_str(body.get("webhook_secret") or body.get("secret")) if isinstance(body, dict) else ""
    query_secret = safe_str(request.query_params.get("secret") or "")
    if x_webhook_secret != WEBHOOK_SECRET and body_secret != WEBHOOK_SECRET and query_secret != WEBHOOK_SECRET:
        raise HTTPException(status_code=401, detail="Invalid WEBHOOK_SECRET")

    dry_run = bool((body or {}).get("dry_run", True))
    preview = build_monthly_live_risk_review_preview()
    if not preview.get("ok"):
        return preview

    if dry_run:
        preview["dry_run"] = True
        preview["message"] = "Preview only. Repost with dry_run=false and confirm=APPLY_MONTHLY_LIVE_RISK to update risk/trade."
        return preview

    if safe_str((body or {}).get("confirm")) != "APPLY_MONTHLY_LIVE_RISK":
        raise HTTPException(status_code=400, detail="Missing confirm=APPLY_MONTHLY_LIVE_RISK")

    proposed = safe_float(preview.get("proposed_risk_per_trade"))
    if proposed is None or proposed <= 0:
        raise HTTPException(status_code=400, detail="Invalid proposed risk amount")

    set_broker_runtime_setting("broker_shadow_auto_risk_amount", f"{proposed:.2f}")
    set_broker_runtime_setting("monthly_live_risk_last_review_utc", now_utc_iso())
    set_broker_runtime_setting("monthly_live_risk_last_nav", f"{safe_float(preview.get('nav')) or 0:.2f}")
    set_broker_runtime_setting("monthly_live_risk_last_raw_formula_risk", f"{safe_float(preview.get('raw_formula_risk')) or 0:.4f}")
    set_broker_runtime_setting("monthly_live_risk_last_applied_risk", f"{proposed:.2f}")
    log_system_event(
        "monthly_live_risk_review_applied",
        f"Applied monthly live risk: NAV={preview.get('nav')}, risk_pct={preview.get('risk_pct_of_nav')}%, previous={preview.get('current_risk_per_trade')}, new={proposed:.2f}, capped={preview.get('capped_by_monthly_increase')}"
    )
    preview["dry_run"] = False
    preview["applied"] = True
    preview["new_effective_risk_per_trade"] = effective_broker_shadow_auto_risk_amount()
    preview["message"] = "Monthly live risk updated. Applies to new broker entries only."
    return preview


# ============================================================
# BROKER EXECUTION PREFLIGHT
# ============================================================

def broker_execution_preflight() -> Dict[str, Any]:
    """Read-only go/no-go checklist for broker execution testing.

    This does not place orders. It checks whether the OANDA bridge, safety flags,
    reconciliation state, queue state, and allowed instruments are coherent.
    """
    init_db()
    now = now_utc_iso()
    safety = oanda_safety_state()
    config = oanda_config_status()
    checks: List[Dict[str, Any]] = []

    def add_check(name: str, ok: bool, level: str, message: str, data: Optional[Dict[str, Any]] = None) -> None:
        checks.append({
            "name": name,
            "ok": bool(ok),
            "level": level,
            "message": safe_str(message),
            "data": data or {},
        })

    add_check("OANDA enabled", bool(OANDA_ENABLED), "required", "OANDA_ENABLED must be true for broker tracking/execution tests.", {"OANDA_ENABLED": OANDA_ENABLED})
    add_check("Environment is allowed", safe_str(OANDA_ENV).lower() in {"practice", "live"}, "required", "OANDA_ENV must be practice or live. Live rollout uses OANDA_ENV=live.", {"OANDA_ENV": OANDA_ENV})
    add_check("Account configured", bool(safe_str(OANDA_ACCOUNT_ID)), "required", "OANDA_ACCOUNT_ID is present.", {"account_id": OANDA_ACCOUNT_ID})
    add_check("Token present", bool(config.get("token_present")), "required", "OANDA_API_TOKEN is present in Railway variables.", {"token_present": config.get("token_present")})
    add_check("Allowed instruments configured", bool(BROKER_ALLOWED_INSTRUMENTS), "required", "BROKER_ALLOWED_INSTRUMENTS should include only instruments we intend to test.", {"allowed_instruments": sorted(list(BROKER_ALLOWED_INSTRUMENTS))})

    health_resp = oanda_request("/v3/accounts") if OANDA_ENABLED else {"ok": False, "error": "OANDA_ENABLED is false"}
    add_check("OANDA API health", bool(health_resp.get("ok")), "required", "Railway can reach OANDA accounts endpoint.", {"status_code": health_resp.get("status_code"), "error": health_resp.get("error")})

    account_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/summary") if OANDA_ENABLED and safe_str(OANDA_ACCOUNT_ID) else {"ok": False, "error": "not configured"}
    account_summary = extract_oanda_account_summary(account_resp.get("data", {})) if account_resp.get("ok") else {}
    add_check("Account summary", bool(account_resp.get("ok")), "required", "OANDA account summary can be read.", {"nav": account_summary.get("NAV"), "balance": account_summary.get("balance"), "marginUsed": account_summary.get("marginUsed"), "error": account_resp.get("error")})

    pricing_resp = None
    pricing_ok = False
    price_count = 0
    try:
        instruments = sorted(list(BROKER_ALLOWED_INSTRUMENTS or []))
        if instruments and OANDA_ENABLED:
            pricing_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/pricing", params={"instruments": ",".join(instruments)})
            prices = pricing_resp.get("data", {}).get("prices", []) if pricing_resp.get("ok") else []
            price_count = len(prices or [])
            pricing_ok = bool(pricing_resp.get("ok")) and price_count > 0
    except Exception as e:
        pricing_resp = {"ok": False, "error": str(e)}
    add_check("Pricing available", pricing_ok, "required", "Current pricing can be read for allowed instruments.", {"price_count": price_count, "error": (pricing_resp or {}).get("error")})

    recon = broker_reconciliation_health()
    add_check("Broker reconciliation", bool(recon.get("ok")), "required", "Railway broker links and OANDA open trades are reconciled.", {"status": recon.get("status"), "issues": recon.get("issues"), "counts": recon.get("counts")})

    # Operational safety checks
    locked_safe = bool(BROKER_READ_ONLY and (not BROKER_EXECUTION_ENABLED) and BROKER_KILL_SWITCH)
    manual_unlocked = bool(safety.get("orders_allowed"))
    add_check("Locked safe state", locked_safe, "info", "Normal resting state should be read-only, execution disabled, kill switch on.", {"broker_read_only": BROKER_READ_ONLY, "broker_execution_enabled": BROKER_EXECUTION_ENABLED, "broker_kill_switch": BROKER_KILL_SWITCH})
    add_check("Broker execution unlocked", manual_unlocked, "info", "True only when read_only=false, execution_enabled=true, kill_switch=false, and OANDA env/account/token are configured.", {"orders_allowed": safety.get("orders_allowed"), "reason": safety.get("reason")})
    add_check(
        "Live execution multiplier hard-lock",
        effective_live_execution_multiplier() == 1.0 and LIVE_EXECUTION_MULTIPLIER_HARD_LOCKED,
        "required",
        "Live broker execution multiplier is hard-locked at 1.00x. Adaptive/research layers cannot increase position sizing.",
        {"live_execution_multiplier": effective_live_execution_multiplier(), "hard_locked": LIVE_EXECUTION_MULTIPLIER_HARD_LOCKED},
    )

    q_status_counts: Dict[str, int] = {}
    try:
        with get_conn() as conn:
            rows = conn.execute("SELECT status, COUNT(*) AS c FROM broker_action_queue GROUP BY status").fetchall()
            q_status_counts = {safe_str(r["status"]): int(r["c"] or 0) for r in rows}
    except Exception:
        q_status_counts = {}
    pending_count = sum(c for st, c in q_status_counts.items() if safe_str(st).upper() in {"QUEUED_DRY_RUN", "QUEUED", "READY", "PENDING"})
    waiting_reopen_count = sum(c for st, c in q_status_counts.items() if safe_str(st).upper() == "WAITING_MARKET_REOPEN")
    waiting_price_retry_count = sum(c for st, c in q_status_counts.items() if safe_str(st).upper() == "WAITING_PRICE_RETRY")
    benign_missed_statuses = {"MISSED_BROKER_ENTRY_RETRY_EXPIRED", "REVIEWED_RESOLVED", "CANCELLED_DUPLICATE_LINK_EXISTS", "CANCELLED_STALE_AFTER_REOPEN"}
    failed_count = sum(c for st, c in q_status_counts.items() if ("FAILED" in safe_str(st).upper() or "ERROR" in safe_str(st).upper()) and safe_str(st).upper() not in ({"WAITING_MARKET_REOPEN", "WAITING_PRICE_RETRY"} | benign_missed_statuses))
    add_check("Queue state", pending_count == 0 and failed_count == 0, "warning", "No pending/failed broker queue items need attention. WAITING_PRICE_RETRY and WAITING_MARKET_REOPEN are controlled retry states and should self-resolve/expire.", {"pending_count": pending_count, "waiting_market_reopen_count": waiting_reopen_count, "waiting_price_retry_count": waiting_price_retry_count, "failed_count": failed_count, "status_counts": q_status_counts})

    required_failures = [c for c in checks if c.get("level") == "required" and not c.get("ok")]
    warnings = [c for c in checks if c.get("level") == "warning" and not c.get("ok")]

    if required_failures:
        status = "NO_GO"
        message = "Required broker preflight checks failed. Do not execute broker actions."
    elif warnings:
        status = "WARN"
        message = "Core broker checks passed, but queue/reconciliation warnings need review."
    elif locked_safe:
        status = "LOCKED_SAFE"
        message = "Broker is healthy and locked. Safe resting state."
    elif manual_unlocked:
        status = "MANUAL_TEST_READY"
        message = "Broker is healthy and manually unlocked for practice testing only."
    else:
        status = "CHECK_FLAGS"
        message = "Broker connectivity is healthy, but safety flags are neither locked-safe nor execution-ready."

    return {
        "status": status,
        "ok": status in {"LOCKED_SAFE", "MANUAL_TEST_READY"},
        "message": message,
        "checks": checks,
        "safety": safety,
        "reconciliation": recon,
        "account_summary": account_summary,
        "time_utc": now,
    }

