@app.get("/broker/oanda/pricing")
def broker_oanda_pricing(instruments: str = "") -> Dict[str, Any]:
    init_db()
    if instruments:
        requested = [normalise_oanda_instrument(x) for x in instruments.split(",") if safe_str(x)]
    else:
        requested = sorted(list(BROKER_ALLOWED_INSTRUMENTS))
    requested = list(dict.fromkeys([x for x in requested if x]))
    valid = []
    invalid = []
    for instrument in requested:
        ok, msg = validate_manual_oanda_instrument(instrument)
        if ok:
            valid.append(instrument)
        else:
            invalid.append({"instrument": instrument, "error": msg})
    if not valid:
        return {"status": "blocked", "ok": False, "prices": [], "invalid": invalid, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}
    resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/pricing", params={"instruments": ",".join(valid)})
    prices = []
    if resp.get("ok"):
        for price in resp.get("data", {}).get("prices", []) or []:
            mid = extract_oanda_mid_price({"prices": [price]})
            prices.append({
                "instrument": safe_str(price.get("instrument")),
                "time": safe_str(price.get("time")),
                "tradeable": price.get("tradeable"),
                "closeoutBid": safe_float(price.get("closeoutBid")),
                "closeoutAsk": safe_float(price.get("closeoutAsk")),
                "mid_price": mid,
            })
    return {"status": "ok" if resp.get("ok") else "error", "ok": bool(resp.get("ok")), "prices": prices, "invalid": invalid, "response": resp, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


