@app.post("/index-basket/manual-reset-cycle")
async def index_basket_manual_reset_cycle(
    request: Request,
    x_webhook_secret: Optional[str] = Header(default=None),
) -> Dict[str, Any]:
    """Manually reset the INDEX_BASKET cycle/high-water to the current reduced basket state.

    This is intentionally local-state only. It does NOT place broker orders and does NOT
    close OANDA trades. Use after a large basket has been defensively reduced and the
    remaining small basket should be treated as a fresh cycle.
    """
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    body_secret = safe_str(body.get("secret", ""))
    query_secret = safe_str(body.get("webhook_secret", ""))
    if x_webhook_secret != WEBHOOK_SECRET and body_secret != WEBHOOK_SECRET and query_secret != WEBHOOK_SECRET:
        raise HTTPException(status_code=401, detail="Invalid webhook secret")

    confirm = safe_str(body.get("confirm", ""))
    if confirm != "RESET_INDEX_BASKET_CYCLE":
        return {
            "status": "blocked",
            "ok": False,
            "reason": "Send confirm='RESET_INDEX_BASKET_CYCLE' to reset INDEX_BASKET high-water/cycle to current state.",
            "time_utc": now_utc_iso(),
        }

    max_open_allowed = int(safe_float(body.get("max_open_trades_allowed") or os.getenv("INDEX_BASKET_RESET_MAX_OPEN_TRADES", "10")) or 10)
    force = parse_bool(body.get("force"), False)
    reset_asset_cycles = parse_bool(body.get("reset_asset_cycles"), True)

    family = "INDEX_BASKET"
    assets = ["NAS100", "US500"]
    now = now_utc_iso()

    with get_conn() as conn:
        placeholders = ",".join(["?"] * len(assets))
        open_rows = conn.execute(f"""
            SELECT * FROM open_trades
            WHERE asset IN ({placeholders}) AND status = 'open'
            ORDER BY asset ASC, entry_time ASC
        """, tuple(assets)).fetchall()

        open_count = len(open_rows)
        if open_count > max_open_allowed and not force:
            return {
                "status": "blocked",
                "ok": False,
                "reason": f"INDEX_BASKET has {open_count} open shadow trades. Reset is blocked above {max_open_allowed} unless force=true.",
                "open_trades": open_count,
                "max_open_trades_allowed": max_open_allowed,
                "time_utc": now,
            }

        family_pnl = 0.0
        losing = 0
        assets_with_open = set()
        per_asset = {}
        for row in open_rows:
            asset = safe_str(row["asset"]).upper()
            assets_with_open.add(asset)
            pnl = pnl_from_return(asset, row["return_pct"])
            family_pnl += pnl
            if pnl < 0:
                losing += 1
            info = per_asset.setdefault(asset, {"open_count": 0, "pnl": 0.0})
            info["open_count"] += 1
            info["pnl"] += pnl

        family_R = family_pnl / 50.0 if 50.0 else 0.0
        losing_pct = losing / open_count * 100.0 if open_count else 0.0

        latest_signal = conn.execute(f"""
            SELECT timestamp_readable
            FROM raw_signals
            WHERE pair IN ({placeholders})
            ORDER BY timestamp_readable DESC, id DESC
            LIMIT 1
        """, tuple(assets)).fetchone()
        latest_signal_time = safe_str(latest_signal["timestamp_readable"]) if latest_signal else now
        reset_started_at = latest_signal_time + " manual_reset " + now
        family_cycle_id = make_basket_cycle_id(family, reset_started_at)

        conn.execute("""
            INSERT OR REPLACE INTO active_family_basket_cycles (
                family, family_cycle_id, status, started_at_signal_time, started_at_utc,
                last_signal_time, open_trades, high_water_pnl_50risk,
                high_water_seen_at_signal_time, last_family_pnl_50risk, last_family_R, updated_at_utc
            ) VALUES (?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            family, family_cycle_id, reset_started_at, now, latest_signal_time,
            open_count, family_pnl, latest_signal_time, family_pnl, family_R, now,
        ))

        latest_candidate_assets = 0
        latest_asset_rows = conn.execute(f"""
            SELECT r1.pair, r1.forward_test_candidate
            FROM raw_signals r1
            INNER JOIN (
                SELECT pair, MAX(id) AS max_id
                FROM raw_signals
                WHERE pair IN ({placeholders})
                GROUP BY pair
            ) x ON r1.pair = x.pair AND r1.id = x.max_id
        """, tuple(assets)).fetchall()
        for r in latest_asset_rows:
            if is_true(r["forward_test_candidate"]):
                latest_candidate_assets += 1

        # Insert an immediate family check row so the dashboard updates without waiting for the next webhook.
        score = 0
        reasons = ["manual_index_basket_cycle_reset"]
        if latest_candidate_assets <= 0:
            score += 1
            reasons.append("no_family_asset_candidate_true")
        if losing_pct >= 40:
            score += 1
            reasons.append("family_40pct_losers_plus")
        if losing_pct >= 60:
            score += 1
            reasons.append("family_60pct_losers_plus")
        if family_R <= 0:
            score += 1
            reasons.append("family_not_positive")
        if family_R <= -2:
            score += 1
            reasons.append("family_minus_2R_or_worse")
        if score <= 1:
            family_status = "GREEN"
            family_action = "HOLD"
        elif score <= 3:
            family_status = "AMBER"
            family_action = "PAUSE_OR_CAUTION_STACKING"
        elif score <= 5:
            family_status = "RED"
            family_action = "DEFENSIVE_ASSESSMENT"
        else:
            family_status = "CRITICAL"
            family_action = "HARD_DEFENCE_CANDIDATE"

        conn.execute("""
            INSERT INTO family_basket_checks (
                created_at_utc, family, assets, latest_signal_time, family_cycle_id,
                open_trades, basket_phase, open_basket_pnl_50risk, open_basket_R,
                basket_high_water_pnl_50risk, basket_giveback_pct, losing_trades,
                losing_trade_pct, latest_candidate_assets, assets_with_open_trades,
                family_score, family_status, family_action, reason
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            now, family, ",".join(assets), latest_signal_time, family_cycle_id,
            open_count, basket_phase_from_count(open_count), family_pnl, family_R,
            family_pnl, 0.0, losing, losing_pct, latest_candidate_assets, len(assets_with_open),
            score, family_status, family_action, ",".join(reasons),
        ))

        asset_cycle_results = []
        if reset_asset_cycles:
            for asset in assets:
                info = per_asset.get(asset, {"open_count": 0, "pnl": 0.0})
                asset_open = int(info["open_count"])
                asset_pnl = float(info["pnl"])
                asset_R = asset_pnl / 50.0 if 50.0 else 0.0
                if asset_open <= 0:
                    conn.execute("DELETE FROM active_basket_cycles WHERE asset = ?", (asset,))
                    asset_cycle_results.append({"asset": asset, "open_trades": 0, "deleted": True})
                    continue
                asset_cycle_id = make_basket_cycle_id(asset, reset_started_at)
                conn.execute("""
                    INSERT OR REPLACE INTO active_basket_cycles (
                        asset, basket_cycle_id, status, started_at_signal_time, started_at_utc,
                        last_signal_time, open_trades, high_water_pnl_50risk,
                        high_water_seen_at_signal_time, last_basket_pnl_50risk, last_basket_R, updated_at_utc
                    ) VALUES (?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (
                    asset, asset_cycle_id, reset_started_at, now, latest_signal_time,
                    asset_open, asset_pnl, latest_signal_time, asset_pnl, asset_R, now,
                ))
                asset_cycle_results.append({"asset": asset, "open_trades": asset_open, "pnl_50risk": asset_pnl, "cycle_id": asset_cycle_id})

        conn.commit()

    log_system_event("manual_index_basket_cycle_reset", "Manual INDEX_BASKET cycle/high-water reset from dashboard", {
        "open_trades": open_count,
        "family_pnl_50risk": family_pnl,
        "family_cycle_id": family_cycle_id,
        "reset_asset_cycles": reset_asset_cycles,
    })

    return {
        "status": "ok",
        "ok": True,
        "message": "INDEX_BASKET cycle/high-water reset to current reduced basket state. No broker orders were sent.",
        "family": family,
        "family_cycle_id": family_cycle_id,
        "open_trades": open_count,
        "family_pnl_50risk": family_pnl,
        "family_R": family_R,
        "new_high_water_pnl_50risk": family_pnl,
        "new_giveback_pct": 0.0,
        "latest_signal_time": latest_signal_time,
        "reset_asset_cycles": reset_asset_cycles,
        "asset_cycles": asset_cycle_results,
        "time_utc": now,
    }

@app.post("/broker/oanda/test/close-all")
async def broker_oanda_test_close_all(request: Request) -> Dict[str, Any]:
    """
    Manual restricted in live mode close-all for allowed instruments.

    v4.9 close-until-flat retry harness:
    - Fetch open positions first.
    - Close only non-zero long/short sides per instrument.
    - Re-check broker positions after each pass.
    - Retry remaining exposure up to max_retries.
    - Return success only after OANDA confirms requested instruments are flat.
    - Still manual restricted in live mode; not connected to strategy/basket execution.
    """
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    requested = body.get("instruments") or list(BROKER_ALLOWED_INSTRUMENTS)
    if isinstance(requested, str):
        requested_instruments = [normalise_oanda_instrument(x) for x in requested.split(",")]
    else:
        requested_instruments = [normalise_oanda_instrument(x) for x in requested]

    requested_instruments = [x for x in requested_instruments if x]

    try:
        max_retries = int(body.get("max_retries", os.getenv("BROKER_CLOSE_ALL_MAX_RETRIES", "3")))
    except Exception:
        max_retries = 3
    max_retries = max(0, min(max_retries, 10))

    try:
        retry_sleep_seconds = float(body.get("retry_sleep_seconds", os.getenv("BROKER_CLOSE_ALL_RETRY_SLEEP_SECONDS", "0.75")))
    except Exception:
        retry_sleep_seconds = 0.75
    retry_sleep_seconds = max(0.0, min(retry_sleep_seconds, 5.0))

    instruments: List[str] = []
    validation_results = []
    for instrument in requested_instruments:
        inst_ok, inst_msg = validate_manual_oanda_instrument(instrument)
        if not inst_ok:
            validation_results.append({
                "instrument": instrument,
                "ok": False,
                "blocked": True,
                "error": inst_msg,
            })
        else:
            instruments.append(instrument)

    # Deduplicate while preserving order.
    instruments = list(dict.fromkeys(instruments))

    if validation_results and not instruments:
        result = {
            "status": "blocked",
            "ok": False,
            "results": validation_results,
            "confirmed_flat": False,
            "remaining_allowed_positions": [],
            "passes": [],
            "safety": oanda_safety_state(),
            "time_utc": now_utc_iso(),
        }
        log_execution_audit_event(
            "practice_manual", "INDEX_BASKET", "", "close_all_until_flat", False,
            "manual practice close-all blocked by invalid instruments", "",
            retry_count=0, close_all_required=True, broker_position_confirmed_flat=False,
            raw=result,
        )
        return result

    def allowed_open_positions() -> Tuple[bool, List[Dict[str, Any]], Dict[str, Any]]:
        resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")
        if not resp.get("ok"):
            return False, [], resp
        positions = resp.get("data", {}).get("positions", []) or []
        remaining = [p for p in positions if safe_str(p.get("instrument")) in set(instruments)]
        return True, remaining, resp

    def close_position_sides(position: Dict[str, Any]) -> Dict[str, Any]:
        instrument = safe_str(position.get("instrument"))
        long_units = safe_float((position.get("long") or {}).get("units")) or 0.0
        short_units = safe_float((position.get("short") or {}).get("units")) or 0.0

        close_body: Dict[str, Any] = {}
        if long_units > 0:
            close_body["longUnits"] = "ALL"
        if short_units < 0:
            close_body["shortUnits"] = "ALL"

        if not close_body:
            return {
                "instrument": instrument,
                "ok": True,
                "skipped": True,
                "reason": "Position exists but both long/short units are zero.",
                "long_units": long_units,
                "short_units": short_units,
            }

        resp = oanda_write_request(
            f"/v3/accounts/{OANDA_ACCOUNT_ID}/positions/{urllib.parse.quote(instrument)}/close",
            "PUT",
            close_body,
        )
        return {
            "instrument": instrument,
            "ok": bool(resp.get("ok")),
            "request": close_body,
            "long_units_before": long_units,
            "short_units_before": short_units,
            "response": resp,
        }

    initial_ok, initial_remaining, initial_resp = allowed_open_positions()
    if not initial_ok:
        result = {
            "status": "error",
            "ok": False,
            "results": validation_results,
            "confirmed_flat": False,
            "error": "Could not fetch open positions before close-all.",
            "response": initial_resp,
            "passes": [],
            "safety": oanda_safety_state(),
            "time_utc": now_utc_iso(),
        }
        log_execution_audit_event(
            "practice_manual", "INDEX_BASKET", "", "close_all_until_flat", False,
            "manual practice close-all failed: could not fetch positions", "",
            retry_count=0, close_all_required=True, broker_position_confirmed_flat=False,
            raw=result,
        )
        return result

    passes = []
    confirmed_flat = len(initial_remaining) == 0
    remaining = initial_remaining

    # attempts = initial pass + retry passes. If max_retries=3, there are up to 4 passes total.
    max_passes = max_retries + 1
    for pass_index in range(max_passes):
        if not remaining:
            confirmed_flat = True
            passes.append({
                "pass": pass_index,
                "skipped": True,
                "reason": "Already flat before this pass.",
                "remaining_before_count": 0,
                "results": [],
                "remaining_after_count": 0,
            })
            break

        pass_results = []
        for pos in remaining:
            pass_results.append(close_position_sides(pos))

        if retry_sleep_seconds > 0:
            time.sleep(retry_sleep_seconds)

        after_ok, after_remaining, after_resp = allowed_open_positions()
        if not after_ok:
            passes.append({
                "pass": pass_index,
                "remaining_before_count": len(remaining),
                "results": pass_results,
                "recheck_ok": False,
                "recheck_response": after_resp,
                "remaining_after_count": None,
            })
            confirmed_flat = False
            break

        passes.append({
            "pass": pass_index,
            "remaining_before_count": len(remaining),
            "results": pass_results,
            "recheck_ok": True,
            "remaining_after_count": len(after_remaining),
            "remaining_after": after_remaining,
        })

        remaining = after_remaining
        confirmed_flat = len(remaining) == 0
        if confirmed_flat:
            break

    all_close_requests_ok = True
    for pass_data in passes:
        for r in pass_data.get("results", []):
            if r.get("blocked") or r.get("ok") is False:
                all_close_requests_ok = False

    success = confirmed_flat and all_close_requests_ok
    status = "ok" if success else "warning"

    result = {
        "status": status,
        "ok": success,
        "confirmed_flat": confirmed_flat,
        "requested_instruments": instruments,
        "validation_results": validation_results,
        "initial_remaining_count": len(initial_remaining),
        "remaining_allowed_positions": remaining,
        "max_retries": max_retries,
        "passes_run": len(passes),
        "passes": passes,
        "safety": oanda_safety_state(),
        "time_utc": now_utc_iso(),
    }

    log_execution_audit_event(
        "practice_manual", "INDEX_BASKET", "", "close_all_until_flat", success,
        "manual practice close-until-flat retry harness v4.9", "",
        retry_count=max(0, len(passes) - 1), close_all_required=True,
        broker_position_confirmed_flat=confirmed_flat,
        raw={
            "requested_instruments": instruments,
            "initial_remaining_count": len(initial_remaining),
            "passes_run": len(passes),
            "confirmed_flat": confirmed_flat,
            "remaining_allowed_positions": remaining,
            "passes": passes,
        },
    )

    return result


@app.post("/broker/oanda/test/close-until-flat")
async def broker_oanda_test_close_until_flat(request: Request) -> Dict[str, Any]:
    """Alias for the v4.9 close-all retry harness."""
    return await broker_oanda_test_close_all(request)


