            weekend_buffer_snapshot = build_weekend_buffer_research_snapshot(limit=5000)
            weekend_buffer_rows = []
            weekend_buffer_summary = {k: v for k, v in weekend_buffer_snapshot.items() if k not in {"candidate_rows", "harvest_stages"}}
