            zf.writestr("weekend-buffer-research.csv", rows_to_csv(weekend_buffer_rows, list(weekend_buffer_rows[0].keys())))
            included_files.append("weekend-buffer-research.csv")


            # 3) Point-in-time operational state snapshots. These are JSON because
