def _managed_fraction_for_hold_research(h: int) -> float:
    """Shared managed-SL research ladder: 48h 25%, 72h 50%, 96h 65%, 120h 75%."""
    try:
        h = int(h or 0)
    except Exception:
        h = 0
    if h >= 120:
        return 0.75
    if h >= 96:
        return 0.65
    if h >= 72:
        return 0.50
    if h >= 48:
        return 0.25
    return 0.0




def _weekend_buffer_multiplier_research(index_status: str, hwm_r: float, candidate_assets: int) -> Tuple[float, str]:
    """Research-only weekend stop-softening policy.

    Multiplier is applied to the normal managed-SL protected profit.
    1.00 = keep normal tightened SL; 0.50 = medium weekend buffer;
    0.25 = soft weekend buffer. This does not modify broker stops.
    """
    status = safe_str(index_status).upper()
    try:
        hwm_r = float(hwm_r or 0.0)
    except Exception:
        hwm_r = 0.0
    try:
        candidate_assets = int(candidate_assets or 0)
    except Exception:
        candidate_assets = 0

    if status in {"RED", "CRITICAL"} and candidate_assets <= 0:
        return 1.00, "KEEP_NORMAL_TIGHT_STOPS__WEAK_BASKET_NO_BUFFER"
    if hwm_r >= 100 and candidate_assets >= 1:
        return 0.50, "POST_100R_MEDIUM_BUFFER_AFTER_MAJOR_HARVEST"
    if hwm_r >= 75 and candidate_assets >= 1:
        return 0.50, "HIGH_R_MEDIUM_WEEKEND_BUFFER"
    if hwm_r >= 60 and candidate_assets >= 1:
        return 0.60, "HIGH_R_MODERATE_WEEKEND_BUFFER"
    if hwm_r >= 40 and candidate_assets >= 1:
        return 0.70, "ARMED_LIGHT_WEEKEND_BUFFER"
    return 0.85, "LOW_R_CONSERVATIVE_WEEKEND_BUFFER"


def _weekend_gap_watch_restore_rule_research() -> str:
    return (
        "Friday: save normal managed SLs and model buffered stops before close. "
        "Sunday/Monday: do not restore tight Friday stops immediately; wait 12-24h or until "
        "gap fill / candidate support / price stability confirms recovery. If weakness follows through, "
        "defence overlay should escalate instead of restoring tight stops."
    )

def build_weekend_buffer_research_snapshot(limit: int = 100) -> Dict[str, Any]:
    """Research-only model for Friday/Sunday/Monday gap-aware managed-stop handling.

    This does NOT modify OANDA stops. It estimates what would happen if, before a
    weekend/gap window, the system saved the normal managed-SL level, temporarily
    softened remaining runner protection, and only restored normal tightening after
    the Sunday/Monday gap-watch window settled.
    """
    init_db()
    limit = max(1, min(int(limit or 100), 500))
    with get_conn() as conn:
        open_rows = conn.execute("SELECT * FROM open_trades ORDER BY asset ASC, entry_time ASC").fetchall()
        family = conn.execute("""
            SELECT f.*
            FROM family_basket_checks f
            INNER JOIN (
                SELECT family, MAX(id) AS max_id
                FROM family_basket_checks
                GROUP BY family
            ) x ON f.family = x.family AND f.id = x.max_id
            WHERE UPPER(f.family) = 'INDEX_BASKET'
            LIMIT 1
        """).fetchone()

    # sqlite3.Row does not support .get(); convert rows used by this research model
    # to plain dicts so the dashboard/export cannot 500 when live data exists.
    open_rows = [dict(r) for r in open_rows]
    family = dict(family) if family else None

    if family:
        index_pnl = safe_float(family.get("open_basket_pnl_50risk")) or 0.0
        index_hwm = safe_float(family.get("basket_high_water_pnl_50risk")) or 0.0
        index_status = safe_str(family.get("family_status") or "UNKNOWN")
        index_action = safe_str(family.get("family_action") or "")
        index_giveback = safe_float(family.get("basket_giveback_pct")) or 0.0
        candidate_assets = int(safe_float(family.get("latest_candidate_assets")) or 0)
        assets_total = len([x for x in safe_str(family.get("assets")).split(",") if x.strip()]) or 2
    else:
        index_pnl = index_hwm = index_giveback = 0.0
        index_status = "UNKNOWN"
        index_action = ""
        candidate_assets = 0
        assets_total = 2

    # Same agreed harvest ladder, including post-100R major harvest.
    harvest_stages = [(40, 0.10), (60, 0.20), (75, 0.25), (100, 0.50)]
    hwm_r = index_hwm / 50.0 if index_hwm else 0.0

    mature_rows: List[Dict[str, Any]] = []
    for r in open_rows:
        asset = safe_str(r.get("asset"))
        hold = int(safe_float(r.get("hold_candles")) or 0)
        ret = safe_float(r.get("return_pct")) or 0.0
        pnl = pnl_from_return(asset, ret)
        if hold >= 48 and pnl > 0:
            normal_frac = _managed_fraction_for_hold_research(hold)
            normal_protected = pnl * normal_frac
            weekend_mult, weekend_model = _weekend_buffer_multiplier_research(index_status, hwm_r, candidate_assets)
            conservative_buffer = normal_protected * 0.75
            medium_buffer = normal_protected * 0.50
            soft_buffer = normal_protected * 0.25
            weekend_protected = normal_protected * weekend_mult
            mature_rows.append({
                "trade_id": safe_str(r.get("trade_id")),
                "asset": asset,
                "hold_candles": hold,
                "return_pct": ret,
                "current_pnl_50risk": pnl,
                "normal_managed_fraction": normal_frac,
                "normal_managed_protected_pnl": normal_protected,
                "weekend_buffer_multiplier": weekend_mult,
                "weekend_buffer_model": weekend_model,
                "conservative_buffer_protected_pnl": conservative_buffer,
                "medium_buffer_protected_pnl": medium_buffer,
                "soft_buffer_protected_pnl": soft_buffer,
                "weekend_buffer_protected_pnl": weekend_protected,
                "temporary_extra_buffer_pnl": max(0.0, normal_protected - weekend_protected),
            })

    mature_pool = sum(x["current_pnl_50risk"] for x in mature_rows)
    remaining_pool = mature_pool
    banked_total = 0.0
    stage_rows: List[Dict[str, Any]] = []
    triggered: List[str] = []
    for threshold, pct_to_bank in harvest_stages:
        hit = hwm_r >= threshold
        banked = remaining_pool * pct_to_bank if hit and remaining_pool > 0 else 0.0
        stage_rows.append({
            "level_R": threshold,
            "hit": bool(hit),
            "bank_pct": pct_to_bank,
            "banked_pnl": banked,
            "banked_R": banked / 50.0 if banked else 0.0,
            "pool_before_pnl": remaining_pool,
        })
        if hit:
            triggered.append(f"{threshold}R")
            banked_total += banked
            remaining_pool -= banked

    normal_ladder_only = sum(x["normal_managed_protected_pnl"] for x in mature_rows)
    weekend_buffer_only = sum(x["weekend_buffer_protected_pnl"] for x in mature_rows)
    remaining_ratio = (remaining_pool / mature_pool) if mature_pool > 0 else 0.0
    normal_remaining_protected = normal_ladder_only * remaining_ratio
    weekend_remaining_protected = weekend_buffer_only * remaining_ratio
    normal_floor = banked_total + normal_remaining_protected
    weekend_floor = banked_total + weekend_remaining_protected
    temporary_buffer_release = max(0.0, normal_floor - weekend_floor)
    weekend_buffer_multiplier, weekend_buffer_model = _weekend_buffer_multiplier_research(index_status, hwm_r, candidate_assets)
    weekend_restore_rule = _weekend_gap_watch_restore_rule_research()

    weekend_flag, weekend_policy = _managed_stop_weekend_policy()
    now_ts = datetime.now(timezone.utc)
    wd = now_ts.weekday()
    hour = now_ts.hour
    if weekend_policy.startswith("friday"):
        phase = "FRIDAY_PRE_CLOSE_BUFFER_RESEARCH"
        proposed_action = "Save normal managed SL levels; model buffered weekend stops; do not restore tight stops until 12-24h gap-watch confirms recovery/stability."
    elif "monday" in weekend_policy:
        phase = "MONDAY_GAP_WATCH_RESEARCH"
        proposed_action = "Do not instantly restore tight Friday stops; hold buffered mode for 12-24h unless recovery/stability confirms, or weakness follows through and defence escalates."
    elif weekend_flag:
        phase = "WEEKEND_REOPEN_GAP_SENSITIVE_RESEARCH"
        proposed_action = "Market/gap-sensitive window: avoid blind tightening; keep buffered/protected approach in research view."
    else:
        phase = "NORMAL_WEEKDAY_RESEARCH"
        proposed_action = "Normal weekday: managed SLs would tighten hourly if execution were enabled. Weekend buffer not active yet."

    if index_status.upper() in {"RED", "CRITICAL"} and candidate_assets == 0:
        risk_note = "Basket already weak: do not loosen blindly; defence overlay should review before any weekend buffer."
    elif hwm_r >= 60 and candidate_assets >= 1:
        risk_note = "High-R basket: harvest first, then use weekend buffer on remaining runners; restore tight stops only after gap-watch settles."
    else:
        risk_note = "Small/young or unsupported basket: weekend buffer should be conservative and research-only."

    # Candidate rows shown oldest/mature first.
    candidate_rows = sorted(mature_rows, key=lambda x: (-int(x.get("hold_candles") or 0), -float(x.get("current_pnl_50risk") or 0.0)))[:limit]

    return {
        "status": "ok",
        "time_utc": now_utc_iso(),
        "phase": phase,
        "weekend_policy": weekend_policy,
        "weekend_sensitive_window": bool(weekend_flag),
        "weekend_buffer_model": weekend_buffer_model,
        "weekend_buffer_multiplier": weekend_buffer_multiplier,
        "weekend_restore_rule": weekend_restore_rule,
        "proposed_action": proposed_action,
        "risk_note": risk_note,
        "index_status": index_status,
        "index_action": index_action,
        "candidate_support": f"{candidate_assets}/{assets_total}",
        "open_basket_pnl": index_pnl,
        "open_basket_R": index_pnl / 50.0 if index_pnl else 0.0,
        "basket_high_water_pnl": index_hwm,
        "basket_high_water_R": hwm_r,
        "basket_giveback_pct": index_giveback,
        "mature_profitable_pool": mature_pool,
        "harvest_banked_estimate": banked_total,
        "harvest_banked_R": banked_total / 50.0 if banked_total else 0.0,
        "normal_managed_floor": normal_floor,
        "normal_managed_floor_R": normal_floor / 50.0 if normal_floor else 0.0,
        "weekend_buffer_floor": weekend_floor,
        "weekend_buffer_floor_R": weekend_floor / 50.0 if weekend_floor else 0.0,
        "temporary_buffer_release": temporary_buffer_release,
        "temporary_buffer_release_R": temporary_buffer_release / 50.0 if temporary_buffer_release else 0.0,
        "normal_remaining_sl_protection": normal_remaining_protected,
        "weekend_remaining_sl_protection": weekend_remaining_protected,
        "triggered_harvest_levels": triggered,
        "harvest_stages": stage_rows,
        "candidate_rows": candidate_rows,
    }


def build_weekend_buffer_research_dashboard_html() -> str:
    snap = build_weekend_buffer_research_snapshot(limit=25)
    rows_html = ""
    for r in snap.get("candidate_rows", []):
        rows_html += f"""
        <tr>
            <td>{esc(r.get('asset'))}</td>
            <td>{esc(r.get('trade_id'))}</td>
            <td>{esc(r.get('hold_candles'))}</td>
            <td class="{pnl_class(r.get('current_pnl_50risk'))}">{money(r.get('current_pnl_50risk'))}</td>
            <td>{esc(round(float(r.get('normal_managed_fraction') or 0.0) * 100, 1))}%</td>
            <td class="{pnl_class(r.get('normal_managed_protected_pnl'))}">{money(r.get('normal_managed_protected_pnl'))}</td>
            <td>{esc(r.get('weekend_buffer_model'))}</td>
            <td class="{pnl_class(r.get('weekend_buffer_protected_pnl'))}">{money(r.get('weekend_buffer_protected_pnl'))}</td>
            <td>{money(r.get('temporary_extra_buffer_pnl'))}</td>
        </tr>
        """
    phase = safe_str(snap.get("phase"))
    phase_class = "warn" if "FRIDAY" in phase or "WEEKEND" in phase or "MONDAY" in phase else "flat"
    return f"""
        <details class="priority">
            <summary>Weekend Buffer / Gap-Watch Research</summary>
            <div class="section-note small">Research-only. This models the proposed Friday/Sunday/Monday exception: save normal managed SLs, temporarily soften/buffer remaining runner stops before the gap window, then restore/tighten only after 12-24h gap-watch confirms recovery/stability. It does not update OANDA stops.</div>
            <div class="metric-grid">
                <div class="mini-card"><div class="k">Weekend Phase</div><div class="v {phase_class}">{esc(phase)}</div><div class="small">{esc(snap.get('weekend_policy'))}</div></div>
                <div class="mini-card"><div class="k">Candidate Support</div><div class="v">{esc(snap.get('candidate_support'))}</div><div class="small">Index status: {esc(snap.get('index_status'))}</div></div>
                <div class="mini-card"><div class="k">Open Basket</div><div class="v {pnl_class(snap.get('open_basket_pnl'))}">{money(snap.get('open_basket_pnl'))}</div><div class="small">{esc(round(float(snap.get('open_basket_R') or 0.0), 2))}R</div></div>
                <div class="mini-card"><div class="k">High-Water</div><div class="v {pnl_class(snap.get('basket_high_water_pnl'))}">{money(snap.get('basket_high_water_pnl'))}</div><div class="small">{esc(round(float(snap.get('basket_high_water_R') or 0.0), 2))}R</div></div>
                <div class="mini-card"><div class="k">Harvest Banked / Protected</div><div class="v {pnl_class(snap.get('harvest_banked_estimate'))}">{money(snap.get('harvest_banked_estimate'))}</div><div class="small">hit: {esc(', '.join(snap.get('triggered_harvest_levels') or []) or 'none')}</div></div>
                <div class="mini-card"><div class="k">Normal Managed Floor</div><div class="v {pnl_class(snap.get('normal_managed_floor'))}">{money(snap.get('normal_managed_floor'))}</div><div class="small">{esc(round(float(snap.get('normal_managed_floor_R') or 0.0), 2))}R</div></div>
                <div class="mini-card"><div class="k">Weekend Buffer Floor</div><div class="v {pnl_class(snap.get('weekend_buffer_floor'))}">{money(snap.get('weekend_buffer_floor'))}</div><div class="small">{esc(round(float(snap.get('weekend_buffer_floor_R') or 0.0), 2))}R research</div></div>
                <div class="mini-card"><div class="k">Buffer Model</div><div class="v warn">{esc(snap.get('weekend_buffer_model'))}</div><div class="small">multiplier {esc(round(float(snap.get('weekend_buffer_multiplier') or 0.0), 2))}x normal SL protection</div></div>
                <div class="mini-card"><div class="k">Temporary Extra Buffer</div><div class="v warn">{money(snap.get('temporary_buffer_release'))}</div><div class="small">softened vs normal floor</div></div>
            </div>
            <div class="section-note"><strong>Proposed action:</strong> {esc(snap.get('proposed_action'))}<br><strong>Restore rule:</strong> {esc(snap.get('weekend_restore_rule'))}<br><strong>Risk note:</strong> {esc(snap.get('risk_note'))}</div>
            <div class="table-scroll"><table class="compact-table"><thead><tr><th>Asset</th><th>Trade ID</th><th>Hold</th><th>Current P&L</th><th>Normal SL %</th><th>Normal Protected</th><th>Buffer Model</th><th>Weekend Buffer Protected</th><th>Extra Buffer</th></tr></thead><tbody>{rows_html}</tbody></table></div>
        </details>
    """


@app.get("/weekend-buffer-research")
def weekend_buffer_research_route(limit: int = 100) -> Dict[str, Any]:
    return build_weekend_buffer_research_snapshot(limit=limit)


@app.get("/export/weekend-buffer-research.csv")
def export_weekend_buffer_research_csv(limit: int = 500) -> Response:
    snap = build_weekend_buffer_research_snapshot(limit=limit)
    rows = []
    summary = {k: v for k, v in snap.items() if k not in {"candidate_rows", "harvest_stages"}}
    for r in snap.get("candidate_rows", []):
        row = dict(summary)
        for k, v in r.items():
            row[f"trade_{k}"] = v
        rows.append(row)
    if not rows:
        rows = [summary]
    return Response(
        content=rows_to_csv(rows, list(rows[0].keys())),
        media_type="text/csv",
        headers={"Content-Disposition": 'attachment; filename="weekend-buffer-research.csv"'},
    )



# ============================================================
# v10.0.86 - NIKKEI / JP225 DEEP RESEARCH DASHBOARD SECTION
# v10.0.87 - METALS DEEP RESEARCH SECTION + ALL DASHBOARD DETAILS COLLAPSED BY DEFAULT
# ============================================================
# Separate dashboard lane for Nikkei so it is not buried inside the generic
# multi-context research table. This is shadow/demo research only and must not
# add Nikkei to live OANDA broker execution while NIKKEI_BROKER_EXECUTION_ENABLED=false.

NIKKEI_RESEARCH_ASSETS = {"NIKKEI", "JP225", "JPN225"}
NIKKEI_RESEARCH_DASHBOARD_LIMIT = max(500, min(int(float(os.getenv("NIKKEI_RESEARCH_DASHBOARD_LIMIT", "50000"))), 100000))


def normalise_nikkei_asset(value: Any) -> str:
    raw = safe_str(value).upper()
    compact = raw.replace(" ", "").replace("-", "").replace("_", "")
    if raw in NIKKEI_RESEARCH_ASSETS or compact in {"NIKKEI", "JP225", "JPN225", "JAPAN225"} or "JP225" in raw or "NIKKEI" in raw:
        return "NIKKEI"
    return raw


def _nikkei_rsi_bucket(value: Any) -> str:
    v = safe_float(value)
    if v is None:
        return "n/a"
    if v < 55:
        return "<55"
    if v < 60:
        return "55-60"
    if v < 65:
        return "60-65"
    if v < 70:
        return "65-70"
    if v < 75:
        return "70-75"
    return ">75"


def _nikkei_atr_bucket_from_values(value: Any, low_cut: Optional[float], high_cut: Optional[float]) -> str:
    v = safe_float(value)
    if v is None or low_cut is None or high_cut is None:
        return "n/a"
    if v <= low_cut:
        return "low"
    if v >= high_cut:
        return "high"
    return "mid"


def _nikkei_raw_where_sql() -> Tuple[str, List[Any]]:
    """Nikkei/JP225 matcher for raw_signals without assuming a ticker column exists."""
    variants = ["NIKKEI", "JP225", "JPN225"]
    pair_placeholders = ",".join(["?"] * len(variants))
    like_clauses = " OR ".join(["UPPER(COALESCE(raw_json,'')) LIKE ?" for _ in variants])
    where_sql = f"(UPPER(pair) IN ({pair_placeholders}) OR {like_clauses})"
    params: List[Any] = variants + [f"%{v}%" for v in variants]
    return where_sql, params


def _nikkei_latest_raw_rows(conn: sqlite3.Connection, limit: int = 30) -> List[Dict[str, Any]]:
    where_sql, params = _nikkei_raw_where_sql()
    rows = conn.execute(f"""
        SELECT id, received_at_utc, pair, timestamp_readable, exec_close, exec_high, exec_low,
               forward_test_candidate, raw_json
        FROM raw_signals
        WHERE {where_sql}
        ORDER BY id DESC
        LIMIT ?
    """, tuple(params + [int(limit)])).fetchall()
    out: List[Dict[str, Any]] = []
    for r in rows:
        d = dict(r)
        raw = _raw_signal_json(r)
        d["asset"] = "NIKKEI"
        d["ticker"] = safe_str(raw.get("ticker") or raw.get("symbol") or "")
        d["signal_side"] = safe_str(raw.get("signal_side"))
        d["score_raw"] = raw.get("score_raw", "")
        d["signal_quality"] = raw.get("signal_quality", "")
        d["setup_type"] = raw.get("setup_type", "")
        d["d_rsi"] = raw.get("d_rsi", "")
        d["d_rsi_bucket"] = _nikkei_rsi_bucket(raw.get("d_rsi"))
        d["exec_rsi"] = raw.get("exec_rsi", "")
        d["exec_atr_pct"] = raw.get("exec_atr_pct", "")
        d["custom_sl_pct"] = raw.get("custom_sl_pct", research_context_sl_pct("NIKKEI"))
        d["target_hold_hours"] = raw.get("target_hold_hours", "48")
        d["research_only"] = raw.get("research_only", "")
        d["test_mode"] = raw.get("test_mode", "")
        d["reject_reason"] = raw.get("reject_reason", "")
        out.append(d)
    return out


def build_nikkei_deep_research_snapshot(limit: int = NIKKEI_RESEARCH_DASHBOARD_LIMIT) -> Dict[str, Any]:
    init_db()
    limit = max(1, min(int(limit or NIKKEI_RESEARCH_DASHBOARD_LIMIT), 100000))
    with get_conn() as conn:
        latest_raw = _nikkei_latest_raw_rows(conn, limit=30)
        where_sql, count_params = _nikkei_raw_where_sql()
        count_raw_rows = conn.execute(f"""
            SELECT pair, forward_test_candidate, received_at_utc, raw_json
            FROM raw_signals
            WHERE {where_sql}
            ORDER BY id ASC
        """, tuple(count_params)).fetchall()

        count_map: Dict[str, Dict[str, Any]] = {}
        for cr in count_raw_rows:
            raw = _raw_signal_json(cr)
            symbol_key = safe_str(cr["pair"] or raw.get("ticker") or raw.get("symbol") or "NIKKEI").upper()
            if normalise_nikkei_asset(symbol_key) == "NIKKEI":
                symbol_key = "NIKKEI / JP225"
            item = count_map.setdefault(symbol_key, {"symbol_key": symbol_key, "signal_count": 0, "candidate_count": 0, "latest_received_at_utc": ""})
            item["signal_count"] += 1
            if is_true(cr["forward_test_candidate"]):
                item["candidate_count"] += 1
            if safe_str(cr["received_at_utc"]) > safe_str(item.get("latest_received_at_utc")):
                item["latest_received_at_utc"] = safe_str(cr["received_at_utc"])
        counts = list(count_map.values())

    all_rows = build_research_context_outcomes(limit=limit, accepted_only=False, candidate_like_only=False)
    nikkei_rows = [r for r in all_rows if normalise_nikkei_asset(r.get("asset")) == "NIKKEI"]
    accepted_rows = [r for r in nikkei_rows if int(r.get("candidate") or 0) == 1]
    candidate_like_rows = [r for r in nikkei_rows if int(r.get("candidate_like") or 0) == 1]
    accepted_summary = summarise_research_context_outcomes(accepted_rows)
    candidate_like_summary = summarise_research_context_outcomes(candidate_like_rows)
    all_summary = summarise_research_context_outcomes(nikkei_rows)

    # Broad daily RSI buckets for accepted Nikkei scenarios, using 48h outcome.
    rsi_buckets: Dict[str, Dict[str, Any]] = {}
    for r in accepted_rows:
        b = _nikkei_rsi_bucket(r.get("d_rsi") or r.get("ctx_rsi"))
        x = rsi_buckets.setdefault(b, {"bucket": b, "rows": 0, "n_48h": 0, "sum_return_48h_pct": 0.0, "wins_48h": 0, "sum_mfe_48h_pct": 0.0, "sum_mae_48h_pct": 0.0, "worst_mae_48h_pct": None})
        x["rows"] += 1
        ret = safe_float(r.get("return_48h_pct"))
        mfe = safe_float(r.get("mfe_48h_pct"))
        mae = safe_float(r.get("mae_48h_pct"))
        if int(r.get("has_48h") or 0) == 1 and ret is not None:
            x["n_48h"] += 1
            x["sum_return_48h_pct"] += ret
            if ret > 0:
                x["wins_48h"] += 1
            if mfe is not None:
                x["sum_mfe_48h_pct"] += mfe
            if mae is not None:
                x["sum_mae_48h_pct"] += mae
                if x["worst_mae_48h_pct"] is None or mae < x["worst_mae_48h_pct"]:
                    x["worst_mae_48h_pct"] = mae
    rsi_bucket_rows: List[Dict[str, Any]] = []
    bucket_order = ["<55", "55-60", "60-65", "65-70", "70-75", ">75", "n/a"]
    for b in bucket_order:
        x = rsi_buckets.get(b)
        if not x:
            continue
        n = int(x.get("n_48h") or 0)
        rsi_bucket_rows.append({
            "bucket": b,
            "rows": x.get("rows", 0),
            "n_48h": n,
            "avg_return_48h_pct": (x["sum_return_48h_pct"] / n) if n else None,
            "win_rate_48h_pct": (x["wins_48h"] / n * 100.0) if n else None,
            "avg_mfe_48h_pct": (x["sum_mfe_48h_pct"] / n) if n else None,
            "avg_mae_48h_pct": (x["sum_mae_48h_pct"] / n) if n else None,
            "worst_mae_48h_pct": x.get("worst_mae_48h_pct"),
        })

    return {
        "ok": True,
        "research_only": True,
        "title": "Nikkei / JP225 Deep Research",
        "mode_note": "Research only. Broker and OANDA execution are hard-disabled in this JP225 Research Hub build.",
        "broker_execution_enabled_for_nikkei": False,
        "nikkei_demo_enabled": bool(NIKKEI_DEMO_ENABLED),
        "nikkei_demo_sl_pct": float(os.getenv("NIKKEI_DEMO_SL_PCT", os.getenv("RESEARCH_NIKKEI_SL_PCT", "2.0"))),
        "counts": counts,
        "latest_raw_rows": latest_raw,
        "accepted_count": len(accepted_rows),
        "candidate_like_count": len(candidate_like_rows),
        "all_scenario_count": len(nikkei_rows),
        "accepted_summary": accepted_summary,
        "candidate_like_summary": candidate_like_summary,
        "all_summary": all_summary,
        "accepted_rows": accepted_rows[:200],
        "candidate_like_rows": candidate_like_rows[:200],
        "rsi_bucket_rows": rsi_bucket_rows,
        "time_utc": now_utc_iso(),
    }


