def build_nikkei_deep_research_html() -> str:
    try:
        snap = build_nikkei_deep_research_snapshot(limit=NIKKEI_RESEARCH_DASHBOARD_LIMIT)
    except Exception as e:
        return f"""
        <details class="priority dashboard-group">
            <summary>Nikkei / JP225 Deep Research — Shadow Demo</summary>
            <div class="section-note warn">Nikkei deep research temporarily unavailable: {esc(e)}</div>
        </details>
        """

    broker_enabled = bool(snap.get("broker_execution_enabled_for_nikkei"))
    broker_label = "BROKER ENABLED" if broker_enabled else "SHADOW ONLY"
    broker_cls = "status_red" if broker_enabled else "status_green"

    counts_html = ""
    for c in snap.get("counts", []) or []:
        signal_count = int(c.get("signal_count") or 0)
        candidate_count = int(c.get("candidate_count") or 0)
        rate = (candidate_count / signal_count * 100.0) if signal_count else 0.0
        counts_html += f"""
        <tr><td><strong>{esc(c.get('symbol_key'))}</strong></td><td>{signal_count}</td><td>{candidate_count}</td><td>{rate:.1f}%</td><td>{esc(display_utc_time(c.get('latest_received_at_utc')))}</td></tr>
        """
    if not counts_html:
        counts_html = '<tr><td colspan="5">No Nikkei / JP225 signals received yet.</td></tr>'

    latest_html = ""
    for r in snap.get("latest_raw_rows", []) or []:
        cand = is_true(r.get("forward_test_candidate"))
        cand_text = "true" if cand else "false"
        side = safe_str(r.get("signal_side"))
        side_class = "true" if side.lower() in {"long", "buy"} else "false" if side.lower() in {"short", "sell"} else "flat"
        latest_html += f"""
        <tr>
            <td>{esc(r.get('id'))}</td><td>{esc(display_candle_time(r.get('timestamp_readable')))}</td><td>{esc(r.get('pair'))}</td><td>{esc(r.get('ticker'))}</td>
            <td class="{side_class}"><strong>{esc(side)}</strong></td><td class="{cand_text}"><strong>{cand_text}</strong></td>
            <td>{esc(r.get('score_raw'))}</td><td>{esc(r.get('signal_quality'))}</td><td>{esc(r.get('setup_type'))}</td>
            <td>{esc(r.get('d_rsi'))}</td><td>{esc(r.get('d_rsi_bucket'))}</td><td>{esc(r.get('exec_atr_pct'))}</td><td>{esc(r.get('exec_close'))}</td>
            <td>{esc(r.get('custom_sl_pct'))}%</td><td>{esc(r.get('target_hold_hours'))}</td><td>{esc(r.get('reject_reason'))}</td>
        </tr>
        """
    if not latest_html:
        latest_html = '<tr><td colspan="16">No latest Nikkei / JP225 raw rows yet.</td></tr>'

    rsi_html = ""
    for r in snap.get("rsi_bucket_rows", []) or []:
        rsi_html += f"""
        <tr><td><strong>{esc(r.get('bucket'))}</strong></td><td>{esc(r.get('rows'))}</td><td>{esc(r.get('n_48h'))}</td><td class="{pnl_class(r.get('avg_return_48h_pct'))}">{pct(r.get('avg_return_48h_pct') or 0)}</td><td>{'' if r.get('win_rate_48h_pct') is None else f'{float(r.get('win_rate_48h_pct')):.1f}%'}</td><td>{pct(r.get('avg_mfe_48h_pct') or 0)}</td><td>{pct(r.get('avg_mae_48h_pct') or 0)}</td><td>{pct(r.get('worst_mae_48h_pct') or 0)}</td></tr>
        """
    if not rsi_html:
        rsi_html = '<tr><td colspan="8">No matured accepted Nikkei rows for RSI bucket review yet.</td></tr>'

    accepted_summary_html = _nikkei_summary_rows_html(snap.get("accepted_summary", []), "No accepted Nikkei context candidates yet.")
    candidate_like_summary_html = _nikkei_summary_rows_html(snap.get("candidate_like_summary", []), "No candidate-like Nikkei rows yet.")
    accepted_detail_html = _nikkei_detail_rows_html(snap.get("accepted_rows", []), limit=80)
    candidate_like_detail_html = _nikkei_detail_rows_html(snap.get("candidate_like_rows", []), limit=80)

    return f"""
    <details class="priority dashboard-group">
        <summary>Nikkei / JP225 Deep Research — Shadow Demo</summary>
        <div class="section-note small">
            Separate Nikkei lane so JP225 is not buried in the generic multi-context table. Current mode: <strong class="{broker_cls}">{esc(broker_label)}</strong>.
            This service is JP225/Nikkei research only. OANDA and broker execution are hard-disabled.
            Exports: <a href="/nikkei-deep-research">JSON</a> | <a href="/export/nikkei-deep-research.csv">CSV</a>.
        </div>
        <div class="cards four">
            <div class="card"><div class="label">Nikkei mode</div><div class="value {broker_cls}">{esc(broker_label)}</div><div class="small">NIKKEI_DEMO_ENABLED={esc(snap.get('nikkei_demo_enabled'))}</div></div>
            <div class="card"><div class="label">Demo / research SL</div><div class="value flat">{float(snap.get('nikkei_demo_sl_pct') or 0):.2f}%</div><div class="small">Research comparison stays export-based.</div></div>
            <div class="card"><div class="label">Accepted scenarios</div><div class="value">{esc(snap.get('accepted_count'))}</div><div class="small">forward_test_candidate=true context rows</div></div>
            <div class="card"><div class="label">All scenario rows</div><div class="value">{esc(snap.get('all_scenario_count'))}</div><div class="small">Nikkei context rows only</div></div>
        </div>

        <details><summary>Nikkei Signal Counts</summary>
            <div class="table-scroll"><table><thead><tr><th>Symbol</th><th>Signals</th><th>Accepted</th><th>Candidate Rate</th><th>Latest Received</th></tr></thead><tbody>{counts_html}</tbody></table></div>
        </details>

        <details><summary>Latest Nikkei / JP225 Raw Alerts</summary>
            <div class="table-scroll"><table><thead><tr><th>ID</th><th>Candle</th><th>Pair</th><th>Ticker</th><th>Side</th><th>Candidate</th><th>Score</th><th>Quality</th><th>Setup</th><th>D RSI</th><th>D RSI Bucket</th><th>Exec ATR%</th><th>Close</th><th>SL</th><th>Hold</th><th>Reject</th></tr></thead><tbody>{latest_html}</tbody></table></div>
        </details>

        <details><summary>Accepted Nikkei Outcomes by Context</summary>
            <div class="table-scroll"><table><thead><tr><th>Asset</th><th>Context</th><th>Rows</th><th>Accepted</th><th>Candidate-Like</th><th>SL</th><th>12h N</th><th>12h Avg Return</th><th>12h Avg P&L</th><th>48h N</th><th>48h Avg Return</th><th>48h Avg P&L</th><th>72h N</th><th>72h Avg Return</th><th>72h Avg P&L</th><th>96h N</th><th>96h Avg Return</th><th>96h Avg P&L</th></tr></thead><tbody>{accepted_summary_html}</tbody></table></div>
        </details>

        <details><summary>Candidate-Like / Watch Nikkei Rows</summary>
            <div class="table-scroll"><table><thead><tr><th>Asset</th><th>Context</th><th>Rows</th><th>Accepted</th><th>Candidate-Like</th><th>SL</th><th>12h N</th><th>12h Avg Return</th><th>12h Avg P&L</th><th>48h N</th><th>48h Avg Return</th><th>48h Avg P&L</th><th>72h N</th><th>72h Avg Return</th><th>72h Avg P&L</th><th>96h N</th><th>96h Avg Return</th><th>96h Avg P&L</th></tr></thead><tbody>{candidate_like_summary_html}</tbody></table></div>
        </details>

        <details><summary>Daily RSI Bucket Check — Accepted Nikkei Rows</summary>
            <div class="section-note small">Broad research buckets only. This is to test the strong-but-not-overheated idea without using curve-fit decimal thresholds.</div>
            <div class="table-scroll"><table><thead><tr><th>D RSI Bucket</th><th>Rows</th><th>48h Matured</th><th>48h Avg Return</th><th>48h Win Rate</th><th>48h Avg MFE</th><th>48h Avg MAE</th><th>Worst MAE</th></tr></thead><tbody>{rsi_html}</tbody></table></div>
        </details>

        <details><summary>Accepted Nikkei Line-by-Line MFE / MAE</summary>
            <div class="table-scroll"><table><thead><tr><th>ID</th><th>Asset</th><th>Context</th><th>Candle</th><th>Candidate</th><th>Score</th><th>Quality</th><th>Setup</th><th>Ctx Trend</th><th>Ctx RSI</th><th>Ctx ATR%</th><th>SL</th><th>12h Ret</th><th>48h Ret</th><th>48h MFE</th><th>48h MAE</th><th>96h Ret</th></tr></thead><tbody>{accepted_detail_html or '<tr><td colspan="17">No accepted Nikkei rows yet.</td></tr>'}</tbody></table></div>
        </details>

        <details><summary>Candidate-Like Nikkei Line-by-Line MFE / MAE</summary>
            <div class="table-scroll"><table><thead><tr><th>ID</th><th>Asset</th><th>Context</th><th>Candle</th><th>Candidate</th><th>Score</th><th>Quality</th><th>Setup</th><th>Ctx Trend</th><th>Ctx RSI</th><th>Ctx ATR%</th><th>SL</th><th>12h Ret</th><th>48h Ret</th><th>48h MFE</th><th>48h MAE</th><th>96h Ret</th></tr></thead><tbody>{candidate_like_detail_html or '<tr><td colspan="17">No candidate-like Nikkei rows yet.</td></tr>'}</tbody></table></div>
        </details>
    </details>
    """


