def build_metals_deep_research_snapshot(limit: int = 5000) -> Dict[str, Any]:
    """Dedicated XAU/XAG deep-research snapshot.

    Metals remain fully shadow-only: no OANDA broker promotion, no index basket
    P&L/high-water impact, and no live-readiness impact. This wrapper exists so
    the dashboard and export routes have a Nikkei-style dedicated metals lane.
    """
    rows = build_metals_research_outcomes(limit=limit, candidates_only=False)
    accepted_rows = [r for r in rows if int(r.get("candidate") or 0) == 1]
    candidate_like_rows = [r for r in rows if int(r.get("candidate_like") or 0) == 1]

    short_rows = build_metals_short_research_outcomes(limit=limit, candidates_only=False)
    short_candidate_rows = [r for r in short_rows if int(r.get("short_candidate") or 0) == 1]
    short_watch_rows = [r for r in short_rows if int(r.get("candidate_like") or 0) == 1]

    def _managed_sl_adjusted_pnl(row: Dict[str, Any], milestone: int = 48) -> Optional[float]:
        asset = safe_str(row.get("asset")).upper()
        sl = metal_research_sl_pct(asset)
        mae = safe_float(row.get(f"mae_{milestone}h_pct"))
        pnl = safe_float(row.get(f"pnl50_{milestone}h"))
        if pnl is None:
            return None
        if mae is not None and mae <= -abs(sl):
            return -50.0
        return pnl

    basket_sim_rows: List[Dict[str, Any]] = []
    for asset in sorted({safe_str(r.get("asset")).upper() for r in accepted_rows if safe_str(r.get("asset"))}):
        subset = [r for r in accepted_rows if safe_str(r.get("asset")).upper() == asset]
        sl = metal_research_sl_pct(asset)
        matured_48 = [r for r in subset if int(r.get("has_48h") or 0) == 1]
        rets = [safe_float(r.get("return_48h_pct")) for r in matured_48]
        maes = [safe_float(r.get("mae_48h_pct")) for r in matured_48]
        pnls = [safe_float(r.get("pnl50_48h")) for r in matured_48]
        adj = [_managed_sl_adjusted_pnl(r, 48) for r in matured_48]
        rets = [v for v in rets if v is not None]
        maes = [v for v in maes if v is not None]
        pnls = [v for v in pnls if v is not None]
        adj = [v for v in adj if v is not None]
        sl_pressure = sum(1 for v in maes if v <= -abs(sl))
        avg_ret = (sum(rets) / len(rets)) if rets else None
        avg_mae = (sum(maes) / len(maes)) if maes else None
        if not matured_48:
            state = "WAITING_FOR_48H_DATA"
        elif sl_pressure > 0 and (avg_ret is not None and avg_ret < 0):
            state = "DEFENCE_LIKELY"
        elif avg_ret is not None and avg_ret < 0:
            state = "CAUTION"
        else:
            state = "BENIGN_SO_FAR"
        basket_sim_rows.append({
            "asset": asset,
            "accepted_rows": len(subset),
            "matured_48h": len(matured_48),
            "placeholder_sl_pct": sl,
            "avg_return_48h_pct": avg_ret,
            "avg_mae_48h_pct": avg_mae,
            "sl_pressure_count_48h": sl_pressure,
            "sl_pressure_rate_48h_pct": (sl_pressure / len(maes) * 100.0) if maes else None,
            "raw_pnl50_sum_48h": sum(pnls) if pnls else None,
            "emergency_sl_adjusted_pnl50_sum_48h": sum(adj) if adj else None,
            "simulation_state": state,
            "note": "Emergency-SL-adjusted research proxy only; no live broker/basket action.",
        })

    short_basket_sim_rows = build_metal_basket_simulation_summary(short_candidate_rows, milestone=48)

    return {
        "ok": True,
        "title": "Metals Deep Research — XAU / XAG Shadow Only",
        "research_only": True,
        "broker_status": "DISABLED",
        "isolation_note": "XAU/XAG are excluded from OANDA broker promotion, index basket P&L, index high-water, live-readiness judgement, and NAS100/US500 basket-manager decisions.",
        "accepted_count": len(accepted_rows),
        "candidate_like_count": len(candidate_like_rows),
        "observation_count": len(rows),
        "generated_short_candidate_count": len(short_candidate_rows),
        "generated_short_watch_count": len(short_watch_rows),
        "short_research_model_version": METALS_SHORT_RESEARCH_VERSION,
        "accepted_summary": summarise_metal_outcomes(accepted_rows, candidate_like_only=False),
        "candidate_like_summary": summarise_metal_outcomes(candidate_like_rows, candidate_like_only=False),
        "all_summary": summarise_metal_outcomes(rows, candidate_like_only=False),
        "generated_short_summary": summarise_metal_outcomes(short_candidate_rows, candidate_like_only=False),
        "generated_short_watch_summary": summarise_metal_outcomes(short_watch_rows, candidate_like_only=False),
        "basket_manager_simulation": basket_sim_rows,
        "short_basket_manager_simulation": short_basket_sim_rows,
        "accepted_rows": accepted_rows[:200],
        "candidate_like_rows": candidate_like_rows[:200],
        "generated_short_candidate_rows": short_candidate_rows[:200],
        "generated_short_watch_rows": short_watch_rows[:200],
        "rows": rows[:500],
        "short_rows": short_rows[:500],
        "time_utc": now_utc_iso(),
    }


