@app.get("/dashboard-legacy", response_class=HTMLResponse)
def dashboard() -> str:
    init_db()
    # v10.0.68: the dashboard must be a read-mostly view. Running broker retry
    # maintenance / flat-cycle cleanup from GET /dashboard caused SQLite write
    # contention when TradingView webhooks or the background worker arrived at
    # the same time. The background worker/webhook path now owns live repair.
    # This keeps /dashboard from throwing 500s just because the DB is briefly
    # busy.
    if env_bool("DASHBOARD_RUN_MAINTENANCE", False):
        try:
            if _broker_retry_worker_lock.acquire(blocking=False):
                try:
                    run_broker_retry_maintenance_tick("dashboard_backup_tick")
                finally:
                    _broker_retry_worker_lock.release()
        except Exception as e:
            log_system_event("dashboard_warning", f"Dashboard maintenance skipped: {e}")
        try:
            auto_close_index_basket_cycle_if_flat("dashboard_maintenance")
        except Exception as e:
            log_system_event("dashboard_warning", f"Index basket flat-cycle auto-close skipped: {e}")
    broker_dashboard_html = build_live_demo_scope_html() + build_oanda_dashboard_html()
    defence_escalation_dashboard_html = build_defence_escalation_dashboard_html()
    advice_outcome_dashboard_html = build_advice_outcome_dashboard_html()
    basket_profit_protection_dashboard_html = build_basket_profit_protection_dashboard_html()
    managed_stop_research_dashboard_html = build_managed_stop_research_dashboard_html()
    live_gap_watch_status_html = build_live_gap_watch_status_html()
    gap_sl_extension_research_html = build_gap_sl_extension_research_html()
