            research_context_accepted_rows = [r for r in research_context_all_rows if int(r.get("candidate") or 0) == 1]
            research_context_candidate_like_rows = [r for r in research_context_all_rows if int(r.get("candidate_like") or 0) == 1]
            research_context_accepted_summary = summarise_research_context_outcomes(research_context_accepted_rows)
            research_context_candidate_like_summary = summarise_research_context_outcomes(research_context_candidate_like_rows)
