    overall = perf["overall"]
    periods = perf["periods"]
    by_asset = perf["by_asset"]
    trade_status = perf.get("trade_status", {})

    # v10.0.7 dashboard live-state repair:
    # Family/tide rows are event snapshots and can be stale immediately after
    # executable closes. For current live tiles/tables, ground displayed
    # open count/P&L/status in the actual open_trades table.
    index_demo_assets = {safe_str(x).upper() for x in (DASHBOARD_SCOPE_ASSETS or ["BCOUSD"])}
    actual_open_by_asset: Dict[str, int] = {}
    actual_pnl_by_asset: Dict[str, float] = {}
    pending_broker_entry_by_asset: Dict[str, int] = {}
    broker_confirmed_open_shadow_ids = broker_confirmed_open_shadow_ids if 'broker_confirmed_open_shadow_ids' in locals() else set()
    broker_pending_entry_shadow_ids = broker_pending_entry_shadow_ids if 'broker_pending_entry_shadow_ids' in locals() else set()
    live_index_open_rows = []
    pending_index_open_rows = []
    phantom_index_open_rows = []
    for _r in open_rows:
        _asset = safe_str(_r["asset"]).upper()
        _tid = safe_str(_r["trade_id"])
        if _asset not in index_demo_assets:
            continue
        if _tid in broker_confirmed_open_shadow_ids:
            live_index_open_rows.append(_r)
            actual_open_by_asset[_asset] = actual_open_by_asset.get(_asset, 0) + 1
            actual_pnl_by_asset[_asset] = actual_pnl_by_asset.get(_asset, 0.0) + pnl_from_return(_asset, _r["return_pct"])
        elif _tid in broker_pending_entry_shadow_ids:
            pending_index_open_rows.append(_r)
            pending_broker_entry_by_asset[_asset] = pending_broker_entry_by_asset.get(_asset, 0) + 1
        else:
            phantom_index_open_rows.append(_r)
    actual_index_open = sum(actual_open_by_asset.get(_a, 0) for _a in index_demo_assets)
    actual_index_pnl = sum(actual_pnl_by_asset.get(_a, 0.0) for _a in index_demo_assets)
    pending_index_entries = sum(pending_broker_entry_by_asset.get(_a, 0) for _a in index_demo_assets)
    phantom_index_entries = len(phantom_index_open_rows)

    # Actual broker/account values from OANDA. In standalone BCO mode the
    # practice account is restricted to BCO_USD, so account UPL is the cleanest
    # broker-actual basket P&L/high-water/giveback source. The linked shadow
    # model P&L remains available as an audit/comparison value.
    broker_nav = safe_float(latest_broker_snapshot["nav"]) if latest_broker_snapshot else None
    broker_balance = safe_float(latest_broker_snapshot["balance"]) if latest_broker_snapshot else None
    broker_unrealized = safe_float(latest_broker_snapshot["unrealized_pl"]) if latest_broker_snapshot else None
    broker_snapshot_time = safe_str(latest_broker_snapshot["created_at_utc"]) if latest_broker_snapshot else ""
    broker_index_upl = broker_unrealized if (broker_unrealized is not None and actual_index_open > 0) else 0.0

    # Build a clear, separate metals research lane. This is deliberately not
    # mixed into index basket P&L, broker promotion, or the June go-live decision.
    metal_sl_placeholder = {"XAUUSD": "2.21%", "XAU": "2.21%", "XAGUSD": "5.24%", "XAG": "5.24%"}

    def _metal_raw_dict(row: Any) -> Dict[str, Any]:
        try:
            return json.loads(row["raw_json"] or "{}")
        except Exception:
            return {}

    def _metal_value(raw: Dict[str, Any], key: str, default: Any = "") -> Any:
        return raw.get(key, default)

    metal_summary_html_rows = ""
    for row in metal_summary_rows if 'metal_summary_rows' in locals() else []:
        pair = safe_str(row["pair"]).upper()
        signal_count = int(row["signal_count"] or 0)
        candidate_count = int(row["candidate_count"] or 0)
        candidate_rate = (candidate_count / signal_count * 100) if signal_count > 0 else 0.0
        metal_summary_html_rows += f"""
        <tr>
            <td><strong>{esc(pair)}</strong></td>
            <td>{signal_count}</td>
            <td>{candidate_count}</td>
            <td>{candidate_rate:.1f}%</td>
            <td>{esc(metal_sl_placeholder.get(pair, 'TBC'))}</td>
            <td>{esc(display_utc_time(row['latest_received_at_utc']))}</td>
            <td><strong>RESEARCH_ONLY</strong></td>
        </tr>
        """

    metal_latest_html_rows = ""
    for row in metal_latest_rows if 'metal_latest_rows' in locals() else []:
        raw = _metal_raw_dict(row)
        pair = safe_str(row["pair"]).upper()
        cand = is_true(row["forward_test_candidate"])
        cand_text = "true" if cand else "false"
        score = _metal_value(raw, "score_raw", "")
        setup = _metal_value(raw, "setup_type", "")
        quality = _metal_value(raw, "signal_quality", "")
        ctx = _metal_value(raw, "ctx_trend_state", "")
        d_bear = _metal_value(raw, "d_bear", "")
        d_bull = _metal_value(raw, "d_bull", "")
        trend_rule = _metal_value(raw, "rule_trend_long_v1", "")
        continuation_rule = _metal_value(raw, "rule_bull_continuation_v1", "")
        reject = safe_str(_metal_value(raw, "reject_reason", ""))
        if not reject and not cand:
            blockers = []
            if str(d_bear).lower() == "true":
                blockers.append("daily bear filter")
            if str(trend_rule).lower() != "true" and str(continuation_rule).lower() != "true":
                blockers.append("long rules false")
            reject = ", ".join(blockers) or "candidate rules not met"
        short_info = infer_metal_short_candidate(raw, row)
        short_cand = int(short_info.get("short_candidate") or 0) == 1
        short_text = "true" if short_cand else "false"
        short_cls = "true" if short_cand else ("warn" if int(short_info.get("short_watch") or 0) == 1 else "false")
        metal_latest_html_rows += f"""
        <tr>
            <td><strong>{esc(pair)}</strong></td>
            <td>{esc(display_candle_time(row['timestamp_readable']))}</td>
            <td class="{cand_text}"><strong>{cand_text}</strong></td>
            <td class="{short_cls}"><strong>{short_text}</strong></td>
            <td>{esc(short_info.get('short_score'))}</td>
            <td>{esc(short_info.get('short_reason'))}</td>
            <td>{esc(score)}</td>
            <td>{esc(quality)}</td>
            <td>{esc(setup)}</td>
            <td>{esc(ctx)}</td>
            <td>{esc(_metal_value(raw, 'exec_rsi', ''))}</td>
            <td>{esc(_metal_value(raw, 'exec_break_high', ''))}</td>
            <td>{esc(_metal_value(raw, 'exec_is_breakout', ''))}</td>
            <td>{esc(d_bull)}</td>
            <td>{esc(d_bear)}</td>
            <td>{esc(trend_rule)}</td>
            <td>{esc(continuation_rule)}</td>
            <td>{esc(metal_sl_placeholder.get(pair, 'TBC'))}</td>
            <td>{esc(reject)}</td>
        </tr>
        """

    metal_recent_html_rows = ""
    for row in metal_recent_rows if 'metal_recent_rows' in locals() else []:
        raw = _metal_raw_dict(row)
        pair = safe_str(row["pair"]).upper()
        cand = is_true(row["forward_test_candidate"])
        cand_text = "true" if cand else "false"
        metal_recent_html_rows += f"""
        <tr>
            <td>{esc(row['id'])}</td>
            <td><strong>{esc(pair)}</strong></td>
            <td>{esc(display_candle_time(row['timestamp_readable']))}</td>
            <td class="{cand_text}">{cand_text}</td>
            <td>{esc(_metal_value(raw, 'score_raw', ''))}</td>
            <td>{esc(_metal_value(raw, 'signal_quality', ''))}</td>
            <td>{esc(_metal_value(raw, 'setup_type', ''))}</td>
            <td>{esc(_metal_value(raw, 'ctx_trend_state', ''))}</td>
            <td>{esc(_metal_value(raw, 'd_bear', ''))}</td>
            <td>{esc(_metal_value(raw, 'exec_rsi', ''))}</td>
            <td>{esc(row['exec_close'])}</td>
        </tr>
        """


    metal_accepted_summary_rows = _metal_outcome_summary_html(
        metal_accepted_candidate_summary if 'metal_accepted_candidate_summary' in locals() else [],
        'No accepted metal forward_test_candidate=true rows yet.'
    )
    metal_candidate_like_summary_rows = _metal_outcome_summary_html(
        metal_candidate_like_summary if 'metal_candidate_like_summary' in locals() else [],
        'No candidate-like metal rows with completed outcome windows yet.'
    )
    metal_all_observation_summary_rows = _metal_outcome_summary_html(
        metal_all_observation_summary if 'metal_all_observation_summary' in locals() else [],
        'No metal signal observation outcome windows yet.'
    )

    metal_accepted_detail_rows = _metal_outcome_detail_html(metal_accepted_candidate_rows if 'metal_accepted_candidate_rows' in locals() else [], limit=80)
    metal_candidate_like_detail_rows = _metal_outcome_detail_html(metal_candidate_like_rows if 'metal_candidate_like_rows' in locals() else [], limit=80)
    metal_all_detail_rows = _metal_outcome_detail_html(metal_outcome_all_rows if 'metal_outcome_all_rows' in locals() else [], limit=80)

    metal_short_candidate_summary_rows = _metal_outcome_summary_html(
        metal_short_candidate_summary if 'metal_short_candidate_summary' in locals() else [],
        'No generated metal short candidates with completed outcome windows yet.'
    )
    metal_short_watch_summary_rows = _metal_outcome_summary_html(
        metal_short_watch_summary if 'metal_short_watch_summary' in locals() else [],
        'No generated metal short watch rows yet.'
    )
    metal_short_candidate_detail_rows = _metal_short_outcome_detail_html(metal_short_candidate_rows if 'metal_short_candidate_rows' in locals() else [], limit=80)

    metal_accepted_count = len(metal_accepted_candidate_rows) if 'metal_accepted_candidate_rows' in locals() else 0
    metal_candidate_like_count = len(metal_candidate_like_rows) if 'metal_candidate_like_rows' in locals() else 0
    metal_observation_count = len(metal_outcome_all_rows) if 'metal_outcome_all_rows' in locals() else 0
    metal_short_candidate_count = len(metal_short_candidate_rows) if 'metal_short_candidate_rows' in locals() else 0
    metal_short_watch_count = len(metal_short_watch_rows) if 'metal_short_watch_rows' in locals() else 0
    metal_short_basket_sim_html_rows = _metal_basket_simulation_html(
        build_metal_basket_simulation_summary(metal_short_candidate_rows if 'metal_short_candidate_rows' in locals() else [], milestone=48),
        empty='No generated metal short candidates ready for basket-manager simulation yet.'
    )

    # v10.0.87: simple metals basket-manager research proxy. This is deliberately
    # not executable and does not touch OANDA, index high-water, or live rules.
    metal_basket_sim_html_rows = ""
    for asset in sorted({safe_str(r.get('asset')).upper() for r in (metal_accepted_candidate_rows if 'metal_accepted_candidate_rows' in locals() else []) if safe_str(r.get('asset'))}):
        subset = [r for r in (metal_accepted_candidate_rows if 'metal_accepted_candidate_rows' in locals() else []) if safe_str(r.get('asset')).upper() == asset]
        sl = metal_research_sl_pct(asset)
        matured_48 = [r for r in subset if int(r.get('has_48h') or 0) == 1]
        returns_48 = [safe_float(r.get('return_48h_pct')) for r in matured_48]
        maes_48 = [safe_float(r.get('mae_48h_pct')) for r in matured_48]
        raw_pnls_48 = [safe_float(r.get('pnl50_48h')) for r in matured_48]
        returns_48 = [v for v in returns_48 if v is not None]
        maes_48 = [v for v in maes_48 if v is not None]
        raw_pnls_48 = [v for v in raw_pnls_48 if v is not None]
        sl_pressure = sum(1 for v in maes_48 if v <= -abs(sl))
        adj_pnls_48 = [(-50.0 if (safe_float(r.get('mae_48h_pct')) is not None and safe_float(r.get('mae_48h_pct')) <= -abs(sl)) else safe_float(r.get('pnl50_48h'))) for r in matured_48]
        adj_pnls_48 = [v for v in adj_pnls_48 if v is not None]
        avg_ret_48 = (sum(returns_48) / len(returns_48)) if returns_48 else None
        avg_mae_48 = (sum(maes_48) / len(maes_48)) if maes_48 else None
        raw_sum_48 = sum(raw_pnls_48) if raw_pnls_48 else None
        adj_sum_48 = sum(adj_pnls_48) if adj_pnls_48 else None
        if not matured_48:
            sim_state = 'WAITING_FOR_48H_DATA'
            sim_cls = 'flat'
        elif sl_pressure > 0 and avg_ret_48 is not None and avg_ret_48 < 0:
            sim_state = 'DEFENCE_LIKELY'
            sim_cls = 'status_red'
        elif avg_ret_48 is not None and avg_ret_48 < 0:
            sim_state = 'CAUTION'
            sim_cls = 'status_amber'
        else:
            sim_state = 'BENIGN_SO_FAR'
            sim_cls = 'status_green'
