    avg_status_rows = ""

    def avg_status_row(label: str, status: Dict[str, Any]) -> str:
        avg_return = float(status.get('avg_return_pct', 0) or 0)
        avg_mfe = float(status.get('avg_mfe_pct', 0) or 0)
        avg_mae = float(status.get('avg_mae_pct', 0) or 0)

        # Signed MFE/MAE ratio:
        # - magnitude = average favourable excursion / absolute average adverse excursion
        # - sign follows the average return, so losing groups show as negative
        mfe_mae_ratio = (avg_mfe / abs(avg_mae)) if avg_mae != 0 else 0.0
        if avg_return < 0:
            mfe_mae_ratio = -abs(mfe_mae_ratio)
        elif avg_return > 0:
            mfe_mae_ratio = abs(mfe_mae_ratio)
        else:
            mfe_mae_ratio = 0.0

