# ============================================================
# LIVE PROTECTION AUTOMATION - NATIVE OANDA STOPS + HARVEST EXECUTION
# ============================================================

def broker_auto_update_managed_stops(limit: int = 250, source: str = "auto") -> Dict[str, Any]:
    """Automatically ratchet eligible linked OANDA trade stop-losses."""
    if not BROKER_MANAGED_STOPS_ENABLED:
        return {"ok": True, "skipped": True, "reason": "BROKER_MANAGED_STOPS_ENABLED=false"}
    if not BROKER_MANAGED_STOPS_AUTO_SYNC_ENABLED:
        return {"ok": True, "skipped": True, "reason": "BROKER_MANAGED_STOPS_AUTO_SYNC_ENABLED=false"}
    safety = oanda_safety_state()
    if not safety.get("orders_allowed"):
        return {"ok": False, "skipped": True, "reason": safe_str(safety.get("reason") or "orders not allowed"), "safety": safety}
    rows = managed_stops_status_rows(limit=limit)
    results = []
    for cand in rows:
        if not cand.get("eligible"):
            continue

        # v10.0.96: do not tighten managed stops during the Sunday/Monday gap-watch
        # window. Existing OANDA stops are left exactly where they are; this does
        # not loosen, remove, or widen any live stop.
        if (
            BROKER_GAP_WATCH_FREEZE_MANAGED_STOP_TIGHTENING
            and is_index_asset(safe_str(cand.get("shadow_asset")))
            and is_sunday_monday_gap_watch_window(cand.get("signal_time"))
        ):
            event_id = insert_managed_stop_event(
                cand.get("link_id"), cand.get("shadow_trade_id"), cand.get("instrument"), cand.get("broker_trade_id"),
                "managed_stop_auto_sync", "SKIPPED_GAP_WATCH_FREEZE", cand.get("rule_stage"), cand.get("side"), cand.get("hold_candles"),
                cand.get("filled_units"), cand.get("broker_fill_price"), cand.get("shadow_current_price"), cand.get("previous_stop_price"),
                cand.get("stop_price"), cand.get("protected_pnl_approx"), cand.get("protected_profit_pct"), None,
                "Sunday/Monday gap-watch: freeze new tightening; existing OANDA stop unchanged.",
                {"candidate": cand, "source": source, "gap_watch_freeze": True},
            )
            results.append({
                "event_id": event_id,
                "ok": True,
                "skipped": True,
                "reason": "gap_watch_freeze_managed_stop_tightening",
                "trade_id": cand.get("shadow_trade_id"),
                "broker_trade_id": cand.get("broker_trade_id"),
                "existing_stop_unchanged": True,
            })
            continue

        resp = oanda_set_trade_stop_loss(cand.get("broker_trade_id"), cand.get("stop_price"), cand.get("instrument"))
        success = bool(resp.get("ok"))
        event_id = insert_managed_stop_event(
            cand.get("link_id"), cand.get("shadow_trade_id"), cand.get("instrument"), cand.get("broker_trade_id"),
            "managed_stop_auto_sync", "UPDATED" if success else "FAILED", cand.get("rule_stage"), cand.get("side"), cand.get("hold_candles"),
            cand.get("filled_units"), cand.get("broker_fill_price"), cand.get("shadow_current_price"), cand.get("previous_stop_price"),
            cand.get("stop_price"), cand.get("protected_pnl_approx"), cand.get("protected_profit_pct"), resp.get("status_code"),
            cand.get("reason"), {"candidate": cand, "response": resp, "source": source},
        )
        results.append({"event_id": event_id, "ok": success, "trade_id": cand.get("shadow_trade_id"), "broker_trade_id": cand.get("broker_trade_id"), "stop_price": cand.get("stop_price"), "response_status_code": resp.get("status_code")})
    return {"ok": True, "enabled": True, "eligible_count": len([r for r in rows if r.get("eligible")]), "processed_count": len(results), "results": results, "time_utc": now_utc_iso()}


def _close_shadow_trade_for_harvest(conn: sqlite3.Connection, trade_dict: Dict[str, Any], exit_price: float, reason: str) -> None:
    class _TradeDict(dict):
        def __getitem__(self, k):
            return self.get(k)
    t = _TradeDict(trade_dict)
    close_open_trade(
        conn=conn,
        trade=t,
        exit_time=safe_str(trade_dict.get("last_seen_time") or now_utc_iso()),
        exit_price=float(exit_price),
        hold_candles=int(safe_float(trade_dict.get("hold_candles")) or 0),
        exit_reason=reason,
        return_pct=safe_float(trade_dict.get("return_pct")) or 0.0,
        mfe_pct=safe_float(trade_dict.get("mfe_pct")) or 0.0,
        mae_pct=safe_float(trade_dict.get("mae_pct")) or 0.0,
        highest_high=safe_float(trade_dict.get("highest_high")) or float(exit_price),
        lowest_low=safe_float(trade_dict.get("lowest_low")) or float(exit_price),
        sl_hit=False,
    )


def execute_index_harvest_if_needed(limit: int = 250, source: str = "auto") -> Dict[str, Any]:
    """Execute the Project Exit Plan 40/60/75/100R ladder for the active dashboard family.

    The historic function name is retained for compatibility, but standalone BCO
    mode targets OIL_BASKET / BCOUSD rather than INDEX_BASKET.
    """
    if not BROKER_HARVEST_EXECUTION_ENABLED:
        return {"ok": True, "skipped": True, "reason": "BROKER_HARVEST_EXECUTION_ENABLED=false"}
    safety = oanda_safety_state()
    if not safety.get("orders_allowed"):
        return {"ok": False, "skipped": True, "reason": safe_str(safety.get("reason") or "orders not allowed"), "safety": safety}
    harvest_family = safe_str(DASHBOARD_SCOPE_FAMILY or "INDEX_BASKET").upper()
    harvest_assets = [safe_str(x).upper() for x in (DASHBOARD_SCOPE_ASSETS or ["NAS100", "US500"])]
    if len(harvest_assets) == 1:
        risk_unit = float(effective_broker_shadow_auto_risk_amount_for_asset(harvest_assets[0]) or 0.0)
    else:
        risk_unit = float(effective_broker_shadow_auto_risk_amount() or BROKER_SHADOW_AUTO_RISK_AMOUNT or 0.0)
    if risk_unit <= 0:
        return {"ok": False, "skipped": True, "reason": "risk unit <= 0"}
    init_db()
    with get_conn() as conn:
        fam = conn.execute("SELECT * FROM active_family_basket_cycles WHERE family=? LIMIT 1", (harvest_family,)).fetchone()
        if not fam:
            return {"ok": True, "skipped": True, "reason": f"no active {harvest_family} family row"}
        fam_d = dict(fam)
        open_count = int(safe_float(fam_d.get("open_trades")) or 0)
        if open_count <= 0 or safe_str(fam_d.get("status")).lower() == "closed":
            return {"ok": True, "skipped": True, "reason": f"{harvest_family} basket flat/closed"}
        cycle_id = safe_str(fam_d.get("family_cycle_id") or harvest_family)
        high_water = safe_float(fam_d.get("high_water_pnl_50risk")) or 0.0
        high_water_r = high_water / risk_unit if risk_unit else 0.0
        already_rows = conn.execute(
            "SELECT threshold_r FROM broker_harvest_events WHERE family=? AND family_cycle_id=? AND status IN ('EXECUTED','PARTIAL')",
            (harvest_family, cycle_id),
        ).fetchall()
        already = {int(safe_float(r["threshold_r"]) or 0) for r in already_rows}
        asset_placeholders = ",".join(["?"] * len(harvest_assets))
        rows = conn.execute(f"""
            SELECT o.*, l.id AS link_id, l.instrument AS broker_instrument, l.broker_trade_id,
                   l.filled_units, l.last_known_units, l.last_known_price, l.side AS broker_side
            FROM open_trades o
            JOIN broker_trade_links l ON l.shadow_trade_id = o.trade_id
            WHERE o.status='open'
              AND UPPER(o.asset) IN ({asset_placeholders})
              AND UPPER(COALESCE(l.status,''))='OPEN'
              AND COALESCE(l.broker_trade_id,'') <> ''
            ORDER BY COALESCE(o.hold_candles,0) DESC
            LIMIT ?
        """, tuple(harvest_assets + [limit])).fetchall()
        candidates = []
        for r in rows:
            d = dict(r)
            hold = int(safe_float(d.get("hold_candles")) or 0)
            if hold < BROKER_HARVEST_MIN_HOLD_CANDLES:
                continue
            ret = safe_float(d.get("return_pct")) or 0.0
            asset = safe_str(d.get("asset")).upper()
            sl = safe_float(CONFIG.get(asset, {}).get("sl_pct")) or BROKER_SHADOW_AUTO_SL_PCT or 1.5
            pnl = (ret / sl) * risk_unit if sl else 0.0
            if pnl <= 0:
                continue
            d["harvest_pnl_approx"] = pnl
            candidates.append(d)
        candidates.sort(key=lambda x: (-(int(safe_float(x.get("hold_candles")) or 0)), -(safe_float(x.get("harvest_pnl_approx")) or 0.0)))
        results = []
        for threshold_r, fraction in BROKER_HARVEST_LEVELS:
            if high_water_r < float(threshold_r) or int(threshold_r) in already:
                continue
            remaining_pool = sum(float(x.get("harvest_pnl_approx") or 0.0) for x in candidates)
            target = remaining_pool * float(fraction)
            if target <= 0 or not candidates:
                conn.execute("""
                    INSERT INTO broker_harvest_events (created_at_utc,family,family_cycle_id,threshold_r,bank_fraction,target_bank_pnl,executed_bank_pnl_approx,risk_per_trade,high_water_pnl,high_water_r,status,reason,raw_json)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
                """, (now_utc_iso(), harvest_family, cycle_id, float(threshold_r), float(fraction), target, 0.0, risk_unit, high_water, high_water_r, "NO_ELIGIBLE_TRADES", "threshold hit but no mature profitable linked trades", json.dumps({"source": source})))
                conn.commit()
                already.add(int(threshold_r))
                continue
            selected = []
            running = 0.0
            for c in candidates:
                if running < target:
                    selected.append(c)
                    running += float(c.get("harvest_pnl_approx") or 0.0)
            close_results = []
            actual_pnl_approx = 0.0
            ok_all = True
            for c in selected:
                broker_trade_id = safe_str(c.get("broker_trade_id"))
                close_body = {"units": "ALL"}
                resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
                details = extract_oanda_execution_details(resp)
                success = bool(resp.get("ok"))
                ok_all = ok_all and success
                actual_price = safe_float(details.get("actual_price")) or safe_float(c.get("current_price")) or safe_float(c.get("entry_price")) or 0.0
                fill_price = safe_float(c.get("last_known_price")) or safe_float(c.get("entry_price")) or 0.0
                units = abs(safe_float(c.get("filled_units")) or safe_float(c.get("last_known_units")) or 0.0)
                approx = max(0.0, (float(actual_price) - float(fill_price)) * units) if success and fill_price and actual_price and units else float(c.get("harvest_pnl_approx") or 0.0)
                if success:
                    actual_pnl_approx += approx
                    conn.execute("""
                        UPDATE broker_trade_links
                        SET updated_at_utc=?, status='CLOSE_SENT', closed_at_utc=COALESCE(NULLIF(closed_at_utc,''), ?),
                            last_reconciled_at_utc=?, notes=?
                        WHERE id=?
                    """, (now_utc_iso(), now_utc_iso(), now_utc_iso(), f"Auto harvest close at {threshold_r}R", int(c.get("link_id"))))
                    _close_shadow_trade_for_harvest(conn, c, float(actual_price), f"broker_harvest_{threshold_r}R")
                close_results.append({"trade_id": c.get("trade_id"), "broker_trade_id": broker_trade_id, "ok": success, "approx_pnl": approx, "response_status_code": resp.get("status_code"), "response": resp})
            status = "EXECUTED" if ok_all else "PARTIAL"
            conn.execute("""
                INSERT INTO broker_harvest_events (created_at_utc,family,family_cycle_id,threshold_r,bank_fraction,target_bank_pnl,executed_bank_pnl_approx,risk_per_trade,high_water_pnl,high_water_r,status,selected_trade_ids,selected_broker_trade_ids,response_status_code,reason,raw_json)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                now_utc_iso(), "INDEX_BASKET", cycle_id, float(threshold_r), float(fraction), target, actual_pnl_approx,
                risk_unit, high_water, high_water_r, status,
                ",".join(safe_str(x.get("trade_id")) for x in selected),
                ",".join(safe_str(x.get("broker_trade_id")) for x in selected),
                200 if ok_all else None,
                f"Auto harvest level {threshold_r}R; target approx {target:.2f}; executed approx {actual_pnl_approx:.2f}",
                json.dumps({"source": source, "close_results": close_results}, default=str),
            ))
            conn.commit()
            results.append({"threshold_r": threshold_r, "target": target, "executed_approx": actual_pnl_approx, "selected_count": len(selected), "status": status})
            already.add(int(threshold_r))
            selected_ids = {safe_str(x.get("trade_id")) for x in selected}
            candidates = [x for x in candidates if safe_str(x.get("trade_id")) not in selected_ids]
        return {"ok": True, "enabled": True, "cycle_id": cycle_id, "risk_per_trade": risk_unit, "high_water": high_water, "high_water_r": high_water_r, "executed_levels": results, "time_utc": now_utc_iso()}


def broker_live_protection_maintenance_tick(source: str = "auto") -> Dict[str, Any]:
    """One protection pass: native stop ratchet first, harvest execution second."""
    result: Dict[str, Any] = {"ok": True, "source": source, "time_utc": now_utc_iso()}
    try:
        result["managed_stops"] = broker_auto_update_managed_stops(source=source)
    except Exception as e:
        result["ok"] = False
        result["managed_stops_error"] = f"{type(e).__name__}: {e}"
    try:
        result["harvest"] = execute_index_harvest_if_needed(source=source)
    except Exception as e:
        result["ok"] = False
        result["harvest_error"] = f"{type(e).__name__}: {e}"
    if not result.get("ok"):
        try:
            log_system_event("broker_live_protection_warning", json.dumps(result, default=str)[:1800])
        except Exception:
            pass
    return result


@app.get("/export/broker-harvest-events.csv")
def export_broker_harvest_events_csv(limit: int = 5000) -> Response:
    init_db()
    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute("SELECT * FROM broker_harvest_events ORDER BY id DESC LIMIT ?", (max(1, min(int(limit or 5000), 20000)),)).fetchall()]
    fieldnames = list(rows[0].keys()) if rows else ["id","created_at_utc","family","family_cycle_id","threshold_r","bank_fraction","target_bank_pnl","executed_bank_pnl_approx","risk_per_trade","high_water_pnl","high_water_r","status","selected_trade_ids","selected_broker_trade_ids","response_status_code","reason","raw_json"]
    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow(row)
    return Response(content=output.getvalue(), media_type="text/csv", headers={"Content-Disposition": 'attachment; filename="broker-harvest-events.csv"'})

