@app.post("/broker/oanda/test/close-latest-shadow-auto-links")
async def broker_oanda_test_close_latest_shadow_auto_links(request: Request) -> Dict[str, Any]:
    """Close the latest N OPEN shadow-demo broker links.

    Intended for demo cleanup after accidental backfill/promotion. Dry-run is the
    default. To actually send closes, POST JSON like:

    {
      "confirm": "CLOSE_LATEST_SHADOW_AUTO_LINKS",
      "count": 15,
      "dry_run": false,
      "reason": "cleanup accidental 25-to-40 capacity backfill"
    }

    This closes broker-side OANDA live account trades only and marks their broker links
    CLOSE_SENT. It does not delete Railway shadow research trades.
    """
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}

    count = int(safe_float(payload.get("count")) or 15)
    count = max(1, min(count, 50))
    dry_run = parse_bool(payload.get("dry_run"), True)
    confirm = safe_str(payload.get("confirm"))
    reason = safe_str(payload.get("reason") or "cleanup latest shadow-auto broker links")

    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute("""
            SELECT *
            FROM broker_trade_links
            WHERE mode = 'shadow_demo_auto'
              AND status = 'OPEN'
            ORDER BY id DESC
            LIMIT ?
        """, (count,)).fetchall()]

    preview = [
        {
            "link_id": r.get("id"),
            "created_at_utc": r.get("created_at_utc"),
            "shadow_trade_id": r.get("shadow_trade_id"),
            "shadow_asset": r.get("shadow_asset"),
            "instrument": r.get("instrument"),
            "side": r.get("side"),
            "filled_units": r.get("filled_units"),
            "broker_trade_id": r.get("broker_trade_id"),
            "last_known_unrealized_pl": r.get("last_known_unrealized_pl"),
        }
        for r in rows
    ]

    if dry_run or confirm != "CLOSE_LATEST_SHADOW_AUTO_LINKS":
        return {
            "status": "dry_run",
            "ok": True,
            "dry_run": True,
            "message": "No broker orders sent. Repost with dry_run=false and confirm=CLOSE_LATEST_SHADOW_AUTO_LINKS to close these latest OPEN shadow-auto links.",
            "selected_count": len(rows),
            "selected_links": preview,
            "time_utc": now_utc_iso(),
        }

    can_close, close_reason = broker_shadow_auto_can_close()
    if not can_close:
        return {
            "status": "blocked",
            "ok": False,
            "reason": close_reason,
            "selected_count": len(rows),
            "selected_links": preview,
            "auto_status": broker_shadow_auto_status(),
            "time_utc": now_utc_iso(),
        }

    results = []
    for link in rows:
        link_id = int(link.get("id") or 0)
        broker_trade_id = safe_str(link.get("broker_trade_id") or "")
        instrument = normalise_oanda_instrument(link.get("instrument") or "")
        side = safe_str(link.get("side") or "")
        shadow_trade_id = safe_str(link.get("shadow_trade_id") or "")
        shadow_asset = safe_str(link.get("shadow_asset") or "")

        if not broker_trade_id:
            results.append({"link_id": link_id, "ok": False, "error": "missing broker_trade_id"})
            continue

        qid = create_broker_action_queue_item(
            action="close_linked_trade",
            instrument=instrument,
            side=side,
            shadow_trade_id=shadow_trade_id,
            shadow_asset=shadow_asset,
            family=get_basket_family(shadow_asset),
            requested_units=safe_float(link.get("last_known_units")) or safe_float(link.get("filled_units")),
            reason=reason,
            preview={"broker_trade_link_id": link_id, "broker_trade_id": broker_trade_id, "cleanup_latest_shadow_auto_links": True},
            mode="shadow_demo_auto",
            source="cleanup_latest_shadow_auto_links",
            status="QUEUED_CLEANUP_CLOSE",
            notes="Cleanup close for accidental/backfilled shadow-auto broker link. Does not alter Railway shadow research trade.",
        )
        with get_conn() as conn:
            conn.execute("UPDATE broker_action_queue SET broker_trade_link_id = ? WHERE id = ?", (link_id, qid))
            conn.commit()

        close_body = {"units": "ALL"}
        resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
        details = extract_oanda_execution_details(resp)
        broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
        success = bool(resp.get("ok"))

        audit_id = log_execution_audit_event(
            "shadow_demo_auto", instrument, shadow_trade_id, "cleanup_close_latest_shadow_auto_link",
            success, f"cleanup close latest shadow-auto broker link {link_id}; queue {qid}; {reason}", broker_order_id,
            raw={"queue_id": qid, "broker_trade_link": link, "request": close_body, "response": resp, "reason": reason},
            side=side, close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
            broker_trade_id=broker_trade_id, response_status_code=details.get("response_status_code"),
        )

        if success:
            now_closed = now_utc_iso()
            with get_conn() as conn:
                conn.execute("""
                    UPDATE broker_trade_links
                    SET updated_at_utc = ?, status = 'CLOSE_SENT',
                        closed_at_utc = COALESCE(NULLIF(closed_at_utc,''), ?),
                        last_reconciled_at_utc = ?,
                        notes = ?
                    WHERE id = ?
                """, (now_closed, now_closed, now_closed, f"Cleanup close sent from queue id {qid}. Reason: {reason}", link_id))
                conn.commit()
            update_broker_action_queue_status(qid, "EXECUTED", "Cleanup close executed", audit_id, link_id)
        else:
            if is_oanda_market_closed_response(resp):
                mark_queue_waiting_market_reopen(qid, resp, audit_id, link_id)
            elif is_oanda_timeout_or_unknown_response(resp):
                mark_queue_waiting_reconciliation(qid, resp, audit_id, link_id)
            else:
                update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA close failed"), audit_id, link_id)

        results.append({
            "link_id": link_id,
            "queue_id": qid,
            "ok": success,
            "waiting_market_reopen": (not success and is_oanda_market_closed_response(resp)),
            "waiting_reconciliation": (not success and is_oanda_timeout_or_unknown_response(resp)),
            "broker_trade_id": broker_trade_id,
            "response_status_code": details.get("response_status_code"),
        })

    try:
        reconcile_result = reconcile_broker_trade_links()
    except Exception as e:
        reconcile_result = {"ok": False, "error": f"reconcile failed after cleanup closes: {type(e).__name__}: {e}"}

    return {
        "status": "ok",
        "ok": True,
        "dry_run": False,
        "requested_count": count,
        "selected_count": len(rows),
        "closed_sent_count": sum(1 for r in results if r.get("ok")),
        "results": results,
        "reconcile": reconcile_result,
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/oanda/test/mark-failed-queue-reviewed")
async def broker_oanda_test_mark_failed_queue_reviewed(
    request: Request,
    x_webhook_secret: Optional[str] = Header(default=None),
    secret: Optional[str] = None,
) -> Dict[str, Any]:
    """Mark reviewed failed/error broker queue rows as resolved.

    This is a local dashboard/DB cleanup helper. It does not send broker orders,
    does not delete audit evidence, and does not change broker_trade_links or
    OANDA positions. It simply moves reviewed failed/error queue rows to a status
    that no longer blocks reconciliation/preflight.

    Dry-run is the default. To apply:
    {
      "confirm": "MARK_FAILED_QUEUE_REVIEWED",
      "dry_run": false,
      "count": 10,
      "reason": "reviewed harmless cleanup failure after broker link count returned to 25"
    }
    """
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}

    body_secret = safe_str(payload.get("secret", ""))
    query_secret = safe_str(secret)
    if (
        x_webhook_secret != WEBHOOK_SECRET
        and body_secret != WEBHOOK_SECRET
        and query_secret != WEBHOOK_SECRET
    ):
        raise HTTPException(status_code=401, detail="Invalid webhook secret")

    count = int(safe_float(payload.get("count")) or 10)
    count = max(1, min(count, 100))
    dry_run = parse_bool(payload.get("dry_run"), True)
    confirm = safe_str(payload.get("confirm"))
    reason = safe_str(payload.get("reason") or "reviewed failed broker queue item")

    raw_ids = payload.get("queue_ids") or payload.get("ids") or []
    queue_ids: List[int] = []
    if isinstance(raw_ids, list):
        for item in raw_ids:
            val = safe_float(item)
            if val is not None:
                queue_ids.append(int(val))
    elif safe_str(raw_ids):
        for part in safe_str(raw_ids).split(","):
            val = safe_float(part)
            if val is not None:
                queue_ids.append(int(val))
    queue_ids = sorted(list({x for x in queue_ids if x > 0}))[:100]

    failed_status_where = """
        (UPPER(COALESCE(status,'')) LIKE '%FAILED%'
         OR UPPER(COALESCE(status,'')) LIKE '%ERROR%')
        AND UPPER(COALESCE(status,'')) NOT IN ('WAITING_MARKET_REOPEN','WAITING_RECONCILIATION','REVIEWED_RESOLVED')
    """

    with get_conn() as conn:
        if queue_ids:
            placeholders = ",".join(["?"] * len(queue_ids))
            rows = [dict(r) for r in conn.execute(f"""
                SELECT *
                FROM broker_action_queue
                WHERE id IN ({placeholders})
                  AND {failed_status_where}
                ORDER BY id DESC
            """, tuple(queue_ids)).fetchall()]
        else:
            rows = [dict(r) for r in conn.execute(f"""
                SELECT *
                FROM broker_action_queue
                WHERE {failed_status_where}
                ORDER BY id DESC
                LIMIT ?
            """, (count,)).fetchall()]

    preview = [
        {
            "queue_id": r.get("id"),
            "created_at_utc": r.get("created_at_utc"),
            "updated_at_utc": r.get("updated_at_utc"),
            "status": r.get("status"),
            "mode": r.get("mode"),
            "source": r.get("source"),
            "action": r.get("action"),
            "shadow_trade_id": r.get("shadow_trade_id"),
            "shadow_asset": r.get("shadow_asset"),
            "instrument": r.get("instrument"),
            "broker_trade_link_id": r.get("broker_trade_link_id"),
            "notes": r.get("notes"),
            "reason": r.get("reason"),
        }
        for r in rows
    ]

    if dry_run or confirm != "MARK_FAILED_QUEUE_REVIEWED":
        return {
            "status": "dry_run",
            "ok": True,
            "dry_run": True,
            "message": "No rows changed. Repost with dry_run=false and confirm=MARK_FAILED_QUEUE_REVIEWED to mark these failed/error queue rows as reviewed/resolved.",
            "selected_count": len(rows),
            "selected_queue_rows": preview,
            "time_utc": now_utc_iso(),
        }

    now = now_utc_iso()
    updated_ids: List[int] = []
    with get_conn() as conn:
        for r in rows:
            qid = int(r.get("id") or 0)
            if qid <= 0:
                continue
            old_status = safe_str(r.get("status"))
            old_notes = safe_str(r.get("notes"))
            new_notes = (old_notes + "\n" if old_notes else "") + f"Reviewed/resolved at {now}. Previous status={old_status}. Reason: {reason}"
            conn.execute("""
                UPDATE broker_action_queue
                SET status = 'REVIEWED_RESOLVED',
                    updated_at_utc = ?,
                    cancelled_at_utc = COALESCE(NULLIF(cancelled_at_utc,''), ?),
                    notes = ?
                WHERE id = ?
            """, (now, now, new_notes[:4000], qid))
            updated_ids.append(qid)
        conn.commit()

    try:
        recon = broker_reconciliation_health()
    except Exception as e:
        recon = {"ok": False, "error": f"reconciliation check failed after marking reviewed: {type(e).__name__}: {e}"}
    try:
        preflight = broker_execution_preflight()
    except Exception as e:
        preflight = {"ok": False, "error": f"preflight check failed after marking reviewed: {type(e).__name__}: {e}"}

    return {
        "status": "ok",
        "ok": True,
        "dry_run": False,
        "updated_count": len(updated_ids),
        "updated_queue_ids": updated_ids,
        "previous_rows": preview,
        "reconciliation_after": recon,
        "preflight_after": preflight,
        "time_utc": now_utc_iso(),
    }

# ============================================================
# V7.1 SHADOW AUTO OPEN SCANNER FIX
# ============================================================

def broker_shadow_auto_scan_unlinked_open_trades(limit: int = 5) -> Dict[str, Any]:
    """
    Demo-only rescue/scanner pass for shadow auto execution.

    v9.7 hotfix: disabled by default. The scanner used to find recent open Railway
    shadow trades without broker links and mirror them later. That can backfill old
    shadow trades when capacity is increased, so the default live/demo-safe mode is
    fresh-arrivals-only. Set BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL=true only
    for a deliberate manual rescue/backfill test.
    """
    init_db()
    try:
        limit = int(limit)
    except Exception:
        limit = 5
    limit = max(1, min(limit, 25))

    if not BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL:
        return {
            "status": "disabled_fresh_arrivals_only",
            "ok": True,
            "skipped": True,
            "reason": "Open-scan backfill is disabled. Broker promotion is only allowed from newly arriving TradingView signals.",
            "requested_limit": limit,
            "allow_open_scan_backfill": bool(BROKER_SHADOW_AUTO_ALLOW_OPEN_SCAN_BACKFILL),
            "auto_status": broker_shadow_auto_status(),
            "time_utc": now_utc_iso(),
        }

    can, reason = broker_shadow_auto_can_execute("")
    if not can:
        return {
            "status": "blocked",
            "ok": False,
            "reason": reason,
            "auto_status": broker_shadow_auto_status(),
            "time_utc": now_utc_iso(),
        }

    with get_conn() as conn:
        active = conn.execute("""
            SELECT COUNT(*) AS c
            FROM broker_trade_links
            WHERE status IN ('OPEN','CLOSE_SENT')
              AND mode IN ('shadow_demo_auto','practice_manual_queue','practice_manual')
        """).fetchone()["c"]
        remaining_slots = max(0, int(BROKER_SHADOW_AUTO_MAX_OPEN_LINKS) - int(active or 0))
        if remaining_slots <= 0:
            return {
                "status": "blocked",
                "ok": False,
                "reason": f"open broker links {active} >= BROKER_SHADOW_AUTO_MAX_OPEN_LINKS {BROKER_SHADOW_AUTO_MAX_OPEN_LINKS}",
                "active_links": int(active or 0),
                "time_utc": now_utc_iso(),
            }

        max_to_scan = min(limit, remaining_slots)
        min_entry_utc = broker_shadow_auto_min_entry_utc()
        rows = conn.execute("""
            SELECT ot.trade_id, ot.asset, ot.created_at_utc, ot.entry_time, ot.status
            FROM open_trades ot
            LEFT JOIN broker_trade_links bl
              ON bl.shadow_trade_id = ot.trade_id
             AND bl.status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
            LEFT JOIN broker_action_queue aq
              ON aq.shadow_trade_id = ot.trade_id
             AND aq.action = 'place_risk_order'
             AND aq.status IN ('QUEUED_AUTO_SHADOW','WAITING_PRICE_RETRY','WAITING_MARKET_REOPEN','WAITING_RECONCILIATION','EXECUTION_PENDING','EXECUTION_BLOCKED')
            WHERE ot.status = 'open'
              AND UPPER(ot.asset) IN ({placeholders})
              AND bl.id IS NULL
              AND aq.id IS NULL
              AND datetime(COALESCE(NULLIF(ot.created_at_utc, ''), ot.entry_time)) >= datetime(?)
            ORDER BY datetime(ot.created_at_utc) DESC, ot.trade_id DESC
            LIMIT ?
        """.format(placeholders=",".join(["?"] * len(BROKER_SHADOW_AUTO_ALLOWED_ASSETS))),
            tuple(sorted(BROKER_SHADOW_AUTO_ALLOWED_ASSETS)) + (min_entry_utc, max_to_scan,)
        ).fetchall()

    results = []
    for row in rows:
        d = dict(row)
        res = broker_auto_execute_new_shadow_trade(d.get("trade_id"), d.get("asset"))
        results.append({"shadow_trade": d, "result": res})

    return {
        "status": "ok",
        "ok": True,
        "requested_limit": limit,
        "active_links_before": int(active or 0),
        "remaining_slots_before": remaining_slots,
        "fresh_only_min_entry_utc": min_entry_utc,
        "scanned_count": len(rows),
        "results": results,
        "time_utc": now_utc_iso(),
    }


