# ============================================================
# v7.4 TEST-ONLY SIMULATED SHADOW CLOSE HARNESS
# ============================================================
# Purpose:
# - Test broker auto-close behaviour without altering real Railway shadow-trade research rows.
# - Lets us simulate that a linked shadow trade has closed, then close the corresponding
#   OANDA live account broker trade and reconcile the broker link.
# - Practice/live-controlled. Obeys the normal broker close safety gates.


def _latest_active_broker_link_for_shadow_trade(shadow_trade_id: str) -> Optional[Dict[str, Any]]:
    shadow_trade_id = safe_str(shadow_trade_id)
    if not shadow_trade_id:
        return None
    with get_conn() as conn:
        row = conn.execute("""
            SELECT *
            FROM broker_trade_links
            WHERE shadow_trade_id = ?
              AND status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
            ORDER BY id DESC
            LIMIT 1
        """, (shadow_trade_id,)).fetchone()
    return dict(row) if row else None


def _execute_simulated_shadow_close_for_link(link: Dict[str, Any], reason: str = "simulated_shadow_close_test") -> Dict[str, Any]:
    """Close one linked OANDA trade for test purposes only, without changing open_trades."""
    can_close, close_reason = broker_shadow_auto_can_close()
    if not can_close:
        return {
            "ok": False,
            "blocked": True,
            "reason": close_reason,
            "broker_trade_link": link,
            "auto_status": broker_shadow_auto_status(),
            "time_utc": now_utc_iso(),
        }

    link_id = int(link.get("id") or 0)
    broker_trade_id = safe_str(link.get("broker_trade_id") or "")
    shadow_trade_id = safe_str(link.get("shadow_trade_id") or "")
    instrument = normalise_oanda_instrument(link.get("instrument") or "")
    side = safe_str(link.get("side") or "")

    if not broker_trade_id:
        return {"ok": False, "error": "broker trade link has no broker_trade_id", "broker_trade_link": link, "time_utc": now_utc_iso()}

    # Create an auditable queue item first, so this follows the same intent -> execution pattern
    # as the real queued close workflow. It is immediately executed by this test harness.
    preview = {
        "ok": True,
        "action": "simulate_shadow_close",
        "broker_trade_link_id": link_id,
        "shadow_trade_id": shadow_trade_id,
        "instrument": instrument,
        "side": side,
        "broker_trade_id": broker_trade_id,
        "close_units": "ALL",
        "test_only": True,
        "does_not_modify_shadow_trade": True,
        "reason": safe_str(reason),
    }
    qid = create_broker_action_queue_item(
        action="close_linked_trade",
        instrument=instrument,
        side=side,
        shadow_trade_id=shadow_trade_id,
        shadow_asset=safe_str(link.get("shadow_asset") or ""),
        family=get_basket_family(safe_str(link.get("shadow_asset") or "")),
        requested_units=safe_float(link.get("last_known_units")) or safe_float(link.get("filled_units")),
        reason=safe_str(reason),
        preview=preview,
        mode="shadow_demo_auto",
        source="simulate_shadow_close_test",
        status="QUEUED_SIMULATED_SHADOW_CLOSE",
        notes="Test-only simulated shadow close. Does not alter open_trades; closes linked OANDA live account trade only.",
    )
    with get_conn() as conn:
        conn.execute("UPDATE broker_action_queue SET broker_trade_link_id = ? WHERE id = ?", (link_id, qid))
        conn.commit()

    close_body = {"units": "ALL"}
    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
    details = extract_oanda_execution_details(resp)
    broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
    success = bool(resp.get("ok"))

    audit_id = log_execution_audit_event(
        "shadow_demo_auto", instrument, shadow_trade_id, "simulate_shadow_close_execute",
        success, f"test-only simulated shadow close for linked broker trade {broker_trade_id}; queue {qid}", broker_order_id,
        raw={"queue_id": qid, "broker_trade_link": link, "request": close_body, "response": resp, "reason": safe_str(reason)},
        side=side, close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
        broker_trade_id=broker_trade_id, response_status_code=details.get("response_status_code"),
    )

    if success:
        now_closed = now_utc_iso()
        with get_conn() as conn:
            conn.execute("""
                UPDATE broker_trade_links
                SET updated_at_utc = ?, status = 'CLOSE_SENT',
                    closed_at_utc = COALESCE(NULLIF(closed_at_utc,''), ?),
                    last_reconciled_at_utc = ?,
                    notes = ?
                WHERE id = ?
            """, (now_closed, now_closed, now_closed, f"Simulated shadow close sent from queue id {qid}. Test-only; open_trades unchanged.", link_id))
            conn.commit()
        update_broker_action_queue_status(qid, "EXECUTED", "Simulated shadow close executed", audit_id, link_id)
    else:
        update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA close failed"), audit_id, link_id)

    reconcile_result = reconcile_broker_trade_links() if success else None

    return {
        "ok": success,
        "queue_id": qid,
        "audit_id": audit_id,
        "broker_trade_link_id": link_id,
        "shadow_trade_id": shadow_trade_id,
        "broker_trade_id": broker_trade_id,
        "instrument": instrument,
        "request": close_body,
        "response": resp,
        "reconcile_result": reconcile_result,
        "note": "Test-only simulated shadow close. The Railway open_trades row is not modified.",
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/oanda/test/simulate-shadow-close")
async def broker_oanda_test_simulate_shadow_close(request: Request) -> Dict[str, Any]:
    """Test-only: close the OANDA broker trade linked to a shadow trade without altering shadow data."""
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    shadow_trade_id = safe_str(payload.get("shadow_trade_id") or "")
    reason = safe_str(payload.get("reason") or "manual simulated shadow close test")

    if not shadow_trade_id:
        raise HTTPException(status_code=400, detail="shadow_trade_id is required")

    link = _latest_active_broker_link_for_shadow_trade(shadow_trade_id)
    if not link:
        raise HTTPException(status_code=404, detail=f"No active broker link found for shadow_trade_id {shadow_trade_id}")

    result = _execute_simulated_shadow_close_for_link(link, reason=reason)
    return {"status": "ok" if result.get("ok") else "error", "result": result, "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/simulate-multi-shadow-close")
async def broker_oanda_test_simulate_multi_shadow_close(request: Request) -> Dict[str, Any]:
    """Test-only: simulate closes for multiple linked shadow trades, or latest open links if no IDs supplied."""
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    reason = safe_str(payload.get("reason") or "manual multi simulated shadow close test")
    supplied = payload.get("shadow_trade_ids") or payload.get("shadow_trade_id") or []
    if isinstance(supplied, str):
        shadow_trade_ids = [x.strip() for x in supplied.split(",") if x.strip()]
    else:
        shadow_trade_ids = [safe_str(x) for x in supplied if safe_str(x)] if isinstance(supplied, list) else []

    try:
        limit = int(payload.get("limit") or 3)
    except Exception:
        limit = 3
    limit = max(1, min(limit, 25))

    links: List[Dict[str, Any]] = []
    if shadow_trade_ids:
        seen = set()
        for stid in shadow_trade_ids:
            if stid in seen:
                continue
            seen.add(stid)
            link = _latest_active_broker_link_for_shadow_trade(stid)
            if link:
                links.append(link)
            else:
                links.append({"missing": True, "shadow_trade_id": stid})
    else:
        with get_conn() as conn:
            rows = conn.execute("""
                SELECT *
                FROM broker_trade_links
                WHERE mode = 'shadow_demo_auto'
                  AND status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
                ORDER BY id ASC
                LIMIT ?
            """, (limit,)).fetchall()
        links = [dict(r) for r in rows]

    results: List[Dict[str, Any]] = []
    closed_count = 0
    for link in links[:limit]:
        if link.get("missing"):
            results.append({"ok": False, "skipped": True, "reason": "no active broker link found", "shadow_trade_id": link.get("shadow_trade_id")})
            continue
        res = _execute_simulated_shadow_close_for_link(link, reason=reason)
        if res.get("ok"):
            closed_count += 1
        results.append(res)

    health = broker_reconciliation_health() if 'broker_reconciliation_health' in globals() else None
    return {
        "status": "ok",
        "ok": True,
        "requested_count": len(shadow_trade_ids) if shadow_trade_ids else len(links),
        "processed_count": len(results),
        "closed_count": closed_count,
        "results": results,
        "reconciliation_health": health,
        "note": "Test-only simulated close. No open_trades or strategy research rows were modified.",
        "time_utc": now_utc_iso(),
    }

# ============================================================
# v8.9 - OANDA managed stop-loss research harness
# ============================================================

def managed_stop_price_precision(instrument: str) -> int:
    inst = safe_str(instrument).upper()
    if inst in {"SPX500_USD", "NAS100_USD", "US30_USD", "UK100_GBP", "DE30_EUR"}:
        return 1
    if inst in {"XAU_USD", "XAG_USD"}:
        return 2
    if inst == BCO_DEMO_INSTRUMENT:
        return max(0, int(BCO_MANAGED_STOP_PRICE_PRECISION))
    return 5


def managed_stop_round_price(instrument: str, price: float) -> float:
    return round(float(price), managed_stop_price_precision(instrument))


def latest_managed_stop_for_trade(conn: sqlite3.Connection, broker_trade_id: str) -> Optional[Dict[str, Any]]:
    row = conn.execute(
        """
        SELECT * FROM broker_managed_stop_events
        WHERE broker_trade_id = ? AND status IN ('SET','UPDATED','UNCHANGED','DRY_RUN')
        ORDER BY id DESC LIMIT 1
        """,
        (safe_str(broker_trade_id),),
    ).fetchone()
    return dict(row) if row else None


def insert_managed_stop_event(
    link_id: Optional[int], shadow_trade_id: str, instrument: str, broker_trade_id: str,
    action: str, status: str, rule_stage: str, side: str, hold_candles: Optional[int],
    filled_units: Optional[float], broker_fill_price: Optional[float], shadow_current_price: Optional[float],
    previous_stop_price: Optional[float], stop_price: Optional[float], protected_pnl_approx: Optional[float],
    protected_profit_pct: Optional[float], response_status_code: Optional[int], reason: str,
    raw: Optional[Dict[str, Any]] = None,
) -> int:
    init_db()
    with get_conn() as conn:
        cur = conn.execute(
            """
            INSERT INTO broker_managed_stop_events (
                created_at_utc, link_id, shadow_trade_id, instrument, broker_trade_id,
                action, status, rule_stage, side, hold_candles, filled_units,
                broker_fill_price, shadow_current_price, previous_stop_price, stop_price,
                protected_pnl_approx, protected_profit_pct, response_status_code, reason, raw_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                now_utc_iso(), link_id, safe_str(shadow_trade_id), safe_str(instrument), safe_str(broker_trade_id),
                safe_str(action), safe_str(status), safe_str(rule_stage), safe_str(side), hold_candles,
                filled_units, broker_fill_price, shadow_current_price, previous_stop_price, stop_price,
                protected_pnl_approx, protected_profit_pct, response_status_code, safe_str(reason),
                json.dumps(raw or {}, default=str),
            ),
        )
        conn.commit()
        return int(cur.lastrowid)


def get_broker_link_for_stop(shadow_trade_id: str = "", broker_trade_id: str = "", link_id: Optional[int] = None) -> Optional[Dict[str, Any]]:
    init_db()
    with get_conn() as conn:
        row = None
        if link_id is not None:
            row = conn.execute("SELECT * FROM broker_trade_links WHERE id = ?", (int(link_id),)).fetchone()
        elif safe_str(shadow_trade_id):
            row = conn.execute(
                "SELECT * FROM broker_trade_links WHERE shadow_trade_id = ? ORDER BY id DESC LIMIT 1",
                (safe_str(shadow_trade_id),),
            ).fetchone()
        elif safe_str(broker_trade_id):
            row = conn.execute(
                "SELECT * FROM broker_trade_links WHERE broker_trade_id = ? ORDER BY id DESC LIMIT 1",
                (safe_str(broker_trade_id),),
            ).fetchone()
        return dict(row) if row else None


def oanda_set_trade_stop_loss(broker_trade_id: str, stop_price: float, instrument: str = "") -> Dict[str, Any]:
    price = managed_stop_round_price(instrument, float(stop_price)) if instrument else float(stop_price)
    body = {
        "stopLoss": {
            "timeInForce": "GTC",
            "price": str(price),
        }
    }
    return oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{broker_trade_id}/orders", "PUT", body)


def managed_stop_protect_fraction(hold_candles: int) -> Tuple[float, str]:
    h = int(hold_candles or 0)
    if h >= 120:
        return BROKER_MANAGED_STOPS_PROTECT_120, "120h_plus_late_runner"
    if h >= 96:
        return BROKER_MANAGED_STOPS_PROTECT_96, "96h_plus_mature_runner"
    if h >= 72:
        return BROKER_MANAGED_STOPS_PROTECT_72, "72h_plus_runner"
    return BROKER_MANAGED_STOPS_PROTECT_48, "48h_plus_runner"


def build_managed_stop_candidate(link: Dict[str, Any], trade: Optional[Dict[str, Any]], previous_stop: Optional[float] = None) -> Dict[str, Any]:
    instrument = safe_str(link.get("instrument"))
    broker_trade_id = safe_str(link.get("broker_trade_id"))
    shadow_trade_id = safe_str(link.get("shadow_trade_id"))
    units = safe_float(link.get("filled_units")) or safe_float(link.get("last_known_units")) or 0.0
    side = safe_str(link.get("side") or ("buy" if units >= 0 else "sell")).lower()
    is_long = side in {"buy", "long"} or units > 0
    abs_units = abs(float(units or 0.0))
    broker_fill = safe_float(link.get("last_known_price"))
    if broker_fill is None and trade:
        broker_fill = safe_float(trade.get("entry_price"))
    current = safe_float(trade.get("current_price")) if trade else None
    hold = int(safe_float(trade.get("hold_candles")) or 0) if trade else 0

    base = {
        "link_id": link.get("id"),
        "shadow_trade_id": shadow_trade_id,
        "shadow_asset": safe_str(link.get("shadow_asset") or (trade.get("asset") if trade else "")),
        "signal_time": safe_str(trade.get("last_seen_time") if trade else ""),
        "instrument": instrument,
        "broker_trade_id": broker_trade_id,
        "side": "long" if is_long else "short",
        "filled_units": units,
        "broker_fill_price": broker_fill,
        "shadow_current_price": current,
        "hold_candles": hold,
        "previous_stop_price": previous_stop,
        "eligible": False,
    }
    if not trade:
        return {**base, "reason": "shadow trade not currently open"}
    if hold < BROKER_MANAGED_STOPS_MIN_HOLD_CANDLES:
        return {**base, "reason": f"hold {hold} < managed stop minimum {BROKER_MANAGED_STOPS_MIN_HOLD_CANDLES}"}
    if not broker_trade_id or not broker_fill or not current or abs_units <= 0:
        return {**base, "reason": "missing broker trade id/fill/current/units"}

    if is_long:
        profit_points = float(current) - float(broker_fill)
        if profit_points <= 0:
            return {**base, "reason": "not profitable versus broker fill"}
    else:
        profit_points = float(broker_fill) - float(current)
        if profit_points <= 0:
            return {**base, "reason": "not profitable versus broker fill"}

    fraction, stage = managed_stop_protect_fraction(hold)
    if is_long:
        raw_stop = float(broker_fill) + profit_points * fraction
        # Stop should remain below current price; leave a tiny buffer if rounding would collide.
        raw_stop = min(raw_stop, float(current) * 0.9999)
        stop_price = managed_stop_round_price(instrument, raw_stop)
        protected_pnl = (stop_price - float(broker_fill)) * abs_units
        if previous_stop is not None:
            min_step_price = float(broker_fill) * BROKER_MANAGED_STOPS_MIN_STEP_PCT / 100.0
            if stop_price <= float(previous_stop) + min_step_price:
                return {**base, "eligible": False, "rule_stage": stage, "stop_price": stop_price, "protected_pnl_approx": protected_pnl, "reason": "candidate stop would not tighten enough"}
    else:
        raw_stop = float(broker_fill) - profit_points * fraction
        raw_stop = max(raw_stop, float(current) * 1.0001)
        stop_price = managed_stop_round_price(instrument, raw_stop)
        protected_pnl = (float(broker_fill) - stop_price) * abs_units
        if previous_stop is not None:
            min_step_price = float(broker_fill) * BROKER_MANAGED_STOPS_MIN_STEP_PCT / 100.0
            if stop_price >= float(previous_stop) - min_step_price:
                return {**base, "eligible": False, "rule_stage": stage, "stop_price": stop_price, "protected_pnl_approx": protected_pnl, "reason": "candidate stop would not tighten enough"}

    protected_profit_pct = ((stop_price / float(broker_fill) - 1.0) * 100.0) if is_long else ((float(broker_fill) / stop_price - 1.0) * 100.0)
    return {
        **base,
        "eligible": True,
        "rule_stage": stage,
        "protect_fraction": fraction,
        "stop_price": stop_price,
        "protected_pnl_approx": protected_pnl,
        "protected_profit_pct": protected_profit_pct,
        "reason": f"{stage}: protecting approx {fraction:.0%} of current broker-side profit",
    }


def managed_stops_status_rows(limit: int = 500) -> List[Dict[str, Any]]:
    init_db()
    limit = max(1, min(int(limit or 500), 2000))
    with get_conn() as conn:
        links = [dict(r) for r in conn.execute(
            """
            SELECT * FROM broker_trade_links
            WHERE UPPER(COALESCE(status,'')) IN ('OPEN','LINKED','PENDING')
            ORDER BY id DESC LIMIT ?
            """,
            (limit,),
        ).fetchall()]
        out = []
        for link in links:
            trade = conn.execute("SELECT * FROM open_trades WHERE trade_id = ?", (safe_str(link.get("shadow_trade_id")),)).fetchone()
            trade_dict = dict(trade) if trade else None
            latest = latest_managed_stop_for_trade(conn, safe_str(link.get("broker_trade_id")))
            prev_stop = safe_float(latest.get("stop_price")) if latest else None
            cand = build_managed_stop_candidate(link, trade_dict, prev_stop)
            cand["latest_stop_status"] = latest.get("status") if latest else "NONE"
            cand["latest_stop_event_time"] = latest.get("created_at_utc") if latest else ""
            out.append(cand)
        return out


@app.get("/broker/oanda/managed-stops/status")
def broker_oanda_managed_stops_status(limit: int = 500) -> Dict[str, Any]:
    rows = managed_stops_status_rows(limit)
    eligible = [r for r in rows if r.get("eligible")]
    protected_total = sum(float(r.get("protected_pnl_approx") or 0.0) for r in rows if r.get("stop_price"))
    return {
        "status": "ok",
        "enabled": BROKER_MANAGED_STOPS_ENABLED,
        "min_hold_candles": BROKER_MANAGED_STOPS_MIN_HOLD_CANDLES,
        "open_link_count": len(rows),
        "eligible_count": len(eligible),
        "protected_pnl_at_stops_approx": protected_total,
        "note": "Protected P&L is an estimate at stop price, not a guaranteed fill; gaps/slippage can differ.",
        "managed_stops": rows,
        "time_utc": now_utc_iso(),
    }


@app.get("/export/managed-stops-status.csv")
def export_managed_stops_status_csv(limit: int = 2000) -> Response:
    rows = managed_stops_status_rows(limit)
    fieldnames = list(rows[0].keys()) if rows else [
        "link_id", "shadow_trade_id", "instrument", "broker_trade_id", "side", "filled_units",
        "broker_fill_price", "shadow_current_price", "hold_candles", "previous_stop_price", "eligible",
        "rule_stage", "protect_fraction", "stop_price", "protected_pnl_approx", "protected_profit_pct",
        "reason", "latest_stop_status", "latest_stop_event_time"
    ]
    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow(row)
    return Response(content=output.getvalue(), media_type="text/csv", headers={"Content-Disposition": 'attachment; filename="managed-stops-status.csv"'})


@app.post("/broker/oanda/test/set-linked-trade-stop")
async def broker_oanda_test_set_linked_trade_stop(request: Request) -> Dict[str, Any]:
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}
    link = get_broker_link_for_stop(
        shadow_trade_id=safe_str(body.get("shadow_trade_id", "")),
        broker_trade_id=safe_str(body.get("broker_trade_id", "")),
        link_id=int(body.get("link_id")) if body.get("link_id") not in (None, "") else None,
    )
    if not link:
        return {"status": "error", "ok": False, "error": "broker trade link not found", "time_utc": now_utc_iso()}
    stop_price = safe_float(body.get("stop_price"))
    if stop_price is None or stop_price <= 0:
        return {"status": "error", "ok": False, "error": "stop_price required", "link": link, "time_utc": now_utc_iso()}
    resp = oanda_set_trade_stop_loss(safe_str(link.get("broker_trade_id")), stop_price, safe_str(link.get("instrument")))
    success = bool(resp.get("ok"))
    event_id = insert_managed_stop_event(
        link.get("id"), safe_str(link.get("shadow_trade_id")), safe_str(link.get("instrument")), safe_str(link.get("broker_trade_id")),
        "manual_set_stop_loss", "SET" if success else "FAILED", "manual", safe_str(link.get("side")), None,
        safe_float(link.get("filled_units")), safe_float(link.get("last_known_price")), None, None,
        managed_stop_round_price(safe_str(link.get("instrument")), stop_price), None, None,
        resp.get("status_code"), "manual linked stop-loss update", {"request": body, "response": resp},
    )
    return {"status": "ok" if success else "error", "ok": success, "event_id": event_id, "link": link, "response": resp, "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/update-managed-stops")
async def broker_oanda_test_update_managed_stops(request: Request) -> Dict[str, Any]:
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}
    dry_run = bool(body.get("dry_run", False))
    force = bool(body.get("force", False))
    limit = max(1, min(int(body.get("limit", 250)), 500))
    if not BROKER_MANAGED_STOPS_ENABLED and not force and not dry_run:
        return {
            "status": "blocked", "ok": False,
            "error": "BROKER_MANAGED_STOPS_ENABLED is false. Use dry_run=true for preview or force=true for manual practice test.",
            "time_utc": now_utc_iso(),
        }
    rows = managed_stops_status_rows(limit)
    results = []
    for cand in rows:
        if not cand.get("eligible"):
            continue
        if dry_run:
            event_id = insert_managed_stop_event(
                cand.get("link_id"), cand.get("shadow_trade_id"), cand.get("instrument"), cand.get("broker_trade_id"),
                "managed_stop_dry_run", "DRY_RUN", cand.get("rule_stage"), cand.get("side"), cand.get("hold_candles"),
                cand.get("filled_units"), cand.get("broker_fill_price"), cand.get("shadow_current_price"), cand.get("previous_stop_price"),
                cand.get("stop_price"), cand.get("protected_pnl_approx"), cand.get("protected_profit_pct"), None,
                cand.get("reason"), {"candidate": cand},
            )
            results.append({"event_id": event_id, "dry_run": True, "candidate": cand})
            continue
        resp = oanda_set_trade_stop_loss(cand.get("broker_trade_id"), cand.get("stop_price"), cand.get("instrument"))
        success = bool(resp.get("ok"))
        event_id = insert_managed_stop_event(
            cand.get("link_id"), cand.get("shadow_trade_id"), cand.get("instrument"), cand.get("broker_trade_id"),
            "managed_stop_update", "UPDATED" if success else "FAILED", cand.get("rule_stage"), cand.get("side"), cand.get("hold_candles"),
            cand.get("filled_units"), cand.get("broker_fill_price"), cand.get("shadow_current_price"), cand.get("previous_stop_price"),
            cand.get("stop_price"), cand.get("protected_pnl_approx"), cand.get("protected_profit_pct"), resp.get("status_code"),
            cand.get("reason"), {"candidate": cand, "response": resp},
        )
        results.append({"event_id": event_id, "ok": success, "candidate": cand, "response": resp})
    return {
        "status": "ok",
        "ok": True,
        "dry_run": dry_run,
        "managed_stops_enabled": BROKER_MANAGED_STOPS_ENABLED,
        "eligible_count": len([r for r in rows if r.get("eligible")]),
        "processed_count": len(results),
        "results": results,
        "note": "Protected P&L is an estimate at the stop price, not guaranteed against gaps/slippage.",
        "time_utc": now_utc_iso(),
    }

